def test_the_post_ejection_p00_and_dap_modes_share_one_source_bounded_cut(tmp_path):
    """P00 idling and CMC DAP control coexist after F37 00E and before the later V49.

    The Apollo 17 CSM Launch Checklist selects P00 after LM ejection (PDF p. 59), while the
    Block II operations handbook names P00 an operative idling program (PDF p. 74). The checklist
    loads and activates the RCS DAP, selects CMC control, then CMC MODE AUTO (pp. 49, 53-55, 59);
    the handbook's attitude-control procedure says that combination enables autopilot control
    (PDF p. 57). `idle` reads the published P00 name directly. `auto` is this model's derived
    mapping from CMC DAP ownership to its service loop. These are two different questions, so a
    P00 computer does not turn the DAP off.

    Broken copies delete the P00 source locator, change the RCS state, replace the RCS relation,
    change one published switch setting while keeping `auto`, or replace the provenance map with
    a list. The launch-state join must refuse each, including a source-free `auto` that would pass
    the generic initial-value agreement.
    """
    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    launch = mission["launch_state"]
    assert launch["as_of_event"] == mission["initial_state"]["as_of_event"] == (
        "post-ejection P00, before V49 maneuver"
    )
    assert "post-ejection P00 selected before V49" in mission["phases"][0]["entry"]
    assert launch["states"]["computer_mode"] == "idle"
    assert launch["states"]["mode"] == "auto"
    assert "computer_mode" in launch["sourced"]
    assert "mode" not in launch["sourced"]
    assert sorted(launch["owed"]) == ["breaker_panel", "hatch_state"]

    avionics = yaml.safe_load((VEHICLE / "domains" / "avionics" / "components.yaml").read_text())
    computer = next(s for s in avionics["state"] if s["id"] == "computer_mode")
    assert computer["initial"] == "idle"
    assert computer["initial_provenance"]["basis"] == "historical"
    rcs = yaml.safe_load((VEHICLE / "domains" / "rcs" / "components.yaml").read_text())
    mode = next(s for s in rcs["state"] if s["id"] == "mode")
    assert mode["initial"] == "auto"
    assert mode["initial_provenance"]["basis"] == "derived"
    assert mode["initial_provenance"]["relation"] == (
        "dap_active and sc_cont_cmc and cmc_mode_auto => auto"
    )
    assert mode["initial_provenance"]["source_configuration"] == {
        "dap_active": {"action": "V46E", "checklist_pdf_page": 53},
        "sc_cont_cmc": {"position": "CMC", "checklist_pdf_page": 55},
        "cmc_mode_auto": {"position": "AUTO", "checklist_pdf_page": 59},
        "mapping_authority": {"handbook_pdf_page": 57, "section": "4.7.1.6"},
    }

    missing_source = copy_definition(fixture_dir(tmp_path, "p00-source-deleted"))
    target = missing_source / "mission.yaml"
    source_text = target.read_text()
    locator = '    computer_mode: "Apollo 17 checklist p. 59 (printed 3-6), `F37 00E` after LM ejection; Block II handbook p. 74, section 4.8.1.1, P00 CMC Idling Program in operate condition, distinct from P06 standby"\n'
    assert locator in source_text
    target.write_text(source_text.replace(locator, "", 1))
    out = run_linter(missing_source).stdout
    assert "state computer_mode" in out and "sourced` map does not cite it" in out, out[-1400:]

    manual_rcs = copy_definition(fixture_dir(tmp_path, "rcs-start-manual"))
    target = manual_rcs / "domains" / "rcs" / "components.yaml"
    state_text = target.read_text()
    old = '    unit: "enum[auto,manual,free_drift]"\n    initial: auto\n'
    assert old in state_text
    target.write_text(state_text.replace(old, old.replace("initial: auto", "initial: manual"), 1))
    out = run_linter(manual_rcs).stdout
    assert "domains/rcs/components.yaml:state mode" in out and "makes it 'auto'" in out, out[-1400:]

    changed_relation = copy_definition(fixture_dir(tmp_path, "rcs-start-relation-changed"))
    target = changed_relation / "domains" / "rcs" / "components.yaml"
    state_text = target.read_text()
    assert "dap_active and sc_cont_cmc and cmc_mode_auto => auto" in state_text
    target.write_text(state_text.replace(
        "dap_active and sc_cont_cmc and cmc_mode_auto => auto",
        "dap_active and sc_cont_cmc => auto", 1,
    ))
    out = run_linter(changed_relation).stdout
    assert "auto` cannot survive a changed input" in out, out[-1400:]

    changed_source = copy_definition(fixture_dir(tmp_path, "rcs-start-source-changed"))
    target = changed_source / "domains" / "rcs" / "components.yaml"
    state_text = target.read_text()
    assert "sc_cont_cmc: {position: CMC, checklist_pdf_page: 55}" in state_text
    target.write_text(state_text.replace(
        "sc_cont_cmc: {position: CMC, checklist_pdf_page: 55}",
        "sc_cont_cmc: {position: SCS, checklist_pdf_page: 55}", 1,
    ))
    out = run_linter(changed_source).stdout
    assert "auto` cannot survive a changed input" in out, out[-1400:]

    changed_basis = copy_definition(fixture_dir(tmp_path, "rcs-start-basis-changed"))
    target = changed_basis / "domains" / "rcs" / "components.yaml"
    state_text = target.read_text()
    old = "    initial: auto\n    initial_provenance:\n      basis: derived\n"
    assert old in state_text
    target.write_text(state_text.replace(old, old.replace("basis: derived", "basis: chosen"), 1))
    out = run_linter(changed_basis).stdout
    assert "Keep `basis: derived`" in out, out[-1400:]

    malformed = copy_definition(fixture_dir(tmp_path, "rcs-start-provenance-list"))
    target = malformed / "domains" / "rcs" / "components.yaml"
    state_text = target.read_text()
    mode_start = state_text.index("  - id: mode\n")
    provenance_start = state_text.index("    initial_provenance:\n", mode_start)
    provenance_end = state_text.index("    initial_note: >-\n", provenance_start)
    target.write_text(
        state_text[:provenance_start]
        + "    initial_provenance: [malformed]\n"
        + state_text[provenance_end:]
    )
    result = run_linter(malformed)
    assert result.returncode == 1, (result.stdout[-1400:], result.stderr[-1400:])
    assert "state mode.initial_provenance: must be a mapping" in result.stdout, result.stdout[-1400:]
    assert "Traceback" not in result.stderr, result.stderr[-1400:]


def test_a_published_launch_position_is_not_a_decision(tmp_path):
    """The launch positions are a lookup, and this block could only call them a decision.

    Round 76 left nine positions owed, and the sentence it left them on is inside this file's own
    refusal: *"A launch position no source publishes is a decision, and the `reason` is what
    separates it from a number somebody typed."* That is true of the four machines the mission's own
    start settles — no engine has been commanded, so the engines are `off` — and it was carried as a
    general truth. **A source does publish them**: `Apollo 17 CSM Launch Checklist (Basic)`, the
    panel-by-panel launch configuration, states `MN BUS TIE (2) - on (up)` (pp. 11, 22), `PCM BIT
    RATE - HI` (p. 10) and `S BD ANT - OMNI` with `S BO ANT OMNI - B` (p. 10). Three of the nine are
    that: a lookup the corpus kept as an open question to the operator.

    So the block gained a `source` — the document — and a `sourced` map giving each position its own
    locator in it, and the state's own `basis` is joined to that map **in both directions**. A
    position read out of a document is `historical`; one the mission's own start settles is
    `derived`; and the two are not interchangeable, which is what the four refusals below hold.

    **And the round corrects four notes that told the next reader to stop looking.** The sharpest is
    `cabin_regulator_position`, whose note asserted in passing that "`closed` is the launch
    configuration" while the checklist's ECS panels read `MAIN REG vlv (2) - OPEN` (p. 18) — a guess
    at a launch configuration wearing the clothes of a fact, in the one place a source could settle
    it. `comm_mode` is the opposite case and is worth the note it now carries: two of its four
    members (`sband_high`, `sband_low`) are the same choice `telemetry_rate` owns, so the source
    answers the rate and cannot answer the mode — one decision declared in two states, where a
    lookup for one of them is not a lookup for the other.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]

    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    block = mission["launch_state"]
    assert block["source"].startswith("Apollo 17 CSM Launch Checklist")
    assert block["sourced"] == {
        "bus_tie_closed": "p. 33 (`MN BUS TIE (2) - OFF`), verified at p. 36, before P15 TLI initiate/cutoff at p. 49",
        "telemetry_rate": "p. 35 (`PCM BIT RATE - LOW` at GET 00:23:27), before P15 TLI initiate/cutoff at p. 49",
        "antenna_selection": "p. 56 (`S BD ANT OMNI - HI GAIN`), before docking at p. 57 and LM ejection at p. 59",
        "cabin_regulator_position": "p. 18, PANEL 351 (`MAIN REG vlv (2) - OPEN` with `EMER CAB "
        "PRESS vlv - OFF` — the main cabin-pressure regulator in service and the emergency one "
        "off, which is `primary`)",
        "computer_mode": "Apollo 17 checklist p. 59 (printed 3-6), `F37 00E` after LM ejection; "
        "Block II handbook p. 74, section 4.8.1.1, P00 CMC Idling Program in operate condition, "
        "distinct from P06 standby",
    }

    # Eleven positions: four settled by the start, five directly read from documents, and two
    # derived through declared mappings (the link rate's mode and CMC DAP control ownership).
    assert block["states"] == {
        "aps_state": "off",
        "dps_state": "off",
        "sps_state": "off",
        "guidance_mode": "coast",
        "bus_tie_closed": "open",
        "telemetry_rate": 1600,
        "antenna_selection": "high_gain",
        "comm_mode": "sband_low",
        "cabin_regulator_position": "primary",
        "computer_mode": "idle",
        "mode": "auto",
    }

    # Every state that cites the block agrees with it, and its `basis` says which half it is in.
    states: dict[str, dict] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []:
            if isinstance(state, dict) and state.get("id"):
                states[state["id"]] = state
    for sid, value in block["states"].items():
        state = states[sid]
        assert str(state["initial"]) == str(value), sid
        provenance = state.get("initial_provenance") or {}
        assert provenance.get("source") == "mission.yaml:launch_state", sid
        expected = "historical" if sid in block["sourced"] else "derived"
        assert provenance.get("basis") == expected, sid

    # The rate is the `high` profile's own number rather than a second copy of it — the same join
    # `derives` makes everywhere else.
    rates = {entry["id"]: entry["bps"] for entry in yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())["comms"]["rates"]}
    assert states["telemetry_rate"]["initial"] == rates["low"] == 1600

    # **And the other half is the block's own declaration rather than a tuple here**, which is round
    # 84. This loop used to name the four states outright and assert that each note contained the
    # words "launch checklist" — a list in a test and a phrase in a note, holding an inventory that
    # belonged to the block. `owed` is where the inventory lives now, so the test reads it, and what
    # it asks of each entry is what makes the debt payable: the state is still unconfigured, its own
    # note names the document or the question it is waiting on, and the block says in a sentence
    # what would close it. `comm_mode` left this list in round 81 and `cabin_regulator_position` in
    # round 83, which found the position the source states — and the *prose* that recorded both
    # departures said the opposite for four rounds, which is the round-84 finding.
    owed = block["owed"]
    for sid in sorted(owed):
        assert states[sid]["initial"] == "UNCONFIGURED", sid
        note = str(states[sid].get("initial_note") or "")
        assert "checklist" in note.lower(), sid
        assert len(str(owed[sid]).strip()) > 40, sid
    # Eleven made and two owed is the launch question's whole inventory, and the two maps cannot
    # overlap — a position this block settles is not one it is still asking for.
    assert not (set(block["states"]) & set(owed)), sorted(set(block["states"]) & set(owed))
    assert len(block["states"]) + len(owed) == 13

    def refusal(name: str, path: tuple[str, ...], old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        target = definition.joinpath(*path)
        text = target.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        target.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1400:]}"

    mission_path = ("mission.yaml",)
    # A position read out of a document whose state says it came from the mission's own start.
    refusal(
        "basis-says-derived",
        ("domains", "power", "components.yaml"),
        "      basis: historical\n      source: mission.yaml:launch_state",
        "      basis: derived\n      source: mission.yaml:launch_state",
        "A published position is `historical`",
    )
    # And the mirror: a position cited by the block whose state claims a document.
    refusal(
        "sourced-not-cited",
        mission_path,
        '    bus_tie_closed: "p. 33 (`MN BUS TIE (2) - OFF`), verified at p. 36, before P15 TLI initiate/cutoff at p. 49"\n',
        "",
        "and the block's `sourced` map does not cite it",
    )
    # A locator for a position the block does not declare. `hatch_state` is still owed; `comm_mode`
    # used to serve here and cannot now, because round 81 put
    # it in the block as a `derived` position — so citing it in `sourced` fires the *basis* join
    # instead, which is the next case down.
    refusal(
        "locator-for-nothing",
        mission_path,
        '    antenna_selection: "p. 56 (`S BD ANT OMNI - HI GAIN`), before docking at p. 57 and LM ejection at p. 59"\n',
        '    antenna_selection: "p. 56 (`S BD ANT OMNI - HI GAIN`), before docking at p. 57 and LM ejection at p. 59"\n'
        '    hatch_state: "p. 10"\n',
        "A locator for a position this block does not make is a citation nothing holds",
    )
    # A position the block makes from a *relation* and the block's own citation claiming a document
    # for it — the two halves of the same join, disagreeing.
    refusal(
        "derived-cited-as-published",
        mission_path,
        '    antenna_selection: "p. 56 (`S BD ANT OMNI - HI GAIN`), before docking at p. 57 and LM ejection at p. 59"\n',
        '    antenna_selection: "p. 56 (`S BD ANT OMNI - HI GAIN`), before docking at p. 57 and LM ejection at p. 59"\n'
        '    comm_mode: "p. 10"\n',
        "A published position is `historical`",
    )
    # A citation with no page, which is a source a reader cannot turn to.
    refusal(
        "locator-missing",
        mission_path,
        '    antenna_selection: "p. 56 (`S BD ANT OMNI - HI GAIN`), before docking at p. 57 and LM ejection at p. 59"\n',
        '    antenna_selection: ""\n',
        "with no locator",
    )
    # The document is what the locators are locators *in*.
    refusal(
        "source-missing",
        mission_path,
        "  source: >-\n    Apollo 17 CSM Launch Checklist (Basic), NASA Manned Spacecraft Center, Flight Procedures Branch,\n    4 September 1972 — launch through post-LM-ejection; and Apollo Operations Handbook, Block II\n    Spacecraft, SM2A-03-BLOCK II, G&C sections 4.6-4.8 — the P00/P06 program meanings and RCS DAP\n    control modes. Page locators below refer to the PDF page numbers in those two documents\n",
        "",
        "and no `source`",
    )
    # And a document cited for nothing.
    refusal(
        "nothing-sourced",
        mission_path,
        '  sourced:\n    bus_tie_closed: "p. 33 (`MN BUS TIE (2) - OFF`), verified at p. 36, before P15 TLI initiate/cutoff at p. 49"\n',
        "",
        "the citation is a declaration nothing reads",
    )


def test_the_launch_block_declares_what_it_owes_and_not_only_what_it_makes(tmp_path):
    """The block's inventory of the launch question lived in prose, and the prose went stale twice.

    `mission.yaml#launch_state` is the one place the vehicle says where it starts. It could say
    which positions it *makes* (`states`) and which of those it read out of a document (`sourced`),
    and it had **no way to say which positions it owes** — so that half lived in a sentence, in two
    files, both written by the round that landed the commanded modes:

    * the comment above the block — *"this covers four of them … a regulator position, a link mode,
      an antenna selection and a telemetry profile are choices the corpus does not make … those stay
      owed"*;
    * the docstring of `test_the_launch_state_is_declared_once_and_held_in_both_directions` — *"The
      other nine stay owed … are choices this corpus does not make"*.

    **Rounds 80, 81 and 83 made all four of those positions**, three of them out of the launch
    checklist the block now cites by page, and both sentences went on saying the opposite. Neither
    was read by anything, and a test cannot read a comment: the count had no reader, so it did not
    have to be plausible. That is this folder's own finding, written down for
    `channels.yaml:coverage` — *a number in prose has no reader, and a number with no reader does
    not have to be plausible* — which is why that claim drifted for thirty rounds and why this one
    drifted for four.

    The repair is a field. `owed` is required beside `states`, keyed by state, and its four refusals
    are the ways it can disagree with the corpus: the block making a position and owing it at once;
    the block owning a position whose state no longer owes anything, which is *precisely* round 84's
    drift and would have fired on the day it happened; an owed name that is no state at all; and an
    owed position with nothing said about what would close it. The corpus change beside them is the
    correction of the two stale sentences and of `hatch_state`'s note, which named a document class
    that does not exist — the LM was never launched on its own, and the archive's HSI series carries
    its *activation* checklist where the CSM's launch checklist sits.

    The count those sentences got wrong is a pin now, in the case below and in the round-76 test: a
    position moving between the two maps moves it.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]

    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    block = mission["launch_state"]
    made, owed = block["states"], block["owed"]
    assert isinstance(owed, dict), type(owed)
    # Eleven made and two owed; `relief_valve_state` was the fourteenth machine and answered itself,
    # so it is in neither map.
    assert len(made) + len(owed) == 13
    assert not (set(made) & set(owed))
    assert sorted(owed) == ["breaker_panel", "hatch_state"]

    states: dict[str, dict] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []:
            if isinstance(state, dict) and state.get("id"):
                states[state["id"]] = state
    for sid in sorted(owed):
        # The two halves of one statement: the block says it owes this position, and the state says
        # it has no value. A block that owes a position the state has already settled is the drift.
        assert states[sid]["initial"] == "UNCONFIGURED", sid
        assert len(str(owed[sid]).strip()) > 40, sid
    for sid in sorted(made):
        assert states[sid]["initial"] != "UNCONFIGURED", sid

    def refusal(name: str, path: tuple[str, ...], old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        target = definition.joinpath(*path)
        text = target.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        target.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1400:]}"

    mission_path = ("mission.yaml",)
    # **The block stating its positions and not what it owes** — the shape the corpus was in until
    # this round, and the reason the two prose sentences were the only record of the other half.
    # Removed as a whole block rather than renamed, so the fixture stays a *plausible* file: the
    # round law's broken copies are broken by meaning, and a copy that does not parse tests the
    # parser rather than the refusal.
    definition = copy_definition(fixture_dir(tmp_path, "owed-missing"))
    target = definition / "mission.yaml"
    text = target.read_text()
    stripped = re.sub(r"(?m)^  owed:\n(?:    .*\n)*", "", text, count=1)
    assert stripped != text, "the fixture no longer matches the `owed` block"
    target.write_text(stripped)
    out = run_linter(definition).stdout
    assert "declares the positions it makes and no `owed` map" in out, out[-1400:]

    # `owed` as anything but a map, which is the same as naming nothing.
    refusal(
        "owed-not-a-map",
        mission_path,
        "  owed:\n    breaker_panel: >-\n      the `breaker_id` key space and the positions reached after extraction. The checklist gives",
        "  owed:\n    - breaker_panel\n  owed_unused:\n    breaker_panel: >-\n"
        "      the `breaker_id` key space and the positions reached after extraction. The checklist gives",
        "declares `owed` as ['breaker_panel'], which names no position",
    )
    # **A position the block makes and owes at once.** An entry in both maps is the drift `owed`
    # exists to catch, written where a reader would take it for an answer.
    refusal(
        "made-and-owed",
        mission_path,
        "    breaker_panel: >-\n      the `breaker_id` key space and the positions reached after extraction.",
        "    bus_tie_closed: >-\n      a position this block also makes below.\n"
        "    breaker_panel: >-\n      the `breaker_id` key space and the positions reached after extraction.",
        "makes a position for 'bus_tie_closed' and owes it in the same block",
    )
    # **The refusal that would have caught round 84's drift on the day it landed**: the round that
    # sources a position adds it to `states`, and a block that leaves it in `owed` is claiming as a
    # debt something it has already paid.
    refusal(
        "owed-and-paid",
        ("domains", "structure", "components.yaml"),
        '    unit: "map[hatch_id,enum[closed,latched,open]]"\n    initial: UNCONFIGURED\n',
        '    unit: "map[hatch_id,enum[closed,latched,open]]"\n    initial: {hatch_crew_csm: latched, hatch_crew_lm: latched}\n',
        "still owes it. A debt the state has already paid is a debt left standing",
    )
    # A debt owed on a machine that does not exist.
    refusal(
        "owed-nothing-real",
        mission_path,
        "    hatch_state: >-\n      each modeled crew hatch's position",
        "    not_a_state_at_all: >-\n      a debt owed on a machine that does not exist.\n"
        "    hatch_state: >-\n      each modeled crew hatch's position",
        "owes 'not_a_state_at_all', which is not a state of any domain",
    )
    # And a debt named without saying what would close it, which is a debt nobody can pay.
    refusal(
        "owed-says-nothing",
        mission_path,
        "    hatch_state: >-\n"
        "      each modeled crew hatch's position after extraction. The CSM side hatch is locked in the\n"
        "      launch checklist (p. 20), but the post-docking tunnel hatch is removed and reinstalled\n"
        "      (p. 58), and it is a different hatch id. The modeled LM crew hatch is the forward surface\n"
        "      EVA hatch, not the overhead docking hatch. It needs a forward-hatch stowage or acceptance\n"
        "      source, or an explicit post-extraction initial-position decision; the overhead hatch's\n"
        "      later flight configuration would not answer this event\n",
        '    hatch_state: ""\n',
        "owes 'hatch_state' with nothing said about what would close it",
    )
    # A state claiming the launch question while the block neither makes it nor owes it. The four
    # owed states do not cite the block — the debt is theirs and the block merely names them — so
    # this is the join that keeps a *third* one from appearing without either side saying so.
    definition = copy_definition(fixture_dir(tmp_path, "claims-the-block-unaccounted"))
    target = definition / "domains" / "structure" / "components.yaml"
    text = target.read_text()
    anchor = "    unit: \"map[hatch_id,enum[closed,latched,open]]\"\n    initial: UNCONFIGURED\n"
    assert anchor in text
    target.write_text(
        text.replace(
            anchor,
            anchor + "    initial_provenance:\n      basis: chosen\n      reason: a state that"
            " claims the launch question\n      source: mission.yaml:launch_state\n",
            1,
        )
    )
    mission_target = definition / "mission.yaml"
    mission_text = mission_target.read_text()
    trimmed = re.sub(r"(?m)^    hatch_state: >-\n(?:      .*\n)*", "", mission_text, count=1)
    assert trimmed != mission_text, "the fixture no longer matches the hatch_state debt"
    mission_target.write_text(trimmed)
    out = run_linter(definition).stdout
    assert "A state claiming the launch question that does not mention it is a citation nothing holds" in out, out[-1400:]


def test_a_telemetry_profile_says_which_link_mode_carries_it(tmp_path):
    """The high/low distinction is declared twice, and until this round nothing joined the two.

    `apollo_diode.md:161` gives `comm.link_mode` as `sband_high/sband_low/vhf/none`; `:165` gives
    `comm.telemetry_rate_bps` as "1,600 / 51,200 Apollo-inspired profiles"; and the corpus's own prose
    says what the pair is — *"the high-rate/low-rate telemetry distinction was 51.2 and 1.6 kbit/s"*.
    The vehicle carries both faithfully, as `comm_mode` and `telemetry_rate`, and **no declaration
    anywhere said which link mode carries which rate.** A vehicle could hold `sband_low` at 51,200
    bit/s — a link mode and a rate that contradict each other — and every check in the linter would
    pass.

    **The claim was in the corpus, as prose, written by the round before this one.**
    `comm_mode`'s note said the two members "are the same choice as `telemetry_rate`'s `high` and
    `low`", and nothing read it — this folder's second most frequent defect, arriving in the round
    that was quoting it. The repair puts the correspondence where the rates are already declared
    once: each profile in `vehicle.yaml#comms.rates` names the `link_mode` that carries it and the
    `rate_state` that holds it, and `check_link_profiles` refuses the two positions disagreeing.

    `comm_mode` is `derived` rather than `historical` for the same reason: the launch checklist sets
    one switch (`PCM BIT RATE - LOW`, pp. 35 and 59), that is `telemetry_rate`'s position, and the link mode
    follows from it through the correspondence — a relation, not a second reading.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]

    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    rates = {entry["id"]: entry for entry in vehicle["comms"]["rates"]}
    # Both profiles name both ends of the join.
    assert {pid: (p["link_mode"], p["rate_state"]) for pid, p in rates.items()} == {
        "low": ("sband_low", "telemetry_rate"),
        "high": ("sband_high", "telemetry_rate"),
    }

    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    states_block = mission["launch_state"]["states"]
    states: dict[str, dict] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []:
            if isinstance(state, dict) and state.get("id"):
                states[state["id"]] = state

    # The two ends of one profile are the two positions the block declares, and they agree.
    assert states_block["telemetry_rate"] == rates["low"]["bps"] == 1600
    assert states_block["comm_mode"] == rates["low"]["link_mode"] == "sband_low"
    provenance = states["comm_mode"]["initial_provenance"]
    assert provenance["basis"] == "derived" and provenance["source"] == "mission.yaml:launch_state"

    # The members that name a rate are the ones a profile carries; `vhf` and `none` are not.
    profile_members = {p["link_mode"] for p in rates.values()}
    vocabulary = set(
        re.findall(r"enum\[([^\]]*)\]", states["comm_mode"]["unit"])[0].split(",")
    )
    assert profile_members == {"sband_high", "sband_low"}
    assert profile_members < vocabulary, sorted(vocabulary)

    def refusal(name: str, path: tuple[str, ...], old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        target = definition.joinpath(*path)
        text = target.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        target.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1400:]}"

    # A link mode no state's vocabulary holds.
    refusal(
        "link-mode-unknown",
        ("vehicle.yaml",),
        "      link_mode: sband_high\n",
        "      link_mode: sband_wide\n",
        "which is no state's vocabulary",
    )
    # A correspondence to a machine that does not exist.
    refusal(
        "rate-state-unknown",
        ("vehicle.yaml",),
        "      rate_state: telemetry_rate\n      provenance:\n        basis: apollo\n        ref: \"apollo_diode.md:7, :165\"\n    - id: high",
        "      rate_state: telemetry_baud\n      provenance:\n        basis: apollo\n        ref: \"apollo_diode.md:7, :165\"\n    - id: high",
        "which is not a state",
    )
    # **The join itself**: the link mode and the rate, disagreeing.
    refusal(
        "the-two-disagree",
        ("mission.yaml",),
        "    comm_mode: sband_low\n",
        "    comm_mode: sband_high\n",
        "so the two positions cannot disagree",
    )
    # A rate that is not one of the declared profiles.
    refusal(
        "rate-not-a-profile",
        ("mission.yaml",),
        "    telemetry_rate: 1600\n",
        "    telemetry_rate: 3200\n",
        "which is no telemetry profile's `bps`",
    )
    # And the owed half: a profile that names no link mode is a debt rather than a refusal, because
    # the correspondence is something somebody has to declare and it is counted like any other.
    definition = copy_definition(fixture_dir(tmp_path, "no-link-mode"))
    path = definition / "vehicle.yaml"
    text = path.read_text()
    assert "      link_mode: sband_low\n" in text
    path.write_text(text.replace("      link_mode: sband_low\n", "", 1))
    out = run_linter(definition).stdout
    assert "declares a telemetry profile and no `link_mode`" in out, out[-1400:]
    assert "(low)" in out, out[-1400:]


def test_a_hysteresis_band_says_what_point_it_is_a_band_on(tmp_path):
    """A band with values says when a state flips. What it never said was what it was *reading*.

    `hysteresis: {assert: 26.5, clear: 27.0, dwell_ms: 500}` carries no unit and no subject, so a
    band can be read against any point at all — and `load_shed_class`'s own note claimed its values
    "are volts on bus A and are shadowed by the four bus thresholds in profiles.yaml" while the
    threshold it named cleared at **27.2 V** and the state cleared at 27.0. A bus recovering to
    27.1 V released the ladder's position while `bus_a_undervoltage` was still asserted: two
    statements about the same volts, disagreeing by 0.2 V, with a sentence asserting they agreed.

    Nothing read the sentence and nothing read the band, which is why the repair is a field and a
    check rather than better prose. `band_on` names the point, and where a threshold on that point
    declares a band of its own, the two must be the same decision — as values when the state's band
    is in the point's units, and as a **ratio** when it is not: `lcl_tripped`'s 1.25/1.05 is
    `lcl_overcurrent`'s 313 A/263 A as a fraction of the load's rating, and 1.190 is 1.190 either
    way. Declaring that band in amperes would be a second source of truth for a limit the threshold
    owns, which is why `band_units` exists rather than a conversion.

    **Two bands name no point, and the round leaves them owed.** A sensor's disagreement with its
    peers and normalized innovation squared are statistics their domains compute; neither is a
    registered point, so neither band can be read against anything — and naming a channel there
    would be a lie rather than a fix. `band_on: UNCONFIGURED` is counted by the generic unset walk
    like every other unset scalar.

    **The mistake this round made first:** it emitted its own debt for those two, so each was
    reported twice — once as "is UNCONFIGURED" by the walker and once by the new check, which is
    round 74's fault (one missing limit counted as two) rebuilt inside the round that was quoting
    it. The new check refuses a *missing* `band_on` and leaves the counting to the walker.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]

    bands: dict[str, dict] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        document = yaml.safe_load(path.read_text())
        for state in document.get("state") or []:
            band = state.get("hysteresis")
            if isinstance(band, dict) and any(
                isinstance(band.get(field), (int, float)) and not isinstance(band.get(field), bool)
                for field in ("assert", "clear")
            ):
                bands[state["id"]] = state
    # The four bands with values in them, and every one of them says what it is on.
    assert sorted(bands) == [
        "innovation_window",
        "lcl_tripped",
        "load_shed_class",
        "sensor_health",
    ], sorted(bands)
    assert {sid: state["band_on"] for sid, state in bands.items()} == {
        "load_shed_class": "power.dc_bus_a_v",
        "lcl_tripped": "power.lcl_[n]_current_a",
        "sensor_health": "UNCONFIGURED",
        "innovation_window": "UNCONFIGURED",
    }

    # The ladder's band is the top tier's own, to the volt — and it is the *threshold's* value the
    # state now carries, so the two cannot drift apart again.
    profiles = yaml.safe_load((VEHICLE / "domains" / "power" / "profiles.yaml").read_text())
    tiers = {t["id"]: t for t in profiles["thresholds"] if t.get("point") == "power.dc_bus_a_v"}
    assert bands["load_shed_class"]["hysteresis"]["assert"] == tiers["bus_a_undervoltage"]["assert"]
    assert bands["load_shed_class"]["hysteresis"]["clear"] == tiers["bus_a_undervoltage"]["clear"] == 27.2

    # And the fraction is the same decision as the amperes, which is what can be compared across
    # units: the ratio.
    overcurrent = next(t for t in profiles["thresholds"] if t["id"] == "lcl_overcurrent")
    band = bands["lcl_tripped"]["hysteresis"]
    assert band["assert"] / band["clear"] == pytest.approx(
        overcurrent["assert"] / overcurrent["clear"], rel=0.01
    )

    # Each of the two owed bands is reported once rather than twice, which is the round's own first
    # mistake: the walker already counts an `UNCONFIGURED` scalar.
    view = subprocess.run(
        [sys.executable, str(LINTER), "--dir", str(VEHICLE), "--debts"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    assert view.count("band_on") == 2, view

    def refusal(name: str, path: tuple[str, ...], old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        target = definition.joinpath(*path)
        text = target.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        target.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1200:]}"

    # A band reading a point it does not name.
    refusal(
        "no-band-on",
        ("domains", "power", "components.yaml"),
        "    band_on: power.dc_bus_a_v\n",
        "",
        "and no `band_on`",
    )
    # A band on a point that does not exist.
    refusal(
        "unregistered",
        ("domains", "power", "components.yaml"),
        "    band_on: power.dc_bus_a_v\n",
        "    band_on: power.dc_bus_c_v\n",
        "which is not a registered point",
    )
    # And the disagreement the round found: the state's clear 0.2 V below the threshold's own.
    refusal(
        "clear-disagrees",
        ("domains", "power", "components.yaml"),
        "hysteresis: {assert: 26.5, clear: 27.2, dwell_ms: 500}",
        "hysteresis: {assert: 26.5, clear: 27.0, dwell_ms: 500}",
        "Two statements about the same quantity in the same units on the same point have to agree",
    )
    # A band claiming other units while dividing differently from the band it names.
    refusal(
        "ratio-disagrees",
        ("domains", "power", "components.yaml"),
        "hysteresis: {assert: 1.25, clear: 1.05, dwell_ms: 500}",
        "hysteresis: {assert: 1.25, clear: 1.02, dwell_ms: 500}",
        "is not the ratio of any band declared there",
    )


def test_a_hysteresis_band_says_what_it_makes_the_state(tmp_path):
    """A band says when a state flips, and round 77 made it say what it reads. Nothing said what it
    *becomes*.

    `becomes:` already existed for the other two ways a state moves — a `command_value` entry maps a
    command's argument into the state's own vocabulary, and round 75's `event_value` does the same
    for an event — and the band, which is the third, had no equivalent. The gap is not cosmetic.
    A `hysteresis` block carries exactly two boundaries, so a comparator has exactly two outcomes,
    and these four states declare three to five members: **§5's latch rule has no output to write**,
    which is why round 77's `band_on` was necessary and not sufficient.

    **The sharp case is the state round 77 was written about.** `load_shed_class` reports the
    ladder's position in `enum[none,P3,P2,P1,P0]` and bands only `bus_a_undervoltage` — and by the
    rung map `coupling.yaml#open_debts` already records, that tier selects `none`, which is what the
    threshold's own provenance says when it calls it a tier that *"does not shed load"*. So both
    outcomes of the one band this state declares are the same member: the band cannot move the state
    at all. Its `band_value` is `UNCONFIGURED` rather than a guess, and the note says why.

    The other three are filled from their own notes and sources. `lcl_tripped`'s reclose-then-latch
    is `tripped` at the assert and `closed` at the clear; `sensor_health`'s note supplies "three
    consecutive implausible samples to condemn, one plausible sample to forgive"; and
    `innovation_window`'s supplies "two of the last m … reach `suspect`, one sample back under it
    clears". Each of the three has at least one member its band cannot produce — `retrying` and
    `latched` are the reclose lifecycle rather than boundaries, and `suspect` and `fault` are the
    ones nothing bounds — and those are **one decision recorded in `coupling.yaml#open_debts`**
    rather than three guesses in three fields, which is the same choice round 75 made when it named
    the effect instead of inventing one.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]

    bands: dict[str, dict] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        document = yaml.safe_load(path.read_text())
        for state in document.get("state") or []:
            band = state.get("hysteresis")
            if isinstance(band, dict) and all(
                isinstance(band.get(field), (int, float)) and not isinstance(band.get(field), bool)
                for field in ("assert", "clear")
            ):
                bands[state["id"]] = state
    assert sorted(bands) == [
        "innovation_window",
        "lcl_tripped",
        "load_shed_class",
        "sensor_health",
    ], sorted(bands)

    # Every band with values says what it makes the state — and the one that cannot is the one whose
    # own band selects a single member whichever way it crosses.
    assert {sid: state.get("band_value") for sid, state in bands.items()} == {
        "lcl_tripped": {"assert": "tripped", "clear": "closed"},
        "sensor_health": {"assert": "fault", "clear": "good"},
        "innovation_window": {"assert": "suspect", "clear": "good"},
        "load_shed_class": "UNCONFIGURED",
    }

    # And every member a band names is one the state's own `unit` can hold — the join round 67 made
    # for a commanded position, applied to a transition.
    for sid, state in bands.items():
        declared = state["band_value"]
        if declared == "UNCONFIGURED":
            continue
        assert set(declared) == {"assert", "clear"}, sid
        vocabulary = set(re.findall(r"enum\[([^\]]*)\]", state["unit"])[0].split(","))
        assert set(declared.values()) <= vocabulary, sid

    # The band that cannot make its own state says so where a reader looks for it: the rung map is
    # the same decision as the missing P1 rung, so it is recorded once rather than counted twice.
    view = subprocess.run(
        [sys.executable, str(LINTER), "--dir", str(VEHICLE), "--debts"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    # The exact path rather than a count of the field's name, because the round's own `open_debts`
    # sentence mentions `band_value` too — and a test satisfied by a prose paragraph would pass on a
    # corpus that had stopped declaring the field at all.
    assert view.count("domains/power/components.yaml.state[11].band_value: is UNCONFIGURED") == 1, view

    def refusal(name: str, path: tuple[str, ...], old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        target = definition.joinpath(*path)
        text = target.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        target.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1200:]}"

    # A band that makes the state nothing at all.
    refusal(
        "no-band-value",
        ("domains", "power", "components.yaml"),
        "    band_value: {assert: tripped, clear: closed}\n",
        "",
        "and no `band_value`",
    )
    # A member the state's own vocabulary cannot hold.
    refusal(
        "member-outside-unit",
        ("domains", "avionics", "components.yaml"),
        "    band_value: {assert: fault, clear: good}\n",
        "    band_value: {assert: condemned, clear: good}\n",
        "cannot hold — the vocabulary is",
    )
    # One boundary named and the other missing: a crossing with no outcome.
    refusal(
        "one-boundary",
        ("domains", "avionics", "components.yaml"),
        "    band_value: {assert: fault, clear: good}\n",
        "    band_value: {assert: fault}\n",
        "a band has exactly the two boundaries",
    )
    # An outcome declared where no band flips, so nothing can read it. `deadband_latch`'s band is
    # entirely owed, which is exactly the state a `band_value` must not be written on speculatively.
    refusal(
        "outcome-without-band",
        ("domains", "rcs", "components.yaml"),
        "    unit: bool\n",
        "    unit: bool\n    band_value: {assert: firing, clear: quiet}\n",
        "carries no band with values in it",
    )


def _delay_ring_advanced_once(plant, world, state, before, after, quiet):
    """A transport delay's ring after one tick, held to its structure and to its own driver.

    The ring's *shape* — depth, cursor, how many slots have been written — must match a quiet
    tick's, because a delay advances once per tick however the queue cut it. The value written is
    the driver's end-of-tick level in *this* run, not the quiet run's: comparing slot values with a
    quiet tick holds only while the driver is constant across the tick, which today it is only
    because `E-PUMP-COOL`'s sensitivity is owed — an oracle that would fail the day an unrelated
    thermal debt is paid (independent review of the round that introduced it).
    """
    ring = f"{state.id}__delay"
    got, calm = after[ring], quiet[ring]
    assert len(got["slots"]) == len(calm["slots"]), (len(got["slots"]), len(calm["slots"]))
    assert got["next"] == calm["next"], (got["next"], calm["next"])
    assert sum(s is not None for s in got["slots"]) == sum(s is not None for s in calm["slots"])
    written = int((before.get(ring) or {}).get("next") or 0)
    edge = plant.canonical_contributors([e for e in world.edges if e.target == state.node])[0]
    assert got["slots"][written] == float(plant.edge_driver(world, edge, after)), written


def test_a_sub_tick_effect_lands_where_a_short_tick_would_have_put_it(tmp_path):
    """§9's step 3 was one line, `horizon = min(dt, events.time_to_next())`, and the queue was absent.

    The plant excused it in prose: *"Step 3's event queue needs latched states, so it is a no-op
    until there are any."* There were seventeen by the time that sentence was read against the
    corpus — the fourteen commanded modes and the three the one-way events move — so `horizon = dt`
    was a no-op whose stated reason had lapsed, the same shape as round 67's exemption, round 70's
    `state_order` guard and round 72's `drains` guard.

    Two things are asserted here, and the first is the one that would catch a queue that merely
    *looks* right. **A split tick is the same arithmetic as consecutive short ticks**: the queue's
    sub-interval is passed to `advance`, which already takes a horizon, so no integrator changed —
    and the identity is checked against the whole committed map rather than against a value, which
    is how it found that computing the last sub-interval as `0.02 - 0.015` gives
    `0.005000000000000001` and moves four stock residual accumulators. Both halves have to be in
    integer microseconds, or half the arithmetic puts back the ambiguity §5 took out.

    **And the stamps decide, not the list.** §5's whole argument is that two events landing in one
    tick on one latched machine are ordered by their delays rather than by a tie-break — "that is a
    tie-break masquerading as physics, and the fix is timestamps, not a smaller `dt`". The triple
    below is the corpus's own: `configuration` has `event_value` for all three of
    `lm_undocking` → `undocked`, `descent_stage_separation` → `separated` and
    `lm_ascent_jettison` → `abandoned`, so the value it ends on is *whichever event is stamped
    last* — and scrambling the list order must not change that.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    values = plant.initial_values(world)
    dt = plant.tick_seconds(world)
    assert values["configuration"] == "docked"

    def event(name: str, at_us: int) -> plant.Effect:
        return plant.Effect(offset_us=at_us, verb="execute_event", arguments={"event": name})

    undock, separate, jettison = (
        event("lm_undocking", 5_000),
        event("descent_stage_separation", 10_000),
        event("lm_ascent_jettison", 15_000),
    )

    # An empty queue is the tick the plant always ran: byte-identical, and the same gaps.
    plain, empty = [], []
    assert plant.step(world, values, dt, plain) == plant.step(world, values, dt, empty, effects=[])
    assert [g.where for g in plain] == [g.where for g in empty]

    # The stamps decide. The list is scrambled on purpose and the answer follows the microseconds.
    assert plant.step(world, values, dt, None, effects=[separate, jettison, undock])[
        "configuration"
    ] == "abandoned"
    swapped = [
        event("lm_ascent_jettison", 5_000),
        event("lm_undocking", 15_000),
    ]
    assert plant.step(world, values, dt, None, effects=swapped)["configuration"] == "undocked"

    # And the split tick is the same run as four short ticks with the effects between them. The
    # horizons are 5 ms, 5 ms, 5 ms and the remainder, in both — for every state that integrates
    # over a horizon. **Not for a transport delay**, and this identity hid that: a delay is a ring
    # with one slot per *tick* (`plant.md` §3), so four 5 ms ticks and a split tick both built a
    # 208,400-slot ring for a 52,100-tick pipe and advanced it four times, and compared equal by
    # being wrong the same way. The delay is held to the plain tick instead — one advance per tick
    # however the queue cut it — and the rest of the map to the short ticks.
    split = plant.step(world, values, dt, None, effects=[separate, jettison, undock])
    manual = plant.step(world, values, 0.005)
    for effect in (undock, separate, jettison):
        manual = plant._merged(
            manual, plant.apply_command(world, manual, effect.verb, effect.arguments)
        )
        manual = plant.step(world, manual, 0.005)
    delayed = {
        key
        for state in world.states
        if state.method == "delay"
        for key in (state.id, state.node, f"{state.id}__delay")
    }
    assert delayed, "the fixture no longer has a transport delay to hold"
    assert {k: v for k, v in split.items() if k not in delayed} == {
        k: v for k, v in manual.items() if k not in delayed
    }, [
        (key, split.get(key), manual.get(key)) for key in (set(split) | set(manual)) - delayed
        if split.get(key) != manual.get(key)
    ][:6]
    quiet = plant.step(world, values, dt)
    for state in world.states:
        if state.method == "delay":
            _delay_ring_advanced_once(plant, world, state, values, split, quiet)

    # §5's two refusals, and both are refused rather than corrected: a stamp outside the tick would
    # otherwise be clamped into a merge, and a verb that stages nothing would look like an effect
    # that landed.
    for bad, needle in (
        (event("lm_undocking", 20_000), "outside the tick"),
        (event("lm_undocking", -1), "outside the tick"),
        (plant.Effect(offset_us=1.5, verb="execute_event", arguments={}), "not an integer number"),
        (plant.Effect(offset_us=1_000, verb="no_such_verb", arguments={}), "not registered"),
        # A real verb, and one of the thirty-seven that stage nothing: `ack_alarm` is a read of the
        # alert state, and an effect that "lands" at a microsecond while writing nothing is the one
        # failure a caller cannot see, because the value map comes back looking like a quiet tick.
        (plant.Effect(offset_us=1_000, verb="ack_alarm", arguments={}), "stages no state"),
    ):
        with pytest.raises(plant.EffectRefused) as refused:
            plant.step(world, values, dt, None, effects=[bad])
        assert needle in str(refused.value), str(refused.value)

    # The tick is 20,000 µs, which is why 20,000 is out of range and 19,999 is not: §5's stamps are
    # integers *inside* one tick, and the last microsecond of the tick is the last one it has.
    assert plant._tick_us(dt) == 20_000
    assert plant.step(world, values, dt, None, effects=[event("lm_undocking", 19_999)])[
        "configuration"
    ] == "undocked"


def test_a_command_inside_a_tick_is_walked_as_one_tick_not_as_several():
    """The sub-tick queue cut a tick into segments, and two parts of the walk took each for a tick.

    `step(effects=...)` had one caller until an executive needed it — the identity test above, whose
    four 5 ms ticks went wrong in the same way as the split tick and so compared equal. Driving one
    real command through it found three symptoms of the one defect:

    - **A transport delay advanced once per segment.** The ring is indexed by tick (`plant.md` §3)
      and `advance` sizes it as `delay_s / dt`; given a 10 ms segment, the coolant transport built a
      104,200-slot ring for its 52,100-tick pipe and stepped it twice, so one command halved the
      transit time for the rest of the run and doubled the state every compare-point hashes.
    - **An effect at the tick's first microsecond crashed the tick.** `offset_us = 0` is inside
      `[0, tick_us)` and `_stamped` accepts it, and the zero-length walk before it divided the
      delay's length by zero. Two effects stamped at one microsecond did the same between them.
    - **Every gap was reported once per segment**, so a tick with three commands owed three times
      what a quiet tick owes, which reads as the configuration getting worse.

    The expected values are the quiet tick's, which no effect touches: the ring, its cursor and the
    gap list. `set_rcs_mode` is used because it stages one state and has no interlock to evaluate.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    values = plant.initial_values(world)
    dt = plant.tick_seconds(world)
    delays = [state for state in world.states if state.method == "delay"]
    assert delays, "the fixture no longer has a transport delay to hold"

    quiet_gaps: list = []
    quiet = plant.step(world, values, dt, quiet_gaps)

    def mode(at_us: int, value: str = "free_drift") -> plant.Effect:
        return plant.Effect(offset_us=at_us, verb="set_rcs_mode", arguments={"mode": value})

    for effects in (
        [mode(10_000)],
        [mode(0)],
        [mode(5_000), mode(5_000, "manual"), mode(15_000)],
    ):
        gaps: list = []
        stepped = plant.step(world, values, dt, gaps, effects=effects)
        for state in delays:
            _delay_ring_advanced_once(plant, world, state, values, stepped, quiet)
        assert [(g.state.id, g.where) for g in gaps] == [
            (g.state.id, g.where) for g in quiet_gaps
        ], (effects, len(gaps), len(quiet_gaps))
        assert stepped["mode"] == "free_drift", effects


def test_the_tick_is_a_whole_number_of_microseconds(tmp_path):
    """§5's stamps are integers, and nothing asked whether a tick **has** an integer number of them.

    `tick_hz` was held against `total_ticks` (round 45) and against the estimator's sub-stepping
    rates (round 35), and both of those are statements about how many ticks there are. The queue
    needs a different one: a stamp is an integer count of microseconds *within* a tick, so a tick
    that is not a whole number of microseconds has no grid to place one on.

    At 50 Hz it does — 20,000 µs exactly — which is why the corpus has been able to assume it. At
    60 Hz it does not, and the failure is silent in the way §5 names: the plant rounds the tick, so
    a stamp meant for the tick's last microsecond lands on the next tick's first and the tie-break
    between two events is decided by a float. `gnc/estimator#sub_stepping` already cites "the
    plant's integer-microsecond event queue" as what its major cycle is a sub-step inside, so this
    is a join between two declarations rather than a preference.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]

    for hertz, needle in (
        ("60", "not a whole number of microseconds"),
        ("2000000", "contains no whole microsecond at all"),
    ):
        definition = copy_definition(fixture_dir(tmp_path, f"tick-{hertz}"))
        path = definition / "mission.yaml"
        text = path.read_text()
        path.write_text(
            re.sub(r"^tick_hz:.*$", f"tick_hz: {hertz}", text, count=1, flags=re.M)
        )
        out = run_linter(definition)
        assert out.returncode == 1, out.stdout[-900:]
        assert needle in out.stdout, out.stdout[-900:]


def test_a_read_is_held_to_the_node_that_drives_the_flux(tmp_path):
    """`reads:` was held to the source node, and for a discharge the source is the end nobody reads.

    `stock_flux` has taken a `driver_node` since round 57, and the stock branch passes `edge.target`
    for a **discharge**: a tank empties at the rate its consumer sets, so the target is what the flux
    multiplies. Round 71's `reads:` rule asked the source every time — so the crowded-source debt
    fired on `E-CABIN-CO2-REMOVAL`'s five-state cabin, which that edge does not read, and the
    correction the round applied overrode a correct driver with a wrong one: `reads:
    csm_cabin_co2_kg` made the flux the cabin's own mass (8.47e-04 kg per tick) instead of the
    removal rate (6.32e-07), a **1,340-fold** overstatement and a decay that would empty the cabin in
    fifty ticks.

    **It was latent, which is why it took a round to find.** The cabin's CO2 stock is refused for
    another reason first, so nothing computed the flux — a wrong declaration survives exactly as long
    as nothing reads it, and the check that would have read it was asking the wrong end. The rule is
    the driving node's now, and round 72 removed the two declarations and declared the one the fix
    surfaced: `E-WATER-RAD`, whose target `radiator_reject` carries two states and whose unit is
    `kg/s per W`.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]

    def refusal(name: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / "coupling.yaml"
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1200:]}"

    # A discharge's name must be on the *target*, and this is the exact declaration round 71 made.
    refusal(
        "reads-the-source-of-a-discharge",
        "  - id: E-CABIN-CO2-REMOVAL\n",
        "  - id: E-CABIN-CO2-REMOVAL\n    reads: csm_cabin_co2_kg\n",
        "which is not a state on `co2_removal_csm`, the node whose value this flux multiplies",
    )
    # And a name on the wrong state of the right node is *not* refused here: which quantity an edge
    # wants is the edge's business, and the tick's own classifier is what refuses a mismatch. The
    # boundary is asserted so the two rules are not confused for one another.
    swapped = copy_definition(fixture_dir(tmp_path, "reads-wrong-state"))
    path = swapped / "coupling.yaml"
    path.write_text(
        path.read_text().replace("    reads: radiator_rejection_w\n", "    reads: zone_radiator_t\n", 1)
    )
    assert run_linter(swapped).returncode == 0

    # The value the declaration is about, read off the real plant.
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    values = plant.initial_values(world)
    edge = next(e for e in world.edges if e.id == "E-CABIN-CO2-REMOVAL")
    assert edge.reads is None
    driver = plant.edge_driver(world, edge, values, edge.target)
    assert driver == pytest.approx(values["co2_removal_csm_kg_s"]), driver
    assert plant.stock_flux(world, edge, values, plant.tick_seconds(world), driver_node=edge.target) == (
        pytest.approx(driver * plant.tick_seconds(world))
    )


def test_a_ratio_refusal_names_the_flow_that_would_fix_it():
    """A refusal that names the missing node is worth more than one that describes the symptom.

    Round 50 established that a dimensionless ratio into a stock is not a flux. That is true and it
    is not actionable: five edges were refused with the same sentence and none of them said what to
    build. The test a ratio actually needs is not "is this a ratio" but **"does the graph carry the
    flow the ratio is against"** — `1.0 kg water per kg reactants` applied to a node holding
    `kg reactants per second` is water per second, which is a flux.

    Nothing in the vehicle carries one, so the refusals stand — and each now names the flow, so the
    five edges resolve into a specification rather than a diagnosis: four consumer intakes, because
    `E-O2-FC` and `E-O2-ECLSS` both draw from `o2_csm` while being the cell's draw and the cabin's
    supply respectively.
    """
    if str(VEHICLE / "tools") not in sys.path:
        sys.path.insert(0, str(VEHICLE / "tools"))
    from check_vehicle import stock_flux_basis

    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    nodes = coupling["nodes"]
    stock_nodes = {k for k, v in nodes.items() if v.get("kind") == "stock"}
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1500:]

    # The class is empty as of round 60, and that is the property worth holding now. Every ratio
    # that used to be refused — `E-O2-FC`, `E-H2-FC`, `E-FC-WATER`, `E-O2-ECLSS`, `E-LM-O2-ECLSS` —
    # has a flow node carrying its denominator, and each refusal named the node that would fix it,
    # which is how five vague debts became one build order and then no debts at all.
    refused_ratios = [
        e["id"]
        for e in coupling["edges"]
        if (e["from"] in stock_nodes or e["to"] in stock_nodes)
        and (e.get("sensitivity") or {}).get("value") not in (None, "UNCONFIGURED")
        and stock_flux_basis(e, nodes)[0] is None
        and "dimensionless ratio" in stock_flux_basis(e, nodes)[1]
    ]
    assert refused_ratios == [], f"a ratio is refused again: {refused_ratios}"

    # And the rule is not simply refusing ratios: one whose denominator *is* carried is computable.
    synthetic = {
        "id": "E-TEST",
        "kind": "rate",
        "from": "tank",
        "to": "sink",
        "sensitivity": {"value": 1.0, "unit": "kg water per kg reactants"},
    }
    world = {
        "tank": {"kind": "stock", "unit": "kg"},
        "driver": {"kind": "flow", "unit": "kg reactants/s"},
        "sink": {"kind": "stock", "unit": "kg"},
    }
    synthetic["from"] = "driver"
    basis, reason = stock_flux_basis(synthetic, world)
    assert basis == "per_second", reason


def test_the_build_order_is_derived_and_partitions_the_vehicle():
    """The folder's answer to "what do I implement first" has to be computed, not authored.

    An authored worklist drifts the moment anybody lands anything, and a stale build order is worse
    than none because it sends the next reader to work that is already done. So `plant.py
    --build-order` classifies every state by `advance()`'s own refusal order — the same sequence of
    tests the plant runs when it gets there — which means the two cannot disagree.

    The shape it reports is the honest one: **half the vehicle owes a rule**, and that is by
    construction, because `plant.md` §3's `algebraic`, `discrete`, `dynamics` and `hazard` classes
    are domain code the configuration deliberately does not carry. The build order is therefore not
    a list of missing numbers; it is mostly a list of missing *code*.
    """
    plant = _plant()
    world = plant.load_world(VEHICLE)
    buckets = plant.build_order(world)

    # A partition, not an approximation: every state is in exactly one bucket. A classifier written
    # as a sequence of skips finds its way past exactly the inputs nobody anticipated, which is the
    # failure this project has already met once in `conserved_dimension`.
    seen = [state.id for rows in buckets.values() for state in rows]
    assert len(seen) == len(set(seen)), "a state is classified twice"
    assert set(seen) == {s.id for s in world.states}, "a state is classified by nothing"
    # 134 -> 135 in round 32, with the oxygen supply tank's pressure state: the channel that
    # publishes it had a mass for a source, and the vehicle had no tank to read.
    # 135 -> 136 in round 40, with the avionics bay's heat rate: the one heated zone whose 360 W no
    # state carried, and the ingredient the loop's collected load was missing.
    # 136 -> 138 in round 41, with the two loops' collected loads: the sums that ingredient fed.
    assert sum(len(rows) for rows in buckets.values()) == 139

    # `ready` means what it says: only the classes the reference plant can actually advance.
    # It is no longer only the plant's two integrators — round 20 taught it to evaluate an
    # `algebraic` state's declared `derivation`, so a relation the corpus already states is ready,
    # and round 49 taught it the **`delay`** ring, so a state whose rule is a `delay_s` is ready too.
    # The sentence the bucket prints changed with the first of those: "the two classes" became "the
    # classes". `dynamics` is in it now, for the one state whose shape is a scalar accumulator;
    # the 6-DOF half of that class is what is left. **And `discrete` joined it**, which is the
    # class this list was most confident about: a mode's rule *is* code — the ladder position, the
    # FDIR conclusion, the allocation verdict — except where the movers are commands, and there the
    # code is the effect path's and the tick's whole rule is the hold. The class is not the
    # question; the movers are, and the set below is checked against what a tick did.
    assert {s.method for s in buckets["ready"]} <= {
        "lag",
        "stock",
        "algebraic",
        "delay",
        "dynamics",
        "discrete",
    }
    # And a state that owes a rule is never also counted as ready.
    assert not ({s.id for s in buckets["rule"]} & {s.id for s in buckets["ready"]})

    # The counts are the vehicle's current shape, and a change here is a change in the build order
    # rather than a cosmetic difference — which is exactly what makes it worth asserting.
    #
    # `ready` fell 13 -> 11 when the ten stocks with no declared initial condition were marked
    # owed. That is the classification working: an integrator with no level to integrate from
    # cannot be advanced, so it is blocked by a *value* rather than counted as ready. It had
    # been counted as ready because the integrator never read a level, which is the defect the
    # round found — the build order was reporting a state as advanceable that could only have
    # produced a wrong number.
    # And `ready` went 16 -> 18 when the two cabins' six gas stocks took their initials: those six
    # were `stock` states whose level was owed, so they were blocked by a value the round found, and
    # four of the twenty-four states that closed a value debt are now blocked by an edge instead.
    # 18 -> 14 in round 18 (four lags with dimensionally-wrong drivers), 14 -> 23 in round 20: the
    # plant now evaluates an `algebraic` state's declared `derivation`, so thirteen relations the
    # corpus already states are ready rather than owing code.
    # 23 -> 27 in round 22: the value space is keyed by state, so the states on a shared node that
    # the map could not hold are advanceable.
    # 27 -> 28 in round 40: `avionics_bay_heat_w` is the fifth heat rate and the first state on the
    # `internal` sentinel whose rule the corpus *declares* — a `derivation` over three dotted paths
    # that the plant evaluates in a real tick. The sentinel routing ran before the arithmetic test,
    # so the one rule that asks "is the rule already in the configuration?" was unreachable for
    # every state on the sentinel, and this one was filed as owing domain code that exists.
    # 28 -> 30 in round 41: `loop_primary_load_w` and `loop_lm_load_w`, the same declared-arithmetic
    # shape one level up — the classifier fix is what lets them be counted ready rather than as
    # owing code.
    # 33 -> 35 in round 47: the two cabins' pressures are arithmetic now, held by a gas law
    # over the four gas stocks and the zone's temperature *as a reading* — the first derivations
    # in the corpus that read another state's value this tick, and the first whose `computes`
    # field is the state's own id rather than a parameter of it.
    # 35 -> 39 in round 52 and 39 -> 42 in rounds 53-56: the `dynamics` scalar shape, the scenario
    # and the window's own states. **42 -> 38 in round 57**, and both halves of that move are the
    # same defect seen from two sides: a tank scheduled before the node whose rate drains it had no
    # value on the first tick (`h2_csm_kg`, `o2_csm_kg`, `o2_lm_kg` — the plant resolves declared
    # arithmetic at t=0 now, so they are ready *and* advanced), and four states whose discharge
    # reads a node that publishes no value under its own name are couplings rather than values
    # (`water_cooling_kg` through `radiator_reject`, and the three cabin-gas stocks that read
    # `crew_state`).
    # **38 -> 36 in round 58, and the move is the bucket's meaning rather than a state.** The first
    # line of this report is now the set a real tick advances — `build_order` runs one tick at t=0
    # and files its gaps by their roots — so `coolant_flow_kg_s` and `prop_rcs_kg`, whose own
    # declarations are complete and which no tick can reach, leave it for the rule their producers
    # owe. The two figures this test used to compare (`counted_more`, `six_dof`) are now the totals
    # below, because a state a tick advances cannot be filed as owing anything.
    # 36 -> 37 when the plant learned to hold a commanded mode: `relief_valve_state` is the one
    # whose starting position the corpus could source («normally closed», `apollo_diode.md:213`),
    # so it is the one of the fourteen that reaches *ready* rather than *owes a value*.
    # 37 -> 38 in round 72: `E-WATER-RAD`'s driver was a crowded node with no name for the state it
    # reads, and naming it (`radiator_rejection_w`) made the coolant's discharge computable.
    # Post-ejection P00 and active CMC DAP give two more commanded modes a sourced initial.
    assert len(buckets["ready"]) == 52
    # `rule` went 71 -> 69 -> 82 across two rounds. The first move was `moved_by`: the two still
    # owed put an `UNCONFIGURED` in their spec and `walk_unset` counts any unset scalar as a value
    # the plant wants, so they left this bucket without the code they need going away. The second
    # was the classifier being fixed to agree with `advance()`, which moved thirteen `internal`
    # states *in* here — no edge can reach the sentinel, so their driver is domain code.
    # `rule` went 71 -> 69 -> 79 -> 82. The last move is the RCS cluster: `thruster_valve`,
    # `thruster_thrust` and `pulse_width` each named an `UNCONFIGURED` field — a dwell, two time
    # constants, a pulse floor — so the classifier sent a reader after a *number* where what the
    # state has always needed is the code that drives it. The numbers were published, on
    # `lm_propulsion_rcs_study_guide.pdf` p. 89, and landing them put the three back in the bucket
    # they belong to. The same three left `value`.
    # 84 -> 75 in round 20: the nine algebraic states whose derivation the plant now evaluates left
    # this bucket, and the four on shared nodes that the map cannot hold entered it. 75 -> 71 in
    # round 22, when the key space stopped being the reason those four were here.
    # 71 -> 68 in round 29, when the integrators' starting values became declarations: three states
    # that were here only because nothing can *drive* them — `comm_amp_t`, `crew_workload` and
    # `suit_loop_flow_cfm`, all lags on the `internal` sentinel — now owe a value the classifier can
    # name, which is the cheaper and truer bucket. They are still domain code's problem in the end;
    # what changed is which debt a reader is sent after first.
    # 68 -> 69 in round 33, the other half of the value move above: the suit circuit's flow took
    # the ECS guide's published 35 cfm as its initial, so `suit_loop_flow_cfm` stopped owing a value
    # and now owes the driver that would advance it, which is domain code.
    # 68 -> 66 in round 47, the other half of the move above: the two pressures left this bucket
    # for `ready` without the rule layer's count changing anywhere else.
    # 60 -> 62 in round 58, the other half of the ready move: the two states a tick cannot reach
    # through a producer that owes code are filed under the producer's bucket, which is this one.
    # 62 -> 64 in round 63, and this one is not a recount: `crew_location` and `crew_availability`
    # were in *owes a value* because `moved_by: UNCONFIGURED` is an unset key, and what they owe is
    # the mover rule — the cheapest-to-close bucket had a state in it with no value to write.
    # 64 -> 52 in round 67, and it is the largest single move this bucket has made: twelve of the
    # fourteen commanded modes left it. What they were filed under was never code — `moved_by` named
    # the verb, `command_value` mapped its argument and `dwell` guarded the re-command — and what
    # the plant owed was the *hold* between commands. Eleven of the twelve moved to `value` because
    # the mode's starting position is owed; the twelfth is `relief_valve_state`, which reaches ready.
    # 49 -> 47 in round 77, and it is the same finding as the value bucket's move above:
    # `sensor_health` and `innovation_window` owe the *point* their hysteresis band is on, which is
    # a value, rather than the logic that would drive them, which is what this bucket was asking
    # for. A band over a statistic nobody publishes is blocked by a missing number, not by code.
    # 47 -> 46 in round 79, the third round running to make this move and for the same reason:
    # `load_shed_class` declares the band it flips on and now owes `band_value` as well, and what
    # blocks it is the ladder's rung-to-class map — a declaration the thresholds do not carry —
    # rather than the domain code this bucket was asking it for.
    assert len(buckets["rule"]) == 45, "just under a third of the vehicle is domain code"
    # Two more moved *in* when a discrete state began owing a value by field name rather than
    # owing the code that would set it: `telemetry_rate` and `bus_tie_closed`, whose
    # `command_value` mappings name profiles and a mode no source prices.
    # One more moved in with the pump: its `on` mapping is an owed rated speed, so what blocks
    # `pump_1_speed_rpm` is named to a field rather than to the code that would drive it.
    # Four more moved in when a `computed` effect began naming its input: `link_snr`, `tx_power`,
    # `instrumentation_power` and `nav_solution` are blocked by a field now rather than by the
    # rule that would compute them.
    # Six left `value` in round 8 — the two cabins' gas stocks, which took the initials the four-gas
    # model derived for them — and four of the twenty-four states that *were* blocked by an edge
    # rather than by code came in behind them, because a stock with no level had been reporting the
    # value debt first. The net move is 27 -> 21 while the debt count fell by six. 21 -> 20 in round
    # 14, when `battery_charge_j.min_flow_per_s` was derived from the smallest load on its bus: the
    # state stopped owing a value and started owing the edge behind it, which is why the *edge*
    # bucket moved the other way in the same round.
    # 20 -> 25 in round 29: the ten integrators that now declare an owed starting value entered
    # this bucket, and five of them were in `edge` or `rule` before — `comm_amp_t`, `crew_workload`,
    # `suit_loop_flow_cfm`, `zone_csm_avionics_t` and `zone_lm_descent_t`. The other five were
    # already here for another field. An `initial` the plant reads is a value it wants, and the
    # build order says so before it says "code".
    # 25 -> 26 in round 32: `o2_supply_pressure_psi` owes its time constant, which is the first
    # thing the plant asks a lag for.
    # 26 -> 25 in round 33: `suit_loop_flow_cfm` took the ECS guide's published 35 cfm as its
    # initial, so it stopped owing a value — and the bucket it moved to is `rule`, above.
    # 25 -> 28 in round 58: the bucket is a *root's* verdict now, so the states blocked behind a
    # value debt are filed here with it. `--readiness` still counts the declarations: 33 states
    # carry one and 29 of them are in this bucket — the four that differ are debts a tick walks
    # past, which is the difference between a value nobody wrote down and a state nothing reaches.
    # 23 -> 34 in round 67: eleven commanded modes whose starting position no source answers. The
    # narrow bucket is where they belong — each is one field — and the count is the shopping list.
    # 30 -> 32 in round 77: the two hysteresis bands whose subject is a statistic no point carries.
    # 32 -> 33 in round 79: `load_shed_class` joins them, and for a reason one layer in — the band
    # it declares is `bus_a_undervoltage`, which by `coupling.yaml#open_debts`'s rung map selects
    # `none`, so what it owes is the rung-to-class map rather than the comparator that reads it.
    # The RCS per-thruster pulse floor became an honest owed value when the LM command time
    # stopped being applied globally, moving one state here from the rule bucket.
    assert len(buckets["value"]) == 27
    # Two of the twenty-eight "owed an edge" were not owed one at all: the three preloaded tanks
    # are advanceable, and the thirteen `internal` states need code. Three more left the bucket
    # when it stopped asking the integrator's question — a `regimes` table is a *declared*
    # coupling, and `instrumentation_power`, `bus_tie_closed` and `thruster_valve` each have every
    # input declared. `load_shed_class` followed its own edge into the table form.
    # 7 -> 11 in round 8, which is the other half of the value move above: four of the six states
    # that stopped owing a value owe an edge, and those edges were already counted as debts — the
    # worklist simply could not see them behind the earlier refusal. 11 -> 12 in round 14, when
    # `battery_charge_j` stopped owing its smallest flow: `E-BUS-BAT` still carries no sensitivity,
    # and that edge was a debt all along. 12 -> 16 in round 18, when four lags whose drivers are in
    # the wrong quantity stopped being counted ready.
    # 16 -> 14 in round 29, the other half of the value move above: the two zones whose driver edge
    # carries no sensitivity were being reported as an edge debt, and the starting value they also
    # owe is now named first.
    # 12 -> 16 in round 57: those four states again. A node with two states publishes no node key,
    # so a flux reading it is not late, it is unreadable — the missing declaration is *which* state
    # the edge reads, which is the coupling's, and the bucket an implementer should open is this one.
    # 16 -> 13 in round 58: three of the sixteen were blocked behind something other than an edge,
    # and the root's verdict is what files them now.
    # 16 -> 15 in round 72, the other half of the ready move: the coolant's drain stopped owing the
    # declaration that names which state on `radiator_reject` it reads.
    assert len(buckets["edge"]) == 15


def test_the_plant_advances_a_node_s_states_in_the_order_the_node_declares(tmp_path):
    """Four of the eleven multi-state nodes were running in an order nobody declared.

    `coupling.yaml#nodes.<node>.state_order` is the order the states on a node advance in, every
    multi-state node carries one with a note arguing it, `--order` prints it — and `plant.md:71`
    promises the scheduler obeys it. `step` did not: `states_on` returned the order the *files* list
    the states in, so `structure_config` computed `configuration` before the two machines it is a
    projection of, `vehicle_dynamics` integrated the orbit before the rate that determines it,
    `link` ran the link budget before the transmit power that is a term in it, and `coolant_flow`
    ran the flow before the pump speed that drives it.

    `link` is the one to look at, because `plant.md` already names it: the frozen lexicographic
    tiebreak "gets `link` wrong — `link_snr` sorts before `tx_power`, and transmit power is a term
    in the link budget". The corpus *declares* the right order and the plant was not reading the
    declaration, so this was not even the tiebreak being wrong; it was a third order, the order the
    YAML happened to be written in, deciding silently.

    Nothing was visibly wrong yet, and the reason is the finding's own shape: the states that would
    expose it are ones the plant cannot advance, so four nodes' worth of declared order had never
    been exercised. This is the reversed-schedule defect arriving one level down.
    """
    plant = _plant()
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    world = plant.load_world(VEHICLE)
    for node, declared in sorted(
        (node, (spec or {}).get("state_order"))
        for node, spec in coupling["nodes"].items()
        if isinstance((spec or {}).get("state_order"), list)
    ):
        assert [s.id for s in world.states_on(node)] == declared, (
            f"{node} advances in a different order from the one it declares"
        )
    # And the two independent nodes still get a frozen order, which is the tiebreak rather than a
    # declaration — the plant must not read "independent" as "whatever the file said".
    assert [s.id for s in world.states_on("link")] == ["tx_power", "link_snr"]
    assert [s.id for s in world.states_on("engine_main")] == sorted(
        ["aps_state", "dps_state", "sps_state"]
    )

    # The negative, in a broken copy: reverse one node's declared order and the plant follows it —
    # which is the property, not the specific sequence. A plant that read the declaration would
    # produce the reversed tuple here; one that ignored it would produce the same tuple twice.
    definition = copy_definition(fixture_dir(tmp_path, "reversed-node-order"))
    path = definition / "coupling.yaml"
    text = path.read_text()
    old = "    state_order: [body_rate, attitude, orbital_state]\n"
    assert old in text, "the fixture no longer matches vehicle_dynamics' state_order"
    path.write_text(text.replace(old, "    state_order: [orbital_state, attitude, body_rate]\n", 1))
    reversed_world = plant.load_world(definition)
    assert [s.id for s in reversed_world.states_on("vehicle_dynamics")] == [
        "orbital_state",
        "attitude",
        "body_rate",
    ]
    # And the reader is the *plant*, not just the loader: `--order` and the plant's own walk agree
    # state for state on the corpus, which is the property the promise in `plant.md:71` is about.
    linter_order = subprocess.run(
        [sys.executable, str(LINTER), "--dir", str(VEHICLE), "--order"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    walked = [s.id for s in world.states if s.node != "internal"]
    printed = [line.strip() for line in linter_order.splitlines() if line.startswith("       ")]
    assert walked == printed, (walked[:6], printed[:6])


def test_the_linter_refuses_a_derivation_that_reads_a_state_that_has_not_advanced(tmp_path):
    """A state's derivation may now read another state — and a reading has to exist when it is read.

    `derivation_value` has always bound a bare name to *that state's value this tick*; it is how a
    channel says "the live cabin temperature" instead of a literal 295 K. A *state's* derivation was
    restricted to numbers and `<file>.yaml:<dotted.path>` sources only because the caller that
    evaluates one had no tick and no order to check a reading against. Round 47 gave it both, so the
    rule that replaces the restriction is the order itself: the producer must advance first.

    Two refusals come out of it, and the second is the one this feature needs: a name that is no
    state at all, and a name whose state the schedule reaches *later* than the reader. The second is
    why the order has to be derived rather than assumed — `zone_csm_cabin_t` is legal for
    `csm_cabin_pressure_pa` because `cabin_zone_t` advances four nodes earlier, and the same reading
    written on a state on an earlier node would be last tick's temperature under this tick's name.
    """
    # The name that is no state at all, first: the older and more obvious half.
    definition = copy_definition(fixture_dir(tmp_path, "unknown-reading"))
    path = definition / "domains" / "eclss" / "components.yaml"
    text = path.read_text()
    old = "          cabin_temperature_k: zone_csm_cabin_t\n"
    assert old in text, "the fixture no longer matches the CSM pressure's temperature reading"
    path.write_text(text.replace(old, "          cabin_temperature_k: cabin_temperature\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "which is no state in this vehicle" in result.stdout, result.stdout[-900:]

    # And the reading the schedule reaches too late: the same law, on the same state, reading a
    # value that is produced by a *later* node. `co2_removal_lm` is node 56 and `cabin_atm` is 53,
    # so binding its rate here is three nodes too late by the corpus's own derived order — and the
    # state has a declared value, which is what makes this the ordering refusal rather than the
    # "nothing to check it against" one.
    late = copy_definition(fixture_dir(tmp_path, "late-reading"))
    path = late / "domains" / "eclss" / "components.yaml"
    text = path.read_text()
    path.write_text(
        text.replace(old, "          cabin_temperature_k: co2_removal_lm_kg_s\n", 1)
    )
    result = run_linter(late)
    assert result.returncode == 1
    assert "advances at or after it in the tick order" in result.stdout, result.stdout[-900:]
    assert "co2_removal_lm_kg_s" in result.stdout

    # The corpus's own two readings are legal, and the linter says so by composing.
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]


def test_the_bus_load_is_the_sum_the_inventory_already_states(tmp_path):
    """The state every electrical reader needs, where before there was only a check.

    `power.bus_a_current_a` is `load_w / voltage_v` and `power.lcl_[n]_current_a` is the load's own
    current, so the domain has needed a *state* holding the bus load since the registry was written —
    and `load_budget.csm_total_demand_w` has held the same number since the round that wrote
    `check_power_inventory`, which sums the fourteen `demand_w` fields and refuses a stated total that
    does not match. So this derivation adds no number: it is the check's sum, promoted to the state
    the solve will read, and the test holds the two together.

    **The scope is the decision the round had to make, and the graph had already made it.** Every
    electrical edge terminates on `bus_a`, the tie runs `bus_b -> bus_tie -> bus_a`, so the two buses
    are one electrical system and the current the cells supply is the whole vehicle's draw — the
    fourteen CSM loads, not the seven that name `csm_bus_a`. A bus-A-only sum would leave the pumps,
    the heaters and the lighting fed from nowhere, and `power.bus_a_current_a` would read 21 A where
    apollo publishes 10-120 A against a 40 A continuous rating.
    """
    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    loads = {row["id"]: row for row in power["loads"]}
    csm = {name: row for name, row in loads.items() if row["vehicle"] == "csm"}
    assert len(csm) == 14, sorted(csm)
    assert sum(int(row["demand_w"]) for row in csm.values()) == 1723
    assert power["load_budget"]["csm_total_demand_w"] == 1723

    state = next(s for s in power["state"] if s["id"] == "bus_a_load_w")
    provenance = state["provenance"]
    assert provenance["basis"] == "derived"
    assert provenance["computes"] == "bus_a_load_w"
    assert state["bus_a_load_w"] == 1723
    # Every CSM load is named, and every input is that load's own declared demand.
    derivation = provenance["derivation"]
    named = {str(v).rsplit(".", 2)[-2] for v in derivation["inputs"].values()}
    assert named == set(csm), sorted(set(csm) ^ named)
    for key, source in derivation["inputs"].items():
        assert source == f"domains/power/components.yaml:loads.{key}.demand_w", key

    # The plant computes it, and the number is the inventory's.
    plant = _plant()
    world = plant.load_world(VEHICLE)
    values = plant.step(world, plant.initial_values(world), 0.02, [])
    assert values["bus_a_load_w"] == 1723.0

    # And moving one load's demand, in a broken copy, is refused rather than silently summed at the
    # old total — which is what makes this a *derived* value rather than a second declaration of one.
    definition = copy_definition(fixture_dir(tmp_path, "load-moved"))
    path = definition / "domains" / "power" / "components.yaml"
    text = path.read_text()
    # `csm_heaters` is the one 300 W load, so its `demand_w` is unambiguous in the file.
    old = "    demand_w: 300\n"
    assert text.count(old) == 1
    path.write_text(text.replace(old, "    demand_w: 320\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "bus_a_load_w.provenance.derivation" in result.stdout, result.stdout[-900:]


def test_the_structural_differential_is_the_compartments_own_pressure(tmp_path):
    """One number, two readers, and a relation that had been written as a citation.

    `structure.cabin_dp_psi` declared a `ref:` to `apollo_diode.md:206` and a note saying it "is a
    read of the ECLSS compartment, expressed in the units a structural limit is stated in" — a
    relation wearing a citation's clothes, and nothing joined it to the compartment. Now it is
    arithmetic over `csm_cabin_pressure_pa`, which round 47 put a gas law behind, so the structural
    chain's input moves with the cabin's actual pressure instead of with a constant.

    The CSM's compartment is the one read, and that is a decision rather than an oversight: the
    channel carries no vehicle qualifier, the LM's differential has no channel, and `structure` does
    not declare `lm_cabin_atm` for this quantity. The separation from `eclss.cabin_pressure_psia` is
    the whole point of the state — the same number is a life-support quantity to one reader and a
    load on a vessel to another — so the test holds the two readers to one number.
    """
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    structure = yaml.safe_load((VEHICLE / "domains" / "structure" / "components.yaml").read_text())
    state = next(s for s in structure["state"] if s["id"] == "cabin_dp_psi")
    provenance = state["provenance"]
    assert provenance["basis"] == "derived"
    assert provenance["computes"] == "cabin_dp_psi"
    assert state["cabin_dp_psi"] == 5.0
    derivation = provenance["derivation"]
    assert derivation["inputs"]["pressure_pa"] == "csm_cabin_pressure_pa"
    assert derivation["inputs"]["pascals_per_psi"] == 6894.757293168361
    # The eclss channel and this state agree, which is the claim the two readers make.
    channel = None
    for row in yaml.safe_load((VEHICLE / "domains" / "eclss" / "points.yaml").read_text())["points"]:
        if row["channel"] == "eclss.cabin_pressure_psia":
            channel = row
    assert channel is not None
    assert channel["derivation"]["inputs"]["pascals_per_psi"] == derivation["inputs"]["pascals_per_psi"]
    cp = next(s for s in eclss["state"] if s["id"] == "csm_cabin_pressure_pa")
    assert cp["provenance"]["computes"] == "csm_cabin_pressure_pa"

    # The plant computes both from the one pressure, so they cannot disagree about the cabin.
    plant = _plant()
    world = plant.load_world(VEHICLE)
    values = plant.step(world, plant.initial_values(world), 0.02, [])
    psi = derivation["inputs"]["pascals_per_psi"]
    assert values["cabin_dp_psi"] == pytest.approx(values["csm_cabin_pressure_pa"] / psi, rel=1e-15)
    assert 4.8 < values["cabin_dp_psi"] < 5.2

    # And it is a reading of the reading: move the pressure in a broken copy and the differential
    # moves with it, because the derivation is not restating a literal.
    definition = copy_definition(fixture_dir(tmp_path, "pressure-moved"))
    path = definition / "domains" / "eclss" / "components.yaml"
    text = path.read_text()
    old = "    csm_cabin_pressure_pa: 34473.783836\n"
    assert old in text
    path.write_text(text.replace(old, "    csm_cabin_pressure_pa: 35000.0\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "A derived value that no longer re-derives" in result.stdout, result.stdout[-900:]


def test_the_cells_output_is_the_load_read_the_other_way(tmp_path):
    """One quantity, two directions, and the state that had said so all along.

    `fuel_cell_power_w`'s own note read "the cell's output is a function of reactant availability and
    **load**, solved to consistency each tick" — and the load became a state in round 50. So this is
    the second pair in the corpus that is one relation read in two directions (round 44's
    `radiator_rejection_w` and `loop_primary_load_w` are the first), and the direction is what a
    reader has to notice: a *load* is what is connected, a *generation* is what has to come from
    somewhere.

    **The test holds the pair against each other rather than against a number**, because the claim is
    that they cannot disagree: both are the fourteen `demand_w` fields, so a load that moves moves the
    generation with it. What it also holds is the thing a fleet would get wrong — the headroom is the
    module capacity, not the difference between these two, and a `load_margin_w` computed as
    generation-minus-load would be zero by construction.
    """
    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    loads = {row["id"]: row for row in power["loads"]}
    csm = {name: row for name, row in loads.items() if row["vehicle"] == "csm"}
    cell = next(s for s in power["state"] if s["id"] == "fuel_cell_power_w")
    bus = next(s for s in power["state"] if s["id"] == "bus_a_load_w")
    assert cell["provenance"]["basis"] == "derived"
    assert cell["provenance"]["computes"] == "fuel_cell_power_w"
    assert cell["fuel_cell_power_w"] == 1723
    # The two derivations name the same declarations, which is what makes them one quantity.
    assert set(cell["provenance"]["derivation"]["inputs"]) == set(
        bus["provenance"]["derivation"]["inputs"]
    )
    assert set(cell["provenance"]["derivation"]["inputs"]) == set(csm)
    # And the headroom is the capacity, which is what `load_margin_w`'s note says a margin means.
    modules = [c for c in power["components"] if str(c.get("id", "")).startswith("fc_")]
    assert len(modules) == 3 and sum(int(c["rated_w"]) for c in modules) == 4260
    assert cell["fuel_cell_power_w"] < sum(int(c["rated_w"]) for c in modules)

    plant = _plant()
    world = plant.load_world(VEHICLE)
    values = plant.step(world, plant.initial_values(world), 0.02, [])
    assert values["fuel_cell_power_w"] == values["bus_a_load_w"] == 1723.0

    # A load that moves moves both, because neither restates the total.
    definition = copy_definition(fixture_dir(tmp_path, "cell-load-moved"))
    path = definition / "domains" / "power" / "components.yaml"
    document = yaml.safe_load(path.read_text())
    heater = next(row for row in document["loads"] if row["id"] == "csm_heaters")
    heater["demand_w"] = 320
    path.write_text(yaml.safe_dump(document, sort_keys=False, width=100))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "fuel_cell_power_w.provenance.derivation" in result.stdout, result.stdout[-900:]
    assert "bus_a_load_w.provenance.derivation" in result.stdout, (
        "the load and the generation are one quantity, so a moved load has to refuse both"
    )


def test_the_plant_integrates_the_scalar_dynamics_state(tmp_path):
    """The sixth method class, and the one state of it the corpus can actually advance.

    `plant.md` §3's `dynamics` row is rigid-body 6-DOF — "semi-implicit/Verlet in coast, RK4 in
    burns", with the argument measured rather than preferred: forward Euler accumulates +1.06 % in
    semi-major axis over eight days, 2,000× the published 0.01 km precision. **That is not what this
    round implemented, and the difference is the finding.** Three of the four `dynamics` states are
    that family and none of them can advance — a state vector nobody supplied, an inertia tensor
    `E-RCS-DYN` owes, a process-noise model that is not declared. The fourth is a `dynamics` state
    for a different reason and the corpus says which: *"an integrated state that is not conserved,
    which is what the `dynamics` class is for: position and velocity are the same kind of thing."*

    So the rule is the **scalar** half: `dv/dt = F/m`, with the driver in newtons and the mass
    declared on the state. The test holds three things — that the state advances at all, that it
    accumulates rather than jumping (explicit Euler, so a newton held for one tick is `F·dt/m`), and
    that the state's own `mass_kg` and `E-ENG-DYN`'s derived `1/mass_kg` are the same figure, because
    a corpus that moved one without the other would integrate with two different masses.
    """
    plant = _plant()
    world = plant.load_world(VEHICLE)
    state = next(s for s in world.states if s.id == "accumulated_dv_m_s")
    assert state.method == "dynamics"
    assert state.spec["driven_by"] == "thrust_main_n"
    assert state.spec["initial"] == 0
    mass = state.spec["mass_kg"]
    assert mass == 44085

    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edge = next(e for e in coupling["edges"] if e["id"] == "E-ENG-DYN")
    assert edge["sensitivity"]["derivation"]["inputs"]["mass_kg"] == (
        "vehicle.yaml:configurations.csm_lm_docked.mass_kg"
    )
    assert edge["sensitivity"]["value"] == pytest.approx(1.0 / mass, rel=1e-4)

    # The driver advances before the sentinel, so the reading is this tick's.
    gaps: list = []
    values = plant.step(world, plant.initial_values(world), 0.02, gaps)
    assert values["accumulated_dv_m_s"] == 0.0, (
        "no engine is firing at MET 0, so the accumulator has nothing to add"
    )
    # Held thrust, one tick: F·dt/m, which is what explicit Euler means and what a jump would not do.
    # **The division is the state's `mass_kg` and never the edge's transfer.** A named driver has no
    # edge sensitivity to read, which is the case the branch falls to `transfer = 1.0` for — and the
    # first version of this branch left the `1/mass_kg` in place from the edge path, so a newton held
    # for one tick accumulated 0.02 m/s and the assertion below caught it. The mass the state
    # declares is the mass the integration divides by; `E-ENG-DYN`'s derived sensitivity is a
    # *separate* declaration of the same ratio, held against it here rather than applied twice.
    held = {"thrust_main_n": 44500.0, "accumulated_dv_m_s": 0.0}
    tick = plant.advance(world, state, held, 0.02)
    assert tick["accumulated_dv_m_s"] == pytest.approx(44500.0 * 0.02 / mass, rel=1e-9)
    # And it accumulates rather than replacing.
    tick2 = plant.advance(world, state, {**held, "accumulated_dv_m_s": 1.0}, 0.02)
    assert tick2["accumulated_dv_m_s"] == pytest.approx(1.0 + 44500.0 * 0.02 / mass, rel=1e-9)

    # The two refusals of the shape: no mass, and a driver that is not a force.
    definition = copy_definition(fixture_dir(tmp_path, "dv-no-mass"))
    path = definition / "domains" / "propulsion" / "components.yaml"
    document = yaml.safe_load(path.read_text())
    dv = next(s for s in document["state"] if s["id"] == "accumulated_dv_m_s")
    del dv["mass_kg"]
    path.write_text(yaml.safe_dump(document, sort_keys=False, width=100))
    gaps = []
    plant.step(plant.load_world(definition), plant.initial_values(plant.load_world(definition)), 0.02, gaps)
    owed = {g.state.id: str(g.owed) for g in gaps}
    assert "mass_kg" in owed["accumulated_dv_m_s"] or "mass" in owed["accumulated_dv_m_s"], owed[
        "accumulated_dv_m_s"
    ]

    # And the worklist counts it ready, because the rule is in the configuration.
    assert "accumulated_dv_m_s" in {s.id for s in plant.build_order(world)["ready"]}


def test_the_two_cabins_compute_their_pressure_by_one_law():
    """Two compartments, one relation, and nothing in the corpus held them together.

    The LM's pressure entry used to be a sentence — "as the CSM compartment, over the LM's own
    volume" — and a sentence is not a link: nothing compared the two, so nothing would have noticed
    the LM's law reading the CSM's molar masses, or its volume, or its gases. Both are arithmetic
    now, and this holds the halves that have to match and the one that must not.
    """
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    states = {state["id"]: state for state in eclss["state"]}
    csm = states["csm_cabin_pressure_pa"]["provenance"]["derivation"]
    lm = states["lm_cabin_pressure_pa"]["provenance"]["derivation"]
    # The law is one expression, character for character.
    assert csm["expression"] == lm["expression"]
    # The constants and the molar masses are the shared declarations; only the gases, the volume and
    # the temperature are the compartment's own.
    shared = {
        "o2_molar",
        "n2_molar",
        "co2_molar",
        "h2o_molar",
        "gas_constant",
    }
    for key in shared:
        assert csm["inputs"][key] == lm["inputs"][key], key
        if key == "gas_constant":
            assert isinstance(csm["inputs"][key], float)
        else:
            assert csm["inputs"][key].startswith("domains/eclss/components.yaml:"), key
    assert csm["inputs"]["cabin_volume_m3"].endswith("volume_m3.csm")
    assert lm["inputs"]["cabin_volume_m3"].endswith("volume_m3.lm")
    # And the reading each one binds is its own compartment's zone — the half a copy-paste breaks.
    assert csm["inputs"]["cabin_temperature_k"] == "zone_csm_cabin_t"
    assert lm["inputs"]["cabin_temperature_k"] == "zone_lm_cabin_t"
    for key in ("o2_mass", "n2_mass", "co2_mass", "h2o_mass"):
        assert csm["inputs"][key].startswith("csm_"), key
        assert lm["inputs"][key].startswith("lm_"), key
    # And both compute something inside the channel's own 4.8-5.2 psia band, which is the claim the
    # two numbers make about the cabins rather than about the arithmetic.
    psi = 6894.757293168361
    for state_id in ("csm_cabin_pressure_pa", "lm_cabin_pressure_pa"):
        declared = states[state_id][state_id]
        assert 4.8 < declared / psi < 5.2, (state_id, declared / psi)


def test_the_lag_integrator_applies_the_conversion_its_edge_declares():
    """Four edges declared a conversion and the integrator applied neither the unit nor the value.

    `lag_driver_basis` required a driver edge to be an *identity* transfer — the state's quantity,
    one for one, scale 1 — because the plant read `values[source]` and relaxed toward it untouched.
    That rule refused four edges that are not identity transfers and are not wrong: `E-BUS-PUMP` is
    the pump's volts-to-flow gain (8.9998e-4 kg/s per V), `E-PROP-ENG` and `E-RCSP-RCS` are
    thrust-to-flow relations, and `E-FC-HEAT` is the cell's waste-heat fraction (0.58336 W per W).
    Each names both of its quantities in its unit and carries the factor between them in its value,
    which is what a converter *is*.

    So the rule is now the one the unit makes checkable: a conversion is well-formed when the unit
    names the state's quantity over the source's, the factor is finite and non-zero, and **the source
    is a level of that quantity rather than a stock's inventory**. The last clause was added by the
    same round after the first three let `E-PROP-ENG` through: 3.2423409e-4 kg/s per N is a *flow* at
    a rated thrust, and the node it leaves holds 18,508 kg of propellant, so multiplying them would
    have produced a number with three units in it the moment its driver was supplied.

    The branches are exercised directly because the corpus's own conversion edges have other debts in
    front of them — `E-BUS-PUMP`'s driver is `bus_a_v`, whose rule is not written, and `E-PROP-ENG`'s
    unit is stated backwards — so a test that waited for a corpus state to move would be testing the
    schedule rather than this rule.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import check_vehicle

    report = check_vehicle.Report()
    coupling = check_vehicle.load(VEHICLE / "coupling.yaml", report)
    nodes = {str(k): dict(v) for k, v in (coupling.get("nodes") or {}).items()}

    def edge(edge_id, source, target, value, unit):
        return {
            "id": edge_id,
            "from": source,
            "to": target,
            "kind": "lag",
            "sensitivity": {"value": value, "unit": unit, "basis": "chosen", "at": "nominal"},
        }

    # The conversion the corpus declares, as the corpus declares it: well-formed.
    ok, why = check_vehicle.lag_driver_basis(
        edge("E-BUS-PUMP", "bus_a", "coolant_flow", 8.9998e-4, "kg/s per V"), "kg/s", nodes
    )
    assert ok, why

    # And the identity transfer is still the identity: the same quantity, one for one.
    ok, why = check_vehicle.lag_driver_basis(
        edge("E-CABIN-EQ-CSM", "cabin_eq_csm", "cabin_zone_t", 1.0, "K per K"), "K", nodes
    )
    assert ok, why

    # A gain between two ends in the *same* quantity is still refused: that is a proportional law,
    # not a conversion, and `plant.md` §3 refuses a mode applied as a gain.
    ok, why = check_vehicle.lag_driver_basis(
        edge("gain", "cabin_eq_csm", "cabin_zone_t", 1.5, "K per K"), "K", nodes
    )
    assert not ok and "same quantity" in why, why

    # A stock's inventory is not a rate. With the edge's unit stated the way the corpus states it,
    # the numerator rule fires first (the corpus's `E-PROP-ENG` says `kg/s per N` for a state in
    # newtons). The stock clause is the one that survives that fix, so it is exercised against a
    # source node that *does* carry the denominator's quantity — which is what makes the clause
    # about the node's kind rather than about its unit.
    ok, why = check_vehicle.lag_driver_basis(
        edge("E-PROP-ENG", "prop_main", "thrust_main", 3.2423409e-4, "kg/s per N"), "N", nodes
    )
    assert not ok, why
    stock_source = dict(nodes)
    stock_source["prop_main"] = {"domain": "consumables", "kind": "stock", "unit": "kg/s"}
    ok, why = check_vehicle.lag_driver_basis(
        edge("E-PROP-ENG", "prop_main", "thrust_main", 3084.4, "N per kg/s"),
        "N",
        stock_source,
    )
    assert not ok, why
    assert "stock" in why and "rate is owed" in why, why

    # The plant's own walk agrees: the state that stopped being refused for the wrong reason is
    # `coolant_flow_kg_s`, and what it owes now is named — the bus voltage it reads, not a rule.
    plant = _plant()
    world = plant.load_world(VEHICLE)
    buckets = plant.build_order(world)
    # **Round 58 moved this state out of *ready* and into the bucket of what actually blocks it.**
    # `coolant_flow_kg_s`'s own declaration is complete — that is what this test established — and
    # the state it reads is not: `bus_a_v` owes its rule, so the pump's flow is filed under the rule
    # its root owes rather than promised to a tick that cannot reach it. The refusal below is the
    # same sentence it always was, read from the gap list the classification is now made of.
    assert "coolant_flow_kg_s" in {s.id for s in buckets["rule"]}
    gaps: list = []
    plant.step(world, plant.initial_values(world), 0.02, gaps)
    owed = {g.state.id: str(g.owed) for g in gaps}
    assert "reads 'bus_a', which nothing supplies" in owed["coolant_flow_kg_s"], owed[
        "coolant_flow_kg_s"
    ]
    root = plant.blame(world, gaps)["coolant_flow_kg_s"]
    assert root.state.id == "bus_a_v", root.state.id
    # And `thrust_main_n`'s debt moved from *the rule* to the *edge*, which is the truthful place:
    # what it lacks is the propellant flow to relax toward, not the code that would relax it.
    assert "thrust_main_n" in {s.id for s in buckets["edge"]}
    assert "thrust_main_n" not in {s.id for s in buckets["rule"]}


def test_the_delay_integrator_hands_back_what_entered_one_pipe_ago(tmp_path):
    """The seventh method, which the reference plant could not advance at all.

    `plant.md` §3 grew a seventh class when the first transport delay landed, and its two
    implementation constraints are stated there as non-negotiable: **a ring, not a chain of small
    nodes**, and **indexed by tick, not by accumulated wall time** — because the delay is part of the
    state, so it is part of the snapshot and the compare-point hash, and a delay stored as a float
    deadline is a replay divergence waiting for a slow machine.

    The corpus's own delay is `loop_transport_t`, and it is the *wrong* one to observe the ring with:
    its driver is `coolant_supply_t`, which nothing advances yet, so the pipe's contents never change
    and a broken ring would look exactly like a working one. So the ring is tested where it can be
    seen — a hand-built world with a driver this test drives, and a **`None` slot for a tick that has
    not happened yet**, which is the difference between a pipe full of 0 K and a pipe that is empty.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    def world(delay_s: float, initial: float = 100.0):
        state = plant.State(
            id="transport_t",
            domain="thermal",
            node="transport",
            method="delay",
            unit="K",
            spec={"id": "transport_t", "method": "delay", "node": "transport", "unit": "K",
                  "delay_s": delay_s, "initial": initial},
        )
        edge = plant.Edge(
            id="E-TRANSPORT",
            source="source",
            target="transport",
            kind="delay",
            sensitivity={"value": 1.0, "unit": "K per K", "basis": "derived", "at": "nominal"},
        )
        return plant.World(
            root=VEHICLE,
            states=[state],
            edges=[edge],
            back_edges=set(),
            schedule=["transport"],
            nodes={"transport": {"unit": "K", "kind": "state"},
                   "source": {"unit": "K", "kind": "state"}},
            channels={},
            frame_fields=[],
            verbs={},
            documents={},
            advance_order={"transport": ["transport_t"]},
        )

    w = world(delay_s=1.0)  # one second at 50 Hz
    values: dict = {"transport_t": 100.0}
    seen = []
    for tick in range(1, 161):
        # The driver steps every ten ticks, so a working ring reproduces a staircase fifty ticks
        # late — and a ring that is off by one tick, or that reads before it writes, cannot.
        values = {**values, "source": 100.0 + 10.0 * ((tick - 1) // 10)}
        values = {**values, **plant.advance(w, w.states[0], values, 0.02)}
        seen.append(values["transport_t"])
    # The first fifty ticks are the pipe filling: nothing has travelled the whole length yet, so the
    # state holds its declared `initial` — which for a transport line is the right answer rather
    # than a fallback, and is what the corpus's own `initial_provenance` says.
    assert seen[:50] == [100.0] * 50, seen[:52]
    # And from the fiftieth tick on, it is exactly what entered fifty ticks ago.
    for index in range(50, 160):
        entered_at = 100.0 + 10.0 * ((index - 50) // 10)
        assert seen[index] == entered_at, (index, seen[index], entered_at)

    # The ring's depth is `delay_s / dt`, and a delay that is not a whole number of ticks is a
    # refusal rather than a rounding: `plant.md` §3 indexes by tick, so the corpus has to say which.
    w = world(delay_s=0.025)
    try:
        plant.advance(w, w.states[0], {"transport_t": 100.0, "source": 100.0}, 0.02)
    except plant.Unconfigured as exc:
        assert "not a whole number" in str(exc.what), exc.what
    else:
        raise AssertionError("a delay of 1.25 ticks was rounded rather than refused")

    # And a delay shorter than one tick is not a delay: reading the driver straight through would be
    # a lag with tau = 0 wearing this class's name.
    # A `dt` a whole number of times larger, so the residence is a *fraction* of a tick rather than
    # a fraction of one that the whole-number rule catches first.
    w = world(delay_s=0.02)
    try:
        plant.advance(w, w.states[0], {"transport_t": 100.0, "source": 100.0}, 0.05)
    except plant.Unconfigured as exc:
        assert "not a delay" in str(exc.what), exc.what
    else:
        raise AssertionError("a sub-tick delay was read straight through")

    # And the linter refuses a delay whose edge carries a scale, so a corpus that would make the ring
    # a record of something the pipe never carried is refused before it runs.
    scaled = copy_definition(fixture_dir(tmp_path, "scaled-delay"))
    path = scaled / "coupling.yaml"
    text = path.read_text()
    old_edge = '    sensitivity: {value: 1.0, unit: "K per K", basis: derived, relation: "the coupling is the signal itself; one unit in, one unit out", at: nominal,\n    delay_ticks: UNCONFIGURED,'
    assert old_edge in text, "the fixture no longer matches E-COOL-TRANSPORT"
    path.write_text(
        text.replace(
            old_edge,
            '    sensitivity: {value: 0.9, unit: "K per K", basis: derived, relation: "a fixture", at: nominal,\n    delay_ticks: UNCONFIGURED,',
            1,
        )
    )
    result = run_linter(scaled)
    assert result.returncode == 1
    assert "into a `delay` state" in result.stdout, result.stdout[-900:]
    assert "record of a quantity the pipe never carried" in result.stdout

    # The corpus's own delay composes, and its real pipe is 1,042 s = 52,100 ticks.
    corpus = plant.load_world(VEHICLE)
    state = next(s for s in corpus.states if s.id == "loop_transport_t")
    assert state.method == "delay" and state.spec["delay_s"] == 1042
    assert float(state.spec["delay_s"]) / 0.02 == 52100.0
    values = plant.step(corpus, plant.initial_values(corpus), 0.02, [])
    assert values["loop_transport_t"] == 280.35
    assert len(values["loop_transport_t__delay"]["slots"]) == 52100




def test_a_run_can_say_which_scenario_it_is(tmp_path):
    """Criterion 3's runner, at its smallest honest size: a run's identity, recorded and replayable.

    `mission.yaml` has declared three scenario postures since it was written — hazard ×1/×5/×10 and
    demand failure ×1/×5/×20, plus a selector over which faults are *placed* rather than left to
    chance — and `tools/faults.py` has scaled by them since the round that found the difficulty knob
    doing nothing. What no tool had was a run's identity: two `crisis` runs were indistinguishable
    in the record and neither could be replayed.

    **A scenario is a posture and a seed, and nothing else is recorded**, which is the decision this
    test holds. `mission.yaml`'s own debt says why: *"the pool is a set of faults, the guaranteed
    seed is drawn from it, and the chain that results is whichever one that fault realises — so a
    `crisis` run is a crisis, and not necessarily the crisis a chain names."*

    **What changed (ADR 0001 choice D, and the review).** The identity is the *directory's*, in its
    own record `.executive.json`, because one directory is one world — so the windows of one
    directory cannot disagree about it, and each case below is its own directory. A second executive
    on a bound directory exits 3, so the remembered half is proved the way the ADR provides for it:
    `--init` records the identity without binding, and the run that names nothing inherits it. A run
    that names the pair on a prepared directory is obeyed, and the plan is asked about the resolved pair.
    """
    postures = yaml.safe_load((VEHICLE / "mission.yaml").read_text())["scenario_postures"]
    ids = [str(row["id"]) for row in postures]
    assert ids == ["nominal", "degraded", "crisis"], ids

    def run_console(*argv: str) -> subprocess.CompletedProcess[str]:
        return subprocess.run(
            [sys.executable, str(VEHICLE / "tools" / "console.py"), *argv],
            capture_output=True,
            text=True,
            check=False,
        )

    root = fixture_dir(tmp_path, "scenario")
    result = run_console(
        "--diode-dir", str(root), "--slug", "vehicle", "--scenario", "crisis", "--seed", "42",
        "--cycles", "2", "--poll", "0",
    )
    assert result.returncode == 0, result.stderr[-600:]
    assert "scenario=crisis seed=42" in result.stdout, result.stdout[-400:]
    window = root / "vehicle"
    published = json.loads((window / "state.json").read_text())
    check = json.loads((root / ".executive.json").read_text())
    # **The fleet is not told which scenario it is in, nor the seed.** The mirror carried
    # `vehicle.scenario` and every window's `pending.json` the pair until the per-slug mounts made the
    # directory's record the operator's alone: the seed keys the fault plan and the scenario says how
    # hard the run is, and publishing either does part of the agents' diagnosis for them.
    assert "scenario" not in published["vehicle"], published["vehicle"]
    # And the directory's own record carries the pair, because `state.json` is never read back.
    assert check["scenario"] == "crisis" and check["seed"] == 42, (check.get("scenario"), check.get("seed"))
    # And no window file that carries run state names either: the record, the mirror and every frame.
    # (HELP.md and README.md are generated from the configuration alone and are the same for every
    # run, so a posture name in their vocabulary is not this run's.)
    mirror_record = json.loads((window / "pending.json").read_text())
    assert "scenario" not in mirror_record and "seed" not in mirror_record, mirror_record
    run_files = sorted(window.rglob("*.json")) + sorted((window / "output").glob("*.txt"))
    for leaked in run_files:
        body = leaked.read_text(errors="replace")
        assert '"seed"' not in body and '"scenario"' not in body and "master_seed" not in body, leaked
        assert "crisis" not in body and "degraded" not in body, leaked

    # A directory prepared with the pair and run without the flags keeps it: the record describes the
    # run, and a run that reset itself to `nominal` would make a crisis run report itself as nominal.
    kept = fixture_dir(tmp_path, "kept")
    made = run_console(
        "--diode-dir", str(kept), "--slug", "kept", "--scenario", "crisis", "--seed", "42", "--init"
    )
    assert made.returncode == 0, made.stderr[-400:]
    assert json.loads((kept / ".executive.json").read_text())["world_id"] is None
    resumed = run_console("--diode-dir", str(kept), "--slug", "kept", "--cycles", "1", "--poll", "0")
    assert resumed.returncode == 0, resumed.stderr[-400:]
    assert "scenario=crisis seed=42" in resumed.stdout, resumed.stdout[-400:]
    record = json.loads((kept / ".executive.json").read_text())
    assert record["scenario"] == "crisis" and record["seed"] == 42, record

    # A scenario the vehicle does not declare is refused, with the list — which is the failure the
    # difficulty knob's own history is about: a name nothing resolves reads exactly like a name
    # that did nothing.
    refused = run_console(
        "--diode-dir", str(fixture_dir(tmp_path, "phantom")), "--slug", "v2", "--scenario", "phantom", "--cycles", "1"
    )
    assert refused.returncode == 3, refused.returncode
    assert "is not one of the vehicle's" in refused.stderr, refused.stderr
    assert "crisis" in refused.stderr and "nominal" in refused.stderr

    # **And the fourth case, which the first three could not see.** The second case proves a run that
    # names *nothing* keeps the pair; this one proves a run that names *something* is obeyed — and the
    # two are the same observation only if the parser can tell them apart. It could not, once:
    # `--scenario` defaulted to `"nominal"`, so `args.scenario` was a string whether the caller had
    # named the posture or named nothing, and the restore overrode both. So the directory is prepared
    # as one posture and run as another, and the *pair* is named, because a run is reproducible from
    # its scenario and its seed.
    renamed = fixture_dir(tmp_path, "renamed")
    made = run_console(
        "--diode-dir", str(renamed), "--slug", "renamed", "--scenario", "degraded", "--seed", "3", "--init"
    )
    assert made.returncode == 0, made.stderr[-400:]
    prepared = json.loads((renamed / ".executive.json").read_text())
    assert prepared["scenario"] == "degraded" and prepared["seed"] == 3, prepared
    ran = run_console(
        "--diode-dir", str(renamed), "--slug", "renamed", "--scenario", "crisis", "--seed", "7",
        "--cycles", "1", "--poll", "0",
    )
    assert ran.returncode == 0, ran.stderr[-400:]
    assert "scenario=crisis seed=7" in ran.stdout, ran.stdout[-400:]
    record = json.loads((renamed / ".executive.json").read_text())
    assert record["scenario"] == "crisis" and record["seed"] == 7, record
    # The record moves; the mirror says nothing of it either way.
    mirror = json.loads((renamed / "renamed" / "state.json").read_text())
    assert "scenario" not in mirror["vehicle"], mirror["vehicle"]
    # And the plan is asked about the *resolved* pair rather than the flag, so `--plan` on this
    # directory with no `--scenario` describes the crisis it is in and not the default it never had.
    planned = run_console("--diode-dir", str(renamed), "--plan-json")
    assert planned.returncode == 0, planned.stderr[-400:]
    assert json.loads(planned.stdout)["posture"] == "crisis", planned.stdout[:200]

    # One directory is one identity: a second window prepared without flags inherits the first's,
    # and both run under it.
    shared = fixture_dir(tmp_path, "shared")
    assert run_console("--diode-dir", str(shared), "--slug", "left", "--scenario", "crisis", "--seed", "42", "--init").returncode == 0
    assert run_console("--diode-dir", str(shared), "--slug", "right", "--init").returncode == 0
    record = json.loads((shared / ".executive.json").read_text())
    assert record["slugs"] == ["left", "right"] and record["scenario"] == "crisis" and record["seed"] == 42, record
    assert "scenario" not in json.loads((shared / "right" / "pending.json").read_text())
    both = run_console("--diode-dir", str(shared), "--slug", "left", "--slug", "right", "--cycles", "1", "--poll", "0")
    assert both.returncode == 0, both.stderr[-400:]
    assert "scenario=crisis seed=42" in both.stdout, both.stdout


def test_a_scenario_plan_is_what_that_scenario_decides(tmp_path):
    """The plan a run announces and the plan it flies are one computation, not two that agree.

    `--plan` returns what the posture and the seed decide: the rates the posture scales, the faults
    the posture *places* rather than leaves to hazard, and every spontaneous event over the mission.
    It reads the same `scenario_report` the scheduler's own `--json` does, which is the property
    worth testing — a second implementation is a second answer.
    """
    def plan(*argv: str) -> dict:
        result = subprocess.run(
            [sys.executable, str(VEHICLE / "tools" / "console.py"), "--plan-json", *argv],
            capture_output=True,
            text=True,
            check=False,
        )
        assert result.returncode == 0, result.stderr[-600:]
        return json.loads(result.stdout)

    nominal = plan("--scenario", "nominal", "--seed", "42")
    crisis = plan("--scenario", "crisis", "--seed", "42")
    assert nominal["hazard_factor"] == 1.0 and crisis["hazard_factor"] == 10.0
    assert nominal["on_demand_factor"] == 1.0 and crisis["on_demand_factor"] == 20.0
    assert nominal["seeded_faults"] == "none"
    assert crisis["seeded_faults"].startswith("one guaranteed major primary")
    # A crisis run schedules strictly more, and it *places* one.
    assert len(crisis["events"]) > len(nominal["events"]), (
        len(crisis["events"]),
        len(nominal["events"]),
    )
    assert any(e.get("scaled_by") == "crisis" for e in crisis["events"]), (
        "the crisis posture places a guaranteed seed, and the plan does not show it"
    )

    # The same scenario and seed are the same plan, twice — which is what makes a run replayable.
    again = plan("--scenario", "crisis", "--seed", "42")
    assert again == crisis

    # And a different seed is a different plan, so the seed is doing something.
    other = plan("--scenario", "crisis", "--seed", "43")
    assert [e["met_h"] for e in other["events"]] != [e["met_h"] for e in crisis["events"]]

    # The scheduler's own `--json` is the same report, because there is one implementation of it.
    faults_json = subprocess.run(
        [
            sys.executable, str(VEHICLE / "tools" / "faults.py"),
            "--seed", "42", "--posture", "crisis", "--json",
        ],
        capture_output=True,
        text=True,
        check=False,
    )
    assert faults_json.returncode == 0, faults_json.stderr[-600:]
    from_faults = json.loads(faults_json.stdout)
    for key in ("posture", "master_seed", "hazard_factor", "on_demand_factor", "seeded_faults"):
        assert from_faults[key] == crisis[key], key
    assert [e["fault"] for e in from_faults["events"]] == [e["fault"] for e in crisis["events"]]



def test_the_telemetry_ring_is_bounded_and_accounts_for_its_losses(tmp_path):
    """The contract asks for a ring "self-describing about its own cadence and its own losses".

    `docs/diode-contract.md:183-189` is emphatic about why: *"An agent that was blocked inside one
    long conversation turn wakes up blind if all it has is the latest frame: it cannot distinguish a
    stall from a shut-down, or a trend from a transient."* And the file that was supposed to be that
    ring was unbounded — `write_frame` wrote `NNN.json` and removed none — so "losses" was a field
    with no possible value and the directory grew for the length of the mission.

    Two properties, and the second is the one the contract is really asking for. The ring is
    **bounded**, and a frame that falls out of the far end is **counted** rather than forgotten:
    `held + losses` is exactly what the window has produced.

    **What changed (ADR 0001).** The old second half restarted the window in a new process and
    expected the sequence to continue from the record; a second executive on a bound window is now
    refused, and the frames it left are untouched, so the accounting is held across one run and the
    refusal is checked instead of the continuation. The figures are derived from the loop: an
    executive publishes no frame until it has ticked, so 14 cycles are frames `000`–`013`; a ring of 5
    holds `009`–`013`; 14 were produced, 5 are held, 9 were lost, and the newest is `013`. The mirror
    is written *after* the frame now, so it describes the directory as it is rather than one behind.
    """
    diode = tmp_path / "diode"
    window = diode / "bounded"
    console = [
        sys.executable,
        str(VEHICLE / "tools" / "console.py"),
        "--diode-dir",
        str(diode),
        "--slug",
        "bounded",
        "--ring-slots",
        "5",
        "--cycles",
        "14",
        "--poll",
        "0",
    ]
    first = subprocess.run(console, capture_output=True, text=True, check=False)
    assert first.returncode == 0, first.stderr[-600:]
    assert "ring=5" in first.stdout, first.stdout[-300:]

    frames = sorted(path.name for path in (window / "telemetry").glob("*.json"))
    assert len(frames) == 5, frames
    # Names are *sequence numbers*, so a new frame is never a rewritten one. A ring that reused
    # names would make "a frame arrived" and "a frame was overwritten" the same observation.
    assert frames == ["009.json", "010.json", "011.json", "012.json", "013.json"], frames

    published = json.loads((window / "state.json").read_text())
    record = json.loads((window / "pending.json").read_text())
    ring = published["ring"]
    assert ring["slots"] == 5 and ring["held"] == 5 and ring["losses"] == 9, ring
    assert ring["newest_seq"] == 13, ring
    assert ring["held"] + ring["losses"] == record["seq"] == 14, (ring, record["seq"])
    # The accounting is *derived* from the files rather than kept beside them, so a reader that
    # counts the directory and a reader that trusts the mirror agree — which is what "self-describing"
    # has to mean if it is to mean anything.
    on_disk = sorted(p.name for p in (window / "telemetry").glob("*.json"))
    assert len(on_disk) == ring["held"] and on_disk[-1] == f"{ring['newest_seq']:03d}.json"
    assert published["executive"]["tick"] == 14 == record["ticks"]

    # A restart does not continue the ring: the directory is bound to the dead executive's world, the
    # second process is refused, and the frames it left are exactly as they were (ADR 0001 choice D).
    world_id = json.loads((diode / ".executive.json").read_text())["world_id"]
    assert world_id == record["world_id"]
    before = {p.name: p.read_bytes() for p in (window / "telemetry").glob("*.json")}
    again = subprocess.run(
        [
            sys.executable,
            str(VEHICLE / "tools" / "console.py"),
            "--diode-dir",
            str(diode),
            "--slug",
            "bounded",
            "--cycles",
            "3",
            "--poll",
            "0",
        ],
        capture_output=True,
        text=True,
        check=False,
    )
    assert again.returncode == 3, (again.returncode, again.stderr[-600:])
    assert world_id in again.stderr, again.stderr
    assert {p.name: p.read_bytes() for p in (window / "telemetry").glob("*.json")} == before

    # And a bound of one is a ring, not a crash: the newest frame is all that is left.
    one = subprocess.run(
        [
            sys.executable,
            str(VEHICLE / "tools" / "console.py"),
            "--diode-dir",
            str(tmp_path / "one"),
            "--slug",
            "one-slot",
            "--ring-slots",
            "1",
            "--cycles",
            "4",
            "--poll",
            "0",
        ],
        capture_output=True,
        text=True,
        check=False,
    )
    assert one.returncode == 0, one.stderr[-600:]
    frames = sorted(path.name for path in (tmp_path / "one" / "one-slot" / "telemetry").glob("*.json"))
    ring_one = json.loads((tmp_path / "one" / "one-slot" / "state.json").read_text())["ring"]
    assert frames == ["003.json"] and ring_one["newest_seq"] == 3 and ring_one["losses"] == 3, (frames, ring_one)



def test_a_restart_may_not_re_bound_the_ring_and_says_so(tmp_path):
    """The ring's bound is the one remembered value a restart keeps, and keeping it in silence is a lie.

    The decision itself is older than this test: the frames on disk were written under a bound, and
    a restart that took a new one would make the frames held, the losses accounted and the declared
    slot count three answers to one question — so the record's bound wins. What was wrong was the
    *manner*: `--ring-slots` defaulted to `300`, so a caller who named `10` and a caller who named
    nothing were the same argument, and the run kept `300` without a word.

    So the refusal is the deliverable, not the override: a named bound that the window does not
    have exits 3 and names the bound it does have, and a bound that *agrees* with the record still
    runs, because there is nothing to disagree about.

    **What changed (ADR 0001 choice D).** A directory that has been ticked is bound, and a second
    executive on it is refused for *that* reason first — so the bound's own refusal is proved on a
    directory `--init` prepared, whose record remembers each window's bound and belongs to no world
    yet. The record is the directory's `.executive.json`, not the agent-writable `pending.json`.
    """
    diode = tmp_path / "diode"
    entry = [sys.executable, str(VEHICLE / "tools" / "console.py"), "--diode-dir", str(diode)]
    made = subprocess.run([*entry, "--slug", "held", "--ring-slots", "6", "--init"], capture_output=True, text=True, check=False)
    assert made.returncode == 0, made.stderr[-600:]
    prepared = json.loads((diode / ".executive.json").read_text())
    assert prepared["ring_slots"] == {"held": 6} and prepared["world_id"] is None, prepared

    # Naming the bound the window already has is not a disagreement, and it runs.
    same = subprocess.run(
        [*entry, "--slug", "held", "--ring-slots", "6", "--cycles", "1", "--poll", "0"],
        capture_output=True,
        text=True,
        check=False,
    )
    assert same.returncode == 0, same.stderr[-600:]
    assert "ring=6" in same.stdout, same.stdout[-300:]

    # Naming another one is refused, with both numbers, and the directory is untouched.
    other = tmp_path / "other"
    other_entry = [sys.executable, str(VEHICLE / "tools" / "console.py"), "--diode-dir", str(other)]
    made = subprocess.run([*other_entry, "--slug", "other", "--ring-slots", "6", "--init"], capture_output=True, text=True, check=False)
    assert made.returncode == 0, made.stderr[-600:]
    assert json.loads((other / ".executive.json").read_text())["ring_slots"] == {"other": 6}
    before = (other / ".executive.json").read_bytes()
    refused = subprocess.run(
        [*other_entry, "--slug", "other", "--ring-slots", "10", "--cycles", "1", "--poll", "0"],
        capture_output=True,
        text=True,
        check=False,
    )
    assert refused.returncode == 3, refused.returncode
    assert "--ring-slots 10" in refused.stderr and "holds 6" in refused.stderr, refused.stderr
    assert (other / ".executive.json").read_bytes() == before
    assert not list((other / "other" / "telemetry").glob("*.json"))
    # And a fresh window is free to be bound however the caller likes, which is what keeps this a
    # rule about *restarts* rather than a rule against naming the bound at all.
    fresh = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "console.py"), "--diode-dir", str(tmp_path / "fresh"), "--slug", "fresh", "--ring-slots", "10", "--cycles", "1", "--poll", "0"],
        capture_output=True,
        text=True,
        check=False,
    )
    assert fresh.returncode == 0, fresh.stderr[-600:]
    assert "ring=10" in fresh.stdout, fresh.stdout[-300:]
    assert json.loads((tmp_path / "fresh" / ".executive.json").read_text())["ring_slots"] == {"fresh": 10}



def test_the_window_s_sixth_file_is_generated_from_the_configuration(tmp_path):
    """`docs/diode-contract.md` lists six files and the console made five of them.

    The missing one is `README.md` — *"the protocol, in the vehicle's words"* — and §8 says what it
    is for: `HELP.md`, `state.json` and `README.md` "are the vehicle's documentation of itself …
    and **they are the only place a verb name can appear**". Five of six is a window whose protocol a
    fleet has to infer from a verb list, and `HELP.md` answers *what may I ask for* rather than *how
    does this work*.

    **The test is the drift detector rather than a golden file**, which is the decision worth
    recording. A committed copy of the generated text would be a second declaration of the
    configuration — and this folder's oldest finding is that a declaration no tool reads has already
    drifted. What is asserted instead is that the file the *window* gets is byte-identical to what
    the generator produces from the configuration **now**, so moving a cadence class, withdrawing a
    channel or adding a refusal code fails here until the file follows.

    The hand-edit half is driven in-process now (ADR 0001): a second process on a ticked window is
    refused, so the cycle that restores the file is the same executive's.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    from generate_readme import generate as generate_readme

    text = generate_readme(VEHICLE)
    # It carries the configuration's own facts rather than a second copy of them.
    presentation = yaml.safe_load((VEHICLE / "presentation.yaml").read_text())
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    rows = [
        row
        for section, value in channels.items()
        if isinstance(value, list) and section not in ("open_debts", "crew_positions")
        for row in value
        if isinstance(row, dict) and row.get("id")
    ]
    assert f"{len(rows)} channels are published" in text, len(rows)
    for entry in presentation["ring"]["cadence_classes"]:
        assert f"| `{entry['class']}` | {entry['rule']} | {entry['members']} |" in text, entry
    for code, _meaning in __import__("generate_help").REFUSAL_VOCABULARY:
        assert f"| `{code}` |" in text, code
    # And it says what the vehicle withholds, which is part of the protocol rather than a leak.
    assert "not published" in text and "named channels" in text
    # The protocol, not the designers' analysis: nothing from `single_cabin`, no fault-catalogue id,
    # no failure-chain id, no "diagnosis". Removed on the owner's direction that the fleet manages
    # its own information (2026-10-09); `single_cabin` is still declared, for the linter.
    single = presentation.get("single_cabin") or {}
    assert single, "the fixture no longer declares single_cabin"
    for channel, why in single.items():
        assert str(why)[:60] not in text, channel
    assert "diagnos" not in text.lower(), "the window README explains a diagnosis"
    # Short and long fault-catalogue ids (`ECL-13`, `ECL-07-suit-loop-fan-failure`), failure-chain
    # ids in both forms (`F-05`, `F-PWR-01`), and citations of corpus files no agent can read.
    assert not re.search(r"\b[A-Z]{3}-\d{2}\b", text), "a fault-catalogue id reached the window README"
    assert not re.search(r"\bF-(?:[A-Z]{3}-)?\d{2}\b", text), "a failure-chain id reached the window README"
    # A citation of a file the agent cannot read; the window's own HELP.md and README.md may be
    # anchored into.
    assert not re.search(r"[\w-]+(?<!HELP)(?<!README)\.(?:md|yaml)(?::\d|#)", text), (
        "a corpus citation reached the window README"
    )
    assert "what the vehicle did" in text and "always carries quality" not in text
    assert "would go looking" not in text and "far_side" not in text

    # No verb list and no thresholds: `HELP.md` owns the vocabulary and design.md §8's boundary is
    # that the vehicle publishes what it concluded and never what it suspects about itself.
    help_text = (VEHICLE / "tools" / "generate_help.py").read_text()
    assert "thresholds" not in text.lower() or "the thresholds" not in text
    assert "failure chain" not in text.lower()
    assert "HELP.md" in text  # it points at the file that does carry the verbs

    # The executive writes it, at attach and every cycle, from that same generator.
    diode = tmp_path / "diode"
    window = diode / "protocol"
    result = subprocess.run(
        [
            sys.executable,
            str(VEHICLE / "tools" / "console.py"),
            "--diode-dir",
            str(diode),
            "--slug",
            "protocol",
            "--cycles",
            "2",
            "--poll",
            "0",
        ],
        capture_output=True,
        text=True,
        check=False,
    )
    assert result.returncode == 0, result.stderr[-600:]
    written = (window / "README.md").read_text()
    assert written == text, "the window's README is not what the generator produces"
    # All six files, which is the contract's list and not five of it.
    for name in ("console.json", "state.json", "HELP.md", "README.md", "pending.json"):
        assert (window / name).exists(), name
    assert (window / "telemetry").is_dir() and (window / "output").is_dir()

    # A hand-edit does not survive a cycle, which is the difference between a generated file and a
    # written one.
    console, _plant, world = console_tools()
    executive = console.Executive(world, tmp_path / "edited", phase="translunar_coast")
    executive.attach("protocol")
    edited = tmp_path / "edited" / "protocol"
    assert (edited / "README.md").read_text() == text
    (edited / "README.md").write_text("# doctored\n")
    (edited / "HELP.md").write_text("# doctored\n")
    executive.cycle()
    assert (edited / "README.md").read_text() == text, "a hand-edit survived a cycle"
    assert (edited / "HELP.md").read_text() == __import__("generate_help").generate(VEHICLE)
    # `HELP.md` is where the verbs are, and nothing in the README is one.
    assert "zzz_definitely_not_a_verb" not in help_text


def test_the_plant_reports_the_build_order():
    """The view is a CLI contract, not an internal function."""
    result = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "plant.py"), "--build-order"],
        capture_output=True,
        text=True,
        check=False,
    )
    assert result.returncode == 0, result.stderr
    assert "139 states, by what blocks them" in result.stdout
    for phrase in ("ready now", "owes a value", "owes an edge", "owes a rule"):
        assert phrase in result.stdout, f"{phrase!r} missing from the build order"


def test_a_declared_rule_is_ready_even_on_the_internal_sentinel(tmp_path):
    """The worklist's one rule about arithmetic was unreachable for every state on the sentinel.

    `build_order` asks "is the rule already in the configuration?" — an `algebraic` state carrying a
    `derivation` over named inputs is *ready*, because the plant evaluates it in a real tick. That
    test sat below the `internal` routing and the routing `continue`s, so for a state on the sentinel
    the answer was always "owes a rule: domain code".

    `avionics_bay_heat_w` is what exposed it: the avionics bay's 360 W, the fifth heat rate, summed
    from the three loads `heat_inputs.csm_avionics_bay` assigns. It is on the sentinel deliberately —
    a heat-rate edge landing on `coldplate_t` would become that lag's canonical driver and relax a
    kelvin state toward a watt — and its rule is a `derivation` the linter re-derives and the plant
    evaluates. The worklist filed it under code that exists, which is the one thing the bucket must
    not do.

    The fixture is the negative: strip the derivation from a copy and the state goes back to owing a
    rule, because then there genuinely is code to write.
    """
    plant = _plant()
    world = plant.load_world(VEHICLE)
    state = next(s for s in world.states if s.id == "avionics_bay_heat_w")
    assert state.node == "internal", state.node
    assert state.method == "algebraic"
    derivation = (state.spec.get("provenance") or {}).get("derivation")
    assert isinstance(derivation, dict) and derivation.get("expression"), derivation
    buckets = plant.build_order(world)
    assert state.id in {s.id for s in buckets["ready"]}, [s.id for s in buckets["rule"]][:5]
    # And the claim the bucket makes: the plant really does compute it, in one tick, from those
    # paths — 360 W, the sum `check_thermal_heat_inputs` also holds against the zone's loads.
    values = plant.step(world, plant.initial_values(world), 0.02, [])
    assert values["avionics_bay_heat_w"] == 360.0, values.get("avionics_bay_heat_w")

    # The negative, in a broken copy: no derivation, no ready — the state owes the code after all.
    definition = copy_definition(fixture_dir(tmp_path, "no-derivation"))
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    start = text.index("  - id: avionics_bay_heat_w\n")
    end = text.index("  - id: zone_csm_cabin_t\n")
    block = text[start:end]
    lines = block.split("\n")
    first = next(i for i, line in enumerate(lines) if line == "      derivation:")
    after = next(i for i in range(first + 1, len(lines)) if lines[i].strip() and not lines[i].startswith("        "))
    stripped = "\n".join(lines[:first] + lines[after:])
    assert stripped != block, "the fixture no longer matches the heat rate's derivation"
    path.write_text(text[:start] + stripped + text[end:])
    broken = plant.build_order(plant.load_world(definition))
    assert "avionics_bay_heat_w" in {s.id for s in broken["rule"]}, "a state with no rule was called ready"


def test_a_state_with_an_outbound_edge_and_no_driver_is_reported():
    """Having *an* edge is not having an input, and the isolation check cannot tell the difference.

    `cabin_zone_t` has an edge — `E-ZONE-ATM` points *out* of it — so it looks connected. But
    nothing drives it, `zone_csm_cabin_t` is a `lag`, and a lag with no driver has nothing to relax
    toward. The cabin's temperature has no heat input anywhere in the graph, while the crew, the
    equipment and the loop all warm it in the prose; the state's own 2,880 s derivation reasons
    about "a 1 kW cabin load" that no edge carries.

    The check also found three nodes that look identical and are not: **`o2_lm`, `prop_rcs` and
    `pressurant_he` have no inbound edge because they are filled at the pad and never again**, which
    they say in `preloaded:`. The first version reported all seven, which is three parts noise to
    one part signal — and the declaration is exactly what separates a stock that nothing fills from
    one that is filled once.
    """
    _plant()
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    nodes = coupling["nodes"]
    # The same rule the plant uses: a *back-edge* is not a driver, because `advance()` skips them
    # when it collects a state's incoming edges. `fuel_cell` is the case that proves it — `E-O2-FC`
    # points into it, and it is the back-edge of `C-REACTANT-DRAW-O2`, so the node still has nothing
    # forward driving it. A test that counted any inbound edge would have called it driven.
    back = {cy["back_edge"] for cy in coupling["cycles"] if cy.get("back_edge")}
    forward = {e["to"] for e in coupling["edges"] if e["id"] not in back}
    driving = {"lag", "stock", "delay", "dynamics"}
    methods = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []:
            methods[state["id"]] = (state.get("method"), state.get("node"))

    undriven = [
        name
        for name in nodes
        if name not in forward
        and any(e["from"] == name for e in coupling["edges"])
        and not nodes[name].get("preloaded")
        and any(m in driving and n == name for m, n in methods.values())
    ]
    # `fuel_cell` left this list in round 70: it has an inbound edge (`E-H2-FC`, from the hydrogen
    # tank) and it is no longer undriven — what the round removed was the *converter* riding on it.
    assert sorted(undriven) == ["imu"], undriven

    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]
    for name in undriven:
        assert f"coupling.yaml:node {name}: has edges but none into it" in result.stdout, name
    for name in ("o2_lm", "prop_rcs", "pressurant_he"):
        assert f"coupling.yaml:node {name}: has edges but none into it" not in result.stdout, (
            f"{name} is pre-loaded and must not be reported as undriven"
        )


def test_the_heat_inputs_are_a_partition_of_the_load_inventory(tmp_path):
    """`load_budget` names the loads as the heat inputs and nothing said which zone each one warms.

    The thermal domain declares the heat *sources* (`heater_bank_csm`'s own provenance says "the
    thermal side owns which zones it serves"), the power domain declares the *loads*, and nothing
    joined them — which is why `zone_csm_cabin_t` was a `lag` with no driver. The assignment lives
    in the thermal domain rather than as a `zone:` field on each power load, because a field there
    would be a second declaration of one fact in the file that explicitly refuses to duplicate the
    numbers.

    The property with teeth is the third: the distinct loads assigned per vehicle must sum to that
    vehicle's declared demand. It closes **exactly** — 1,723 W of CSM load and 1,007 W of LM load —
    which is what makes this a partition rather than a wish.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    loads = {str(r["id"]): r for r in power["loads"]}

    seen: dict[str, set[str]] = {}
    for block in thermal["heat_inputs"].values():
        for load_id in block["loads"]:
            assert load_id in loads, f"{load_id} is not a load"
            seen.setdefault(str(loads[load_id]["vehicle"]), set()).add(load_id)
    for vehicle, expected in (("csm", 1723), ("lm", 1007)):
        total = sum(int(loads[i]["demand_w"] or 0) for i in seen[vehicle])
        assert total == expected, f"{vehicle}: {total} W assigned against {expected} W declared"
    # Nothing unaccounted: every load in the inventory heats somewhere.
    assert sum(len(ids) for ids in seen.values()) == len(loads)

    # A load assigned to no zone is a watt that heats nothing, and the check says which one.
    definition = copy_definition(tmp_path / "gap")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    anchor = "    loads: [csm_imu, csm_guidance_computer, csm_instrumentation]\n"
    assert anchor in text, "the fixture no longer matches the avionics bay"
    path.write_text(
        text.replace(anchor, "    loads: [csm_guidance_computer, csm_instrumentation]\n", 1)
    )

    result = run_linter(definition)
    assert result.returncode == 1
    assert "A load assigned to no zone is a watt that heats nothing" in result.stdout
    assert "csm_imu" in result.stdout


def test_the_cabin_heat_rates_are_derived_from_the_load_inventory(tmp_path):
    """The heat-rate state is where the thermal and power domains finally meet, so it is checked there.

    `heat_inputs` assigns every load to a zone; the heat-rate state sums that zone's loads. Two
    declarations of one quantity, in two files, is exactly the shape that drifts — and it drifts in
    the quiet direction: a load re-rated in `domains/power/` would change what the cabin's equipment
    actually draws while the thermal state went on relaxing toward the old figure, modelling a cabin
    cooler than it is.

    The state's `total_w` is re-derived twice on every run: against its own `computation`, and
    against the loads `heat_inputs` assigns. `cabin_heat_lm_w` at 827 W against the CSM cabin's 733,
    with two crew rather than three, because the LM has no avionics-bay zone.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    loads = {str(r["id"]): r for r in power["loads"]}
    states = {str(s["id"]): s for s in thermal["state"]}

    for state_id, zone, expected in (
        ("cabin_heat_csm_w", "csm_cabin", 733),
        ("cabin_heat_lm_w", "lm_cabin", 827),
    ):
        state = states[state_id]
        declared = sum(
            int(loads[i]["demand_w"] or 0) for i in thermal["heat_inputs"][zone]["loads"]
        )
        assert state["total_w"] == declared == expected, state_id

    # A load re-rated under the state's feet is refused rather than absorbed.
    definition = copy_definition(tmp_path / "rate")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    anchor = "    total_w: 733\n"
    assert anchor in text, "the fixture no longer matches cabin_heat_csm_w"
    path.write_text(text.replace(anchor, "    total_w: 740\n", 1))

    result = run_linter(definition)
    assert result.returncode == 1
    # The message says "the zone" since round 38, because the rule covers the service and descent
    # bays too — it said "the cabin" while the check found the state by node name and skipped every
    # zone that was not a cabin.
    assert (
        "would relax toward a heat rate its equipment does not produce" in result.stdout.lower()
    )


def test_every_heated_zone_declares_the_state_that_carries_its_heat(tmp_path):
    """Two of six zones were compared, and the other four were skipped without a word.

    The check that holds a heat rate against the loads it sums found the state by node name:
    `node == f"cabin_heat_{block.get('rate')}"`, with `if state is None: continue` behind it. So it
    compared the two cabins and **silently skipped the service bay (630 W), the descent bay (180 W)
    and the avionics bay (360 W)** — three of the six declarations in the file whose whole purpose is
    the partition — and the `rate` field existed only so the convention could work, which is why it
    is gone with it. A zone that owes its heat rate now owes it loudly.

    The zone declares `heat_state` and `cooled_by`, the state is resolved rather than guessed, a link
    that does not resolve is refused, an absent one is a debt, and two zones may not name one state
    (a loop's collected load sums its zones, so a shared state would count the same watts twice).

    The avionics bay was the one that was owed — `heat_inputs.csm_avionics_bay` assigns the IMU, the
    guidance computer and the instrumentation, and no state summed them — and the debt is
    **closed**: `avionics_bay_heat_w` carries the 360 W, and the fixtures below are what keep the
    rule honest now that the corpus no longer trips it. An absent link is still a debt (the checker
    is exercised by a fixture that removes one), a link that does not resolve is still a refusal,
    and two zones still may not share a state.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    loads = {str(r["id"]): r for r in power["loads"]}
    zones = {str(z["id"]): z for z in vehicle["thermal"]["zones"]}
    loops = {str(x["id"]) for x in vehicle["thermal"]["loops"]}
    states = {str(s["id"]): s for s in thermal["state"]}
    unheated = {str(k) for k in thermal.get("unheated") or {}}

    # Every heated zone names a loop **and** a state that carries exactly its own loads — including
    # the avionics bay, which was the debt this check reported until the round that landed
    # `avionics_bay_heat_w` closed it. The fixture below is what keeps the rule itself honest: the
    # debt is gone from the corpus, not from the check.
    for zone, block in thermal["heat_inputs"].items():
        row = zones[zone]
        assert row["cooled_by"] in loops, zone
        assert "heat_state" in row, zone
        declared = sum(int(loads[i]["demand_w"] or 0) for i in block["loads"])
        assert states[row["heat_state"]]["total_w"] == declared, zone
    assert zones["csm_avionics_bay"]["heat_state"] == "avionics_bay_heat_w"
    assert zones["csm_service_bay"]["heat_state"] == "service_bay_heat_w"
    assert zones["lm_descent_bay"]["heat_state"] == "descent_bay_heat_w"
    for zone in unheated:
        assert "heat_state" not in zones[zone], zone

    # The debt is closed, and the check still reports an absent link when one comes back.
    intact = run_linter(VEHICLE)
    assert intact.returncode == 0
    assert "COMPOSES, with 273 declared debt(s)." in intact.stdout
    assert "names no heat-rate state" not in intact.stdout

    def fixture(name: str, old: str, new: str) -> subprocess.CompletedProcess[str]:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / "vehicle.yaml"
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        return run_linter(definition)

    # A heated zone that names no loop: the heat has nowhere to go.
    refused = fixture(
        "no-loop",
        "        cooled_by: loop_primary\n        heat_state: service_bay_heat_w\n",
        "        heat_state: service_bay_heat_w\n",
    )
    assert refused.returncode == 1
    assert "names None, which is not a loop" in refused.stdout, refused.stdout[-900:]

    # A link that does not resolve: `check_zone_nodes`' rule, applied to the heat state.
    refused = fixture(
        "wrong-state",
        "        heat_state: descent_bay_heat_w\n",
        "        heat_state: descent_bay_heat_x\n",
    )
    assert refused.returncode == 1
    assert "which is not a state in domains/thermal/components.yaml" in refused.stdout

    # Two zones, one state: a loop's collected load would count the same watts twice.
    refused = fixture(
        "shared-state",
        "        heat_state: service_bay_heat_w\n",
        "        heat_state: descent_bay_heat_w\n",
    )
    assert refused.returncode == 1
    assert "already names. One state cannot be two compartments' heat" in refused.stdout

    # An absent link is a debt rather than a refusal: the zone's heat has no carrier, and the
    # message names the zone's own figure so the reader can paste it into the state to build.
    absent = fixture("no-state", "        heat_state: service_bay_heat_w\n", "")
    assert absent.returncode == 0, absent.stdout[-900:]
    assert "names no heat-rate state" in absent.stdout, absent.stdout[-900:]
    assert "summing to 630 W" in absent.stdout

    # And the total itself, now that the service bay's is held: 630 W against its four loads.
    definition = copy_definition(fixture_dir(tmp_path, "bay-total"))
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    anchor = "    total_w: 630.0\n"
    assert anchor in text, "the fixture no longer matches service_bay_heat_w"
    path.write_text(text.replace(anchor, "    total_w: 600.0\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "would relax toward a heat rate its equipment does not produce" in result.stdout


def test_a_loop_s_collected_load_is_the_sum_over_the_zones_that_name_it(tmp_path):
    """The figure the domain's own debt called "a sum over `heat_inputs` that nothing evaluates".

    Every ingredient existed before this round — five zone heat rates, each held against the loads
    `heat_inputs` assigns, and a `cooled_by` on each heated zone — and the sum did not: the heat
    balance's rise is `load_w / (mass_flow_kg_s * c_p)`, the flow is a published reading, and the
    numerator was a sentence. `loop_primary_load_w` and `loop_lm_load_w` are the sums now, and the
    zones are the declaration rather than a list in the state: a zone moved to another loop moves
    the sum instead of disagreeing with it, which is the rule the fixture below exercises.

    The join is the loop's own `load_state` — the same shape as the zone's `heat_state`, and for the
    same reason: a link found by naming convention goes quiet when the name moves. A loop that no
    zone names is a **note** rather than a debt (`loop_secondary`: which CSM circuit serves which
    zones is C-28's open question), and a loop whose zones do name it owes the state loudly.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    states = {str(s["id"]): s for s in thermal["state"]}
    zones = {str(z["id"]): z for z in vehicle["thermal"]["zones"]}
    loops = {str(x["id"]): x for x in vehicle["thermal"]["loops"]}

    served: dict[str, list[str]] = {loop_id: [] for loop_id in loops}
    for zone in thermal["heat_inputs"]:
        served[zones[zone]["cooled_by"]].append(zone)
    assert sorted(served["loop_primary"]) == ["csm_avionics_bay", "csm_cabin", "csm_service_bay"]
    assert sorted(served["loop_lm"]) == ["lm_cabin", "lm_descent_bay"]
    assert served["loop_secondary"] == []
    for loop_id, zones_served in served.items():
        if not zones_served:
            assert "load_state" not in loops[loop_id], loop_id
            continue
        total = sum(states[zones[zone]["heat_state"]]["total_w"] for zone in zones_served)
        assert states[loops[loop_id]["load_state"]]["total_w"] == total, (loop_id, total)
    assert states["loop_primary_load_w"]["total_w"] == 1723
    assert states["loop_lm_load_w"]["total_w"] == 1007

    # The note rather than a debt, in the linter's own words, and the count unmoved by it.
    intact = run_linter(VEHICLE)
    assert intact.returncode == 0
    assert "COMPOSES, with 273 declared debt(s)." in intact.stdout
    assert (
        "vehicle.yaml#thermal.loops.loop_secondary.load_state: is not declared, and no zone names "
        "this loop" in intact.stdout
    ), intact.stdout[-1200:]

    def fixture(name: str, relative: str, old: str, new: str) -> subprocess.CompletedProcess[str]:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / relative
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        return run_linter(definition)

    # A zone moved to the other loop: both sums are now wrong, and the message names the loop and
    # the zones that carry it.
    moved = fixture(
        "moved-zone",
        "vehicle.yaml",
        "        cooled_by: loop_primary\n        temperature_state: zone_csm_cabin_t\n",
        "        cooled_by: loop_lm\n        temperature_state: zone_csm_cabin_t\n",
    )
    assert moved.returncode == 1
    assert "A loop's collected load is the sum over the zones it cools" in moved.stdout, (
        moved.stdout[-1200:]
    )

    # An absent link is a debt, with the zone list and the figure in the message.
    absent = fixture(
        "no-loop-state",
        "vehicle.yaml",
        "        load_state: loop_lm_load_w\n",
        "",
    )
    assert absent.returncode == 0, absent.stdout[-900:]
    assert "names no state carrying this loop's collected load" in absent.stdout
    assert "['lm_cabin', 'lm_descent_bay']" in absent.stdout

    # A link that does not resolve is a refusal, and the total itself is held.
    wrong = fixture(
        "wrong-loop-state",
        "vehicle.yaml",
        "        load_state: loop_lm_load_w\n",
        "        load_state: loop_lm_load_x\n",
    )
    assert wrong.returncode == 1
    assert "which is not a state in domains/thermal/components.yaml" in wrong.stdout

    total = fixture(
        "loop-total",
        "domains/thermal/components.yaml",
        "    total_w: 1007\n",
        "    total_w: 1000\n",
    )
    assert total.returncode == 1
    assert "carry 1007 W between them" in total.stdout


def test_the_coolants_specific_heat_is_arithmetic_from_the_loops_own_figures(tmp_path):
    """The figure the corpus carried as "about 3,600 J/kg-K", and the term nobody could check.

    `coolant_loop_t`'s relation has said "with c_p about 3,600 J/kg-K" since the loop landed, and
    the round that named the heat balance's missing terms could only repeat it: the rise is
    `load_w / (m_dot * c_p)`, the flow is a reading, and the property was prose. `Q = m_dot * c_p *
    dT` is exact, and TN D-6718 publishes all three of the other terms for this loop — the
    **4,850-Btu/hr requirement** for an average earth-orbital environment (PDF p. 17), the
    **200 lb/hr** flow (PDF p. 11) and the **45 F to 73-75 F** rise those pages give — so the
    property is arithmetic: 1,421.4 W over 0.025199576 kg/s and 15.5556 K is **3,626.1 J/kg-K**,
    inside the range a 62.5/37.5 glycol-water mixture can have and 0.7 % from the prose.

    The declaration is `derived` and `check_thermal_bindings` re-derives it, so the field cannot
    drift from its own arithmetic. And the conversion it unblocked is the point: with the property
    declared, `thermal.radiator_inlet_c` is `supply + load_w / (m_dot * c_p)` — the first of the two
    coolant temperatures that have waited since round 34 — so the frame publishes a number where it
    published a gap, at 26.06 C.

    That reading is above the loop's **design** band [22.8, 23.9] and below the channel's 35 C
    caution, which is C-29's subject rather than an error: the band is the point at which the
    radiator carries the requirement alone, and a vehicle at its full 1,723 W demand makes the
    evaporator take the difference.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    loop = {str(x["id"]): x for x in vehicle["thermal"]["loops"]}["loop_primary"]
    requirement = loop["heat_rejection_requirement_w"]
    rise = loop["thermal_rise_k"]
    flow = loop["nominal_flow_lb_per_h"]
    cp = loop["specific_heat_j_per_kg_k"]
    m_dot = flow * 0.45359237 / 3600
    # The requirement is the document's 4,850 Btu/hr converted and rounded to a tenth of a watt,
    # which is the precision it is declared to; the specific heat then follows from it.
    assert requirement == pytest.approx(4850 * 0.29307107, abs=0.05)
    assert cp == pytest.approx(requirement / (m_dot * rise), rel=1e-4)
    # 3,626 is what the prose said "about": 3,600 to within a percent.
    assert abs(cp - 3600) / 3600 < 0.01

    # The channel that reads it, and the number a tick publishes.
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    values = plant.step(world, plant.initial_values(world), 1.0 / 50.0, [])
    frame = plant.emit_frame(
        world,
        tick=1,
        seq=1,
        boot_id="0" * 32,
        met_s=0.02,
        sensor_time_s=0.02,
        values=values,
        quality={},
        phase="translunar_coast",
        vehicle="csm",
        state_revision=1,
    )
    inlet = frame["values"]["thermal.radiator_inlet_c"]
    assert inlet == pytest.approx(7.2 + 1723.0 / (0.025199576111111112 * cp), rel=1e-6)
    assert inlet == pytest.approx(26.06, abs=0.01)
    # Inside the channel's own range and below its event, which is what makes it a reading.
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    row = next(r for rows in channels.values() if isinstance(rows, list)
               for r in rows if isinstance(r, dict) and r.get("id") == "thermal.radiator_inlet_c")
    assert row["range"][0] <= inlet <= row["range"][1]

    # A specific heat that disagrees with the loop's own three terms is refused.
    definition = copy_definition(fixture_dir(tmp_path, "cp"))
    path = definition / "vehicle.yaml"
    text = path.read_text()
    anchor_text = "        specific_heat_j_per_kg_k: 3626.1\n"
    assert anchor_text in text, "the fixture no longer matches the loop's specific heat"
    path.write_text(text.replace(anchor_text, "        specific_heat_j_per_kg_k: 3600\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "the loop's own published terms give" in result.stdout, result.stdout[-900:]


def test_a_loop_declares_whether_it_serves_zones_or_backs_them_up(tmp_path):
    """`loop_secondary` had no declared role, and nothing said what the 167 lb/hr was.

    The corpus has carried two CSM glycol circuits since the loop list landed: `loop_primary` at
    200 lb/hr with the published supply and radiator-inlet bands, and `loop_secondary` at 18 L with
    figures *scaled* from the primary's and a reason that said only that no source gives them. The
    zones all name `loop_primary`, so the second circuit's role was a note the check could not turn
    into a rule, and C-28 carried the open question — two circuits, or one circuit at two points?

    TN D-6718, the Apollo experience report the corpus already takes its 200 lb/hr and 73-75 F inlet
    from, answers both on **PDF p. 11**: *"The coolant system consists of a primary loop, which is
    operated continuously, and a secondary loop, which serves as a backup system. The primary loop
    uses a centrifugal pump to circulate 200 lb/hr of coolant"*; the flow leaving the evaporator
    *"is divided into a 35-lb/hr flow directed to the inertial measurement unit (IMU) … and a
    165-lb/hr flow is routed to the suit heat exchanger"*; the two rejoin and *"the 200-lb/hr flow is
    directed through a series-parallel arrangement of 22 coldplates"*. So the study guide's 167 lb/hr
    is that **165-lb/hr suit-and-cabin branch of the same loop**, and the second circuit is a
    **backup**: *"may be operated at the discretion of the crewmembers … does not have cabin-heating
    capability, nor does it provide cooling to the guidance and navigation equipment."*

    The role is a declaration now, and the check holds it against the zone join in both directions:
    a `backup` a zone assigns itself to is refused (selection is `set_coolant_loop`'s mode), a
    `primary` no zone names is refused, and an absent role is a debt.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    loops = {str(x["id"]): x for x in vehicle["thermal"]["loops"]}
    zones = {str(z["id"]): z for z in vehicle["thermal"]["zones"]}
    served: dict[str, list[str]] = {loop_id: [] for loop_id in loops}
    for zone in zones.values():
        if zone.get("cooled_by") in served:
            served[zone["cooled_by"]].append(str(zone["id"]))
    for loop_id, loop in loops.items():
        assert loop["role"] in ("primary", "backup"), loop_id
        assert (loop["role"] == "primary") == bool(served[loop_id]), (loop_id, loop["role"], served[loop_id])
    assert loops["loop_secondary"]["role"] == "backup" and served["loop_secondary"] == []

    # The role's reason cites the document, and the asymmetry the document implies is declared: the
    # primary has the published 200 lb/hr and the backup has no published flow at all, which is why
    # its figures are the primary's and marked `chosen`.
    assert "TN D-6718" in str(loops["loop_secondary"]["provenance"]["reason"])
    assert loops["loop_primary"]["nominal_flow_lb_per_h"] == 200
    assert "nominal_flow_lb_per_h" not in loops["loop_secondary"], loops["loop_secondary"]
    assert loops["loop_secondary"]["provenance"]["basis"] == "chosen"

    def fixture(name: str, old: str, new: str) -> subprocess.CompletedProcess[str]:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / "vehicle.yaml"
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        return run_linter(definition)

    # A zone assigning itself to the backup: the assignment is the primary's.
    assigned = fixture(
        "zone-on-backup",
        "        cooled_by: loop_primary\n        heat_state: service_bay_heat_w\n",
        "        cooled_by: loop_secondary\n        heat_state: service_bay_heat_w\n",
    )
    assert assigned.returncode == 1
    assert "is `backup` and" in assigned.stdout and "name it in `cooled_by`" in assigned.stdout, (
        assigned.stdout[-900:]
    )

    # The primary called a backup while three zones name it.
    swapped = fixture(
        "primary-as-backup",
        "        # the heat balance needs to know.\n        role: primary\n",
        "        # the heat balance needs to know.\n        role: backup\n",
    )
    assert swapped.returncode == 1
    assert "is `backup` and" in swapped.stdout, swapped.stdout[-900:]

    # And no role at all is a debt, in the check's own words.
    absent = fixture("no-role", "        role: primary\n        provenance:\n", "        provenance:\n")
    assert absent.returncode == 0
    assert "is None, and a loop is either `primary`" in absent.stdout, absent.stdout[-900:]


def test_the_equilibrium_check_resolves_what_the_zone_declares(tmp_path):
    """The check found all four of its inputs by convention, and skipped silently when one moved.

    `check_cabin_equilibrium` is the check that found the swapped `supply_c`/`evaporator_outlet_c`
    pair — the one whose own docstring says the difference is invisible without it. And it found
    everything it needed by hand:

    - the loop, from `served = {"csm_cabin": "loop_primary", "lm_cabin": "loop_lm"}` — a literal in
      the tool, with a comment admitting the corpus says it nowhere;
    - the heat state, from `f"cabin_heat_{zone.split('_')[0]}_w"` — string surgery on the zone id;
    - the cabin's temperature state, by scanning the domain for a node named `cabin_zone_t` or
      `lm_cabin_zone_t`;
    - the equilibrium state, from `f"cabin_eq_{zone.split('_')[0]}_k"`.

    **And every one of those lookups ended in a `continue` or an `if ... is not None`.** So renaming
    `cabin_heat_csm_w` *composed*: the check went quiet, and the probe that proved it is the first
    fixture below. That is this folder's oldest sentence arriving at the check that exists to make a
    difference visible.

    Writing the fixture that unset the heat rate found the other half: `float(heat.get("total_w") or
    0)` is zero for a missing value and a `ValueError` for the string `UNCONFIGURED`, so the check's
    most important input was the one that would either vanish or take the linter down with a
    traceback — which is what the committed version did when the fixture was run against it.

    The zone declares the four links now — `cooled_by`, `temperature_state`, `heat_state`,
    `equilibrium_state` — the check refuses one that does not resolve, and the two tests that used
    to repeat the pairing read the declaration instead.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    states = {str(s["id"]): s for s in thermal["state"]}
    zones = {str(z["id"]): z for z in vehicle["thermal"]["zones"]}
    loops = {str(x["id"]): x for x in vehicle["thermal"]["loops"]}
    for zone in ("csm_cabin", "lm_cabin"):
        declared = zones[zone]
        for field in ("cooled_by", "temperature_state", "heat_state", "equilibrium_state"):
            assert declared.get(field), f"{zone} declares no {field}"
        assert declared["cooled_by"] in loops
        for field in ("temperature_state", "heat_state", "equilibrium_state"):
            assert declared[field] in states, declared[field]

    def refusal(name: str, edits: list[tuple[str, str, str]], needle: str) -> None:
        definition = copy_definition(tmp_path / name)
        for rel, old, new in edits:
            path = definition / rel
            text = path.read_text()
            assert old in text, f"the fixture no longer matches {old!r}"
            path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1500:]}"

    # Each of the four links, moved in both files so the zone join is silent and only the
    # resolution can catch it — which is exactly what the check could not do before.
    def both(field: str, old: str, new: str) -> list[tuple[str, str, str]]:
        return [
            ("vehicle.yaml", f"        {field}: {old}\n", f"        {field}: {new}\n"),
            ("domains/thermal/components.yaml", f"    {field}: {old}\n", f"    {field}: {new}\n"),
        ]

    refusal("heat", both("heat_state", "cabin_heat_csm_w", "cabin_heat_csm_x"),
            "which is not a state in domains/thermal/components.yaml")
    refusal("temperature", both("temperature_state", "zone_csm_cabin_t", "zone_csm_cabin_x"),
            "which is not a state in domains/thermal/components.yaml")
    refusal("equilibrium", both("equilibrium_state", "cabin_eq_csm_k", "cabin_eq_csm_x"),
            "which is not a state in domains/thermal/components.yaml")
    refusal("loop", both("cooled_by", "loop_primary", "loop_primary_x"),
            "which is not a loop vehicle.yaml#thermal.loops declares")
    # And the two inputs the states are supposed to carry.
    refusal(
        "unset_heat",
        [("domains/thermal/components.yaml", "    total_w: 733\n", "    total_w: UNCONFIGURED\n")],
        "declares 'UNCONFIGURED' as its `total_w`",
    )
    refusal(
        "no_conductance",
        [("domains/thermal/components.yaml", "    tau_s: 2880\n    lumped_mass_kg: 400\n    specific_heat_j_per_kg_k: 900\n    conductance_w_per_k: 125\n    provenance:\n      basis: derived", "    tau_s: 2880\n    provenance:\n      basis: derived")],
        # The break removes the whole lump — mass, heat capacity and conductance together — so the
        # lump check stays silent and the equilibrium check names the missing field. Removing the
        # conductance *alone* is a different case, and the lump check owns it: see
        # `test_a_zones_time_constant_is_its_lump_over_its_conductance`.
        "carries no numeric `conductance_w_per_k`",
    )


def test_the_cabin_equilibrium_is_inside_its_own_limit_band(tmp_path):
    """Four declarations across three files have to agree for the cabin to be a habitable cabin.

    The heat its equipment puts in (from the power domain's load inventory, summed), the lumped
    conductance, the coolant supply temperature, and the zone's own `limit_c`. Nothing joined them,
    and the arithmetic is one line: **T = supply + Q/G**.

    Writing it found a swapped pair of fields. `loop_primary` declared `supply_c: [2.8, 7.2]` and
    `evaporator_outlet_c: 5.3`, while its own source reads *"mixed supply 45 F = 7.2 C, evaporator
    outlet 41.5 F = 5.3 C over a 37-45 F range"* — the supply carried the evaporator's span and the
    evaporator carried that span's midpoint. Taken at face value the lower end is a 2.8 C supply, and
    at 2.8 C the CSM cabin sits at **8.66 C against a 10 C floor**: the vehicle would trip its own
    cabin-low alarm on every cold pass of a nominal mission.

    `loop_lm` was worse. Its `supply_c: [1.7, 12]` was the *magnitude* of the operating range's cold
    end with its sign lost, paired with an upper bound from nowhere — and the source gives an
    operating range, not a supply temperature at all.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    loops = {str(x["id"]): x for x in vehicle["thermal"]["loops"]}
    zones = {str(x["id"]): x for x in vehicle["thermal"]["zones"]}
    states = {str(s["id"]): s for s in thermal["state"]}

    # The four links are read from the zone's own declaration rather than repeated here: the pairs
    # were a hand-written list in this test until the corpus declared them, which is the same defect
    # the check had in the tool.
    for zone in ("csm_cabin", "lm_cabin"):
        declared = zones[zone]
        supply = loops[declared["cooled_by"]]["supply_c"]
        assert isinstance(supply, (int, float)), f"{zone}.cooled_by holds a band, not a supply"
        heat = states[declared["heat_state"]]
        cabin = states[declared["temperature_state"]]
        equilibrium = supply + heat["total_w"] / cabin["conductance_w_per_k"]
        low, high = declared["limit_c"]
        assert low < equilibrium < high, f"{zone} sits at {equilibrium:.2f} C in [{low}, {high}]"

    # And a supply that puts the cabin under its own floor is refused rather than absorbed.
    definition = copy_definition(tmp_path / "cold")
    path = definition / "vehicle.yaml"
    text = path.read_text()
    anchor = "        supply_c: 7.2\n        # **`return_c` was this field's name until round 37"
    assert anchor in text, "the fixture no longer matches loop_primary"
    path.write_text(text.replace(anchor, "        supply_c: 1.0\n        # **`return_c` was this field's name until round 37", 1))

    result = run_linter(definition)
    assert result.returncode == 1
    assert "trip its own cabin-low alarm" in result.stdout


def test_the_cabin_relaxes_toward_supply_plus_its_own_rise(tmp_path):
    """A cabin has two heat inputs and a `lag` takes one driver — so the two are combined upstream.

    Round 55 gave the cabins a driver and introduced an 8 K error in the same move: relaxing toward
    `Q/G` *absolute* rather than `supply + Q/G`, which is wrong in the direction that makes a warm
    cabin look nominal. The fix is not a new method but a node: `cabin_eq_csm_k` and `cabin_eq_lm_k`
    are algebraic states carrying the equilibrium, fed by two edges each — the heat rate through
    `1/G` and the coolant supply through one-for-one — and the cabins relax toward them.

    **These are the vehicle's first states whose rule is completely specified**: nothing in either is
    owed, and every term comes from a declaration that already existed.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    states = {str(s["id"]): s for s in thermal["state"]}
    loops = {str(x["id"]): x for x in vehicle["thermal"]["loops"]}

    zones = {str(x["id"]): x for x in vehicle["thermal"]["zones"]}
    for zone in ("csm_cabin", "lm_cabin"):
        declared = zones[zone]
        supply_k = loops[declared["cooled_by"]]["supply_c"] + 273.15
        heat = states[declared["heat_state"]]
        cabin = states[declared["temperature_state"]]
        eq = states[declared["equilibrium_state"]]
        expected = supply_k + heat["total_w"] / cabin["conductance_w_per_k"]
        assert eq["total_k"] == pytest.approx(expected, abs=0.02), zone
        # Nothing owed: the rule's every input is a declaration that exists.
        assert "UNCONFIGURED" not in yaml.safe_dump(eq)

    # And the two cabins differ by exactly their heat loads' difference over G.
    delta = (states["cabin_heat_lm_w"]["total_w"] - states["cabin_heat_csm_w"]["total_w"]) / 125
    assert states["cabin_eq_lm_k"]["total_k"] - states["cabin_eq_csm_k"][
        "total_k"
    ] == pytest.approx(delta, abs=0.02)

    definition = copy_definition(tmp_path / "stale")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    anchor = "    total_k: 286.21\n"
    assert anchor in text, "the fixture no longer matches cabin_eq_csm_k"
    path.write_text(text.replace(anchor, "    total_k: 290.0\n", 1))

    result = run_linter(definition)
    assert result.returncode == 1
    assert "relax toward an equilibrium its own declarations do not produce" in result.stdout


def test_the_readme_status_matches_the_tools():
    """The status section is the one place every count is written down, and it had drifted.

    Three rounds of structural work moved the state count, the node count and the debt count, and
    the commit messages carried the right figures while the README kept the old ones — which is this
    folder's own recurring finding arriving at its own status section: **a declaration no tool reads
    has already drifted.** The paragraph even said "with every one of them named", about a number
    that was two out of date.

    So every figure is derived here from the tools' own output rather than from a second counter. A
    counter written for this test would be one more declaration to drift; the linter and the plant
    already compute all of them, and a test that reads their reports cannot disagree with them.
    """
    readme = (VEHICLE / "README.md").read_text()
    lint = run_linter(VEHICLE)
    assert lint.returncode == 0, lint.stdout[-1200:]
    plant = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "plant.py"), "--readiness"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    order = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "plant.py"), "--build-order"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout

    channels, edges = re.search(r"(\d+) channels, (\d+) edges,", lint.stdout).groups()
    debts = re.search(r"with (\d+) declared debt", lint.stdout).group(1)
    states, nodes = re.search(r"world: (\d+) states over (\d+) nodes", plant).groups()
    scalars = re.search(r"UNCONFIGURED scalars\s+(\d+)", plant).group(1)
    # **The figure the definition of done watches, which nothing pinned.** Every needle below is a
    # number the tools derive; the count of states the plant can actually advance was stated nowhere
    # in this file and asserted nowhere either, so it could move — and did, twice, silently. It is
    # a declaration now, in the status paragraph and in this list.
    configured = re.search(r"states fully configured\s+(\d+)", plant).group(1)
    with_debt = re.search(r"states with a debt\s+(\d+)", plant).group(1)
    # **And the definition of done's own second figure.** `--build-order`'s ready-now bucket is what
    # an implementer reads; what a tick actually does with the same corpus is printed by
    # `--readiness`, and until round 17 nothing held the two against each other anywhere outside
    # this file's own prose. The objective states the gap as its second completion criterion
    # ("today 15 versus 1"), so the number belongs in the README beside the others.
    advanced = re.search(r"(\d+) of \d+ states advanced", plant).group(1)
    # The build order is a *second* run of the tool, so its ready bucket is parsed from that.
    ready = re.search(
        r"(\d+)\s+\d+ %\s+ready now",
        subprocess.run(
            [sys.executable, str(VEHICLE / "tools" / "plant.py"), "--build-order"],
            capture_output=True,
            text=True,
            check=False,
        ).stdout,
    ).group(1)
    rule = re.search(r"(\d+)\s+\d+ %\s+owes a rule", order).group(1)

    # The sentence that carries them, and the paragraphs that restate two of them.
    for needle, what in (
        (f"{channels} channels, {states} states over {nodes} scheduled nodes", "the status line"),
        (f"with {debts} declared debts", "the debt count"),
        (f"Current state: **composes, with {debts} declared debts.**", "the header"),
        (f"**{scalars}** literal unset scalars, matching that subtotal", "the plant's scalar count"),
        (f"so {rule} of the {states} states need code", "the domain-code count"),
        (f"{states} states, by what blocks them", "the build-order view"),
        (
            f"{configured} of the {states} states are fully configured and {with_debt} carry a debt",
            "the configured-state count, which is the one the objective watches",
        ),
        (
            f"a real tick advances **{advanced}** of the {states} states, and the build order's "
            f"**{ready}** ready are that same set",
            "the tick figure, which is the objective's second completion criterion",
        ),
    ):
        assert needle in readme, f"{what} is stale: expected {needle!r} in the README"

    # Every occurrence, not just the first. The loop above pins the *presence* of the right figure,
    # and that is what let the same paragraph keep a second, stale one for eleven rounds: line 59
    # carried "223 declared debts" and line 177 carried "252", so a test satisfied by either was
    # satisfied by a file that contradicted itself. It is this folder's own finding arriving at the
    # test that exists to catch it — a check that reads the declaration it is looking for cannot see
    # the one beside it.
    #
    # A figure the README *asserts* is unquoted; a figure it *quotes* is history. The section that
    # records this very drift says *it said "… with 254 declared debts …" while the tools said 124,
    # 45 and 252* — and those are the evidence, not a claim, so the quoted spans come out first and
    # what remains is what the file is currently telling a reader.
    # And the build-order view the README embeds, which is an *output* rather than a figure and had
    # therefore drifted further than any of them: it read "12 owes a value / 36 owes an edge / 61
    # owes a rule" against the tool's 24 / 28 / 71, under a sentence promising that "`plant.py
    # --build-order` classifies every state by `advance()`'s own refusal order ... so the two cannot
    # disagree". They disagreed by ten states in one bucket and fifteen in another. An embedded
    # transcript is the most convincing thing in a README and the least likely to be re-run.
    order_view = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "plant.py"), "--build-order"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    # The four bucket lines are the block the README embeds; the "first of the N" listings below
    # them are the view's tail and are not quoted.
    buckets = [line for line in order_view.splitlines() if re.match(r"^\s+\d+\s+\d+ %", line)]
    assert len(buckets) == 4, buckets
    for line in buckets:
        assert line in readme, f"the README's build-order block is stale: missing {line!r}"

    asserted = re.sub(r'"[^"]*"', "", readme)
    written = re.findall(r"(\d+) declared debts?", asserted)
    assert written, "the README states no debt count at all"
    assert set(written) == {debts}, (
        f"the README states the debt count as {sorted(set(written))}; the linter says {debts}"
    )

    # And the tools' own prose, which is the same claim in the same shape one directory over and
    # had drifted further. `tools/plant.py` told a reader that "`check_vehicle.py` ... reports 202
    # declared debts by path" and that "the linter reports 202 debts" — both true when they were
    # written, both read by nothing since, and both 51 adrift by the time this was added. A figure a
    # reader uses to size the remaining work is exactly the figure this folder exists to keep
    # honest, and where it is written makes no difference to that.
    #
    # Only the tools are scanned, and only the `N declared debts` form: the quotation marks are
    # everywhere in Python and stripping them the way the README's scan does would mangle the text,
    # so the phrase itself is the marker. A tool that wants to record a *historical* count quotes
    # it, exactly as the README's own history section does.
    for tool in sorted((VEHICLE / "tools").glob("*.py")):
        in_tool = re.findall(r"(\d+) declared debts?", tool.read_text())
        assert set(in_tool) <= {debts}, (
            f"{tool.name} states the debt count as {sorted(set(in_tool))}; the linter says {debts}"
        )

def _in_words(n: int) -> str:
    """Enough of a number-to-words conversion for a count in the low hundreds.

    Written rather than imported because the alternative is a dependency the operator-side services
    are not allowed to have, and because the range is small and known: this file's test count, in
    the hundreds, spelled the way the reconciliation README spells it.
    """
    units = (
        "zero",
        "one",
        "two",
        "three",
        "four",
        "five",
        "six",
        "seven",
        "eight",
        "nine",
        "ten",
        "eleven",
        "twelve",
        "thirteen",
        "fourteen",
        "fifteen",
        "sixteen",
        "seventeen",
        "eighteen",
        "nineteen",
    )
    tens = ("", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety")
    if n < 20:
        return units[n]
    if n < 100:
        return tens[n // 10] + (f"-{units[n % 10]}" if n % 10 else "")
    # **The hundreds digit, which this dropped.** The first version returned a bare "hundred" for a
    # round hundred and the caller prefixed a hard-coded "One", so 200 and 100 spelled the same —
    # and this file reached exactly 200 tests, which is when an ambiguity stops being theoretical.
    # The caller no longer prefixes anything and the digit is spelled here.
    head = f"{units[n // 100]} hundred"
    if n % 100 == 0:
        return head
    return f"{head} {_in_words(n % 100)}"


def test_the_registry_coverage_claim_is_data_rather_than_a_sentence(tmp_path):
    """The last vehicle-wide count in prose, and two of its three numbers were wrong.

    Each domain has made a `coverage` claim since round 42 and each is checked against its own
    faults. The *registry's* own claim was a sentence in `channels.yaml:open_debts`, and nothing
    read it: it said twelve of the twenty-two unperturbed channels are `layer: service` where the
    policy gives fifteen of twenty, and it said faults perturb **117** `service` channels where
    they perturb 42.

    That second number is the one that matters, because it was never arithmetically possible. The
    `service` layer is 57 of the registry's 148 channels, so no split of it can reach 117 — and the
    sentence sat there through several rounds of channel additions. **A number in prose has no
    reader, and a number with no reader does not have to be plausible.** The two domain-level
    claims beside it were caught the moment they became fields; this one stayed prose for thirty
    rounds longer.

    So the numbers are data now, and this test does two things the linter's own check cannot do for
    itself: it re-derives all three from the YAML rather than trusting the report, and it proves
    the check refuses the historical value by putting it back.
    """
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    coverage = channels["coverage"]

    def flatten(name: object) -> str:
        return re.sub(r"\[[^\]]*\]", "[]", str(name))

    registry, layers = set(), {}
    for section, rows in channels.items():
        if section in {"coverage", "crew_positions", "open_debts", "defaults"}:
            continue
        if not isinstance(rows, list):
            continue
        for row in rows:
            if isinstance(row, dict) and row.get("id"):
                registry.add(flatten(row["id"]))
                layers[flatten(row["id"])] = row.get("layer")
    assert len(registry) == 148, f"the registry is {len(registry)} channels, not 148"

    perturbed = set()
    for policy_path in sorted((VEHICLE / "domains").glob("*/fault_policy.yaml")):
        policy = yaml.safe_load(policy_path.read_text())
        for fault in policy.get("faults") or []:
            perturbed.update(flatten(c) for c in fault.get("perturbs") or [])
    unperturbed = registry - perturbed

    assert coverage["unperturbed"] == len(unperturbed)
    assert coverage["unperturbed_service_layer"] == sum(
        1 for c in unperturbed if layers.get(c) == "service"
    )
    assert coverage["perturbed_service_layer"] == sum(
        1 for c in perturbed if layers.get(c) == "service"
    )
    assert coverage["provenance"]["basis"] == "derived"

    # The sentence no longer restates them, which is the half that makes the block the only source.
    prose = " ".join(str(d) for d in channels["open_debts"])
    assert "Twelve of the 22" not in prose, "the stale count is back in the prose"
    assert "117 of the channels" not in prose, "the impossible count is back in the prose"

    # And the check refuses the historical value, at the field that carried it.
    definition = copy_definition(tmp_path / "coverage")
    path = definition / "channels.yaml"
    text = path.read_text()
    broken = text.replace("perturbed_service_layer: 42", "perturbed_service_layer: 117", 1)
    assert broken != text, "the fixture no longer matches channels.yaml"
    path.write_text(broken)

    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "channels.yaml:coverage.perturbed_service_layer" in result.stdout, result.stdout[-900:]
    assert "claims 117 and the policies give 42" in result.stdout, result.stdout[-900:]


def test_a_configuration_cannot_declare_two_different_masses(tmp_path):
    """`mass_kg` and `mass_breakdown_total_kg` are one quantity, and only one of them was checked.

    The breakdown was summed against `mass_breakdown_total_kg`, and `mass_kg` went to
    `check_propulsion` as a burn's wet mass. **Nothing required the two to agree**, so a
    configuration could declare a 400 kg disagreement and compose — and the README quotes the
    unchecked one in its mass-closure table. A fleet's trajectory and its mass closure would have
    been working from two different vehicles.

    This is the same shape the folder has found four times before (the phase sum, the cabin leak,
    the bay's mass-and-conductance, the threshold's `assert`/`clear`). The difference is that here
    *both names are right* — the breakdown's total really is the configuration's mass — so the fix
    is not to collapse them into one but to make them agree.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    for cfg in vehicle["configurations"]:
        assert cfg["mass_kg"] == cfg["mass_breakdown_total_kg"], cfg["id"]
        assert sum(cfg["mass_breakdown"].values()) == cfg["mass_kg"], cfg["id"]

    definition = copy_definition(tmp_path / "mass")
    path = definition / "vehicle.yaml"
    text = path.read_text()
    broken = text.replace("mass_kg: 28807", "mass_kg: 28407", 1)
    assert broken != text, "the fixture no longer matches vehicle.yaml"
    path.write_text(broken)

    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "vehicle.yaml:configuration csm_alone" in result.stdout, result.stdout[-900:]
    assert "which are the same quantity" in result.stdout, result.stdout[-900:]


def test_an_irreversible_event_names_configurations_that_exist(tmp_path):
    """`from_configuration` and `to_configuration` say what an event irreversibly *does*, unread.

    `verb`, `arm_required` and `observable` were all checked; the two fields that say what the
    event does to the vehicle were read by nothing. Writing the join found the defect it was
    written for — `lm_ascent_jettison` ran `csm_alone -> csm_alone`, the configuration defined as
    "CSM alone *after* the LM is jettisoned" — which was only expressible because the vehicle the
    event actually begins in had no configuration at all.

    The mission spends 7.5 hours in it. `lunar_orbit_docked` is named "docked again" and declared
    `csm_alone`; `ascent_rendezvous` ended there too. All three files were individually consistent.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    declared = {c["id"] for c in vehicle["configurations"]}
    assert "csm_lm_ascent_docked" in declared, "the re-docked configuration is missing again"

    events = yaml.safe_load((VEHICLE / "domains" / "structure" / "components.yaml").read_text())[
        "one_way_events"
    ]
    by_id = {e["id"]: e for e in events}
    for event in events:
        for field in ("from_configuration", "to_configuration"):
            value = event[field]
            assert value in declared or value in {"any", "depends on the device"}, (
                event["id"],
                field,
            )

    # `lm_ascent_jettison` removes the ascent stage, so it has to begin where the ascent stage is.
    jettison = by_id["lm_ascent_jettison"]
    assert jettison["from_configuration"] == "csm_lm_ascent_docked"
    assert jettison["to_configuration"] == "csm_alone"
    # And the two phases either side of it name the same vehicle, in order.
    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    phases = {p["id"]: p["configurations"] for p in mission["phases"]}
    assert phases["ascent_rendezvous"] == ["lm_ascent_stage", "csm_lm_ascent_docked"]
    assert phases["lunar_orbit_docked"] == ["csm_lm_ascent_docked", "csm_alone"]

    # A dangling endpoint is refused, which is the check the live definition cannot demonstrate.
    definition = copy_definition(tmp_path / "endpoint")
    path = definition / "domains" / "structure" / "components.yaml"
    text = path.read_text()
    broken = text.replace("from_configuration: csm_lm_docked", "from_configuration: bogus_cfg", 1)
    assert broken != text, "the fixture no longer matches structure/components.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "bogus_cfg" in result.stdout, result.stdout[-900:]


def test_a_stock_integrates_its_level_and_carries_the_residue():
    """The integrator returned the tick's flux as the tank's new value, and never read the tank.

    `stock_flux` returns a *delta* — `sensitivity x driver x dt` — and the stock branch summed
    those deltas and returned the sum as the node's value. So a tank holding 279 kg with a drain
    became `-6.4e-06` on the first tick: **the integrator did not integrate**, in the one class
    the plant claims it can advance and `--build-order` counts as "ready now". `lag` read
    `current`; `stock` did not.

    This test is `plant.md` §4's own worked example, which is this vehicle's: a 0.0064 g/s leak
    against a 1 mg quantum is 0.128 quanta per tick at the 50 Hz tick, so *"every tick rounds to
    zero and the stock never moves"* — "the leak never happens". The Bresenham residual
    accumulator is what makes it happen exactly, and the assertion below is the one that
    distinguishes the two: over a second the level must fall by the true flow to within one
    quantum, where a quantum-only implementation loses **nothing at all**.
    """
    plant = _plant()

    def make_world():
        empty = {
            "kind": "sink",
            "domain": "x",
            "unit": "W",
        }
        stock = plant.State(
            id="o2_csm_kg",
            domain="consumables",
            node="o2_csm",
            method="stock",
            unit="kg",
            spec={"quantum": 1e-6},
        )
        sink = plant.State(id="sink", domain="x", node="sink", method="lag", unit="kg", spec={})
        edge = plant.Edge(
            id="E",
            source="o2_csm",
            target="sink",
            kind="rate",
            sensitivity={"value": 0.0064e-3, "unit": "kg/s per W"},
            drains="o2_csm_kg",
        )
        return plant.World(
            root=VEHICLE,
            states=[stock, sink],
            edges=[edge],
            back_edges=set(),
            schedule=["o2_csm"],
            nodes={
                "o2_csm": {
                    "kind": "stock",
                    "domain": "consumables",
                    "unit": "kg",
                    "preloaded": "pad",
                },
                "sink": empty,
            },
            channels={},
            frame_fields=[],
            verbs={},
        )

    world = make_world()
    dt = 0.02
    values = {"o2_csm": 279.0, "sink": 1.0}
    for _ in range(50):
        values = plant.step(world, values, dt)

    moved = 279.0 - values["o2_csm"]
    quantum = 1e-6
    assert moved > 0, "the leak never happens — the accumulator is not carrying the residue"
    assert abs(moved - 6.4e-6) <= quantum, f"moved {moved}, which is more than one quantum out"

    # The level is integrated from, not replaced: 50 ticks of 0.128 quanta cannot leave a
    # 279 kg tank within a milligram of zero, which is what returning the flux would do.
    assert values["o2_csm"] > 278.0, "the level was replaced by the flux rather than integrated"
    assert "o2_csm_kg__residual" in values, "no residue is carried between ticks"


def test_every_stock_declares_where_it_starts():
    """A stock's initial amount is what the plant integrates *from*, and nothing declared one.

    The integrator bug hid this and this hid the bug. `vehicle.yaml#consumables` carries the
    loads, `coupling.yaml`'s `preloaded` prose names them a second time, the atmosphere model
    derives the cabin oxygen from the published volume and pressure — and **no state carried a
    starting amount**, because a branch that never reads a level never asks for one.

    So every stock now declares `initial`, and a numeric one must say where it came from: either
    `initial_source`, a resolvable path into the document that declares the same number, or its
    own `initial_provenance`. A figure with neither is a guess wearing a unit.

    **And the rule reaches every integrator now, which is why two of the counts below moved.**
    `lag` and `delay` carry a value across ticks exactly as a `stock` does, and the plant answered
    for them while the configuration was silent; the round that extended the rule left the three
    groundings identical, so this test's per-stock assertions stand unchanged and only the map's
    shape grew. `test_every_integrator_declares_where_its_value_starts` is the other half.
    """
    plant = _plant()
    world = plant.load_world(VEHICLE)
    stocks = [s for s in world.states if s.method == "stock"]
    assert len(stocks) == 25, f"{len(stocks)} stocks"

    seeded = plant.initial_values(world)
    # **The map a tick starts from is no longer only what the integrators seed**, and this test is
    # about what they seed. Round 57 resolves the `algebraic` states whose rule is a declaration at
    # t=0 as well (`plant.resolve_declared_states`), so the map it returns grew by every derivable
    # state; the count below is about the *integrators* declaring where they start, so the
    # resolution is taken back out for it rather than absorbed into a stock pin. The superset is
    # asserted at the end, so a resolution that stopped happening would fail here too.
    resolver, plant.resolve_declared_states = plant.resolve_declared_states, lambda world, values: []
    try:
        seeded_integrators = plant.initial_values(world)
    finally:
        plant.resolve_declared_states = resolver
    # Sixteen stocks declare a value. **All sixteen now reach the map**, and the six that did not
    # until round 32 are the accumulators on the `internal` sentinel — `bias_accumulator`,
    # `sensor_bus_errors`, `frame_loss`, `recorder`, `pulse_residual`, `impulse_total`. They are six
    # *keys of the sentinel* rather than one shared key, which is what the sentinel means and what
    # the map could not say: it held `values["internal"]` as a single slot, so `initial_values` and
    # `step` both dropped it and six declared starting values were read by nothing.
    declared = [s for s in stocks if isinstance(s.spec.get("initial"), (int, float))]
    declared_ids = {s.id for s in declared}
    # 16 -> 18 when the two propellant stocks stopped owing their `initial`: `prop_main_kg` is
    # the SPS's load and `prop_rcs_kg` the three RCS loads summed, both `derived` now. 18 -> 24
    # when the two cabins' six gas stocks landed behind them: four `derived` from a declared partial
    # pressure and two `derived` as exactly zero, which is what `atmosphere_model.check` says the
    # nitrogen is. The two oxygens were already declared and *moved* rather than closed — they are
    # the remainder of the cabin's total now — so they are not part of the six. 24 -> 25 when the
    # helium charge landed from the Operational Data Book's loading table (round 13), which is the
    # last stock in the corpus whose `initial` was owed to a document nobody had opened.
    assert len(declared) == 25, f"{len(declared)} stocks declare a numeric initial"
    on_nodes = {k: v for k, v in seeded_integrators.items() if k != "internal"}
    # 10 -> 12 with `prop_main` and `prop_rcs`: the two stocks whose `initial` was owed because
    # nothing said which tanks the nodes were. Both carry their loads now. **The six cabin gases
    # round 8 landed do not move this count**, which is the map's own shape showing: `cabin_atm` and
    # `lm_cabin_atm` were already keys because each node's *oxygen* was declared, and four stocks
    # share each of those keys, so the map holds the last of them and six new values are invisible
    # here. The per-stock figures are the round-8 closure test's business rather than this count's.
    # **Round 22's key space: a state key for every stock, a node key only where the node is
    # single-state.** So this counts node keys, and the number it counts is no longer the number of
    # stocks: thirteen nodes carry one stock each and keep their node key, the rest are states on
    # shared nodes and are addressable by state id alone.
    # **36 -> 52 and 6 -> 9 when the rule was widened from `stock` to `INTEGRATOR_METHODS`.** The
    # map is now the seed of every integrator, not of every tank: sixteen more node keys (the two
    # cabin zones, the coolant supply, the transport delay, the fuel-cell converter, the main thrust
    # and the rest) and three more sentinel entries (`gyro_bias`, `dps_throttle_pct` and
    # `chamber_pressure_pct`, which are lags on the `internal` node — the other seven lags that
    # declare `UNCONFIGURED` are owed, and an owed value is not a seeded one).
    # 52 -> 53 in round 32: the oxygen supply tank's pressure state, whose own id is a key of this
    # map beside the sentinel's sub-map — which is what `on_nodes` counts, node aliases *and* every
    # state id that is not the sentinel's own name.
    # 53 -> 54 in round 33: `suit_loop_flow_cfm` is seeded at the ECS guide's 35 cfm, so its own id
    # joins this map beside the sentinel's sub-map.
    # 55 -> 56 in round 67: `relief_valve_state`, the one commanded mode whose starting position
    # the corpus could source. It is a sentinel state, so it is seeded under its own id *and* in
    # the sentinel's sub-map — and this counts the ids beside the sub-map, which is why one state
    # moves the figure by one.
    # 56 -> 57 in round 70, with `source_converter`: the regulator's node is a node like any
    # other, and its state being seeded is what makes the cell's node single-state again.
    # 57 -> 60 in round 75: the three states the effect path owns through a one-way event, which
    # are seeded now that they declare the position they hold.
    # 60 -> 65 in round 76: the four machines `mission.yaml#launch_state` settles, whose node
    # keys are seeded now that they hold a position.
    # 65 -> 69 in round 80: the three positions the launch checklist publishes. **Four keys for
    # three states**, and the arithmetic is the map's own shape rather than a mistake —
    # `bus_tie_closed` is the only state on `bus_tie`, so it seeds the node alias *and* its own id,
    # while `telemetry_rate` and `antenna_selection` are sentinel states and seed under their ids
    # alone.
    # P00 computer mode and CMC-owned RCS mode each add a seeded state key.
    assert len(on_nodes) == 74, f"{len(on_nodes)} node keys carry a value"
    # And the map a tick actually starts from is that seed plus the declared arithmetic, so the
    # resolved states are a strict superset and every one of them is `algebraic`.
    assert seeded_integrators.keys() < seeded.keys(), "the resolution added nothing to the seed"
    resolved = set(seeded) - set(seeded_integrators)
    assert all(s.method == "algebraic" for s in world.states if s.id in resolved), sorted(resolved)
    assert "fc_o2_draw_kg_s" in resolved and "fc_h2_draw_kg_s" in resolved
    # 12 -> 13 in round 67, with `relief_valve_state`: the sentinel gains a *mode* beside its
    # twelve accumulators, which is the same one state the node-key count above moved for and a
    # different map — this one is the sub-map rather than the ids beside it.
    # 13 -> 15 in round 80: `telemetry_rate` and `antenna_selection` are sentinel states with a
    # position now, so they join this sub-map as well as the ids beside it.
    assert len(seeded_integrators["internal"]) == 18, sorted(seeded_integrators["internal"])
    # Six of the sentinel's `algebraic` states resolve at t=0 as well — the bus load, the bay heat,
    # the cabin pressure differential and three more — so the sentinel's sub-map is the same map the
    # tick commits, merged rather than replaced.
    assert len(seeded["internal"]) == 24, sorted(seeded["internal"])
    # The map is keyed by node and holds one value per key, so this is **not** a stock count and
    # stopped being one in round 8: four stocks share `cabin_atm` and four share `lm_cabin_atm`, so
    # six of the twenty-four declared values are the last of their key rather than a key of their
    # own. The invariant that survives is that every declared stock's *node* is a key — nothing a
    # stock declares is dropped by the map's shape — and that the sentinel is keyed by state id.
    # **Round 22 changed what the map's keys are.** They are state ids now, plus a node alias where
    # the node carries one state — so a *stock* is always addressable by its own id, and a stock on a
    # shared node is addressable *only* that way: `cabin_atm` is no longer a key at all, which is the
    # fix rather than a loss. The invariant that survives is the one that matters: every declared
    # stock has an entry under its own id.
    assert declared_ids <= set(seeded), sorted(declared_ids - set(seeded))
    assert {"cabin_atm", "lm_cabin_atm"} & set(seeded) == set(), (
        "a node carrying four gas stocks must not be a key: one value cannot mean four"
    )
    # The ones the corpus can supply, and the numbers it supplies them with. The last is the
    # battery's charge, which stopped being owed in this round: 3,360 Wh of entry cells times
    # 3,600, which is the same energy `check_power_inventory` holds against the cells' own
    # `ah x v_nominal`.
    for node, expected in (
        ("o2_csm", 279.0),
        ("o2_lm", 24.1),
        ("h2_csm", 24.5),
        ("water_potable", 14.0),
        ("water_cooling", 13.0),
        # **0 since round 33, and that is the point of the pair.** These are consumption counters
        # (the node's own `accumulates` says they count man-hours *spent*), so they start at nothing
        # spent; they carried the *rating* here, sourced from the same node's `exhausted_at`, which
        # is the equality round 33 removed.
        ("absorber_capacity_csm", 0.0),
        ("absorber_capacity_lm", 0.0),
        ("battery_energy", 12096000.0),
    ):
        assert seeded[node] == expected, node
    # The sentinel IS seeded, as a map keyed by state id — the six accumulators, plus the lags that
    # live here and declare a starting value of their own. The accumulator key existing at all is the
    # point: a command that writes one of them needs a place to put the value, and before that round
    # there was none. Several of the lags happen to be zero, one is the oxygen supply tank's 900 psig
    # and one is the suit circuit's 35 cfm, and the values assertion below cannot tell those reasons
    # apart — an accumulator starts at zero because that is what an accumulator is; a supply pressure
    # starts at 900 because `csm_ecs_study_guide.pdf` p. 12 says so; and a suit loop starts at 35
    # because p. 39 says so. Which is which is the *declaration's* business, and this is the map's.
    assert set(seeded_integrators["internal"]) == {
        "bias_accumulator",
        "sensor_bus_errors",
        "frame_loss",
        "recorder",
        "pulse_residual",
        "impulse_total",
        "gyro_bias",
        "o2_supply_pressure_psi",
        "suit_loop_flow_cfm",
        "dps_throttle_pct",
        "chamber_pressure_pct",
        # Round 52: the first `dynamics` state the seeder seeds. It is a third *kind* of sentinel
        # value — not an accumulator's origin and not a published constant, but the zero an
        # integrator has to start from — and it is listed here rather than folded into either.
        "accumulated_dv_m_s",
        # Round 67: the fourth kind, and the one this list could not have anticipated — a *mode*
        # rather than a level. `relief_valve_state` is `auto` because the source that gives its
        # three members also says the valve is normally closed, and it is here rather than in a
        # list of its own because the sentinel's sub-map does not care what shape a value has.
        "relief_valve_state",
        # Round 80: two more modes, and the first ones here whose position comes out of a published
        # launch checklist rather than a decision — the `low` telemetry profile's 1,600 bit/s and
        # the selected high-gain antenna after extraction.
        "telemetry_rate",
        "antenna_selection",
        # Round 81: the link mode that carries that profile, which is `derived` from it rather
        # than read out of the checklist a second time.
        "comm_mode",
        # Post-ejection P00 and the active CMC DAP are separate seeded modes.
        "computer_mode",
        "mode",
    }, sorted(seeded_integrators["internal"])
    # **And the six `algebraic` states the resolver adds**, the sentinel's half of the declared
    # arithmetic: the bus load, the bay heat rate, the cabin pressure differential, the two loops'
    # collected loads and the RCS propellant estimate. They are values a tick computes and a seed
    # cannot, which is why the map a tick starts from is a strict superset of what it seeds.
    assert set(seeded["internal"]) == set(seeded_integrators["internal"]) | {
        "bus_a_load_w",
        "avionics_bay_heat_w",
        "cabin_dp_psi",
        "loop_primary_load_w",
        "loop_lm_load_w",
        "propellant_estimate",
    }
    # Zero everywhere except the supply tank's pressure, which is the one seeded sentinel value that
    # is not an accumulator's origin — and, from round 67, `auto`, which is not a number at all and
    # is the reason the value assertions below name their states rather than ranging over the map.
    assert set(seeded_integrators["internal"].values()) == {
        0.0,
        35.0,
        900.0,
        "auto",
        # Round 80's two, and they are the first pair here that is a *reading* rather than a
        # constant or an origin: the checklist's `PCM BIT RATE - LOW` and `S BD ANT OMNI - HI GAIN`.
        1600,
        "high_gain",
        # Round 81's, and it is the profile's other half — the link mode the rate travels on.
        "sband_low",
        "idle",
    }
    assert seeded["internal"]["o2_supply_pressure_psi"] == 900.0
    assert seeded["internal"]["suit_loop_flow_cfm"] == 35.0

    # Every numeric initial is grounded, and every `initial_source` resolves and agrees — through
    # `initial_factor` where the source is published in other units than the state integrates.
    # Two widenings here, both of them the same defect one level down: the walk is the linter's own
    # `resolve_dotted` rather than a second copy of it, and the documents are every document the
    # corpus has rather than the two this assertion was written against. The battery is why — its
    # charge is stated in the *power* domain's load budget, which is neither `vehicle.yaml` nor
    # `coupling.yaml`, so the narrow version would have read a resolvable link as a broken one.
    linter = _linter()
    documents: dict[str, object] = {}
    # **`plant.corpus_files` rather than `VEHICLE.rglob("*.yaml")`**, which is not the corpus: the
    # round law plants broken copies under `.scratch/rNN/`, and a broken copy is a corpus-shaped tree.
    # See that function's docstring — sixteen rounds of fixtures were read here as the vehicle.
    for path in _plant().corpus_files(VEHICLE):
        documents[str(path.relative_to(VEHICLE))] = yaml.safe_load(path.read_text()) or {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        components = documents[str(path.relative_to(VEHICLE))]
        assert isinstance(components, dict)
        for state in components.get("state") or []:
            if state.get("method") != "stock":
                continue
            assert "initial" in state, f"{state['id']} declares no initial condition"
            if state["initial"] == "UNCONFIGURED":
                assert state.get("initial_note"), f"{state['id']} is owed with no note"
                continue
            source = state.get("initial_source")
            assert source or state.get("initial_provenance"), (
                f"{state['id']} declares {state['initial']!r} with no grounding"
            )
            if not source:
                continue
            filename, dotted = source.split(":", 1)
            assert filename in documents, f"{state['id']} names {filename!r}, which is not loaded"
            node = linter.resolve_dotted(documents[filename], dotted)
            factor = state.get("initial_factor", 1)
            resolved = float(node) * float(factor)
            assert abs(resolved - float(state["initial"])) < 1e-9, (
                f"{state['id']} says {state['initial']} and {source} x {factor} says {resolved}"
            )


def test_the_linter_refuses_a_stock_initial_whose_source_stopped_agreeing(tmp_path):
    """The link from a stock's starting amount back to the declaration it came from, end to end.

    The assertion above holds the corpus; this holds the check. Every surface of that link had
    gone unexercised — `check_initial_sources` was written with the initial conditions and no test
    ever broke one — which matters more for this idiom than for most, because the whole point of
    `initial_source` is that it is *not* a provenance note: it is the other declaration, resolvable
    and comparable, and a check whose refusals are never fired is a check whose silence means
    nothing. `initial_factor` is the newest link in it: a source published in watt-hours against a
    state that integrates joules, where the honest alternatives were a conversion or a debt.
    """

    def refusal(name: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(tmp_path / name)
        path = definition / "domains" / "power" / "components.yaml"
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1500:]}"

    # The two declarations drift apart, which is the failure the field exists to catch.
    refusal(
        "drift",
        "    initial: 12096000\n",
        "    initial: 12000000\n",
        "One of the two is the load and the other is a copy of it",
    )
    # Dropped, the conversion is gone and the source is read as joules: 3,360 J of charge.
    refusal(
        "dropped",
        "    initial_factor: 3600\n",
        "",
        "resolves to 3360. One of the two is the load",
    )
    # Wrong, and the message says which factor it used — so the reader can see the error is the
    # conversion rather than the source.
    refusal(
        "wrong-factor",
        "    initial_factor: 3600\n",
        "    initial_factor: 60\n",
        "times `initial_factor: 60`",
    )
    # Not a number to convert with, in both of the ways a number can fail to be one.
    refusal(
        "factor-text",
        "    initial_factor: 3600\n",
        "    initial_factor: sixty\n",
        "which is not a number to convert a source with",
    )
    refusal(
        "factor-zero",
        "    initial_factor: 3600\n",
        "    initial_factor: 0\n",
        "is 0, which is not a number to convert a source with",
    )
    # The path itself: a document the check cannot load, a key the document does not have, and a
    # value that is not a number. Each is a link that has stopped linking.
    refusal(
        "no-document",
        "domains/power/components.yaml:load_budget.csm_battery_energy_wh",
        "domains/power/nowhere.yaml:load_budget.csm_battery_energy_wh",
        "the documents this check can resolve are",
    )
    refusal(
        "no-key",
        "domains/power/components.yaml:load_budget.csm_battery_energy_wh",
        "domains/power/components.yaml:load_budget.csm_battery_energy_j",
        "has no 'load_budget.csm_battery_energy_j'",
    )
    refusal(
        "not-a-number",
        "domains/power/components.yaml:load_budget.csm_battery_energy_wh",
        "domains/power/components.yaml:load_budget.provenance",
        "which is not a number to compare an initial against",
    )
    # And the form, which is the one refusal a reader can fix without opening a second file.
    refusal(
        "no-document-named",
        "domains/power/components.yaml:load_budget.csm_battery_energy_wh",
        "load_budget.csm_battery_energy_wh",
        "which names no document. The form is `<file>.yaml:<dotted.path>`",
    )


def test_every_discrete_state_says_what_moves_it(tmp_path):
    """Forty-three states declared their vocabulary and their guard and not what changes them.

    The gap is not academic and the corpus says so in as many words — `domains/crew/` carries a debt
    reading *"Nothing declares what moves the crew. `crew_location` can take `surface_eva` and
    `crew_availability` can take `suit`, and no verb writes either"* — and that debt was the only
    place the question was asked, for forty-three states.

    **It is also not derivable, which is worth recording because I tried.** A verb's `gate` or
    `conflict_domain` names the state in **three** cases out of forty-three. And overlapping enum
    *values* are actively misleading: `bus_tie_closed` shares `open`/`closed` with
    `set_hatch_valve`, so the rule would have the hatch moving the bus tie. The declaration is an
    author's judgement and the linter's job is to check it rather than to invent it.

    Three movers, and the third is most of them. `command:<verb>` is a verb — **possibly of another
    domain**, since three of the movers cross: the crew's breaker panel is written by `power`'s
    `set_breaker`. `event:<id>` is a declared `one_way_event`. And `logic:<reason>` is the vehicle's
    own machinery — FDIR conclusions, the undervoltage ladder, a geometric occultation.

    The rule that draws the line between the first and the third is that **a `command:` mover has to
    be able to say the value it is said to set**. `request_imu_alignment` takes reference frames and
    `imu_alignment` takes `unaligned/aligning/aligned/drifted`: the verb starts an alignment the
    vehicle then drives, so it is a trigger and the mover is `logic` with the verb named in the
    reason. Three of my own classifications failed that rule and had to be rewritten.
    """
    verbs = {}
    for path in sorted((VEHICLE / "domains").glob("*/commands.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for verb in doc.get("commands") or []:
            verbs[str(verb["verb"])] = verb

    states = 0
    commands = events = logic = triggers = 0
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        events_here = {str(e["id"]) for e in doc.get("one_way_events") or []}
        for state in doc.get("state") or []:
            if state.get("method") != "discrete":
                continue
            states += 1
            movers = state.get("moved_by")
            assert movers is not None, f"{state['id']} declares no mover"
            if movers == "UNCONFIGURED":
                assert state.get("moved_by_note"), state["id"]
                continue
            assert isinstance(movers, list) and movers, state["id"]
            for mover in movers:
                kind, _, name = str(mover).partition(":")
                if kind == "command":
                    commands += 1
                    assert name in verbs, (state["id"], name)
                    offered = set()
                    for argument in (verbs[name].get("argument_schema") or {}).values():
                        if isinstance(argument, dict) and argument.get("type") == "enum":
                            offered.update(str(v) for v in argument.get("values") or [])
                    values = set()
                    for match in re.findall(r"enum\[([^\]]*)\]", str(state.get("unit") or "")):
                        values.update(v.strip() for v in match.split(","))
                    # A state with no vocabulary — `telemetry_rate` is `bit/s` — has nothing to
                    # overlap with, so the verb only has to be the plausible writer. That is the
                    # linter's rule too: the overlap is required *where there are values*.
                    if values:
                        assert values & offered, (state["id"], name)
                elif kind == "trigger":
                    # A verb that *starts* the state without being able to set it, which is the
                    # whole of the kind — so the vocabulary test is required to **fail**, and a
                    # trigger whose arguments reach the state's values would be a `command:` that
                    # had opted out of the rule holding it to what it claims to write.
                    triggers += 1
                    assert name in verbs, (state["id"], name)
                    offered = set()
                    for argument in (verbs[name].get("argument_schema") or {}).values():
                        if isinstance(argument, dict) and argument.get("type") == "enum":
                            offered.update(str(v) for v in argument.get("values") or [])
                    values = set()
                    for match in re.findall(r"enum\[([^\]]*)\]", str(state.get("unit") or "")):
                        values.update(v.strip() for v in match.split(","))
                    if values:
                        assert not (values & offered), (state["id"], name, sorted(values & offered))
                elif kind == "event":
                    events += 1
                    assert name in events_here, (state["id"], name)
                elif kind == "logic":
                    logic += 1
                    assert len(name.strip()) >= 12, (state["id"], mover)
                    # A verb named in the reason is a declaration in a sentence, and five of these
                    # were exactly that until `trigger:` gave them a form the linter resolves.
                    named = [t for t in re.findall(r"`([^`]+)`", name) if t in verbs]
                    assert not named, (state["id"], named)
                else:
                    raise AssertionError((state["id"], mover))
    assert states == 43, states
    assert (commands, triggers, events, logic) == (17, 5, 6, 23), (
        commands, triggers, events, logic,
    )
    # Two states still owe it, and they are the two the crew debt names.
    owed = {
        state["id"]
        for path in sorted((VEHICLE / "domains").glob("*/components.yaml"))
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []
        if state.get("moved_by") == "UNCONFIGURED"
    }
    assert owed == {"crew_location", "crew_availability"}, owed

    definition = copy_definition(tmp_path / "movers")
    path = definition / "domains" / "rcs" / "components.yaml"
    text = path.read_text()
    broken = text.replace("command:set_rcs_mode", "command:set_rcs_quad", 1)
    assert broken != text, "the fixture no longer matches rcs/components.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "cannot express the value" in result.stdout, result.stdout[-900:]


def test_the_adversarys_ids_and_rates_are_validated(tmp_path):
    """Two more fields on the 128 faults that composed under mutation.

    **Fault ids are unique across the whole vehicle, because they key the randomness.** `faults.py`
    derives every stochastic stream from `(master_seed, domain, component_id, purpose)` and
    `--check` asserts that name-keying holds — *"no existing fault's events moved"* is the property
    that makes a run reproducible when a fault is added. Two faults sharing an id would take the
    same stream: their draws would be the same numbers in the same order, and a vehicle with two
    faults would behave like a vehicle with one of them applied twice.

    **`seeding.unit` is a one-word vocabulary declared 66 times and validated nowhere.** It is the
    rate's *time basis*, and `faults.py` scales the hazard by it across the mission's ladder — so
    `per_hour`, which reads like `per_h`, is a silent change of rate rather than a refusal.
    """
    import collections

    ids = collections.Counter()
    units = collections.Counter()
    faults = 0
    for path in sorted((VEHICLE / "domains").glob("*/fault_policy.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for fault in doc.get("faults") or []:
            faults += 1
            ids[fault["id"]] += 1
            seeding = fault.get("seeding") or {}
            if "hazard" in seeding:
                units[str(seeding.get("unit"))] += 1
    assert faults == 128, faults
    assert set(ids.values()) == {1}, [i for i, n in ids.items() if n > 1]
    assert set(units) == {"per_h"}, dict(units)

    definition = copy_definition(tmp_path / "faults")
    path = definition / "domains" / "gnc" / "fault_policy.yaml"
    text = path.read_text()
    broken = text.replace("unit: per_h", "unit: per_hour", 1)
    assert broken != text
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "seeding.unit" in result.stdout, result.stdout[-900:]

    # A duplicate id **across two domains**, which is the case a per-domain check would miss.
    definition = copy_definition(tmp_path / "collide")
    path = definition / "domains" / "avionics" / "fault_policy.yaml"
    text = path.read_text()
    broken = text.replace("id: AVI-01-instrumentation-power", "id: GNC-01-imu-drift", 1)
    assert broken != text
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "declared again" in result.stdout, result.stdout[-900:]


def test_a_points_layer_is_the_registrys_layer(tmp_path):
    """`layer` is declared twice per channel and only the registry's copy was checked.

    The registry validates its own — a channel with a layer outside
    `{measurement, estimate, service}` is refused, and so is one with no layer at all — and each
    domain's `points.yaml` repeats the field for the same channel with **nothing comparing the
    two**. That is round 79's `mass_kg` exactly: one quantity declared twice with only one of the
    two read, except that here it is the *copy* that is unchecked.

    What a disagreement decides is not cosmetic, and `presentation.yaml` says so — a service state
    is layer A with a different subject, and the mapping *"decides whether a commanded valve
    position carries a quality code."* A domain that marked a service channel as a measurement
    would put a SUSPECT code on a statement of what the vehicle did, and a fleet would go looking
    for a sensor fault in `rcs.mode`.

    The mapping's keys are the third declaration of the same vocabulary, and it is checked against
    the registry too: a layer with no mapping is a kind of channel the contract has no layer for.
    """
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    registered = {}
    for rows in channels.values():
        if not isinstance(rows, list):
            continue
        for row in rows:
            if isinstance(row, dict) and row.get("id") and row.get("layer"):
                registered[str(row["id"])] = str(row["layer"])
    assert len(registered) == 148, len(registered)
    assert set(registered.values()) == {"measurement", "estimate", "service"}

    points = 0
    for path in sorted((VEHICLE / "domains").glob("*/points.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for row in doc.get("points") or []:
            cid = str(row["channel"])
            points += 1
            # Every point names a channel the registry knows, and restates its layer.
            if cid in registered:
                assert row["layer"] == registered[cid], (cid, row["layer"], registered[cid])
            else:
                # A template instantiation; its layer must still be one of the three.
                assert row["layer"] in set(registered.values()), (cid, row["layer"])
    assert points == 142, points

    mapping = yaml.safe_load((VEHICLE / "presentation.yaml").read_text())["epistemic_layers"][
        "mapping"
    ]
    assert set(mapping) == set(registered.values())

    definition = copy_definition(tmp_path / "layer")
    path = definition / "domains" / "avionics" / "points.yaml"
    text = path.read_text()
    broken = text.replace("layer: service", "layer: measurement", 1)
    assert broken != text, "the fixture no longer matches avionics/points.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert ".layer" in result.stdout, result.stdout[-900:]


def test_the_postures_transitions_and_objectives_are_validated(tmp_path):
    """The blocks that decide what the strike is — swept the way the command registry's were.

    Mutating each field in turn left six that composed, and they are the fields a *challenge* turns
    on: a posture is what a fleet is authorized to do, a transition is the guard that moves it, and
    an objective is the score. A hole in these is a hole in the experiment rather than in a
    subsystem.

    The transition strings are parsed rather than matched, because two of the five are not a plain
    `A -> B`: `execute -> hold on stale evidence` appends the *reason* to the target and
    `any -> aborting` has no source posture. So the source must be `any` or a declared posture, and
    the target's **first word** must be one — which accepts both forms and still refuses
    `safe -> standbye`.

    `requires` must be *present* and may be empty. `any -> aborting` declares `{}` with the best
    sentence in the block: *"Abort requires no fresh evidence because requiring it would make the
    abort conditional on the very instrumentation whose failure is a reason to abort."* A
    present-but-empty list is that decision; an absent one is indistinguishable from an oversight —
    the same distinction `interlocks: none` draws for a command.

    And `channels` may be empty **only** when `evaluated_by` is `external`, which is the case the
    check found live: `coordination` is "twenty metrics, computed externally and never shown to the
    fleet" and declares no channels at all. `far_side` is not an exemption — the corpus says what
    the vehicle owes the operator's verdict is *the record*.
    """
    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    postures = [p["id"] for p in mission["postures"]]
    assert len(postures) == len(set(postures)) == 10, postures
    assert all(isinstance(p["terminal"], bool) for p in mission["postures"])

    for row in mission["transition_evidence"]:
        source, _, target = row["transition"].partition("->")
        assert source.strip() == "any" or source.strip() in postures, row["transition"]
        assert target.strip().split()[0] in postures, row["transition"]
        assert "requires" in row, row["transition"]

    objectives = mission["objectives"]
    ids = [o["id"] for o in objectives]
    assert len(ids) == len(set(ids)) == 9, ids
    for objective in objectives:
        assert objective["kind"] in {"outcome", "margin", "research"}, objective["id"]
        if objective["kind"] == "margin":
            assert objective["sense"] in {"higher_is_better", "closest_to_limit"}, objective["id"]
        if not objective.get("channels"):
            assert objective["evaluated_by"] == "external", objective["id"]

    for old, new, expect in (
        ('"safe -> standby"', '"safe -> standbye"', "arrives at"),
        (
            "    requires:\n      mission.abort_latched",
            "    requires_off:\n      mission.abort_latched",
            ".requires",
        ),
        ("channels: [crew.available]", "channels: []", "is empty and"),
        ("kind: outcome", "kind: outcomee", "crew_survive.kind"),
    ):
        definition = copy_definition(tmp_path / expect.replace(" ", "_").replace(".", "_"))
        path = definition / "mission.yaml"
        text = path.read_text()
        broken = text.replace(old, new, 1)
        assert broken != text, f"the fixture no longer matches {old!r}"
        path.write_text(broken)
        result = run_linter(definition)
        assert result.returncode == 1, (expect, result.stdout[-700:])
        assert expect in result.stdout, (expect, result.stdout[-700:])


def test_every_field_a_command_declares_is_validated(tmp_path):
    """Found by mutating each field in turn and watching which mutations composed.

    Five of the fourteen fields on the fifty-eight verbs were unvalidated, and every one is *read*
    by something, which is what makes them worth checking. `execution_class` decides whether a
    command may be held for a due time; `maximum_queue_age_s` decides when it expires;
    `allowed_phases` decides which phases offer the verb; `help` is the whole of what a fleet is
    told; and `gate.kind` is **read by nothing at all**.

    The sharpest is `execution_class`: three tools compare it against the literal `deferred`, so
    `defered` does not fail a build — it makes a deferrable verb take effect in the tick it is
    accepted. And `allowed_phases` *absent* composed, which is not the same as one naming every
    phase: the availability check can tell the difference and a reader cannot.
    """
    phases = {
        str(p["id"]) for p in yaml.safe_load((VEHICLE / "mission.yaml").read_text())["phases"]
    }
    verbs = 0
    for path in sorted((VEHICLE / "domains").glob("*/commands.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for verb in doc.get("commands") or []:
            verbs += 1
            where = f"{path.parent.name}/{verb['verb']}"
            assert verb.get("execution_class") in {"declarative", "deferred", "armed"}, where
            age = verb.get("maximum_queue_age_s")
            assert isinstance(age, (int, float)) and age > 0, where
            allowed = verb.get("allowed_phases")
            assert isinstance(allowed, list) and allowed, where
            assert set(map(str, allowed)) <= phases, where
            assert (verb.get("gate") or {}).get("kind") == "preference", where
            assert str(verb.get("help") or "").strip(), where
    assert verbs == 58, f"{verbs} verbs"

    for old, new, expect in (
        ("execution_class: declarative", "execution_class: defered", "execution_class"),
        ("maximum_queue_age_s: 60", "maximum_queue_age_s: 0", "maximum_queue_age_s"),
        ("kind: preference", "kind: service_owned", "gate.kind"),
    ):
        definition = copy_definition(tmp_path / expect.replace(".", "_"))
        path = definition / "domains" / "gnc" / "commands.yaml"
        text = path.read_text()
        broken = text.replace(old, new, 1)
        assert broken != text, f"the fixture no longer matches {old!r}"
        path.write_text(broken)
        result = run_linter(definition)
        assert result.returncode == 1, (expect, result.stdout[-700:])
        assert expect in result.stdout, (expect, result.stdout[-700:])


def test_a_command_cannot_be_grouped_under_a_domain_of_its_own(tmp_path):
    """`conflict_domain` says which commands must not both take effect in one tick, unvalidated.

    The console expands the field and the first valid command in a domain wins, so a typo does not
    fail — it makes the command's collisions silently stop happening and two contradictory orders
    are both accepted. The console already knows: `conflict_domains` falls back to the literal text
    when a template will not expand, with the comment that *"a domain that cannot be expanded is a
    domain nothing can collide in, which is worse than a wrong one."* A fallback at runtime is what
    the linter is for at build time.

    **Four verbs had the defect the gate check was written for and did not reach.**
    `power.source_<id>`, `power.contactor_<id>`, `power.load_<id>` and `power.breaker_<id>` name
    `id`, and their arguments are called `source`, `battery`, `load` and `breaker` — the same eight-
    verb class round 43 recorded when it fixed the *gate* templates and left the conflict domains
    beside them, because the check was written for the field rather than for the defect.

    The effect was over-broad rather than under-broad, which is why nothing noticed: an
    unexpandable template falls back to its literal text, so **every** `set_source` shared one
    conflict domain no matter which source it named, and two commands touching different sources
    in one tick refused each other.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import check_vehicle as linter

    allowed = set(linter.DOMAINS) | set(linter.PREFIX_DOMAIN)
    seen = 0
    for path in sorted((VEHICLE / "domains").glob("*/commands.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for verb in doc.get("commands") or []:
            conflict = str(verb.get("conflict_domain") or "")
            assert conflict, f"{path.parent.name}/{verb['verb']} declares no conflict_domain"
            assert conflict.split(".")[0] in allowed, (verb["verb"], conflict)
            for placeholder in re.findall(r"<([^>]+)>", conflict):
                spec = (verb.get("argument_schema") or {}).get(placeholder)
                assert isinstance(spec, dict) and spec.get("type") == "enum", (
                    verb["verb"],
                    conflict,
                    placeholder,
                )
            seen += 1
    assert seen == 58, f"{seen} verbs"

    # Both spellings of a domain are legitimate — `PREFIX_DOMAIN` exists so a reference may be
    # qualified by the directory or by the channel prefix, and the corpus uses both.
    assert "res" in linter.PREFIX_DOMAIN and "prop" in linter.PREFIX_DOMAIN
    assert "comms" in linter.DOMAINS and "comm" in linter.PREFIX_DOMAIN

    definition = copy_definition(tmp_path / "conflict")
    path = definition / "domains" / "gnc" / "commands.yaml"
    text = path.read_text()
    broken = text.replace("conflict_domain: gnc.guidance", "conflict_domain: gncz.guidance", 1)
    assert broken != text, "the fixture no longer matches gnc/commands.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "neither a domain directory" in result.stdout, result.stdout[-900:]


def test_the_acceleration_ceiling_is_a_property_of_two_sets(tmp_path):
    """`uncommanded_acceleration`'s limit is the largest acceleration the thrust can explain.

    `apollo_diode.md:210`'s event on this channel is exactly "uncommanded impulse", and the entry
    held two different accounts of what its value *is*: `point_units` says "the largest component
    the configured thrust can explain", while the note said the value "is owed — it needs a noise
    floor and the smallest impulse the vehicle can produce ... the minimum impulse bit that
    `domains/rcs/` records as unpublished". Those are different questions. The ceiling is derivable
    from data the corpus already declares — every engine's thrust and every configuration's mass —
    and the impulse bit sizes the *detectability*, which is a separate obligation already counted
    where it lives.

    The statistic is computed rather than quoted for a reason worth keeping: it is the **LM ascent
    engine on the ascent stage alone**, 15,569 N against 4,888 kg = 0.32479 g, and it wins by a hair
    over the CSM's own 0.32279 g with the LM gone. A reader who guessed which of the two it was
    would be 0.6 % wrong, in the direction that misses the event.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    propulsion = yaml.safe_load(
        (VEHICLE / "domains" / "propulsion" / "components.yaml").read_text()
    )
    engines = {
        c["id"]: c.get("thrust_n") or c.get("thrust_max_n")
        for c in propulsion["components"]
        if c.get("class") == "engine"
    }
    assert set(engines) == {"sps", "dps", "aps"}
    stage = {"sps": "csm_", "dps": "lm_descent_", "aps": "lm_ascent_"}
    best, winner = 0.0, None
    for engine, thrust in engines.items():
        for cfg in vehicle["configurations"]:
            if not any(k.startswith(stage[engine]) for k in cfg["mass_breakdown"]):
                continue
            accel = thrust / cfg["mass_kg"] / 9.80665
            if accel > best:
                best, winner = accel, f"{engine} on {cfg['id']}"
    assert winner == "aps on lm_ascent_stage", winner
    assert abs(best - 0.32479) < 5e-5, best
    # And the CSM's own ceiling is a hair below it, which is why the figure is computed.
    sps_alone = engines["sps"] / 28807 / 9.80665
    assert sps_alone < best and best - sps_alone < 0.005

    structure = yaml.safe_load((VEHICLE / "domains" / "structure" / "profiles.yaml").read_text())
    threshold = next(t for t in structure["thresholds"] if t["id"] == "uncommanded_acceleration")
    assert threshold["derives_from"] == "vehicle.yaml:max_explainable_acceleration_g"
    assert abs(threshold["assert"] - best) < 1e-3 * best, threshold["assert"]
    # The two accounts of what the value is are separated now, and the note says so.
    assert "detectability" in threshold["provenance"]["note"]

    # Weakening the ascent engine moves the ceiling to the CSM's figure — a 0.63 % change that the
    # one-per-cent tolerance this check first copied from `rederive` accepted in silence.
    definition = copy_definition(tmp_path / "thrust")
    path = definition / "domains" / "propulsion" / "components.yaml"
    text = path.read_text()
    broken = text.replace("thrust_n: 15569", "thrust_n: 12569", 1)
    assert broken != text, "the fixture no longer matches propulsion/components.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "0.322789" in result.stdout, result.stdout[-900:]


def test_a_limit_that_is_a_property_of_the_registry_is_re_derived(tmp_path):
    """`sensor_stale`'s limit is twice the slowest publish period, and the registry says which.

    The threshold's own reason says the value "cannot be a constant and is therefore a function of
    the active profile", and that each *point* has its own limit of one publish period while this
    is the aggregate's at twice the slowest. So the number was derivable all along from
    `channels.yaml` — 0.05 Hz is the slowest publishing channel, one per 20 s, and twice that is
    40,000 ms. Channels at `rate_hz: 0` are published on change and have no period to be stale
    against, which is why the source is the slowest *positive* rate.

    `channels.yaml` is not a document with that key in it, so the linter **computes** it and hands
    it to the same resolver every other `derives_from` uses. That is what makes the limit
    re-derived on every run rather than a figure somebody typed once: change a channel's rate and
    the threshold is refused until it moves with it.

    What the value cannot carry is the profile dependence, and the provenance says so rather than
    leaving it implied. It is the default profile's limit, and the `avionics` alternatives scale
    `above` thresholds by their own factor — which would *tighten* this one where `minimal`'s own
    note says dropping channels must loosen it. Nothing applies the factors yet.
    """
    avionics = yaml.safe_load((VEHICLE / "domains" / "avionics" / "profiles.yaml").read_text())
    stale = next(t for t in avionics["thresholds"] if t["id"] == "sensor_stale")
    assert stale["assert"] == 40000, stale["assert"]
    assert stale["clear"] == 20000, stale["clear"]
    assert stale["derives_from"] == "channels.yaml:slowest_publish_period_ms"
    assert stale["derives_factor"] == 2
    assert "profile" in stale["derives_note"], "the profile caveat must be stated"

    # The arithmetic, against the registry rather than against a copy of the number.
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    rates = [
        row["rate_hz"]
        for rows in channels.values()
        if isinstance(rows, list)
        for row in rows
        if isinstance(row, dict) and isinstance(row.get("rate_hz"), (int, float)) and row["rate_hz"]
    ]
    assert rates, "no channel declares a publishing rate"
    assert stale["assert"] == 2 * 1000 / min(rates)

    # A channel slowed down leaves the limit stale, and the linter refuses it.
    definition = copy_definition(tmp_path / "rates")
    path = definition / "channels.yaml"
    text = path.read_text()
    broken = text.replace("rate_hz: 0.05", "rate_hz: 0.02", 1)
    assert broken != text, "the fixture no longer matches channels.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "sensor_stale" in result.stdout, result.stdout[-900:]
    assert "derives_from` resolves to" in result.stdout, result.stdout[-900:]


def test_a_threshold_that_derives_its_limit_is_not_a_second_debt(tmp_path):
    """Three `gnc` thresholds take their limit from a component field the domain also owes.

    The alignment error is measured "against the platform's alignment budget", the gyro bias
    against `imu.drift_deg_per_h`, the radar's altitude against `landing_radar.range_km` — and all
    three of those fields are `UNCONFIGURED`. So **each missing datum was counted twice**, once
    where the quantity lives and once where it is used, and `drift_deg_per_h` was counted *three*
    times because a fault's seeding names it as well.

    That is the inflation round 74 removed from `assert`/`clear`, arriving through a different
    door: two files instead of two fields. The instrument is the same in spirit — name the
    dependency so the use is not a second obligation — and `derives_from` is where it is named.

    The factor is not decoration, which is why it is checked: the bias threshold is in deg/s and
    the drift it is sized from is in deg/h (1/3600), and the radar's range is published in
    kilometres while the altitude channel is in metres (1,000).
    """
    gnc = yaml.safe_load((VEHICLE / "domains" / "gnc" / "profiles.yaml").read_text())
    by_id = {t["id"]: t for t in gnc["thresholds"]}
    for tid, path, factor in (
        (
            "alignment_error_high",
            "domains/gnc/components.yaml:components.imu.alignment_budget_deg",
            1,
        ),
        (
            "gyro_bias_growing",
            "domains/gnc/components.yaml:components.imu.drift_deg_per_h",
            1 / 3600,
        ),
        (
            "radar_out_of_range",
            "domains/gnc/components.yaml:components.landing_radar.range_km",
            1000,
        ),
    ):
        threshold = by_id[tid]
        assert threshold["derives_from"] == path, tid
        assert abs(threshold.get("derives_factor", 1) - factor) < 1e-12, tid
        assert threshold.get("derives_note"), tid
        # And the source really is owed, which is the whole reason the pair was a double count.
        document, dotted = path.split(":", 1)
        node = yaml.safe_load((VEHICLE / document).read_text())
        for step in dotted.split("."):
            node = (
                node[step]
                if isinstance(node, dict)
                else next(r for r in node if str(r.get("id")) == step)
            )
        assert node == "UNCONFIGURED", (tid, node)

    # Supplying the source sets the limit, and a limit that disagrees with it is refused.
    definition = copy_definition(tmp_path / "derived")
    components = definition / "domains" / "gnc" / "components.yaml"
    components.write_text(
        components.read_text().replace(
            "alignment_budget_deg: UNCONFIGURED", "alignment_budget_deg: 0.1", 1
        )
    )
    profiles = definition / "domains" / "gnc" / "profiles.yaml"
    text = profiles.read_text()
    profiles.write_text(text.replace("assert: UNCONFIGURED", "assert: 0.2", 2))
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "`derives_from` resolves to" in result.stdout, result.stdout[-900:]

    # A renamed source is refused rather than tolerated: it reads exactly like an unset one.
    definition = copy_definition(tmp_path / "renamed")
    profiles = definition / "domains" / "gnc" / "profiles.yaml"
    text = profiles.read_text()
    broken = text.replace(
        "components.imu.alignment_budget_deg", "components.imu.alignment_budget", 1
    )
    assert broken != text
    profiles.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "has no" in result.stdout, result.stdout[-900:]


def test_a_profile_that_scales_nothing_says_what_it_changes(tmp_path):
    """Four alternatives declare the identity, and each is accurate rather than lazy.

    `comms.burst` multiplies a *rate*, `gnc.radar_aided` weights a *measurement*,
    `rcs.conservative` widens a controller *deadband*, `rcs.safe_vector` is a mode whose content is
    the safe target. None of them moves a published limit — so a factor that scaled one would be
    the wrong number, and `rcs.conservative`'s original `factor: 1.5` would have *raised* a ceiling
    if it had been read as a threshold scale. The identity is the true statement.

    But the identity on its own is indistinguishable from a profile somebody scaled by one and
    never thought about, so an all-identity `factors` has to carry a `factors_note` saying what it
    changes instead. That is what makes the declaration read rather than decorative.
    """
    definition = copy_definition(tmp_path / "identity")
    path = definition / "domains" / "rcs" / "profiles.yaml"
    text = path.read_text()
    broken = text.replace("      factors_note: >-", "      factors_unused: >-", 1)
    assert broken != text, "the fixture no longer matches rcs/profiles.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "scales every threshold by one" in result.stdout, result.stdout[-900:]


def test_the_narrowing_rule_reads_both_places_alternatives_are_declared():
    """The rule that caught `power.tight` had never run on seven of the eleven domains.

    A profile's `factors` scale its thresholds, and the direction depends on the comparator:
    tightening a ceiling means lowering it, tightening a floor means raising it. One number cannot
    do both — that is the defect the rule was written for, and `power`'s `tight`, selected by a
    fleet wanting warning *earlier*, dropped the bus undervoltage ladder from 26.5 V to 23.85 V.

    `check_profiles` read `profiles_doc.get("alternatives")`, which is where four domains put the
    list. The other **seven** nest it under `profile_selection.alternatives`, so the rule had never
    been applied to thirteen alternatives — including one in `rcs` named `tight`, the same name as
    the one that was wrong. Every one declares a single scalar `factor`.

    A scalar is an *unmet requirement* rather than a false claim, and the distinction decides the
    instrument: a domain that declares the two-key form and gets a direction wrong is refused,
    because it made a claim and the claim is false. A domain that declares one number is owed, and
    the obligation is named and counted. Which way `rcs.conservative` moves — `factor: 1.5` for "a
    wider deadband and a *lower* authority floor" — is its author's judgement, not the linter's.
    """
    shapes = {}
    for path in sorted((VEHICLE / "domains").glob("*/profiles.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        nested = (doc.get("profile_selection") or {}).get("alternatives") or []
        top = doc.get("alternatives") or []
        assert not (nested and top), f"{path.parent.name} declares alternatives twice"
        shapes[path.parent.name] = nested or top

    assert sum(1 for v in shapes.values() if v) == 11, "a domain declares no alternatives at all"
    assert shapes["avionics"] and shapes["rcs"], "the nested shape has gone"

    # The thirteen that declared one number now declare one per comparator, and every domain's
    # list covers the comparators its own valued thresholds use.
    total = 0
    identity = []
    for domain, alts in shapes.items():
        doc = yaml.safe_load((VEHICLE / "domains" / domain / "profiles.yaml").read_text())
        comparators = {
            str(t.get("comparator"))
            for t in doc.get("thresholds") or []
            if isinstance(t.get("assert"), (int, float))
        }
        for alt in alts:
            total += 1
            assert "factor" not in alt, f"{domain}/{alt['id']} still declares a scalar factor"
            factors = alt["factors"]
            assert set(factors) >= comparators, (domain, alt["id"], factors, comparators)
            for comparator, value in factors.items():
                if comparator == "below":
                    assert value >= 1, f"{domain}/{alt['id']} lowers a floor"
                else:
                    assert value <= 1, f"{domain}/{alt['id']} raises a ceiling"
            if all(v == 1.0 for v in factors.values()):
                identity.append((domain, alt["id"]))
                # A profile that scales nothing says what it changes instead — a rate, a
                # measurement weight, a control parameter.
                assert alt.get("factors_note"), (
                    f"{domain}/{alt['id']} scales nothing and says nothing"
                )
    assert total == 17, f"{total} alternatives"

    # Four of them move something other than a limit, and each is accurate rather than lazy.
    assert sorted(identity) == [
        ("comms", "burst"),
        ("gnc", "radar_aided"),
        ("rcs", "conservative"),
        ("rcs", "safe_vector"),
    ], identity

    # And the whole corpus composes, with none of the thirteen outstanding.
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]
    assert "One number cannot tighten both" not in result.stdout


def test_the_presentation_references_resolve_and_the_table_is_whole(tmp_path):
    """Five claims about other files, and nothing resolved any of them.

    `presentation.yaml` names the frozen contract and the probe that tests it; `coupling.yaml`
    names the corpus document it was generated from and the design section that fixes its
    provenance rule. Each is a reference in the folder's own sense — a name whose whole value is
    that it points at something — and all four are right today, which is the condition under which
    the fifth is written wrong.

    The conformance table is the vehicle's claim to satisfy `docs/diode-contract.md` §9: twelve
    rows for the contract's twelve numbered checks. Nothing joined the two, so a dropped row would
    leave a check nobody claims and a duplicate would claim one twice — neither visible in a table
    that reads perfectly.

    The seed's provenance was the seventh unread block, and it is the declaration determinism
    rests on: `plant.md` §6 keys every stochastic stream to it.
    """
    presentation = yaml.safe_load((VEHICLE / "presentation.yaml").read_text())
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())

    # **The references are cited, not opened.** This test used to `stat` all four against the
    # repository root, which was right while the vehicle lived inside `space_chassis` and is a
    # boundary violation now that it is its own repository: the contract, the probe and the corpus
    # documents are *outside* this root, and a suite that stats them is a suite that cannot run
    # without the other half checked out — the same "a check that cannot run is not a check that
    # passed" this file's own docstrings are about. Their existence is asserted where they live
    # (`space_chassis/tests/test_vehicle_reconciliation.py`); what belongs here is that the vehicle
    # *names* them, which is the claim the table actually makes.
    for value in (
        presentation["contract"],
        presentation["contract_probe"],
        coupling["generated_from"],
        coupling["provenance_rules"],
    ):
        assert isinstance(value, str) and value.strip(), value

    numbers = sorted(row["check"] for row in presentation["conformance"])
    assert numbers == list(range(1, 13)), numbers
    assert {row["status"] for row in presentation["conformance"]} <= {
        "demonstrated",
        "satisfied_by_configuration",
        "far_side",
        "shared",
        "vacuous",
    }

    # A renamed reference is refused by its identity rather than by a lookup: the linter used to
    # stat these by walking up from the vehicle, which refused all four correct references in a
    # standalone checkout and failed this repository's own CI, and the first standalone repair
    # dropped this case altogether. `test_an_external_citation_is_held_to_its_canonical_identity`
    # holds the rest — fragments, decoys and a foreign working directory.
    definition = copy_definition(tmp_path / "refs")
    path = definition / "presentation.yaml"
    text = path.read_text()
    broken = text.replace(
        "contract: docs/diode-contract.md", "contract: docs/diode-contract-v2.md", 1
    )
    assert broken != text, "the fixture no longer matches presentation.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "presentation.yaml:contract" in result.stdout, result.stdout[-900:]
    assert "the path differs from the canonical" in result.stdout, result.stdout[-900:]

    # And a citation that could not be repository-relative at all is refused as that, not as a
    # rename, because the fix for it is different.
    for escaped in ("../docs/diode-contract.md", "/docs/diode-contract.md"):
        definition = copy_definition(tmp_path / f"refs{len(escaped)}")
        path = definition / "presentation.yaml"
        text = path.read_text()
        broken = text.replace("contract: docs/diode-contract.md", f"contract: {escaped}", 1)
        assert broken != text, "the fixture no longer matches presentation.yaml"
        path.write_text(broken)
        result = run_linter(definition)
        assert result.returncode == 1, result.stdout[-900:]
        assert "presentation.yaml:contract" in result.stdout, result.stdout[-900:]
        assert "not relative to the citing repository" in result.stdout, result.stdout[-900:]

    definition = copy_definition(tmp_path / "holes")
    path = definition / "presentation.yaml"
    text = path.read_text()
    broken = text.replace("  - check: 12", "  - check: 13", 1)
    assert broken != text
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "skips [12]" in result.stdout, result.stdout[-900:]


def test_an_external_citation_is_held_to_its_canonical_identity_and_no_ambient_file_rescues_it(
    tmp_path,
):
    """The four citations into `space_chassis` are checked by identity, never by a lookup.

    Issue #16: the linter resolved these by walking up from the vehicle directory and from the
    process's working directory, so it passed inside a chassis checkout and refused all four
    correct citations in a standalone one. The first repair kept only the shape rules — no
    absolute path, no `..` — and with them a renamed contract, a dropped section fragment, or a
    fragment on a whole-file citation all composed. Those are the failures the check exists for:
    a reference whose target has been renamed reads exactly like a reference whose target is there.

    So each case below plants a *decoy* first — the wrong file, created both in an ancestor of the
    copy and in the working directory the linter runs from — because the old resolver would have
    accepted exactly those, and a check that can be rescued by an ambient file is a check on the
    machine rather than on the vehicle. The unbroken copy composes from that same foreign working
    directory, which is the standalone property CI depends on.
    """
    foreign = tmp_path / "foreign_cwd"
    foreign.mkdir()

    def lint_from(definition: Path) -> subprocess.CompletedProcess[str]:
        return subprocess.run(
            [sys.executable, str(LINTER), "--dir", str(definition)],
            capture_output=True,
            text=True,
            check=False,
            cwd=foreign,
        )

    clean = copy_definition(fixture_dir(tmp_path, "clean"))
    result = lint_from(clean)
    assert result.returncode == 0, result.stdout[-900:]
    assert "COMPOSES" in result.stdout, result.stdout[-900:]

    cases = (
        (
            "presentation.yaml",
            "contract: docs/diode-contract.md",
            "contract: docs/diode-contrat.md",
            "presentation.yaml:contract",
            "the path differs from the canonical",
        ),
        (
            "presentation.yaml",
            "contract_probe: contract/diode_probe.py",
            "contract_probe: contract/fake_diode.py",
            "presentation.yaml:contract_probe",
            "the path differs from the canonical",
        ),
        (
            "coupling.yaml",
            "generated_from: docs/deep_research/apollo_diode.md",
            "generated_from: docs/deep_research/apollo_diode.md#7",
            "coupling.yaml:generated_from",
            "is cited as a whole file and carries no fragment",
        ),
        (
            "presentation.yaml",
            "contract_probe: contract/diode_probe.py",
            "contract_probe: [contract/diode_probe.py]",
            "presentation.yaml:contract_probe",
            "is a list",
        ),
        (
            "coupling.yaml",
            "provenance_rules: docs/deep_research/integration/simulator-design.md#31",
            "provenance_rules: docs/deep_research/integration/simulator-design.md",
            "coupling.yaml:provenance_rules",
            "the fragment differs from the canonical section `#31`",
        ),
        (
            "coupling.yaml",
            "provenance_rules: docs/deep_research/integration/simulator-design.md#31",
            "provenance_rules: docs/deep_research/integration/simulator-design.md#3",
            "coupling.yaml:provenance_rules",
            "the fragment differs from the canonical section `#31`",
        ),
    )
    for filename, old, new, where, words in cases:
        definition = copy_definition(fixture_dir(tmp_path, "citation"))
        path = definition / filename
        text = path.read_text()
        broken = text.replace(old, new, 1)
        assert broken != text, f"the fixture no longer matches {filename}"
        path.write_text(broken)
        decoy = new.split(": ", 1)[1].split("#", 1)[0].strip("[]")
        for base in (definition.parent, foreign):
            (base / decoy).parent.mkdir(parents=True, exist_ok=True)
            (base / decoy).write_text("a decoy that a filesystem lookup would have accepted\n")
        result = lint_from(definition)
        assert result.returncode == 1, (new, result.stdout[-900:])
        assert where in result.stdout and words in result.stdout, (new, result.stdout[-1200:])


def test_the_guidance_model_is_re_derived_rather_than_trusted(tmp_path):
    """Three `gnc` blocks were the last of the nine a deletion test found unread, and all three
    declare things arithmetic can check.

    The interesting one is `trajectory_segment`, because it is `rederive`'s idiom applied to six
    *formulas* instead of one number. The segment states its own boundary conditions — position,
    velocity and acceleration at both ends — and those six conditions determine all six quintic
    coefficients, so whether the declared expressions are the determined ones is a question the
    algebra answers. **A sign flipped in one of twenty-five terms would leave a trajectory that
    still starts and ends in the right place**, which is why a derivation needs a reader more than
    a number does.

    The other two are consistency claims: the error state's blocks must be the covariance's blocks
    and three times as many as the dimension says, and the filter's rates must divide the *mission's*
    tick, which is declared in a different file.
    """
    gnc = yaml.safe_load((VEHICLE / "domains" / "gnc" / "components.yaml").read_text())
    estimator = gnc["estimator"]
    vector = estimator["error_vector"]
    # The field is named after the convention it copies, so that its citation pairs with it.
    assert set(estimator["covariance_units"]) == set(vector)
    assert estimator["dimension"] == 3 * len(vector) == 15
    assert estimator["sub_stepping"]["plant_tick_hz"] == 50
    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    assert estimator["sub_stepping"]["plant_tick_hz"] == mission["tick_hz"]

    # `gnc` was the only domain with a components file and no `open_debts`, which is how the two
    # limits named inside `trajectory_segment`'s note stayed out of every count.
    assert gnc["open_debts"], "gnc declares no obligations again"
    assert any("jerk" in str(d) for d in gnc["open_debts"])
    assert any("keep-out" in str(d) or "keep_out" in str(d) for d in gnc["open_debts"])

    # A flipped sign in `a3` is caught by the boundary conditions, not by a reader.
    definition = copy_definition(tmp_path / "quintic")
    path = definition / "domains" / "gnc" / "components.yaml"
    text = path.read_text()
    broken = text.replace('a3: "10*(pf-p0)', 'a3: "10*(p0-pf)', 1)
    assert broken != text, "the fixture no longer matches gnc/components.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "do not satisfy their own boundary conditions" in result.stdout, result.stdout[-900:]

    # And the tick the filter sub-steps inside is the mission's, not its own.
    definition = copy_definition(tmp_path / "tick")
    path = definition / "domains" / "gnc" / "components.yaml"
    text = path.read_text()
    broken = text.replace("plant_tick_hz: 50", "plant_tick_hz: 60", 1)
    assert broken != text
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "sub_stepping.plant_tick_hz" in result.stdout, result.stdout[-900:]


def test_a_check_that_iterates_a_missing_block_is_not_a_check(tmp_path):
    """Three blocks could be deleted outright and the build stayed green.

    A deletion test — remove a block, run every tool, diff the output — found nine blocks the
    vehicle does not notice losing. Three of them were worse than unread: **the linter had code
    for them, and the code could not run.** `quality_assignment` was guarded by
    `if isinstance(quality, dict)`, `display_contract` by `or {}` and an empty loop, and
    `atmosphere_model` by an early `return` — so all three reported on nothing when the block was
    gone, which is indistinguishable from reporting that all is well.

    Between them they are four hundred lines: the quality-assignment function
    `simulator-design.md:496-508` requires, the display contract the perception bound is
    cross-checked against, and the atmosphere model that makes a cabin's contents species rather
    than one mass. Each is now refused by name when absent.
    """
    for domain, key, filename in (
        ("avionics", "quality_assignment", "components.yaml"),
        ("crew", "display_contract", "components.yaml"),
        ("eclss", "atmosphere_model", "components.yaml"),
    ):
        definition = copy_definition(tmp_path / domain)
        path = definition / "domains" / domain / filename
        lines = path.read_text().split("\n")
        start = next(i for i, line in enumerate(lines) if line.startswith(f"{key}:"))
        end = start + 1
        while end < len(lines) and not re.match(r"^[A-Za-z_]", lines[end]):
            end += 1
        removed = end - start
        assert removed > 5, f"{domain}/{key} is only {removed} lines"
        path.write_text("\n".join(lines[:start] + lines[end:]))

        result = run_linter(definition)
        assert result.returncode == 1, f"{domain}/{key} deleted and nothing noticed"
        assert f":{key}" in result.stdout, result.stdout[-900:]


def test_the_blocks_no_tool_read_name_things_that_resolve(tmp_path):
    """Three more of the nine, and what makes them worth wiring is that they are full of names.

    `consumables/ledgers` names twelve channel ids across four rows, `crew/alert_overlays` names
    three overlay ids a verb has to be able to set, and `thermal/load_budget` states a rejection
    total that is the sum of two figures in its own file. All fifteen names and the closure are
    right today — which is exactly the condition under which the sixteenth is added wrong, and
    until this round nothing read any of them.
    """
    report = run_linter(VEHICLE)
    assert report.returncode == 0, report.stdout[-900:]

    # The thermal totals are closures over their **own vehicle's** parts. This summed every
    # component in the file into one number until the LM sublimator's capacity was published and
    # the two vehicles arrived in the same total; the demands had been split all along.
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    budget = thermal["load_budget"]
    parts: dict[str, list[float]] = {"csm": [thermal["radiator_model"]["csm"]["rejection_w"]]}
    for component in thermal["components"]:
        if isinstance(component.get("rejection_w"), (int, float)):
            parts.setdefault(str(component["vehicle"]), []).append(component["rejection_w"])
    assert {v: sum(rows) for v, rows in parts.items()} == {
        "csm": budget["csm_rejection_capacity_w"],
        "lm": budget["lm_rejection_capacity_w"],
    }, parts

    # Every ledger channel resolves, and the resource is a coupling node.
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    raw_nodes = coupling["nodes"]
    nodes = (
        {str(n["id"]) for n in raw_nodes}
        if isinstance(raw_nodes, list)
        else {str(k) for k in raw_nodes}
    )
    assert nodes, "no coupling nodes were read"
    consumables = yaml.safe_load(
        (VEHICLE / "domains" / "consumables" / "components.yaml").read_text()
    )
    assert len(consumables["ledgers"]) == 4
    for row in consumables["ledgers"]:
        assert row["resource"] in nodes, row["resource"]

    # A deletion the checks exist to catch, in the shape a typo takes.
    definition = copy_definition(tmp_path / "ledger")
    path = definition / "domains" / "consumables" / "components.yaml"
    text = path.read_text()
    broken = text.replace('"res.ledger_o2_kg"', '"res.ledger_o2_kq"', 1)
    assert broken != text, "the fixture no longer matches consumables/components.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "res.ledger_o2_kq" in result.stdout, result.stdout[-900:]

    # And the budget's, which is the closure that has no other reader.
    definition = copy_definition(tmp_path / "budget")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    broken = text.replace("csm_rejection_capacity_w: 4933", "csm_rejection_capacity_w: 5933", 1)
    assert broken != text, "the fixture no longer matches thermal/components.yaml"
    path.write_text(broken)
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "load_budget.csm_rejection_capacity_w" in result.stdout, result.stdout[-900:]


def test_the_internal_sentinel_is_not_exempt_from_the_ordering_rule():
    """The rule says "each node with more than one producing state". The code said "unless internal".

    `check_domains` requires a node advanced by two or more states to declare a `state_order` or
    to claim `independent`, and the comment beside it records what the requirement is for: the
    frozen lexicographic tiebreak sorted `link_snr` before `tx_power`, on a node where transmit
    power is a term in the link budget, so the derived order computed this tick's ratio from last
    tick's power. *"Silence about them means the alphabet decides."*

    The loop implementing it read `if node and node != "internal"`, and neither `plant.md` nor
    `coupling.yaml` says why. So 54 states across nine domains stayed alphabetical. The sentinel
    is the worse place for it, not the better one: a node's producing states are at least joined
    by edges that say what feeds what, and `internal` states have no edges at all — that is what
    the sentinel means — so the alphabet was the only signal there was.

    **Round 19 declared all nine**, so this test no longer measures a debt: it holds the nine
    declarations to the states they order, and it holds the *linter* to refusing the two shapes that
    would make a declaration meaningless — an order that is not the domain's own sentinel set, and
    one with no note saying what the order is for.
    """
    declared = []
    for components_path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        components = yaml.safe_load(components_path.read_text()) or {}
        on_sentinel = sorted(
            str(s["id"])
            for s in components.get("state") or []
            if isinstance(s, dict) and str(s.get("node")) == "internal" and s.get("id")
        )
        if len(on_sentinel) < 2:
            assert "internal_order" not in components, (
                f"{components_path.parent.name} declares an order for fewer than two sentinel states"
            )
            continue
        order = components.get("internal_order")
        assert isinstance(order, list), (components_path.parent.name, order)
        assert sorted(str(x) for x in order) == on_sentinel, (
            f"{components_path.parent.name}'s order is not its own sentinel states"
        )
        assert len(str(components.get("internal_order_note") or "")) > 80, (
            f"{components_path.parent.name} declares an order with no reason"
        )
        declared.append((components_path.parent.name, on_sentinel))

    # 9 -> 10 with eclss, for the same reason as the test above.
    assert len(declared) == 10, f"{len(declared)} domains declare one: {[d for d, _ in declared]}"
    # 54 -> 56: the oxygen supply tank's pressure joined the sentinel, and — the same round — the
    # count it is part of is what this assertion exists to notice.
    assert sum(len(states) for _, states in declared) == 59, "the sentinel's state count moved"

    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]
    assert "internal_order" not in result.stdout, "a declaration is still reported as a debt"


def test_vehicle_yaml_counts_its_own_open_debts():
    """The file's `VEHICLE_SECTIONS` comment said these were counted, and nothing counted them.

    `channels.yaml`, `coupling.yaml` and the eleven domains each report their `open_debts` as
    debts. `vehicle.yaml`'s **nine** were read by no code at all, and the linter's own comment
    beside the section name claimed otherwise: *"counted and printed, like every other
    `open_debts` in the folder"*. Dropping eight of the nine left the headline count unchanged.

    What was missing from the number that exists to count what is missing is not marginal — the
    inertia tensor per configuration, the thermal zones' capacities and conductances, the minimum
    impulse bit for all three RCS systems, the forty-four thrusters' geometry, the fuel cell's
    reactant consumption, the ullage motors and the power inventory's unchecked relationships.
    **A file's own statement that a section is read is not evidence that it is**, which is this
    folder's oldest finding pointed at the tool that enforces it.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    entries = vehicle["open_debts"]
    # Nine until the round that closed the fuel cell's reactant chain: "Fuel-cell reactant
    # consumption per kWh: not published" was one of them, and it was one division from three
    # published numbers. Eight until round 9 retired the inertia entry — that one was *false* (the
    # Operational Data Book is in the library) and its content became four walkable fields under
    # `mass_properties`, so what left the list is now counted by the scalar walk instead. The floor
    # moves with the list because the list is the thing being counted; the assertion below, which
    # compares the count against the linter's own report, is the one that cannot move.
    assert len(entries) >= 7, f"vehicle.yaml declares only {len(entries)} open debts"

    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]
    reported = [
        line
        for line in result.stdout.splitlines()
        if line.strip().startswith("- vehicle.yaml:open_debts:")
    ]
    assert len(reported) == len(entries), (
        f"{len(entries)} entries declared and {len(reported)} counted; the rest are in no number"
    )

    # The headline is the sum of the two halves, which is what makes it worth quoting.
    owed = re.search(r"OWED \(a value that is needed and unset\) — (\d+)", result.stdout)
    assert owed, result.stdout[:400]
    assert f"with {owed.group(1)} declared debt(s)" in result.stdout


def test_the_fuel_cell_reactant_chain_is_grounded_but_for_one_figure():
    """The cell's draws are nodes now, and everything downstream of them is derivable.

    The tanks the cell drains had no computable outflow: the oxygen inventory is shared between
    ECLSS and the cells and nothing said at what rate. `fc_o2_draw` and `fc_h2_draw` are flow nodes
    with the whole chain declared. **This docstring said "exactly one figure in it is owed, the
    cell's per-joule oxygen consumption, which no source publishes" — and that figure is derived
    now**, from the module's rated 29 V and the reactant rate per ampere; see
    `test_the_fuel_cells_reactant_chain_re_derives_from_the_operating_point`. Nothing in this test
    changed when it landed, which is the point: the chain was already the right shape and the last
    number was the only thing missing from it.

    The hydrogen draw is the reactant rate over the reaction's mass ratio, and the water is
    stoichiometry. The availability edges moved with the draws, which is what let the two
    `C-REACTANT-DRAW` cycles close again — the path is `fuel_cell -> fc_o2_draw -> fuel_cell`
    rather than through the tank, because what limits the cell is the *draw*, not the tank level.
    """
    plant = _plant()
    world = plant.load_world(VEHICLE)
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {e["id"]: e for e in coupling["edges"]}
    nodes = coupling["nodes"]

    for node, unit in (("fc_o2_draw", "kg O2/s"), ("fc_h2_draw", "kg H2/s")):
        assert nodes[node]["kind"] == "flow" and nodes[node]["unit"] == unit

    # The chain: the cell sets the draw, the tank supplies it, and the draw limits the cell.
    assert (edges["E-FC-DRAW-O2"]["from"], edges["E-FC-DRAW-O2"]["to"]) == (
        "fuel_cell",
        "fc_o2_draw",
    )
    assert (edges["E-O2-DRAW"]["from"], edges["E-O2-DRAW"]["to"]) == ("o2_csm", "fc_o2_draw")
    assert (edges["E-O2-FC"]["from"], edges["E-O2-FC"]["to"]) == ("fc_o2_draw", "fuel_cell")
    assert (edges["E-FC-WATER"]["from"], edges["E-FC-WATER"]["to"]) == (
        "fc_o2_draw",
        "water_potable",
    )

    # Both tank drains and the water production are computable, and the water is per kg of oxygen.
    for edge_id, driver in (("E-O2-DRAW", "to"), ("E-H2-DRAW", "to"), ("E-FC-WATER", "from")):
        edge = next(e for e in world.edges if e.id == edge_id)
        node = edge.target if driver == "to" else edge.source
        flux = plant.stock_flux(
            world, edge, {edge.source: 1.0, edge.target: 1.0}, 1.0, driver_node=node
        )
        assert flux > 0, edge_id
    water = next(e for e in world.edges if e.id == "E-FC-WATER")
    assert water.sensitivity["value"] == pytest.approx(36.03056 / 31.9988, rel=1e-3)

    # The two tanks are loaded at the pad, and now say so: with the draws moved off them they had no
    # inbound edge at all, which is the state the linter refuses unless `preloaded:` explains it.
    assert nodes["o2_csm"]["preloaded"] and nodes["h2_csm"]["preloaded"]


def test_the_cabin_oxygen_supplies_are_derived_from_the_losses(tmp_path):
    """The last two ratio refusals were the cabin supplies, and both are fully grounded.

    `E-O2-ECLSS` said "1 kg enters the cabin per kg of O2" against a *level* rather than a flow, so
    nothing could apply it. `cabin_o2_supply_csm` and `cabin_o2_supply_lm` are flow nodes now, and
    what the regulator admits is what the cabin loses: the leak plus the crew's metabolic
    consumption, both published.

    **`E-O2-SUPPLY-LM` is the better-attested of the two**, because the leak datum is Apollo 11's LM
    cabin leak of 0.05 lb/hr. The CSM's own leak is published nowhere, yet `consumables` sizes
    `o2_csm_kg`'s quantum from the same 0.023 kg/h as though it were the CSM's — so the figure is
    used here, and the attribution conflict is a named debt rather than a silent assumption.
    """
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    states = {str(s["id"]): s for s in eclss["state"]}
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {e["id"]: e for e in coupling["edges"]}

    for state_id, expected in (
        ("cabin_o2_supply_csm_kg_s", (0.023 + 3 * 0.91 / 24) / 3600),
        ("cabin_o2_supply_lm_kg_s", (0.05 * 0.453592 + 2 * 0.91 / 24) / 3600),
    ):
        assert states[state_id]["nominal_kg_s"] == pytest.approx(expected, rel=1e-5), state_id
        assert states[state_id]["method"] == "algebraic"

    # Every stock edge on the oxygen path computes now, and the two cabin supplies are what closed it.
    assert edges["E-O2-SUPPLY-CSM"]["to"] == "cabin_o2_supply_csm"
    assert edges["E-O2-ECLSS"]["from"] == "cabin_o2_supply_csm"
    assert edges["E-O2-SUPPLY-LM"]["to"] == "cabin_o2_supply_lm"
    assert edges["E-LM-O2-ECLSS"]["from"] == "cabin_o2_supply_lm"

    definition = copy_definition(tmp_path / "derivation")
    path = definition / "domains" / "eclss" / "components.yaml"
    text = path.read_text()
    # The rule is a `derivation` now, whose inputs are the leak, the crew size and the metabolic
    # rate by dotted path rather than three numbers restated in an expression. The needle moves
    # with the spelling and the break is the same break: drop the per-hour-to-per-second step.
    anchor = (
        'expression: "(leak_kg_per_h + crew * o2_kg_per_crew_day / hours_per_day) '
        '/ seconds_per_hour"'
    )
    assert anchor in text, "the fixture no longer matches the CSM supply rule"
    # The break multiplies by the seconds instead of dividing by them — a wrong *value* rather
    # than a wrong shape. Dropping the term entirely leaves `seconds_per_hour` bound and unused,
    # which the derivation rule refuses first and for a different reason.
    path.write_text(
        text.replace(anchor, anchor.replace("/ seconds_per_hour", "* seconds_per_hour"), 1)
    )

    result = run_linter(definition)
    assert result.returncode == 1
    # `check_declared_derivation`'s wording, which is the rule a `derivation` is held by. The
    # message says "no longer re-derives" where `rederive` — still used by an edge's `sums_to_h`
    # and the tick arithmetic — says "does not re-derive".
    assert "no longer re-derives" in result.stdout


def test_the_water_cycle_edges_have_the_right_way_round(tmp_path):
    """One relation, two edges, and until round 61 the stock was on the wrong side of both.

    `E-RAD-WATER` said `kg/s per W` and ran *into* `water_cooling`, so the plant **filled** the tank
    with the water the radiator consumes. `E-WATER-RAD` ran out of it — the side a stock discharges
    through — carrying `kg per J`, which is the *forward* relation's unit: the edge's own note said
    "the inverse of E-RAD-WATER" and then stated the same number in the same unit.

    Swapped, the two are one relation with the stock on opposite sides: the discharge takes
    `kg/s per W` and computes, and the availability half takes `J per kg` — what a kilogram of water
    *buys*, 2.45e6 J — and is refused as a stock flux, correctly, because availability is a clamp
    rather than a slope. The linter's cycle check confirms the pair still closes
    `radiator_reject -> water_cooling -> radiator_reject`.
    """
    plant = _plant()
    world = plant.load_world(VEHICLE)
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {e["id"]: e for e in coupling["edges"]}

    assert edges["E-WATER-RAD"]["from"] == "water_cooling"
    assert edges["E-WATER-RAD"]["sensitivity"]["unit"] == "kg/s per W"
    assert edges["E-RAD-WATER"]["sensitivity"]["unit"] == "J per kg"
    assert edges["E-RAD-WATER"]["sensitivity"]["value"] == pytest.approx(2.45e6)

    # The discharge computes, and it is the *target* that drives it: the radiator's wattage sets
    # how fast the water goes.
    edge = next(e for e in world.edges if e.id == "E-WATER-RAD")
    flux = plant.stock_flux(
        world, edge, {edge.source: 100.0, edge.target: 1000.0}, 1.0, driver_node=edge.target
    )
    assert flux == pytest.approx(4.0816e-4, rel=1e-3)

    # The cycle still closes, and the linter refuses it if it stops.
    cycle = next(c for c in coupling["cycles"] if c["id"] == "C-WATER-BUDGET")
    assert set(cycle["members"]) == {"E-WATER-RAD", "E-RAD-WATER"}
    assert cycle["back_edge"] == "E-WATER-RAD"
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-800:]


def test_the_propulsion_edges_are_stated_as_drains(tmp_path):
    """`N per kg/s` is thrust per unit of flow — an engine's *production*, under a tank's edge.

    `prop_main` and `prop_rcs` discharge through their outbound edges, and an outbound edge reads
    its **target** as the driver: the tank drains at whatever rate the thrust demands. Stated as
    `N per kg/s` the edge gave the plant a force to multiply a propellant mass by, and the
    dimensional check refused it — correctly, because N per (kg/s) is what an engine *produces*, not
    what a tank loses.

    Both reversed figures are published rather than owed: Isp 314.5 s and **277.8 s** are in
    `vehicle.yaml#propulsion` (the second moved by C-26, which closed on the RCS study guide's
    corroborated figure), so `1/(Isp x g0)` closes each edge exactly and **249 became 247**.
    """
    plant = _plant()
    world = plant.load_world(VEHICLE)
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {e["id"]: e for e in coupling["edges"]}

    for edge_id, isp in (("E-PROP-ENG", 314.5), ("E-RCSP-RCS", 277.8)):
        edge = edges[edge_id]
        assert edge["sensitivity"]["unit"] == "kg/s per N", edge_id
        assert edge["sensitivity"]["value"] == pytest.approx(1.0 / (isp * 9.80665), rel=1e-9)
        # No `advances`: each target carries a single state, so the declaration is not required —
        # and it would be wrong now, because the edge reads the thrust rather than producing it.
        assert edge.get("advances") is None, edge_id

    # A thousand newtons of SPS thrust drains 1000/3084.2 kg/s of propellant.
    e = next(x for x in world.edges if x.id == "E-PROP-ENG")
    flux = plant.stock_flux(
        world, e, {e.source: 100.0, e.target: 1000.0}, 1.0, driver_node=e.target
    )
    assert flux == pytest.approx(1000.0 / (314.5 * 9.80665), rel=1e-9)

    # `prop_rcs` has no *inbound* edge at all — it is loaded at the pad and never refilled — so the
    # linter would report it undriven if the declaration were absent.
    assert coupling["nodes"]["prop_rcs"]["preloaded"]

    definition = copy_definition(tmp_path / "forward")
    path = definition / "coupling.yaml"
    text = path.read_text()
    anchor = '      unit: "kg/s per N"'
    assert anchor in text, "the fixture no longer matches the propulsion edges"
    path.write_text(text.replace(anchor, '      unit: "N per kg/s"', 1))

    # A stock-flux failure is reported as a *debt* rather than a refusal — the vehicle genuinely is
    # not finished — so the build still composes and the edge appears in the owed list by name.
    result = run_linter(definition)
    assert result.returncode == 0, result.stdout[-800:]
    assert "whose unit is 'N'" in result.stdout
    assert "coupling.yaml:edge E-PROP-ENG:" in result.stdout


def test_the_absorbers_remove_from_their_own_cabin(tmp_path):
    """One removal rate for two absorbers is the round-42 defect one layer up.

    The counters were split then; the *rate that spends them* was not. `co2_removal_kg_s` was a
    single algebraic state on the `internal` sentinel **reading both counters**, so it converted two
    beds' remaining capacity into one rate for one vehicle — and a crew on the surface spent the CSM
    element while a crew back in the CM spent the LM cartridge.

    Split into `co2_removal_csm_kg_s` and `co2_removal_lm_kg_s`, each on its own flow node, the chain
    is per-compartment end to end: the cabin loses CO2 to its own removal, the removal spends its own
    counter, and the removal rate is two thirds of the CSM's on the LM because two crew produce it
    rather than three — a *different* number, and one a shared state could not express.

    It also made the two absorber edges computable. `man-hours per kg CO2` had no time basis, so the
    classifier refused it; applied to a node carrying `kg CO2/s` it is man-hours per second, which is
    what the counter integrates. **247 became 245**, and seventeen of the twenty-one stock-adjacent
    edges now compute.
    """
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    states = {str(s["id"]): s for s in eclss["state"]}
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {str(e["id"]): e for e in coupling["edges"]}
    nodes = coupling["nodes"]

    assert "co2_removal_kg_s" not in states, "the shared removal state is back"
    for state_id, node in (
        ("co2_removal_csm_kg_s", "co2_removal_csm"),
        ("co2_removal_lm_kg_s", "co2_removal_lm"),
    ):
        assert states[state_id]["node"] == node
        assert nodes[node]["kind"] == "flow" and nodes[node]["unit"] == "kg CO2/s"

    # Each removal spends its own counter, and each cabin loses CO2 to its own removal.
    assert (edges["E-ATM-ABSORB"]["from"], edges["E-ATM-ABSORB"]["to"]) == (
        "co2_removal_csm",
        "absorber_capacity_csm",
    )
    assert (edges["E-LM-ATM-ABSORB"]["from"], edges["E-LM-ATM-ABSORB"]["to"]) == (
        "co2_removal_lm",
        "absorber_capacity_lm",
    )
    assert edges["E-CABIN-CO2-REMOVAL"]["drains"] == "csm_cabin_co2_kg"
    assert edges["E-LM-CABIN-CO2-REMOVAL"]["drains"] == "lm_cabin_co2_kg"

    plant = _plant()
    world = plant.load_world(VEHICLE)
    for edge_id, driver, expected_unit in (
        ("E-ATM-ABSORB", "from", "man-hours per kg CO2"),
        ("E-CABIN-CO2-REMOVAL", "to", "kg CO2 per kg CO2"),
    ):
        edge = next(e for e in world.edges if e.id == edge_id)
        assert edge.sensitivity["unit"] == expected_unit, edge_id
        flux = plant.stock_flux(
            world,
            edge,
            {edge.source: 1.0, edge.target: 1.0},
            1.0,
            driver_node=edge.source if driver == "from" else edge.target,
        )
        assert flux > 0, edge_id


def test_the_battery_derating_is_a_capacity_not_a_flux():
    """A cold pack gives up less than it holds, and that belongs on a capacity rather than a charge.

    `E-PLATE-BAT` carried `0.0 J per K` from `coldplate_t` into `battery_energy` — a *capacity*
    relation landing on a quantity that is conserved, which the linter refused as a lag edge on a
    stock. `battery_usable_j` is the capacity node now, and the loop runs bus -> charge -> usable
    capacity -> bus: **the last step is what the bus actually draws on**, and without it `C-BAT-BUS`
    did not close and the linter said so.

    The nominal derating is 1.0 and the sensitivity is `0.0 J per K`, which the edge's own note
    already flagged as the review-findings.md #8 case: **a closure computed at nominal passes a
    fidelity decision that is wrong exactly when it matters.** In the crisis the pack is cold and the
    derating is not 1.0 — and no source publishes the curve, so it is `UNCONFIGURED` rather than
    invented.
    """
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {str(e["id"]): e for e in coupling["edges"]}
    nodes = coupling["nodes"]
    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    states = {str(s["id"]): s for s in power["state"]}

    assert nodes["battery_usable_j"]["kind"] == "flow"
    assert edges["E-PLATE-BAT"]["to"] == "battery_usable_j"
    assert edges["E-PLATE-BAT"]["advances"] == "battery_usable_j_j"
    assert edges["E-BAT-BUS"]["from"] == "battery_usable_j", (
        "the bus draws on usable energy, not on the raw charge"
    )
    assert states["battery_usable_j_j"]["derate_curve"] == "UNCONFIGURED"

    # The cycle it belongs to still closes, with the new step declared as a member.
    cycle = next(c for c in coupling["cycles"] if c["id"] == "C-BAT-BUS")
    assert "E-BAT-USABLE" in cycle["members"]

    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]
    # And it is no longer a stock-flux debt: only the water clamp is left in that class.
    assert "against a stock denominated" not in result.stdout
    assert " is a 'lag' edge on a stock" not in result.stdout


def test_what_a_cabin_removes_is_what_its_crew_produce(tmp_path):
    """Three declarations in three files, joined for the first time.

    The crew count (`mission.yaml#crew`), the metabolic production rate
    (`vehicle.yaml#consumables.metabolic`), and the removal rate the ECLSS domain declares per
    compartment. The arithmetic is one line each — **rate = crew x kg_per_crew_day / 86400** — and
    it is the cabin equilibrium's three-way join applied to a different quantity.

    The two figures are deliberately *not* the same figure, which is the point of the round-63
    split: the CSM element removes what `size` crew produce and the LM cartridge what
    `surface_party` produce, so the LM's rate is two thirds of the CSM's on one metabolic constant.
    A single shared state could not have expressed either.
    """
    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    states = {str(s["id"]): s for s in eclss["state"]}
    per_day = vehicle["consumables"]["metabolic"]["co2_kg_per_crew_day"]

    for state_id, key, expected in (
        ("co2_removal_csm_kg_s", "size", 3 * 0.91 / 86400),
        ("co2_removal_lm_kg_s", "surface_party", 2 * 0.91 / 86400),
    ):
        crew = mission["crew"][key]
        assert states[state_id]["nominal_kg_s"] == pytest.approx(crew * per_day / 86400, rel=1e-5)
        assert states[state_id]["nominal_kg_s"] == pytest.approx(expected, rel=1e-5)

    # Two thirds, on one metabolic constant — the relationship the split made visible.
    ratio = (
        states["co2_removal_lm_kg_s"]["nominal_kg_s"]
        / states["co2_removal_csm_kg_s"]["nominal_kg_s"]
    )
    assert ratio == pytest.approx(mission["crew"]["surface_party"] / mission["crew"]["size"])

    # Move the crew count and the domain's rate is refused rather than silently stale.
    definition = copy_definition(tmp_path / "crew")
    path = definition / "mission.yaml"
    text = path.read_text()
    anchor = "  surface_party: 2\n"
    assert anchor in text, "the fixture no longer matches mission.yaml#crew"
    path.write_text(text.replace(anchor, "  surface_party: 3\n", 1))

    result = run_linter(definition)
    assert result.returncode == 1
    assert "A cabin's equipment that removes a different amount" in result.stdout


def test_the_oxygen_supplies_are_checked_against_the_same_three_declarations(tmp_path):
    """The CO2 join's twin: the regulator replaces what the cabin loses, and both terms are published.

    Round 60 declared these two rates with their arithmetic and nothing checked them beyond
    re-deriving their own `computation`. They are held to the *other* files now — the crew count, the
    metabolic rate and the leak — which is the same three-way join the removal rates got in round 66,
    applied to the supply side.

    The leak is the interesting half. `vehicle.yaml#consumables.leak` was **one figure doing two
    cabins' work** while its own source named only one of them; it is per cabin now, and the CSM's is
    declared as borrowed (A11 gives one leak and it is the LM's, 0.05 lb/hr = 0.0226796 kg/h, while
    the CSM's own is published nowhere). A leak is a property of a seal rather than of a programme,
    and two cabins with one number between them read as though they had two.
    """
    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    states = {str(s["id"]): s for s in eclss["state"]}
    leak = vehicle["consumables"]["leak"]
    o2 = vehicle["consumables"]["metabolic"]["o2_kg_per_crew_day"]

    assert leak["lm_kg_per_h"] == pytest.approx(0.05 * 0.453592, rel=1e-4)
    assert leak["csm_kg_per_h"] != leak["lm_kg_per_h"], "the two cabins have different seals"

    for state_id, crew_key, leak_per_h in (
        ("cabin_o2_supply_csm_kg_s", "size", leak["csm_kg_per_h"]),
        ("cabin_o2_supply_lm_kg_s", "surface_party", leak["lm_kg_per_h"]),
    ):
        crew = mission["crew"][crew_key]
        expected = (leak_per_h + crew * o2 / 24.0) / 3600.0
        assert states[state_id]["nominal_kg_s"] == pytest.approx(expected, rel=1e-5), state_id

    # A leak changed in `vehicle.yaml` is refused rather than silently absorbed.
    definition = copy_definition(tmp_path / "leak")
    path = definition / "vehicle.yaml"
    text = path.read_text()
    anchor = "    lm_kg_per_h: 0.0226796\n"
    assert anchor in text, "the fixture no longer matches the leak block"
    path.write_text(text.replace(anchor, "    lm_kg_per_h: 0.05\n", 1))

    result = run_linter(definition)
    assert result.returncode == 1
    assert "The regulator replaces what the cabin loses" in result.stdout


def test_a_channel_about_a_cabin_is_paired_or_explained(tmp_path):
    """A channel that is not paired with its twin is a *claim*, and until round 68 it was implicit.

    The vehicle has two crewed compartments, so a channel about a cabin's air is about one cabin:
    `eclss.cabin_temp_c` and `eclss.lm_cabin_temp_c` are one quantity in two rooms with no shared air
    between them. Most ECLSS channels are paired that way. **The CO2 exposure average was not** — a
    limit that governs how long a surface stay can be extended, published for the cabin the crew
    leave and none for the one they live in, and nothing could tell that from a channel that is
    legitimately single because its subject is.

    `presentation.yaml#single_cabin` names each unpaired channel with its reason, and the comparison
    is exact in both directions: an unpaired channel must be explained, and an explanation of a
    *paired* channel is stale — a reader told to expect a gap that has been closed.
    """
    registry = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    presentation = yaml.safe_load((VEHICLE / "presentation.yaml").read_text())
    published = {
        str(c["id"])
        for section in registry.values()
        if isinstance(section, list)
        for c in section
        if isinstance(c, dict) and "id" in c
    }
    eclss = {cid for cid in published if cid.startswith("eclss.")}
    paired = {
        cid for cid in eclss if ".lm_" not in cid and cid.replace("eclss.", "eclss.lm_", 1) in eclss
    }
    single = {cid for cid in eclss if ".lm_" not in cid and cid not in paired}

    assert single == set(presentation["single_cabin"]), "the declaration and the registry disagree"
    assert "eclss.co2_pp_1h_avg_mmhg" in paired, "the exposure average gained its twin in round 68"
    assert len(paired) == 6

    # An unpaired channel with no explanation is refused.
    definition = copy_definition(tmp_path / "unexplained")
    path = definition / "presentation.yaml"
    text = path.read_text()
    anchor = "  eclss.leak_rate_g_s: >-\n"
    assert anchor in text, "the fixture no longer matches single_cabin"
    stripped = re.sub(r"  eclss\.leak_rate_g_s: >-\n(?:    .*\n|\n)*", "", text, count=1)
    assert stripped != text
    path.write_text(stripped)

    result = run_linter(definition)
    assert result.returncode == 1
    assert "does not explain" in result.stdout and "eclss.leak_rate_g_s" in result.stdout


def test_every_declared_gas_is_held_in_every_cabin(tmp_path):
    """The round-68 question one file over, and it found the same shape.

    The atmosphere model declares four gases — `o2`, `n2`, `co2`, `h2o` — and `cabin_atm` held four
    stock states while `lm_cabin_atm` held three. **There was no `lm_cabin_h2o_kg`**, and
    `lm_water_separator` sits in the same file to remove the vapour that had no state to be in: a
    component whose subject the model does not hold, which is the round-42 absorber finding arriving
    in the atmosphere.

    A cabin may legitimately lack a gas, so the rule is a declaration rather than a refusal — the
    pair goes in `atmosphere_model.absent` with its reason. Nothing is absent today, and the list is
    what keeps a future one from being silent.
    """
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    gases = [str(g["id"]) for g in eclss["atmosphere_model"]["gases"]]
    assert gases == ["o2", "n2", "co2", "h2o"]

    for cabin in ("cabin_atm", "lm_cabin_atm"):
        held = {
            str(s["id"])
            for s in eclss["state"]
            if str(s.get("node")) == cabin and s.get("method") == "stock"
        }
        assert len(held) == 4, f"{cabin} holds {sorted(held)}"
        for gas in gases:
            assert any(gas in name for name in held), f"{cabin} has no state for {gas}"

    # And the LM's separator now has something to act on.
    components = {str(c["id"]) for c in eclss["components"]}
    assert "lm_water_separator" in components

    # Removing the state is refused rather than silently asymmetric.
    definition = copy_definition(tmp_path / "asymmetric")
    path = definition / "domains" / "eclss" / "components.yaml"
    text = path.read_text()
    stripped = re.sub(r"  - id: lm_cabin_h2o_kg\n(?:    .*\n|\n)*?(?=  - id: )", "", text, count=1)
    assert stripped != text, "the fixture no longer matches lm_cabin_h2o_kg"
    path.write_text(stripped)

    result = run_linter(definition)
    assert result.returncode == 1
    assert "names a species and no state to hold it" in result.stdout


def test_a_zone_temperature_is_on_a_node_or_declared(tmp_path):
    """Six zones carry a temperature state and five carry a *driver*, and the gap hid in the state's home.

    Two sat on the `internal` sentinel — which is not a node, so no edge can terminate on them, and
    `internal` has no inbound edge at all. The two crewed cabins were in exactly that position until
    round 55 gave them heat-rate nodes, and the radiator was in it until round 70 moved
    `zone_radiator_t` onto `radiator_reject`, where a node already existed and was already driven.

    Moving it was not free: `radiator_reject` then held two states, which the linter required an
    `advances` on `E-WATER-RAD` for, and a `state_order` — because rejection is
    `epsilon x sigma x A x T^4`, and the frozen lexicographic tiebreak sorts `radiator_rejection_w`
    *first*, computing the rejection from last tick's temperature. A one-tick error in a quantity
    that enters every thermal edge on the vehicle.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    states = {str(s["id"]): s for s in thermal["state"]}

    # Round 70 moved the radiator onto `radiator_reject` and back, because its only inbound edge
    # there was a back-edge. Round 71 gave the node a forward one — `E-ENV-RAD`, from the
    # environment — and round 72 took the last two zones, so the exemption list is empty and gone.
    assert states["zone_radiator_t"]["node"] == "radiator_reject"
    assert thermal.get("zones_not_on_nodes") in (None, {})
    node = coupling["nodes"]["radiator_reject"]
    assert node["state_order"] == ["zone_radiator_t", "radiator_rejection_w"]
    assert next(e for e in coupling["edges"] if e["id"] == "E-ENV-RAD")["kind"] == "algebraic"

    # A zone back on the sentinel with no explanation is refused.
    definition = copy_definition(tmp_path / "sentinel")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    # The exemption list is gone, so the fixture now builds a *stale* one: a zone declared as having
    # no node while its state sits on one. That is the direction the round-70 check was missing.
    path.write_text(text.rstrip("\n") + '\nzones_not_on_nodes:\n  csm_service_bay: "stale"\n')

    result = run_linter(definition)
    assert result.returncode == 1
    # The stale direction, because the exemption list is empty now: the fixture adds an entry rather
    # than removing one.
    assert "stale exemption" in result.stdout


def test_every_thermal_zone_has_a_driver_and_the_exemption_list_is_empty(tmp_path):
    """Six zones, six nodes, six drivers — and the exemption list retired rather than left standing.

    Rounds 70 and 71 took the crewed cabins and the radiator; this round takes the two bays, whose
    heat rates were already summed (`heat_inputs` assigns 630 W to the service bay and 180 W to the
    descent stage) and whose states were on the `internal` sentinel. `service_bay_heat` and
    `descent_bay_heat` are nodes now, feeding `E-BAY-HEAT-CSM` and `E-BAY-HEAT-LM`.

    **What the edges do not carry is the conductance**, and that is declared rather than filled:
    `thermal_diode.md:965` calls every thermal constant UNSPECIFIED, so the scalar that turns watts
    into kelvin is owed and a plausible one would be exactly the invented typical-spacecraft number
    that document refuses. The zone is drivable and the missing scalar is named — which is strictly
    better than a zone that is neither.

    Chasing it also found a gap in the round-70 check: it refused a zone with no node and no
    explanation, but **not a stale explanation** — so the two bays' exemptions survived the round
    that closed them. It checks both directions now.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    states = {str(s["id"]): s for s in thermal["state"]}

    # Every zone is on a node, so there is nothing left to exempt.
    assert thermal.get("zones_not_on_nodes") in (None, {}), (
        "the exemption list is stale: every zone has a node now"
    )
    assert states["zone_csm_service_t"]["node"] == "service_bay_zone_t"
    assert states["zone_lm_descent_t"]["node"] == "descent_bay_zone_t"
    assert states["service_bay_heat_w"]["total_w"] == 630
    assert states["descent_bay_heat_w"]["total_w"] == 180

    # And each zone's node has an inbound edge, which is the property all of this was for.
    driven = {str(e["to"]) for e in coupling["edges"]}
    for zone, state_id, node in (
        ("csm_cabin", "zone_csm_cabin_t", "cabin_zone_t"),
        ("csm_avionics_bay", "zone_csm_avionics_t", "coldplate_t"),
        ("csm_service_bay", "zone_csm_service_t", "service_bay_zone_t"),
        ("lm_cabin", "zone_lm_cabin_t", "lm_cabin_zone_t"),
        ("lm_descent_bay", "zone_lm_descent_t", "descent_bay_zone_t"),
        ("radiator_loop", "zone_radiator_t", "radiator_reject"),
    ):
        assert states[state_id]["node"] == node, zone
        assert node in driven, f"{zone}: {node} has no driver"
    assert len(vehicle["thermal"]["zones"]) == 6

    # A stale exemption is refused rather than tolerated.
    definition = copy_definition(tmp_path / "stale")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    path.write_text(text.rstrip("\n") + '\nzones_not_on_nodes:\n  csm_service_bay: "stale"\n')

    result = run_linter(definition)
    assert result.returncode == 1
    assert "stale exemption" in result.stdout


def test_the_bay_conductances_owe_one_scalar_each_not_two(tmp_path):
    """`G = C/tau` with `tau` declared means the conductance and the mass are one obligation.

    The two bays' time constants are **chosen** where the cabin's is derived — the cabin's relation
    gives `C = 400 kg x 900 J/kg-K = 360,000 J/K` and `G = 125 W/K`, and `tau = C/G` follows. The
    bays have a tau and a qualitative reason ("the propellant is the mass and the tank wall is the
    path") and nothing else, so their edges carried `UNCONFIGURED` and the debt was vague.

    Naming *both* the mass and the conductance would be two debts for one unknown, since either
    determines the other given tau — so the states declare `lumped_mass_kg` alone and the edges'
    relations say how `1/G` follows from it. What is owed is one scalar per bay: the mass of the
    propellant and structure the reason already names. `thermal_diode.md:965`'s refusal to publish
    thermal constants is why it is owed rather than derived, and it is why a plausible number would
    be exactly the invented figure that document refuses.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    states = {str(s["id"]): s for s in thermal["state"]}
    edges = {str(e["id"]): e for e in coupling["edges"]}

    for state_id, edge_id, tau in (
        ("zone_csm_service_t", "E-BAY-HEAT-CSM", 7200),
        ("zone_lm_descent_t", "E-BAY-HEAT-LM", 10800),
    ):
        state = states[state_id]
        assert state["tau_s"] == tau
        assert state["lumped_mass_kg"] == "UNCONFIGURED"
        # One obligation, not two: the conductance follows from the mass and tau by division.
        assert "conductance_w_per_k" not in state, f"{state_id} declares the same unknown twice"
        assert edges[edge_id]["sensitivity"]["value"] == "UNCONFIGURED"
        assert "G = C/tau" in edges[edge_id]["sensitivity"]["relation"], edge_id
        # **And the relation is a derivation now.** The round that found `lumped_mass_kg` read by
        # nothing made both edges name the scalar and the division, so the edge is no longer a
        # second count of the zone's unknown: `check_declared_derivation` skips an owed input and
        # the debt stays where the quantity lives.
        sensitivity = edges[edge_id]["sensitivity"]
        assert sensitivity["basis"] == "derived", edge_id
        assert sensitivity["derivation"]["expression"] == (
            "tau_s / (lumped_mass_kg * specific_heat_j_per_kg_k)"
        ), edge_id

    # The cabin's, by contrast, is derived from both — which is what makes the pair the template.
    cabin = states["zone_csm_cabin_t"]
    assert cabin["conductance_w_per_k"] == 125
    assert cabin["tau_s"] == 2880
    assert "360,000 J/K" in cabin["provenance"]["relation"]


def test_a_threshold_with_no_limit_is_one_debt_not_two():
    """`assert` and `clear` are one missing limit, and the walk reported them as two.

    A comparator with no value has neither term: **twenty-six thresholds declared both
    `UNCONFIGURED`**, so the vehicle's headline count carried 26 obligations that were 13... rather,
    26 fields that were 26 halves of 26 limits — one number closes each pair. The count went from 249
    to 223 the moment the walk reported the pair once at the threshold.

    The number is the folder's headline claim, which is why a double-count in it matters more than a
    double-count anywhere else: it is the figure a reader uses to judge how much is left.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]
    owed = [
        line
        for line in result.stdout.splitlines()
        if line.strip().startswith("- domains/") and "UNCONFIGURED" in line
    ]
    paired = [line for line in owed if "one missing limit" in line]
    assert paired, "no threshold pair is reported — is the fixture still unconfigured?"
    # Every collapsed pair is reported once, at the `assert`, and never also at the `clear`.
    assert all(".assert" in line for line in paired), paired[:2]
    assert not any(line.rstrip().endswith(".clear: is UNCONFIGURED") for line in owed), (
        "a `clear` is still reported separately from its `assert`"
    )

    # And the count is the honest one, not the inflated one.
    assert "with 273 declared debt(s)" in result.stdout, result.stdout[-400:]


def test_a_note_that_only_points_at_another_entry_is_refused(tmp_path):
    """A bare `note: "as above"` is a claim whose content lives somewhere else.

    This folder's recurring finding is that **a declaration no tool reads has already drifted**, and
    a note is the one field nothing read at all — every other check looks at values. Two entries had
    drifted into a bare pointer: `recon_mismatch_o2` said only "as above" while its sibling carried
    the whole argument, and `release_allocation` said the same while `release_reservation` one entry
    above it had a sentence of its own. Neither is *wrong*, which is exactly why nothing caught them.

    The failure a bare pointer produces is positional. "Above" means whatever happens to precede it,
    so reordering a file silently repoints the note: the entry goes on looking sourced while its
    justification has moved to a different claim. It also costs the reader the sentence that says why
    this entry exists separately at all — and here `consumables_diode.md:852` refuses a universal
    tolerance *per resource*, so the two reconciliation limits are separate numbers even where the
    argument they rest on is shared.

    Four pointer notes survive in the live definition and every one of them keeps a clause, so the
    check refuses a pointer with nothing behind it rather than the pattern of its opening words.
    """
    # The clause is the whole reason the second entry exists rather than being merged into the first.
    # There were four of these and there are three: the fuel-cell hydrogen entry's note was a bare
    # pointer ("as above; the 8:1 O2:H2 mass ratio fixes the relationship, not the magnitude") and
    # the round that landed the operating point replaced it with the derivation it points at, so the
    # clause it kept is now a relation rather than an anchor.
    for filename, snippet in (
        ("domains/consumables/profiles.yaml", "as above, at apollo's second propellant level"),
        ("domains/thermal/components.yaml", "as above, for the LM"),
        ("domains/thermal/profiles.yaml", "as above; 2 K wider than the CSM's upper limit"),
    ):
        assert snippet in (VEHICLE / filename).read_text(), f"{filename} lost its clause"
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-900:]
    assert "pointer with nothing behind it" not in result.stdout

    # Break one, with a *different* pointer phrase than the two the corpus had drifted into.
    definition = copy_definition(tmp_path / "bare")
    path = definition / "domains" / "consumables" / "commands.yaml"
    text = path.read_text()
    broken = text.replace(
        'why: "the inverse of a declined verb is a declined verb"', 'why: "see above"', 1
    )
    assert broken != text, "the fixture no longer matches consumables/commands.yaml"
    path.write_text(broken)

    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "pointer with nothing behind it" in result.stdout, result.stdout[-900:]
    assert "commands.yaml:declined" in result.stdout, result.stdout[-900:]


def test_a_word_that_only_starts_like_a_pointer_is_not_one(tmp_path):
    """`as aboveboard` is one word, and the check has to know that before it may refuse anything.

    The first cut of the pattern had no word boundary, so it refused `as aboved` and `as aboveboard`
    — notes that never point anywhere. A check that refuses correct prose is worse than no check,
    because the only way to satisfy it is to rewrite a sentence that was already right.
    """
    definition = copy_definition(tmp_path / "prefix")
    path = definition / "domains" / "consumables" / "commands.yaml"
    text = path.read_text()
    broken = text.replace(
        'why: "the inverse of a declined verb is a declined verb"',
        'why: "as aboveboard, which is a single word, points at nothing and is not a pointer phrase"',
        1,
    )
    assert broken != text, "the fixture no longer matches consumables/commands.yaml"
    path.write_text(broken)

    result = run_linter(definition)
    assert result.returncode == 0, result.stdout[-900:]
    assert "pointer with nothing behind it" not in result.stdout


def test_the_two_reconciliation_tolerances_are_declared_alike():
    """Two thresholds on one channel template, and only one of them said what it measures.

    `res.recon_[resource]_kg` is a template, so `res.recon_main_propellant_kg` and `res.recon_o2_kg`
    resolve to the same registered channel with the same `unit: kg`. Both thresholds are `above` on
    `|observed - ledger|`, both are owed, both carry the same dwell — and one declared
    `point_units: "kg of |observed - ledger|"` while the other declared nothing.

    Nothing was broken by the omission: `point_units` is read as an *exemption* from the linter's
    unit-agreement check, and the O2 point agrees with its channel, so no exemption was needed. That
    is what made it invisible — the field is only ever read when it is already there, so its absence
    on one half of a matched pair cannot be detected by the check that reads it. The two entries are
    now declared alike, because a reader comparing them should not have to work out whether the
    difference is meaningful.
    """
    profiles = yaml.safe_load((VEHICLE / "domains" / "consumables" / "profiles.yaml").read_text())
    by_id = {str(t["id"]): t for t in profiles["thresholds"]}

    propellant = by_id["recon_mismatch_main_propellant"]
    oxygen = by_id["recon_mismatch_o2"]

    # The same point shape and the same comparison, which is what makes them a pair at all.
    assert propellant["point"].replace("main_propellant", "[resource]") == "res.recon_[resource]_kg"
    assert oxygen["point"].replace("o2", "[resource]") == "res.recon_[resource]_kg"
    for field in ("comparator", "assert", "clear", "dwell_assert_ms", "dwell_clear_s", "severity"):
        assert propellant[field] == oxygen[field], field

    # And the same statement of what the number is, which is the half that was missing.
    assert propellant["point_units"] == oxygen["point_units"] == "kg of |observed - ledger|"
    # Neither is a pointer at the other any more: both say why this resource is its own entry.
    for threshold in (propellant, oxygen):
        note = threshold["provenance"]["note"]
        assert "consumables_diode.md:852" in note
        assert "as above" not in note
    assert "separate entry" in propellant["provenance"]["note"]
    assert "separate entry" in oxygen["provenance"]["note"]


def test_the_debts_view_groups_by_what_each_one_wants():
    """The view that looks for round 74's class of inflation, and the answer for the prose half.

    Round 74 found twenty-six thresholds reporting `assert` and `clear` separately — one missing limit
    counted as two. `--debts` is how that is looked for now: it splits the owed list into literal
    `UNCONFIGURED` scalars and prose `open_debts`, groups the first by the field it wants and the
    second by the file that keeps it.

    **Run against the corpus the round after, the prose half is clean.** `coupling.yaml`'s nineteen
    per-edge debts and the seventeen edge ids named inside its eight `open_debts` sentences are
    *disjoint*, and the one subject named from two files — the inertia tensor, in `coupling.yaml` and
    `domains/rcs/` — is one missing datum with two genuinely different consequences, each recorded
    where it bites. That is the folder's style rather than a double-count, and it is worth being able
    to say so, because the count is the headline claim.
    """
    result = subprocess.run(
        [sys.executable, str(LINTER), "--dir", str(VEHICLE), "--debts"],
        capture_output=True,
        text=True,
        check=False,
    )
    assert result.returncode == 0, result.stderr
    assert "grouped by what each wants" in result.stdout
    assert "a literal `UNCONFIGURED` scalar" in result.stdout
    assert "a prose obligation in an `open_debts` list" in result.stdout
    assert "by the field it wants" in result.stdout
    assert "by the file that keeps it" in result.stdout

    owed = re.search(r"(\d+) owed, grouped", result.stdout).group(1)
    # 247 -> 257 when every integrator began declaring its starting value (ten of the new
    # obligations are literal `UNCONFIGURED` scalars, so they are in this view as well as in the
    # headline), 257 -> 258 when the missing supply-tank pressure became a named prose debt, and
    # 258 -> 259 when the ledger block's eight unpublished names became one, 259 -> 262 when the
    # oxygen supply tank landed, and 262 -> 263 when the avionics bay's heat-rate state was named as
    # the one heated zone that has none: its 360 W is assigned to a compartment and carried by
    # nothing.

    # 273 -> 286 in round 67, and the whole of the move is one class: thirteen commanded modes
    # whose starting position no source answers, each a literal `UNCONFIGURED` scalar and therefore
    # in *both* views — the headline and this one — which is what makes them countable rather than
    # merely named.
    # 286 -> 281 in round 70, and the whole of the move is five debt entries that were one
    # node's: the fuel cell published no key while a voltage rode on it, and five edges said so.
    # 281 -> 275 in round 71, and the whole of the move is six `reads:` declarations: the edges
    # that read `link`, `vehicle_dynamics` and the two cabins no longer owe a decision.
    # 275 -> 278 in round 72: the three crew edges, whose source node the check was not asking
    # about, because it counted a different set of states than the value map writes.
    # 278 -> 280 in round 73 (the two phases whose subject sequence could not balance against one
    # phase-wide `also_present`) and straight back to 278 in round 74, which made the field one
    # entry per subject: the shape can say it now, so there is nothing left for a debt to name.
    # 278 -> 274 in round 76: the four machines `mission.yaml#launch_state` settles stopped
    # owing a starting position.
    # Unmoved in round 78, and that is the round's own measurement: §5's queue landed with nothing
    # scheduled on it, so no obligation was answered and none was created.
    # 274 -> 276 in round 77, and the two are a new *kind* of obligation rather than more of an old
    # one: `sensor_health` and `innovation_window` carry hysteresis bands whose subject is a
    # statistic — a sensor's disagreement with its peers, and normalized innovation squared — that
    # no registered point carries, so the bands name no point and cannot be read against anything.
    # 276 -> 278 in round 79, and both are declarations rather than numbers: one scalar
    # (`load_shed_class.band_value`, whose one band selects `none` at both of its boundaries) and one
    # prose obligation in `coupling.yaml#open_debts` for the three bands whose vocabulary is wider
    # than their comparator. The round adds a field to four states; nothing was answered, so nothing
    # fell.
    assert owed == "273", "the view must agree with the headline count"


def test_a_placeholder_inside_an_owed_entry_says_so(tmp_path):
    """`basis: UNCONFIGURED` is a *decision*, not an undecided one — and this round found nothing to settle.

    Round 75 called the 28 entries carrying it "open judgements" and proposed finishing them. They are
    correctly declared: `UNCONFIGURED` is the class for a value no source supplies, and the twenty-eight
    are owed values rather than undecided ones. That is the useful answer, and it corrects the premise.

    Two of them, though, carry a number the plant **uses** while the entry says its magnitudes are
    owed: `pressurant_pressure_psi.tau_s = 5`, integrated as a lag and the seed of PRP-03, and
    `pressurant_he_kg.quantum = 1.0e-05`, without which the fixed-point stock cannot exist. Read
    against `basis: UNCONFIGURED` those look contradictory until a reader finds the sentence that
    reconciles them — and a reader who does not cannot tell whether to use the number or ignore it.

    So an owed entry carrying a numeric *integrator parameter* must mark that parameter a placeholder:
    `tau_s`, `quantum`, `delay_s` and `lambda_per_h` are the four the plant reads, and whose absence
    stops a tick rather than merely leaving a quantity unset.
    """
    propulsion = yaml.safe_load(
        (VEHICLE / "domains" / "propulsion" / "components.yaml").read_text()
    )
    consumables = yaml.safe_load(
        (VEHICLE / "domains" / "consumables" / "components.yaml").read_text()
    )
    p_states = {str(s["id"]): s for s in propulsion["state"]}
    c_states = {str(s["id"]): s for s in consumables["state"]}

    assert p_states["pressurant_pressure_psi"]["provenance"]["basis"] == "UNCONFIGURED"
    assert "placeholder" in p_states["pressurant_pressure_psi"]["tau_s_placeholder"]
    # **The helium entry is the case that moved.** It was the corpus's example of a placeholder
    # inside a wholly-owed entry — `basis: UNCONFIGURED` with a `quantum_placeholder` beside a
    # `quantum` — and round 13 landed its charge from the Operational Data Book, so its provenance
    # is `historical` now. What is still owed is the *flow*, so the placeholder is still a
    # placeholder and the entry still carries one obligation: the assertion that matters is the
    # one that says the placeholder is attached to something unset.
    assert c_states["pressurant_he_kg"]["min_flow_per_s"] == "UNCONFIGURED", (
        "the placeholder's justification is that the smallest flow is owed; if that landed, this "
        "entry no longer needs the note"
    )
    assert (
        "picked because the helium feed is slow"
        in c_states["pressurant_he_kg"]["quantum_placeholder"]
    )

    definition = copy_definition(tmp_path / "unmarked")
    path = definition / "domains" / "propulsion" / "components.yaml"
    text = path.read_text()
    i = text.index("    tau_s_placeholder: >-")
    j = text.index("    provenance:", i)
    path.write_text(text[:i] + text[j:])

    result = run_linter(definition)
    assert result.returncode == 1
    assert "does not say it is a placeholder" in result.stdout


def test_every_vehicle_yaml_parses():
    """A file that does not parse is not a definition, and the linter's report is too late.

    This is a cheap guard with an embarrassing history: a flow mapping whose closing brace
    count is wrong parses on the way in and fails on the way out, and the author only finds out
    when something downstream refuses. One second here beats a debugging round later.
    """
    files = sorted(VEHICLE.glob("*.yaml")) + sorted(VEHICLE.glob("domains/*/*.yaml"))
    assert files, "no vehicle definition files found"
    broken = []
    for path in files:
        try:
            yaml.safe_load(path.read_text())
        except yaml.YAMLError as exc:  # noqa: PERF203 - one bad file should not hide the rest
            broken.append(f"{path.relative_to(VEHICLE)}: {str(exc).splitlines()[0]}")
    assert not broken, "unparseable vehicle files:\n" + "\n".join(broken)


def test_every_reserve_floor_is_a_level_the_command_can_set():
    """Fifteen floors, nine-then-eleven resources, and nothing that had ever joined them.

    `reserve_floor` is the whole of this vehicle's reserve policy and it was read by no tool: the
    level lives on a threshold in a domain's `profiles.yaml`, the resource lives in
    `set_reserve_policy`'s `resource` enum, and the gate variable above the two —
    `reserve_floor_<resource>_enable` — is what a fleet opens and closes. The join is
    `floor_resource`, and this holds it from the corpus's side the way
    `test_every_stock_initial_is_grounded` holds `initial_source`: every floor names a resource the
    command offers, the resource's declared unit is the unit of the channel the threshold monitors,
    and every resource the command offers has a floor behind it.

    The unit is the half that is easy to lose. Eight of the fifteen floors are on a percent
    channel and five on a kg channel, so `floor_kg` — the argument's name before this round — asked
    four of the resources for a number in a unit they are not measured in. The registry comes from
    the command file and the units come from `channels.yaml` through the linter's own
    `ChannelIndex`, so neither side of this assertion is a copy of the check.
    """
    linter = _linter()
    commands = yaml.safe_load((VEHICLE / "domains" / "consumables" / "commands.yaml").read_text())
    verb = next(v for v in commands["commands"] if v.get("verb") == "set_reserve_policy")
    spec = verb["argument_schema"]["resource"]
    resources = [str(v) for v in spec["values"]]
    units = {str(k): str(v) for k, v in spec["floor_units"].items()}
    assert sorted(units) == sorted(resources), (
        "the units and the resources are two lists of the same thing and they disagree"
    )

    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    registry = linter.check_channels(channels, linter.Report())
    index = linter.ChannelIndex(registry)

    floors: dict[str, list[str]] = {}
    for path in sorted((VEHICLE / "domains").glob("*/profiles.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for threshold in doc.get("thresholds") or []:
            if "reserve_floor" not in threshold:
                continue
            tid = threshold["id"]
            where = f"{path.parent.name}/{tid}"
            resource = threshold.get("floor_resource")
            assert resource, f"{where} floors a resource it does not name"
            assert resource in resources, f"{where} names {resource!r}, which the command does not offer"
            row = index.row(str(threshold["point"]))
            assert row is not None, f"{where} monitors an unregistered channel"
            assert row["unit"] == units[resource], (
                f"{where} floors {threshold['point']} in {row['unit']!r} while the command "
                f"declares {resource!r} in {units[resource]!r}"
            )
            assert isinstance(threshold["reserve_floor"], (int, float)), where
            floors.setdefault(resource, []).append(where)

    # The forwarding direction. A resource the verb offers and no threshold floors is a gate
    # variable over a level that does not exist — `o2_lm` and `pressurant_he` were exactly that
    # until this round, and they are two debts now rather than two silences.
    unfloored = sorted(set(resources) - set(floors))
    assert unfloored == ["o2_lm", "pressurant_he"], (
        f"the resources with no floor changed: {unfloored}. Each one is a debt in the linter's "
        "report, and this assertion is what stops the list drifting into a silence"
    )
    # And the link is two-way rather than a name that happens to appear: two domains floor the
    # absorbers, and both of them name the same resource.
    assert floors["absorber_capacity_csm"] == [
        "consumables/absorber_reserve_20",
        "eclss/co2_absorber_low",
    ]
    assert len(floors["prop_main"]) == 3, "apollo's 20/10/5 ladder is three floors, not one"


def test_the_linter_refuses_a_floor_whose_resource_half_disagrees(tmp_path):
    """The check held, from three directions, because the join has three ways to be wrong.

    A floor that names no resource is a level no verb can reach; a floor naming a resource the
    command does not offer is a level nothing can set; and a floor whose unit is not the unit of
    the channel it monitors is a number whose meaning depends on which file the reader opened.
    The third is the one with a defect behind it — the argument was named `floor_kg` while four of
    its resources are measured in percent — and it is refused at the *threshold* rather than at the
    argument, because the argument can only be judged against the channels.
    """

    def refusal(name: str, relative: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(tmp_path / name)
        path = definition / relative
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        result = run_linter(definition)
        assert result.returncode == 1, f"{name}: the linter composed on a broken corpus"
        assert needle in result.stdout, f"{needle!r} did not fire:\n{result.stdout[-1500:]}"

    commands = "domains/consumables/commands.yaml"
    profiles = "domains/consumables/profiles.yaml"
    # The link is absent.
    refusal(
        "unlinked",
        profiles,
        "    reserve_floor: 20\n    floor_resource: prop_main\n",
        "    reserve_floor: 20\n",
        "declares a `reserve_floor` and no `floor_resource`",
    )
    # The link names a resource the verb does not offer.
    refusal(
        "unknown-resource",
        profiles,
        "    floor_resource: prop_main\n",
        "    floor_resource: propellant\n",
        "names resource 'propellant', which the registry does not declare",
    )
    # The two halves disagree about the unit. Three thresholds floor `prop_main`, so the refusal
    # is three refusals — one per threshold, which is where the unit can be read.
    refusal(
        "unit",
        commands,
        '          prop_main: "%"\n',
        "          prop_main: kg\n",
        "while `set_reserve_policy` declares 'prop_main' to be floored in 'kg'",
    )
    # And the argument may not be named for one of the units its resources are not all in.
    refusal(
        "argument-name",
        commands,
        "      floor: {type: number, minimum: 0}\n",
        "      floor_kg: {type: number, minimum: 0}\n",
        "is named for the unit 'kg'",
    )


def test_every_command_edge_lands_where_a_state_says_a_command_writes():
    """The command surface's two halves, held in *both* directions.

    Round 23 joined the state's side to the graph's: a state declaring `command:<verb>` must live on
    a node an `E-CMD-*` edge reaches. The other direction was never walked, and six of the eleven
    edges landed on a node where no state declares a command mover — including four states that
    declared nothing at all about what moves them, each of which is the whole of what its verb
    changes. `E-CMD-*`'s own sensitivity says what the edge means — *"the coupling is the signal
    itself; one unit in, one unit out"* — so the family asserts that a command **sets a state** on
    the node it lands on, and that assertion had no reader.

    This derives both sides from the corpus rather than restating a count: the edges from the graph,
    the writers from the domain components. The symmetry is the property — ten and ten with nothing
    on either side is what "the two halves agree" looks like, and an assertion on one direction
    alone would pass on a graph that had grown an edge to nowhere.
    """
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    commanded = {
        str(edge["to"]): str(edge["id"])
        for edge in coupling["edges"]
        if str(edge.get("from")) == "command_executive" and edge.get("kind") == "discrete"
    }
    written: dict[str, list[str]] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for state in doc.get("state") or []:
            verbs = [
                str(m).split(":", 1)[1]
                for m in state.get("moved_by") or []
                if str(m).startswith("command:")
            ]
            if verbs and state.get("node") != "internal":
                written.setdefault(str(state["node"]), []).append(f"{path.parent.name}.{state['id']}")

    assert len(commanded) == 10, f"the E-CMD family changed size: {sorted(commanded.values())}"
    assert sorted(commanded) == sorted(written), (
        "a node the executive reaches with no state declaring a command mover is the signal "
        "arriving where nothing is commanded, and a state declaring one on a node no edge reaches "
        f"is a command with no path in. Edges: {sorted(commanded)}; writers: {sorted(written)}"
    )
    # The four that were silent, named, because a future round that adds a fifth mover here should
    # have to say which state it is moving.
    assert written["instrumentation"] == ["avionics.instrumentation_power"]
    assert written["link"] == ["comms.link_snr", "comms.tx_power"]
    assert written["nav_state"] == ["gnc.nav_solution"]
    assert written["structure_config"] == ["structure.pyro_fired"]

    # And the one edge that turned out to be a false claim rather than a missing declaration. The
    # ladder is a threshold response to bus voltage — its own `logic:` reason says the bus
    # thresholds drive it — so `E-CMD-BUS` was retargeted, and the id went with it.
    ids = {str(edge["id"]) for edge in coupling["edges"]}
    assert "E-CMD-BUS" not in ids, "the ladder edge is back on the executive and no command sets a tier"
    shed = next(edge for edge in coupling["edges"] if edge["id"] == "E-BUS-SHED")
    assert shed["from"] == "bus_a" and shed["to"] == "load_shed_state"
    assert shed["sensitivity"]["regimes"], "a discrete edge out of the bus is a table, not a gain"
    # Its rungs are the profile's thresholds reused by id rather than restated, which is the
    # construction `E-BUS-RCS` uses and the reason a change to the ladder moves this edge with it.
    rungs = [r["when"] for r in shed["sensitivity"]["regimes"]]
    assert rungs == [
        "nominal",
        "bus_a_undervoltage",
        "bus_a_shed_p3",
        "bus_a_shed_p2",
        "bus_a_survival",
        "otherwise",
    ], rungs
    profiles = yaml.safe_load((VEHICLE / "domains" / "power" / "profiles.yaml").read_text())
    declared = {str(t["id"]) for t in profiles["thresholds"]}
    for rung in rungs[1:-1]:
        assert rung in declared, f"the rung {rung!r} names no threshold in the power profile"
    # The ladder has no rung that selects P1, and that is a debt rather than a silence.
    class_state = next(
        state
        for state in yaml.safe_load(
            (VEHICLE / "domains" / "power" / "components.yaml").read_text()
        )["state"]
        if state["id"] == "load_shed_class"
    )
    assert "P1" in class_state["unit"], class_state["unit"]
    assert not [t for t in profiles["thresholds"] if "shed_p1" in str(t["id"])]


def test_the_plant_counts_a_regime_table_as_a_declared_sensitivity():
    """Two questions about one field, and the readiness figure was answering the wrong one.

    The integrator asks *can I multiply by this?* — and a `regimes` table cannot be multiplied by,
    so `usable` is right to say no. A reader asking whether a sensitivity has been *declared* has a
    different question: the corpus has two complete forms, and the linter *requires* the table form
    of a discrete edge out of physical equipment, because *"a mode selection is a table rather than
    a sensitivity, and a scalar here would be a proportional law the vehicle does not have."*

    `--readiness` used `usable` for both, so every regime edge read as undeclared — **eight** of
    them, including the three bus edges the flagship thermal cycle turns on. The figure said the
    vehicle owed a number where it had correctly declared a table. It surfaced when `E-CMD-BUS`'s
    retarget moved a ninth edge from one form to the other and the headline fell, which is a
    question about the vehicle having no answer in the vehicle at all.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = [
        plant.Edge(
            id=str(edge["id"]),
            source=str(edge["from"]),
            target=str(edge["to"]),
            kind=str(edge["kind"]),
            sensitivity=edge.get("sensitivity") or {},
        )
        for edge in coupling["edges"]
    ]
    by_id = {edge.id: edge for edge in edges}
    table = by_id["E-BUS-COMM"]
    assert table.sensitivity.get("value") is None and table.sensitivity["regimes"]
    assert table.declared, "a regime table is the complete answer and must read as declared"
    assert not table.usable, (
        "the integrator multiplies by a value and a table is not one; if this ever becomes True the "
        "stock integrator will start applying a mode selection as a gain"
    )
    assert by_id["E-CMD-PUMP"].usable is False, "the pump edge owes its rated speed"
    assert by_id["E-GEOM-LINK"].usable is True

    # And the headline is the count of *declared* edges, which is the two forms together.
    scalar = [e for e in edges if e.sensitivity.get("value") not in (None, "UNCONFIGURED")]
    tables = [e for e in edges if e.sensitivity.get("regimes")]
    assert len(tables) == 8, f"the regime edges changed: {[e.id for e in tables]}"
    assert len(scalar) + len(tables) == 69
    ready = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "plant.py"), "--readiness"],
        capture_output=True,
        text=True,
        check=False,
    )
    assert ready.returncode == 0, ready.stderr
    found = re.search(r"edges with a sensitivity\s+(\d+) / (\d+)", ready.stdout)
    assert (int(found.group(1)), int(found.group(2))) == (69, len(edges)), found.group(0)


def test_a_verb_that_starts_a_state_is_declared_rather_than_described(tmp_path):
    """`logic:<reason>` was where the corpus put a verb, and a sentence is read by nothing.

    `moved_by`'s rule draws a line between a `command:` mover, which must be able to express the
    value it sets, and a verb that only *starts* the state — its own comment names
    `request_imu_alignment` and `arm_event` as the class. The corpus wrote those as prose, and five
    of the twenty-two reasons named a verb in backticks. **`trigger:<verb>` is the declaration**:
    resolved against the registry exactly as `command:` is, and skipped from the vocabulary test
    because that test is the one a trigger cannot pass.

    Two properties make the kind honest rather than a loophole, and both are asserted here. A
    `trigger:` whose vocabulary *does* reach the state's values is a `command:` wearing a weaker
    kind — the weaker kind has no obligation, so without the guard the field would be a way to opt
    out of the rule instead of a statement about the verb. And a `logic:` reason may no longer name
    a registered verb at all, because naming one is what `trigger:` is for.

    The state this found is the reason it matters. `power.lcl_tripped`'s reason read *"the
    protection trips it and `reset_latched_fault` is the only thing that clears it"* — and
    `reset_latched_fault`'s `fault_id` takes `thruster_health`, `allocation_status` and
    `safety_state`, three RCS conclusions with no LCL among them. The verb that clears an LCL is
    `set_breaker`, whose own help says "`reset` clears a latched LCL". A prose mover is checked by
    nothing, so a wrong one read exactly like a right one.
    """
    verbs: dict[str, dict[str, object]] = {}
    for path in sorted((VEHICLE / "domains").glob("*/commands.yaml")):
        for verb in (yaml.safe_load(path.read_text()) or {}).get("commands") or []:
            verbs[str(verb["verb"])] = verb

    found: dict[str, list[str]] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []:
            for mover in state.get("moved_by") or []:
                kind, _, name = str(mover).partition(":")
                if kind == "trigger":
                    assert name in verbs, (state["id"], name)
                    found.setdefault(str(state["id"]), []).append(name)

    assert found == {
        "maneuver_state": ["load_burn"],
        "imu_alignment": ["request_imu_alignment"],
        "lcl_tripped": ["set_breaker"],
        "arm_state": ["arm_event"],
        "docking_latch_state": ["set_docking_latch"],
    }, found
    # The verb that clears an LCL is the one whose help says so, and the one the reason used to
    # name cannot — which is the whole of what the prose form cost.
    assert "reset" in verbs["set_breaker"]["argument_schema"]["state"]["values"]
    assert "clears a latched LCL" in verbs["set_breaker"]["help"]
    assert "lcl" not in verbs["reset_latched_fault"]["argument_schema"]["fault_id"]["values"]

    def refusal(name: str, rel: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(tmp_path / name)
        path = definition / rel
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {rel}: {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, out[-1400:]

    # A trigger that could set the value is a command wearing a weaker kind.
    refusal(
        "trigger-dodges",
        "domains/power/components.yaml",
        '      - "command:set_bus_tie"\n',
        '      - "command:set_bus_tie"\n      - "trigger:set_bus_tie"\n',
        "as a `trigger:`, and its arguments can take",
    )
    # A trigger naming a verb nobody registers, which is what the prose form could always be.
    refusal(
        "trigger-unknown",
        "domains/power/components.yaml",
        '      - "trigger:set_breaker"\n',
        '      - "trigger:reset_the_lcl"\n',
        "which no domain registers",
    )
    # And the prose form itself, closed.
    refusal(
        "prose-verb",
        "domains/power/components.yaml",
        '      - "logic:the protection trips it and reports it on power.lcl_[n]_state; one controlled reclose, then latch"\n',
        '      - "logic:the protection trips it and `set_breaker` is the only thing that clears it"\n',
        "names verb 'set_breaker' inside a `logic:` reason",
    )


def test_interlocks_is_a_list_or_the_sentinel_and_nothing_else(tmp_path):
    """A field with two forms, of which the check read one.

    Every rule about `interlocks` was written `if isinstance(interlocks, list)`, so the sentinel was
    skipped — and so was *anything else written as a string*. A verb declaring its real guards as
    `"pressurant_low, feed_pressure_low"` composed with the guards silently gone, and so did
    `"nothing to see here"`; two of those are broken copies in `.scratch/r29/`. Meanwhile the rule's
    own message named the sentinel `none` while the corpus wrote `none - reviewed` in **twenty-three
    of the fifty-eight verbs**, which is what a field nothing validates accumulates: a sentence
    fragment in a value position, and no way to tell a deliberate "there are none" from a typo.

    The sentinel is `none` and it is exact. What the old spelling recorded — that somebody looked —
    is a `provenance` note like every other basis here, and a second wording for one value is a second
    name for it.
    """
    verbs: dict[str, dict[str, object]] = {}
    for path in sorted((VEHICLE / "domains").glob("*/commands.yaml")):
        for verb in (yaml.safe_load(path.read_text()) or {}).get("commands") or []:
            verbs[str(verb["verb"])] = verb

    assert len(verbs) == 58, len(verbs)
    sentinel = sorted(v for v, s in verbs.items() if s.get("interlocks") == "none")
    guarded = sorted(v for v, s in verbs.items() if isinstance(s.get("interlocks"), list))
    assert len(sentinel) == 23, sentinel
    assert len(guarded) == 35, guarded
    assert not [v for v, s in verbs.items() if isinstance(s.get("interlocks"), str) and v not in sentinel]
    for name in guarded:
        assert verbs[name]["interlocks"], f"{name} declares an empty guard list; write `none`"
    # No verb declares a guard list *and* the sentinel's spelling, which is the shape a migration
    # that missed a file leaves behind.
    assert not [v for v in verbs if verbs[v].get("interlocks") == "none - reviewed"]

    def refusal(name: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / "domains" / "propulsion" / "commands.yaml"
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, out[-1400:]

    guards = "    interlocks: [pressurant_low, feed_pressure_low, prop_cutoff_guard_5]\n"
    # The three real guards, written as a string, composed before this round.
    refusal(
        "guards-as-string",
        guards,
        '    interlocks: "pressurant_low, feed_pressure_low, prop_cutoff_guard_5"\n',
        "A string is not a guard list",
    )
    refusal(
        "nothing-as-string",
        guards,
        '    interlocks: "nothing to see here"\n',
        "A string is not a guard list",
    )
    refusal(
        "sentinel-reworded",
        "    interlocks: none\n",
        "    interlocks: none whatsoever\n",
        "A string is not a guard list",
    )


def test_a_guard_that_applies_to_one_value_of_an_argument_says_so(tmp_path):
    """A guard is per-verb and a verb's arguments are not, so the conditional case was inexpressible.

    Two verbs state one anyway, and they fail in opposite directions:

    `propulsion.arm_engine` declares `pressurant_low`, `feed_pressure_low` and `prop_cutoff_guard_5`
    for the whole verb, and its help says *"`safe` is always available and never refused"*. The
    `not_implemented` entry that merged apollo's `arm_engine` and `safe_engine` says the same — the
    asymmetry "is preserved in the single verb's semantics instead". It was not: the merged verb
    refused `safe` exactly when the feed was failing, which is the one moment safing matters, and
    refusing to de-energise an engine because its feed is low is backwards.

    `rcs.set_rcs_quad` is the mirror. Its help said a latched group "cannot be re-enabled until those
    are cleared", its provenance said the asymmetry "survives from the spec ... in `help`", and the
    verb declared `interlocks: none` — so `HELP.md`, the whole of what a fleet is told before it
    calls a verb, promised a refusal nothing produced. The fix there is the opposite one: the
    declaration is the decision (the vehicle shows the authority cost rather than preventing the
    decision, which the same file argues at length), so the prose moved.

    `interlocks_when` is the condition, and it is refused wherever it would say nothing — on `none`,
    on a non-enum argument, on a value the argument cannot take, on *every* value it can take, or
    without a reason.
    """
    arm = yaml.safe_load((VEHICLE / "domains" / "propulsion" / "commands.yaml").read_text())
    verb = next(v for v in arm["commands"] if v["verb"] == "arm_engine")
    assert verb["interlocks"] == ["pressurant_low", "feed_pressure_low", "prop_cutoff_guard_5"]
    assert verb["interlocks_when"]["argument"] == "state"
    assert verb["interlocks_when"]["values"] == ["armed"]
    assert verb["interlocks_when"]["why"].strip()
    # `safe` is the value the guards do not apply to, and it is the one the help promises for.
    assert "never refused" in verb["help"]

    rcs = yaml.safe_load((VEHICLE / "domains" / "rcs" / "commands.yaml").read_text())
    quad = next(v for v in rcs["commands"] if v["verb"] == "set_rcs_quad")
    assert quad["interlocks"] == "none"
    assert "interlocks_when" not in quad
    assert "cannot be re-enabled" not in quad["help"], "the help promises a refusal nothing produces"
    assert "permitted rather than refused" in quad["help"]

    # The condition reaches the fleet: `HELP.md` is generated from the registry and is where a
    # fleet reads what will refuse it.
    generated = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "generate_help.py"), "--dir", str(VEHICLE)],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    assert "only when `state` is `armed`" in generated, generated[-800:]

    block = (
        "    interlocks_when:\n"
        "      argument: state\n"
        "      values: [armed]\n"
        "      why: >-\n"
        "        the three guards are about *arming*, and safing is not refused by any of them. `apollo_diode.md:241`\n"
        "        lists arm and safe as two verbs and this vehicle merged them into one binary argument, so the\n"
        "        asymmetry the merge was made to preserve has to be sayable here or it is lost: an armed engine\n"
        "        on a failing feed is the hazard F-01 is about, and a *safe* command is how a crew ends that\n"
        "        hazard. Declaring the three guards for the whole verb refused `safe` exactly when the feed was\n"
        "        failing — the one moment it matters — and refusing to de-energise an engine because its feed is\n"
        "        low is backwards\n"
    )

    def refusal(name: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / "domains" / "propulsion" / "commands.yaml"
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, out[-1400:]

    refusal("no-argument", block, block.replace("argument: state", "argument: throttle"),
            "which is not an enum argument of this verb")
    refusal("bad-value", block, block.replace("values: [armed]", "values: [disarmed]"),
            "cannot take")
    refusal("every-value", block, block.replace("values: [armed]", "values: [armed, safe]"),
            "names every value 'state' takes")
    refusal(
        "no-why",
        block,
        block[: block.index("why: >-")] + 'why: ""\n',
        "which is a claim about the vehicle",
    )


def test_a_command_value_says_which_argument_carries_the_value():
    """The rule proved the verb could say *a* value, and nothing said what each value becomes.

    `check_domain` requires `values & offered` non-empty for a `command:` mover — and that was the
    whole of it. Which argument carries the value, and what each of its values becomes, was prose;
    and for three states there was not even a vocabulary to compare against, so the rule was silent
    exactly where the state could not hold what its command sets.

    `structure.relief_valve_state` was a `bool` and `set_relief_valve`'s `state` takes `auto`,
    `open` and `isolated`: two of the three had to collapse onto one boolean, so the vehicle could
    be told to isolate its last line of defence against F-09's trapped-line overpressure and could
    not report that it was isolated. The corpus had already written that diagnosis, on
    `power.bus_tie_closed` — *"a boolean has no third value to latch into … the same fault as a
    regulator position it cannot report, arriving through a type rather than a vocabulary."*

    `crew.switch_panel` was the second and the link was simply wrong: its own note and its channel's
    both say agents observe it and cannot move it, and `set_display_mode`'s gate, conflict domain
    and provenance are all about displays. That is this test's other half — a state may not be moved
    by a verb its own record says cannot move it.
    """
    states: dict[str, dict[str, object]] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        doc = yaml.safe_load(path.read_text()) or {}
        for state in doc.get("state") or []:
            states[f"{path.parent.name}.{state['id']}"] = state
    verbs = {}
    for path in sorted((VEHICLE / "domains").glob("*/commands.yaml")):
        for verb in (yaml.safe_load(path.read_text()) or {}).get("commands") or []:
            verbs[str(verb["verb"])] = verb

    # The two type fixes, and the mis-link.
    assert states["structure.relief_valve_state"]["unit"] == "enum[auto,open,isolated]"
    panel = states["crew.switch_panel"]
    assert panel["unit"] == "map[switch_id,bool]"
    assert not [m for m in panel["moved_by"] if str(m).startswith("command:")], panel["moved_by"]
    assert "cannot move them" in " ".join(str(panel["provenance"]["note"]).split())
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    switches = next(
        row for row in channels["crew"] if isinstance(row, dict) and row.get("id") == "controls.switches"
    )
    assert switches["unit"] == panel["unit"], "the channel and the state are one declaration"

    # Every declared effect: the verb is a mover, the argument is an enum argument, the targets are
    # values the state can hold, and no two argument values become one state value.
    declared = 0
    constants: list[str] = []
    for where, state in sorted(states.items()):
        movers = [
            str(m).split(":", 1)[1] for m in state.get("moved_by") or [] if str(m).startswith("command:")
        ]
        entries = state.get("command_value") or []
        for entry in entries:
            declared += 1
            assert entry["verb"] in movers, (where, entry["verb"])
            spec = verbs[str(entry["verb"])]["argument_schema"][str(entry["argument"])]
            assert spec["type"] == "enum", (where, entry["argument"])
            assert str(entry.get("why") or "").strip(), where
            if entry.get("constant") is not None:
                constants.append(f"{where}.{entry['verb']}")
                continue
            if entry.get("computed") is not None or entry.get("constant") is not None:
                # A state the command changes rather than assigns, and a value the same every
                # time: neither has a mapping to check.
                continue
            if "maps" not in entry:
                # An entry that declares only a key: the values are the state's own.
                assert entry.get("key"), (where, entry)
                continue
            values = set()
            for match in re.findall(r"enum\[([^\]]*)\]", str(state.get("unit") or "")):
                values.update(v.strip() for v in match.split(","))
            targets: dict[str, str] = {}
            for source, target in entry["maps"].items():
                assert str(source) in [str(v) for v in spec["values"]], (where, source)
                if target == "UNCONFIGURED":
                    assert entry.get("note"), (where, source)
                    continue
                if values:
                    # A state with a vocabulary holds values *from* it. `str(False)` is not `'off'`:
                    # YAML 1.1 reads an unquoted `off` as a boolean, so a value spelled that way has
                    # to be quoted and this is what says so.
                    assert str(target) in values, (where, source, target)
                else:
                    # A state with none — a per-element boolean, or a rate — holds whatever its
                    # type holds, and the mapping is the only place that says so.
                    assert isinstance(target, (bool, int, float)), (where, source, target)
                key = repr(target)
                assert key not in targets, (
                    f"{where} sends both {targets[key]!r} and {source!r} to {target!r}: a state that "
                    "cannot tell two modes apart cannot report either"
                )
                targets[key] = str(source)
    # Five quantity states joined the eight mode ones this round, and one keyed state declares
    # nothing but its key.
    assert declared == 17, declared
    assert sorted(constants) == [
        "rcs.thruster_valve.isolate_rcs_manifold",
        "structure.pyro_fired.execute_event",
    ], constants
    # The two grounded mappings, and the one that is honestly owed.
    tie = states["power.bus_tie_closed"]["command_value"][0]
    assert tie["maps"] == {"auto": "UNCONFIGURED"} and tie["note"].strip()
    assert states["propulsion.sps_state"]["command_value"][0]["maps"] == {"safe": "standby"}
    assert states["propulsion.aps_state"]["command_value"][0]["maps"] == {"safe": "off"}
    rate = states["comms.telemetry_rate"]["command_value"][0]
    assert rate["maps"]["low"] == 1600 and rate["maps"]["high"] == 51200
    published = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())["comms"]["rates"]
    assert {r["id"]: r["bps"] for r in published} == {"low": 1600, "high": 51200}


def test_the_linter_refuses_a_command_whose_effect_is_not_declared(tmp_path):
    """The check held, in the five ways the declaration can be wrong.

    The type defect and its cover-up: a `bool` state for a three-valued command, and a mapping that
    sends two of the three modes to one boolean. The gap: a value the verb offers that no mapping
    answers. The shape: an effect for a verb the state does not claim, an argument the verb does not
    have, a target the state cannot hold, an empty reason, and an `UNCONFIGURED` with no note saying
    what would close it. And the mis-link: the display mode wired back to the crew's switch panel.
    """

    def refusal(name: str, rel: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / rel
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, out[-1400:]

    # A `bool` cannot hold three modes, and no mapping may pretend otherwise.
    refusal(
        "bool-again",
        "domains/structure/components.yaml",
        '    unit: "enum[auto,open,isolated]"\n',
        '    unit: "bool"\n',
        "declares none, and 'set_relief_valve' is a `command:` mover",
    )
    refusal(
        "collapse",
        "domains/structure/components.yaml",
        '    unit: "enum[auto,open,isolated]"\n',
        '    unit: "bool"\n'
        "    command_value:\n"
        "      - verb: set_relief_valve\n"
        "        argument: state\n"
        "        maps:\n"
        "          auto: false\n"
        "          open: true\n"
        "          isolated: false\n"
        '        why: "a mapping that throws away two of the three modes"\n',
        "sends both",
    )
    # A value the command takes that the state has no answer for.
    refusal(
        "gap",
        "domains/crew/components.yaml",
        "          reset: in\n",
        "",
        "declares no mapping for ['reset']",
    )
    # The shape rules.
    refusal(
        "target",
        "domains/crew/components.yaml",
        "          reset: in\n",
        "          reset: closed\n",
        "which breaker_panel cannot hold",
    )
    refusal(
        "not-a-mover",
        "domains/power/components.yaml",
        "      - verb: set_bus_tie\n",
        "      - verb: set_load\n",
        "which is not a `command:` mover of this state",
    )
    refusal(
        "no-why",
        "domains/power/components.yaml",
        "        why: >-\n"
        "          `open` and `closed` are the identity. `auto` is not a position at all: it hands the\n"
        "          decision to the service, \"which closes only when the two buses are within 1 V and no\n"
        "          ground fault is active\" (`set_bus_tie`'s help), so it names no value this state can hold\n",
        '        why: ""\n',
        "is empty. What a command value becomes in a state is a claim",
    )
    # And the mis-link this round removed.
    refusal(
        "display-on-switches",
        "domains/crew/components.yaml",
        '      - "logic:the crew throw them, and no verb writes a switch — which is what `controls.switches` being a crew-only surface means"\n',
        '      - "command:set_display_mode"\n',
        "declares none, and 'set_display_mode' is a `command:` mover",
    )


def test_a_vocabulary_says_which_of_its_members_the_source_gives(tmp_path):
    """One vocabulary, declared twice, with two accounts of it — and only one said where the fourth
    member came from.

    `apollo_diode.md:95` gives `cabin_regulator_state` as `primary/emergency/isolated`; the state
    declares four. The fourth is `closed`, and the reason it exists was written down **in the
    channel's note rather than the state's**: `channels.yaml#eclss.cabin_regulator_state` records
    that the state/channel binding caught the channel publishing three values for a state that can
    take four, so the vehicle could be in a configuration its own telemetry could not report. A
    reader of the *state* saw `enum[closed,primary,emergency,isolated]` beside a note saying apollo
    publishes three members, and nothing reconciled them — **an addition the vehicle argued for and a
    typo look the same.**

    `unit_source` names the members the cited source gives, `unit_added` names the vehicle's own with
    a reason, and `check_unit_provenance` holds the split against the state's `unit` so it is complete
    and cannot overlap.

    **And the same round sources the position.** Round 80 withdrew this note's guess that `closed`
    was the launch configuration and left the mapping open. The launch checklist answers it: `MAIN REG
    vlv (2) - OPEN` with `EMER CAB PRESS vlv - OFF` (p. 18, PANEL 351) is the main regulator in
    service and the emergency one off — `primary` — which is two valves in the source's vocabulary
    rather than one word in the corpus's.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1200:]

    states: dict[str, dict] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []:
            if isinstance(state, dict) and state.get("id"):
                states[state["id"]] = state

    regulator = states["cabin_regulator_position"]
    # The split is the source's three and the vehicle's one, and it accounts for every member.
    assert regulator["unit_source"] == ["primary", "emergency", "isolated"]
    assert list(regulator["unit_added"]) == ["closed"]
    assert regulator["unit_added"]["closed"].strip()
    assert set(regulator["unit_source"]) | set(regulator["unit_added"]) == {
        "closed",
        "primary",
        "emergency",
        "isolated",
    }

    # The channel declares the same four members — the binding holds them as a set, and the two
    # spellings do not even agree on order — and the state now carries the account the channel's
    # note used to be the only home of.
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    channel = next(c for c in channels["eclss"] if c["id"] == "eclss.cabin_regulator_state")
    members = re.findall(r"enum\[([^\]]*)\]", regulator["unit"])[0].split(",")
    channel_members = re.findall(r"enum\[([^\]]*)\]", channel["unit"])[0].split(",")
    assert set(channel_members) == set(members)
    assert "unit_added" not in channel, "the vocabulary's provenance belongs where the unit is"

    # And the position is sourced, declared once, and the state agrees with the block.
    mission = yaml.safe_load((VEHICLE / "mission.yaml").read_text())
    assert mission["launch_state"]["states"]["cabin_regulator_position"] == "primary"
    assert "p. 18" in mission["launch_state"]["sourced"]["cabin_regulator_position"]
    assert regulator["initial"] == "primary"
    provenance = regulator["initial_provenance"]
    assert provenance["basis"] == "historical"
    assert provenance["source"] == "mission.yaml:launch_state"

    def refusal(name: str, path: tuple[str, ...], old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        target = definition.joinpath(*path)
        text = target.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        target.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1400:]}"

    eclss = ("domains", "eclss", "components.yaml")
    # A member credited to the source that the state cannot take.
    refusal(
        "source-member-not-in-unit",
        eclss,
        "    unit_source: [primary, emergency, isolated]\n",
        "    unit_source: [primary, emergency, isolated, open]\n",
        "a member credited to the source that the state cannot take",
    )
    # A member of the vocabulary that the split does not account for.
    refusal(
        "member-unaccounted",
        eclss,
        "    unit_source: [primary, emergency, isolated]\n",
        "    unit_source: [primary, emergency]\n",
        "does not account for",
    )
    # A member that is both the source's and the vehicle's.
    refusal(
        "member-in-both",
        eclss,
        "    unit_added:\n      closed: >-\n",
        "    unit_added:\n      isolated: >-\n      closed: >-\n",
        "A member is the source's or the vehicle's",
    )
    # An addition with no reason. The reason's own prose is moved onto a second key rather than
    # deleted, because the break has to leave a document that still parses — a fixture that does not
    # parse tests the parser, and round 82 is the round that learned that the hard way.
    refusal(
        "addition-without-reason",
        eclss,
        "      closed: >-\n        the vehicle's own, and the most consequential of the four:",
        '      closed: ""\n      spare: >-\n        the vehicle\'s own, and the most consequential of the four:',
        "with no reason",
    )
    # A split on a state whose unit is not a vocabulary at all.
    refusal(
        "split-with-no-vocabulary",
        ("domains", "comms", "components.yaml"),
        "    unit: bit/s\n",
        "    unit: bit/s\n    unit_source: [high]\n",
        "so there is nothing for the split to be a split of",
    )


def test_the_corpus_is_a_declared_set_of_files_and_not_every_yaml_in_the_tree(tmp_path):
    """Two tests answered "every document the corpus has" with `VEHICLE.rglob("*.yaml")`, and that
    set is not the corpus.

    **The round law plants broken copies under `.scratch/rNN/fixtures/`**, and a broken copy of the
    corpus is a corpus-shaped tree — five top-level documents and a `domains/` directory. So every
    fixture any round had ever planted was read by those two tests as if it were the vehicle:
    sixteen rounds of them, `r66` through `r81`. It was invisible because a fixture with one field
    changed is still valid YAML, and it became loud only when round 81 planted a `vehicle.yaml` that
    does not parse — which is the *right* thing to plant for a check about parse failures and the
    wrong thing to leave where a glob can find it.

    **The repair is a declaration rather than a better glob**, because a set a test has to infer is a
    set that will be inferred differently: `plant.corpus_files` says what the vehicle is made of, and
    the two tests read that instead. This asserts both halves — that the declared set is the corpus's
    own shape, and that a corpus-shaped copy under a scratch directory is not in it.
    """
    plant = _plant()
    declared = {str(path.relative_to(VEHICLE)) for path in plant.corpus_files(VEHICLE)}
    domains = sorted(path.name for path in (VEHICLE / "domains").iterdir() if path.is_dir())
    assert declared == set(plant.CORPUS_TOP_LEVEL) | {
        f"domains/{domain}/{name}" for domain in domains for name in plant.CORPUS_DOMAIN_FILES
    }, sorted(declared)
    # Nothing under a scratch directory is the vehicle, however corpus-shaped it is.
    assert not [name for name in declared if ".scratch" in name], sorted(declared)

    # And the copy the round law plants is invisible to the declaration — the fixture that broke
    # this is the one to hand it, non-parsing content and all.
    where = copy_definition(fixture_dir(tmp_path, "corpus-set"))
    planted = where / ".scratch" / "r99" / "fixtures" / "broken"
    planted.mkdir(parents=True)
    (planted / "vehicle.yaml").write_text("  : :\n")
    (planted / "mission.yaml").write_text("{}\n")
    reached = {str(path.relative_to(where)) for path in plant.corpus_files(where)}
    assert not [name for name in reached if ".scratch" in name], sorted(reached)
    # The corpus the declaration names is still all there: the copy has the same sixty files.
    assert len(reached) == len(declared), sorted(reached ^ declared)


def test_no_vocabulary_is_written_in_a_word_yaml_reads_as_a_boolean(tmp_path):
    """`values: [on, off]` is the list `[True, False]`, and the fleet is what reads it.

    **YAML 1.1 counts `on`, `off`, `no` and `yes` as booleans.** Eleven arguments across nine verbs
    declared a two-valued vocabulary that way, and every consequence was at the fleet-facing
    surface: `state.json`'s capability snapshot publishes the schema so a machine can build a call
    and it published `true`/`false`; `HELP.md` — the whole of what a fleet is told before it calls —
    rendered ``- `state`: one of: True, False`` beside prose saying "Switch the power amplifier on or
    off"; and `set_o2_flow` and `set_o2_source` were worse, because their `flow` vocabulary is
    `off, low, nominal, high` and `off` became `False` *in the middle of a list* beside three
    strings.

    The trap was met twice before it was understood. Round 30 found it in a mapping *target* —
    `safe: off` against an engine vocabulary that contains `off`, where `str(False)` is not `'off'`
    — and fixed the line. This round met it in the pump's own `maps` keys, and the crash that
    followed (`'bool' object has no attribute 'endswith'`, from a convention walk that expected a
    string key) is what showed it is a property of the format rather than of a line: two positions
    are vocabularies the corpus reads and prints as text — a `values` member and a mapping key — and
    a boolean *value* is neither, which is why this is not "no booleans".

    The linter also had to stop crashing on it. A refusal that never gets printed because a later
    walk raised is the failure `test_an_unloadable_vehicle_refuses_instead_of_crashing` exists for,
    so the walk is guarded and the refusal is reported before any of them run.
    """
    words: list[str] = []
    # `plant.corpus_files`, not `VEHICLE.rglob("*.yaml")` — the round law's fixture trees are
    # corpus-shaped and were being read here as the vehicle. See that function's docstring.
    for path in _plant().corpus_files(VEHICLE):
        document = yaml.safe_load(path.read_text())

        def walk(node: object, where: str, named: str) -> None:
            # `named` is passed rather than closed over: a closure that reads the loop variable is
            # the binding ruff's B023 flags, and here it would also be a claim about *when* `walk`
            # runs rather than about what it reads.
            if isinstance(node, dict):
                for key, value in node.items():
                    if isinstance(key, bool):
                        words.append(f"{named}:{where}: key {key!r}")
                    walk(value, f"{where}.{key}", named)
            elif isinstance(node, list):
                for value in node:
                    if where.endswith("values") and isinstance(value, bool):
                        words.append(f"{named}:{where}: {value!r}")
                    walk(value, f"{where}", named)

        walk(document, "", path.name)
    assert not words, "a word YAML read as a boolean:\n" + "\n".join(words)

    # The nine verbs the round fixed, read back through the registry rather than listed: every
    # two-valued `state` vocabulary must be words.
    two_valued = []
    for path in sorted((VEHICLE / "domains").glob("*/commands.yaml")):
        for verb in (yaml.safe_load(path.read_text()) or {}).get("commands") or []:
            for name, spec in (verb.get("argument_schema") or {}).items():
                if isinstance(spec, dict) and name == "state" and spec.get("type") == "enum":
                    values = [str(v) for v in spec.get("values") or []]
                    if set(values) == {"on", "off"} or set(values) == {"on", "off", "standby"}:
                        two_valued.append(f"{verb['verb']}.{name}")
    assert len(two_valued) == 9, two_valued
    # And what HELP.md renders is those words rather than Python's repr of a boolean.
    generated = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "generate_help.py"), "--dir", str(VEHICLE)],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    assert "one of: on, off" in generated
    assert "one of: True, False" not in generated
    assert "one of: off, low, nominal, high" in generated

    def refusal(name: str, rel: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / rel
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, out[-1400:]

    refusal(
        "vocabulary",
        "domains/thermal/commands.yaml",
        '      pump: {type: enum, values: [pump_1, pump_2, pump_lm]}\n'
        '      state: {type: enum, values: ["on", "off"]}',
        "      pump: {type: enum, values: [pump_1, pump_2, pump_lm]}\n"
        "      state: {type: enum, values: [on, off]}",
        "the vocabulary this argument publishes to the fleet is a boolean",
    )
    refusal(
        "mixed-list",
        "domains/eclss/commands.yaml",
        'values: ["off", "low", "nominal", "high"]',
        "values: [off, low, nominal, high]",
        "the vocabulary this argument publishes to the fleet is a boolean",
    )
    # A mapping key, which the linter crashed on before this round.
    refusal(
        "key",
        "domains/thermal/components.yaml",
        '          "on": UNCONFIGURED\n          "off": 0\n',
        "          on: UNCONFIGURED\n          off: 0\n",
        "as a key. YAML 1.1 reads",
    )


def test_every_command_that_writes_a_state_can_be_applied_or_refuses_by_name():
    """The effect, implemented — and the remainder refusing rather than doing nothing.

    Until this round the plant could *describe* a command and not perform one: `capability_snapshot`
    reported whether one was available, `command_value` said what each of its values becomes, and
    `console.py` said so in every success it wrote — *"this reference implementation resolves,
    refuses and settles; it does not simulate the effect."*

    Two things had to be true first. The **declaration** took rounds 27 to 31: which state a verb
    writes, which argument carries the value, what each value becomes, which element of a keyed
    state is set, and what the value is where the state's own rule computes it. And the **storage**
    took one more: eight of the twenty-four command→state links land on the `internal` sentinel,
    where `initial_values` and `step` both used to *drop* the key, because one key shared by
    forty-eight states is a slot that means nothing. So a command like `set_rcs_mode` or
    `set_computer_mode` was accepted, acknowledged, and changed nothing at all — the one outcome a
    fleet cannot tell from success.

    `internal` is a key space now. What this asserts is the whole surface: every verb that declares
    a `command:` mover either changes a value or refuses with a sentence naming the field it is
    owed, and no verb does neither.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    values = plant.initial_values(world)
    assert isinstance(values.get("internal"), dict), (
        "the sentinel is one key rather than a key space, so a commanded state on it has nowhere "
        "to go"
    )

    applied: list[str] = []
    owed: dict[str, str] = {}
    for verb in sorted(world.verbs):
        targets = plant.command_targets(world, verb)
        if not targets:
            continue
        schema = world.verbs[verb].get("argument_schema") or {}
        arguments = {
            name: str(spec["values"][0])
            for name, spec in schema.items()
            if isinstance(spec, dict) and spec.get("type") == "enum" and spec.get("values")
        }
        try:
            staged = plant.apply_command(world, values, verb, arguments)
        except plant.Unconfigured as exc:
            owed[verb] = str(exc)
            continue
        applied.append(verb)
        # A verb that writes a state must put it somewhere the map can hold.
        assert staged, f"{verb} writes {[s.id for s in targets]} and staged nothing"
        # **There are three shapes of key and there used to be two.** A node the world declares, the
        # sentinel, and — from round 67 — the *state's own id*, which `state_values` writes beside
        # the node's because `state_level` reads it first. The node key is not the state key even on
        # a node that carries one state: `bus_tie_closed` lives on `bus_tie` and
        # `cabin_regulator_position` on `cabin_regulator`, so a command that wrote only the node left
        # `values[<state>]` holding the pre-command value, and the tick's hold read that first and put
        # it back. Which is the round's own finding arriving in the assertion that guards the map.
        for key in staged:
            # The key is a node the world declares, or the sentinel, or a state those commands write.
            # It is not necessarily a key `initial_values` seeded: only *stocks* have declared
            # starting amounts, so a mode node like `engine_main` is absent from the seed and appears
            # the first time a command writes it.
            # **And the states a one-way event moves**, which the effect pass stages under their own
            # ids: `targets` is what the *verb* writes through `command_value`, and an event writes
            # states the verb has no `command_value` entry for.
            known = {state.id for state in world.states}
            assert key == "internal" or key in world.nodes or key in known, key
    # **Fourteen apply and seven are owed**, and the eighth moved across in round 33: a
    # rule-computed state is changed through an *input*, and `select_antenna`'s input
    # (`comms.antenna_selection`) is a state that exists and declares the same verb — so the command
    # stages it and leaves `link_snr` to the rule. The other five `computed` effects name
    # `UNCONFIGURED`, which is the honest answer for an input nobody has declared.
    assert len(applied) == 14, applied
    assert "select_antenna" in applied
    assert len(owed) == 7, sorted(owed)
    # Every refusal names the field it is owed and says what would close it, which is the plant's
    # contract for a value it does not have.
    for verb, sentence in sorted(owed.items()):
        assert "is owed" in sentence, (verb, sentence)
    assert sorted(owed) == [
        "load_state_vector",
        "point_hga",
        "select_nav_source",
        "set_coolant_pump",
        "set_instrumentation_mode",
        "set_power_amplifier",
        "set_telemetry_profile",
    ], sorted(owed)

    # And the mapping itself, on the two links that prove the key space and the key argument.
    staged = plant.apply_command(world, values, "set_rcs_mode", {"mode": "manual"})
    # Two keys, and the second is the state's own — `state_level` reads it before the sentinel's
    # sub-map, so a command that wrote only the sub-map left the flat key holding the pre-command
    # value for the next tick to read back. Round 67's finding, in the map this test guards.
    assert staged == {
        "internal": {**values["internal"], "mode": "manual"},
        "mode": "manual",
    }, staged
    staged = plant.apply_command(world, values, "set_hatch_valve",
                                 {"vehicle": "csm", "hatch": "hatch_crew_lm", "state": "open"})
    assert staged["internal"]["hatch_state"] == {"hatch_crew_lm": "open"}, staged
    # The keyed state's element has the same second key, one level down, and for the same reason.
    assert staged["hatch_state"] == {"hatch_crew_lm": "open"}, staged
    # And the rule-computed half: the command writes its *input*, and the state the rule owns is
    # left alone rather than guessed at.
    staged = plant.apply_command(world, values, "select_antenna", {"antenna": "high_gain"})
    assert staged["internal"]["antenna_selection"] == "high_gain", staged
    assert "link" not in staged, "the computed state was assigned a value the plant invented"


def test_a_command_puts_a_keyed_state_beside_its_siblings_never_on_top_of_them():
    """The command path wrote a keyed state's elements into the node's key space, bare.

    `plant.state_values` says what the value map's shape is: a state's value goes under its own id,
    a node carrying exactly one state also keeps its node key, and the `internal` sentinel is a key
    space of its own. A state whose `unit` is a `map[...]` is a fourth case — its value is itself a
    map, so its elements sit one level below the value a scalar sibling occupies — and **the two
    writers of a keyed element disagreed about that level.** `state_values` nests. `apply_command`
    wrote `staged[state.node][element] = value` with no state id in the path, which is the same key
    space a scalar state's whole value lives in.

    `pyro_fired` is the state that shows it, because `structure_config` carries it *beside* three
    scalars rather than alone on a node. Before the fix, with `values['structure_config']` holding
    `lm_separation_state` as `docked`:

        execute_event(event='lm_undocking')  ->  {'structure_config': {'lm_undocking': True}}

    which is an event name in the slot a mode belongs in. Every value `execute_event` can take
    collided with something: three of the four `one_way_events` share their id with a scalar
    sibling, and the fourth, `pyro_fire`, shares the *state's* own node key.

    **Why nothing caught it.** Every keyed state a command could write — `hatch_state`,
    `breaker_panel`, `thruster_valve`, `rcs.mode` and the rest — lives on the `internal` sentinel,
    where `apply_command` nested correctly. The broken copy of the rule sat on a node no command
    reached until `structure_config`. And the state it writes is `discrete`, which `advance` refuses,
    so `state_values` — the writer that does nest on a node — was never reached for one. A latent
    collision is still a collision: the first tick that could advance `lm_separation_state` would
    have read `'lm_undocking'` and published it as a configuration.

    The fix is `plant._stage_element`, one writer for both containers, because the duplication is
    what let two halves of one sentence drift apart. This is the half of the finding the corpus
    cannot hold: `key_space` says which level a value lives at, and this asserts the writer obeys it.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    values = plant.initial_values(world)
    siblings = sorted(s.id for s in world.states_on("structure_config"))
    assert siblings == ["configuration", "descent_stage_state", "lm_separation_state", "pyro_fired"], (
        f"the node this asserts about changed shape: {siblings}"
    )

    # A scalar sibling's slot, seeded the way `advance` writes one.
    values["structure_config"] = {"lm_separation_state": "docked", "configuration": "docked"}
    staged = plant.apply_command(world, values, "execute_event",
                                 {"event": "lm_undocking", "arm_token": "token"})

    # **One level down, under the state's own id.** The helper reads the node's existing map first
    # — that is what lets a second event accumulate — so the siblings come through *unchanged*,
    # which is the other half of the claim: the element is added beside them and not over them.
    assert staged["structure_config"] == {
        "lm_separation_state": "docked",
        "configuration": "docked",
        "pyro_fired": {"lm_undocking": True},
    }, staged
    # The three assertions the flat write would have broken, one per sibling shape. The flat form
    # staged `{'lm_undocking': True}` and *dropped both scalars*, because it built the map from the
    # element rather than from the node's own values.
    assert "lm_undocking" not in staged["structure_config"], (
        "the element took the key space a sibling state's value lives in"
    )
    assert staged["structure_config"]["lm_separation_state"] == "docked"
    assert staged["structure_config"]["configuration"] == "docked"
    # And a second event accumulates rather than replacing the first, which the flat form could
    # never do: it wrote to `values[node]` and the caller's commit is a shallow update.
    merged = {**values, **staged}
    again = plant.apply_command(world, merged, "execute_event",
                                {"event": "pyro_fire", "arm_token": "token"})
    assert again["structure_config"]["pyro_fired"] == {
        "lm_undocking": True, "pyro_fire": True,
    }, again
    assert again["structure_config"]["lm_separation_state"] == "docked"
    # The sentinel still nests, and the helper did not change that: the two containers differ in
    # which map holds the state and in nothing else.
    hatched = plant.apply_command(world, values, "set_hatch_valve",
                                  {"vehicle": "csm", "hatch": "hatch_crew_lm", "state": "open"})
    assert hatched["internal"]["hatch_state"] == {"hatch_crew_lm": "open"}, hatched



def test_the_console_applies_the_effect_and_says_what_changed(tmp_path):
    """`console.py`'s own words, which were the honest admission and are now a report.

    Every success it wrote ended *"it does not simulate the effect"*. Now the executive stages the
    accepted command into `plant.step` and reports, after the step, what the command's own target
    states became — `set_rcs_mode` writes a state on the sentinel, and the frame carries it.

    **What changed (ADR 0001 choice C).** The old version of this test closed the bus tie and read
    `bus_tie=closed` back. `set_bus_tie` declares `tie_dv_limit`, a threshold on `power.dc_bus_a_v`
    whose source state has no rule, so the executive cannot guard the command and refuses it
    `INTERLOCK UNEVALUATED`; the tie stays `open` in the ring. And `set_coolant_pump`, the old
    NOT IMPLEMENTED case, declares interlocks too, so the owed-value refusal is proved on `point_hga`
    — interlock-free, and its `link_snr.command_value.selects` is owed (`domains/comms/components.yaml`).
    """
    console, _plant, world = console_tools()
    diode = tmp_path / "diode"
    executive = console.Executive(world, diode, phase="translunar_coast")
    executive.attach("applied")
    root = diode / "applied"

    def run(command: str) -> str:
        clear_results(root)
        submit(root, [command])
        executive.cycle()
        bodies = results_of(root)
        assert len(bodies) == 1, bodies
        return bodies[0]

    # The post-extraction tie starts open, and stays open: the command cannot be guarded.
    tied = run("set_bus_tie tie=csm_tie_ab state=closed")
    assert "refused: INTERLOCK UNEVALUATED" in tied and "tie_dv_limit" in tied, tied
    assert "succeeded" not in tied, tied
    assert newest_frame(root)["values"]["power.bus_tie_state"] == "open"
    # A state on the sentinel, which had no storage before round 32, and is stepped truth now.
    mode = run("set_rcs_mode mode=manual")
    assert "succeeded" in mode and "internal:mode=manual" in mode, mode
    assert newest_frame(root)["values"]["rcs.mode"] == "manual"
    # A valid command the corpus cannot apply: refused by name, with the reason.
    pointed = run("point_hga target=earth mode=auto")
    assert "refused: NOT IMPLEMENTED" in pointed, pointed
    assert "link_snr.command_value.selects" in pointed and "is owed" in pointed, pointed
    assert "does not simulate the effect" not in pointed, pointed
    # And setting what is already set changes nothing and says so.
    again = run("set_comm_mode mode=sband_low")
    assert "succeeded" in again and "No value changed" in again, again


def test_a_computed_effect_names_the_input_the_command_changes(tmp_path):
    """`computed` said why a state follows from a rule and not what the command changes.

    That made it a place a missing state could hide, and one of them hid with a *claim* attached.
    Six entries declare a `computed` effect across five verbs — `select_antenna` and `point_hga` on
    `link_snr`, `set_power_amplifier` on `tx_power`, `set_instrumentation_mode` on
    `instrumentation_power`, and `load_state_vector` and `select_nav_source` on `nav_solution` — and
    the input each command writes has a state for exactly one of them. For the other five the
    command's real effect is a state the corpus does not declare, which is a debt.

    `select_nav_source`'s reason claimed otherwise: that its missing state "is published as
    `gnc.nav_source`" and that the gap was "recorded in this domain's `open_debts`". Neither is
    true — `gnc.nav_source` is not a registered channel, and no such debt was ever written. A
    `computed` effect is prose, and prose is where a claim like that survives.

    So `selects` is required: a state id that exists and declares the same verb — the two halves of
    the command surface agreeing about which state the command actually writes — or `UNCONFIGURED`
    with a note. One of the six resolves, and it is what moved an eighth verb into the plant's
    applied set.
    """
    states: dict[str, dict[str, object]] = {}
    for path in sorted((VEHICLE / "domains").glob("*/components.yaml")):
        for state in (yaml.safe_load(path.read_text()) or {}).get("state") or []:
            states[f"{path.parent.name}.{state['id']}"] = state

    computed: dict[str, tuple[str, object]] = {}
    for where, state in sorted(states.items()):
        for entry in state.get("command_value") or []:
            if entry.get("computed") is not None:
                computed[f"{where} <- {entry['verb']}"] = (
                    str(entry["verb"]),
                    entry.get("selects"),
                )
    assert len(computed) == 6, sorted(computed)
    resolved = {k: v for k, v in computed.items() if v[1] != "UNCONFIGURED"}
    assert sorted(resolved) == ["comms.link_snr <- select_antenna"], resolved
    assert resolved["comms.link_snr <- select_antenna"][1] == "antenna_selection"
    # The two halves agree, which is what the check enforces and what makes the effect performable.
    assert "command:select_antenna" in [
        str(m) for m in states["comms.antenna_selection"]["moved_by"]
    ]
    # The five that owe name no state, and the thing the false claim named is not a channel.
    assert {k for k, v in computed.items() if v[1] == "UNCONFIGURED"} == {
        "comms.link_snr <- point_hga",
        "comms.tx_power <- set_power_amplifier",
        "avionics.instrumentation_power <- set_instrumentation_mode",
        "gnc.nav_solution <- load_state_vector",
        "gnc.nav_solution <- select_nav_source",
    }, sorted(computed)
    registered = set()
    for path in [VEHICLE / "channels.yaml", *sorted((VEHICLE / "domains").glob("*/points.yaml"))]:
        document = yaml.safe_load(path.read_text()) or {}

        def collect(node: object) -> None:
            if isinstance(node, dict):
                for key in ("id", "channel"):
                    if isinstance(node.get(key), str):
                        registered.add(node[key])
                for value in node.values():
                    collect(value)
            elif isinstance(node, list):
                for value in node:
                    collect(value)

        collect(document)
    assert "gnc.nav_source" not in registered, "the claim the round removed is true after all"

    def refusal(name: str, rel: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / rel
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, out[-1400:]

    # The resolved half, in both directions.
    refusal(
        "disagrees",
        "domains/comms/components.yaml",
        '    moved_by:\n'
        '      - "command:select_antenna"\n'
        "    dwell:\n",
        '    moved_by:\n'
        '      - "logic:the crew throw it"\n'
        "    dwell:\n",
        "which does not declare 'select_antenna' as a `command:` mover",
    )
    refusal(
        "ghost",
        "domains/comms/components.yaml",
        "        selects: antenna_selection\n",
        "        selects: antenna_pick\n",
        "which is not a state of this domain",
    )
    # And the owed half must say what is missing.
    refusal(
        "bare-owe",
        "domains/avionics/components.yaml",
        "        selects: UNCONFIGURED\n"
        "        note: >-\n"
        "          the active instrumentation profile has no state. The verb's gate is\n"
        "          `instrumentation_profile_<profile>_enable`, which is a *preference* the fleet opens and\n"
        "          not a record of what the vehicle is running, and `groups` narrows it further — so the\n"
        "          vehicle can be told which instruments are active and cannot report which set that is,\n"
        "          while `instrumentation_power` and the fresh-evidence limit are both computed from it\n",
        "        selects: UNCONFIGURED\n",
        "is UNCONFIGURED with no `note`",
    )


def test_a_commanded_state_is_guarded_by_a_dwell_and_the_executive_reads_it(tmp_path):
    """The rule's comment stated the distinction; the code did not, and nothing read the field.

    `check_domain`'s own comment says a commanded state machine "has no comparator to band — what it
    needs is minimum on and off times, because a machine that can be re-commanded every tick is a
    machine that chatters on command instead of on noise". Then the three branches below it accept
    `hysteresis`, `dwell` or `one_way` from any state at all — so `bus_tie_closed`, moved by
    `set_bus_tie`, composes with a comparator band in place of its dwell, which leaves a commanded
    mode guarded by `assert: 1.25` volts against values of `open`, `closed` and `tripped`.

    And **no tool read a dwell at all**: thirty-three discrete states declare one, fifteen of them
    commanded, and the guard is evaluated at the moment of effect — the executive's own step
    (`plant.md` step 2). So a fleet could re-command `set_rcs_mode` every tick, or move the bus tie
    twice inside its 0.2 s, while every declaration said it could not. The RCS group command now
    carries a chosen zero policy dwell so its promised immediate inhibit stays available; the
    per-thruster electrical pulse floor remains `UNCONFIGURED`.

    Two halves are asserted here. The linter refuses a band on a commanded state, with `one_way` as
    the exemption the existing rule already reasons about. And the guard reaches the executive:
    `command_dwell` reports it, and the console refuses a command inside its dwell by name.
    """
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    commanded = [
        state
        for state in world.states
        if state.method == "discrete"
        and any(str(m).startswith("command:") for m in state.spec.get("moved_by") or [])
    ]
    assert len(commanded) == 16, [s.id for s in commanded]
    guarded = [s for s in commanded if s.spec.get("dwell")]
    assert len(guarded) == 15, [s.id for s in commanded if not s.spec.get("dwell")]
    # The one that is not is one-way, and that is the exemption rather than a gap.
    assert [s.id for s in commanded if not s.spec.get("dwell")] == ["pyro_fired"]
    assert all(s.spec.get("one_way") for s in commanded if not s.spec.get("dwell"))
    # The group-command dwell is a chosen zero policy. The LM guide's 10 ms refers to a
    # pulse-mode electrical command, while this state is moved by group enable/inhibit.
    assert [(s.id, on, off) for s, on, off in plant.command_dwell(world, "set_rcs_quad")] == [
        ("thruster_valve", 0, 0)
    ]
    assert [(s.id, on, off) for s, on, off in plant.command_dwell(world, "set_bus_tie")] == [
        ("bus_tie_closed", 0.2, 0.2)
    ]

    # A band on a commanded state is refused; a band on an uncommanded one is not.
    definition = copy_definition(fixture_dir(tmp_path, "band"))
    path = definition / "domains" / "power" / "components.yaml"
    text = path.read_text()
    old = "    dwell: {min_on_s: 0.2, min_off_s: 0.2}\n"
    assert text.count(old) == 1, "the fixture no longer matches bus_tie_closed's dwell"
    path.write_text(text.replace(old, "    hysteresis: {assert: 1.25, clear: 1.05, dwell_ms: 500}\n"))
    out = run_linter(definition).stdout
    assert "guards itself with a hysteresis band" in out, out[-1400:]

    # And the guard end to end, one command per tick on one executive — the way a fleet's commands
    # arrive. The first version kept the clock in memory in a process per command, so it fired never;
    # the second restored it from `pending.json`, which ADR 0001 withdraws. The clock is the
    # executive's now, in simulated microseconds, so exactly one tick of 1/50 s has passed when the
    # second command arrives — 0.0 s held against a 10 s floor.
    console_module, _plant, _shared = console_tools()
    diode = tmp_path / "diode"
    executive = console_module.Executive(world, diode, phase="translunar_coast")
    executive.attach("dwell")
    window = diode / "dwell"

    def run(command: str) -> str:
        clear_results(window)
        submit(window, [command])
        executive.cycle()
        bodies = results_of(window)
        assert len(bodies) == 1, bodies
        return bodies[0]

    first = run("select_antenna antenna=omni_a")
    assert "succeeded" in first and "antenna_selection=omni_a" in first, first
    # `antenna_selection` holds for ten seconds, so the second command is inside its dwell.
    second = run("select_antenna antenna=high_gain")
    assert "refused: DWELL." in second, second
    assert "must hold a value for 10 s" in second, second
    # **And an owed guard still refuses rather than being read as zero**, which needs a fixture
    # now: the live vehicle has no commanded machine with an unset dwell any more, so asserting it
    # against `set_rcs_quad` would be asserting a state the corpus has left. The property is the
    # one the field exists for, so it is proved against a copy with the guard removed.
    unguarded = copy_definition(fixture_dir(tmp_path, "owed_dwell"))
    path = unguarded / "domains" / "rcs" / "components.yaml"
    text = path.read_text()
    old_dwell = "      min_on_s: 0\n      min_off_s: 0\n"
    assert old_dwell in text, "the fixture no longer matches the valve's dwell"
    path.write_text(text.replace(old_dwell, "      min_on_s: UNCONFIGURED\n      min_off_s: UNCONFIGURED\n", 1))
    assert [(s.id, on, off) for s, on, off in plant.command_dwell(plant.load_world(unguarded), "set_rcs_quad")] == [
        ("thruster_valve", None, None)
    ], "an owed guard must be reported as owed rather than as zero"

    # A first group command and an immediate inhibit both succeed. The latter is the safety
    # direction promised by the command's own help; the pulse generator still owes its floor.
    assert "succeeded" in run("set_rcs_quad group=sm_primary state=enable")
    assert "succeeded" in run("set_rcs_quad group=sm_primary state=inhibit")
    assert "succeeded" in run("set_rcs_quad group=sm_primary state=enable")


def test_a_faults_magnitude_is_one_name_with_its_unit_and_its_channel(tmp_path):
    """The other half of a fault, which had twenty spellings and no reader.

    `seeding` declares a fault in two halves: when it fires — `hazard` with `unit`, `on_demand_p`,
    `coupled_to`, `trigger` — and how far it moves the channel it perturbs. Only the first was read.
    The second had **twenty spellings**: `bias_walk` and its five suffixed variants, four `drift_*`,
    `rate_kg_per_h` beside `rate_per_s`, `loss_pct`, `bias_psia`, `bias_m`, and four that were not
    magnitudes at all — `schedule`, `stress`, `onset` and `bias` held *sentences* in the field meant
    for a number. The unit was inside the key name rather than in a field, so one idea had six
    names, and nothing compared it with the channel: `bias_walk_kpa_per_h: 0.05` sat against a
    channel published in psi, and `rate_kg_per_h: 0.02` against one in g/s.

    Three declarations now, and the key set is *closed* — which is the part that stops the twenty
    recurring. `magnitude` is the number, `magnitude_unit` is what it is in, `magnitude_channel` is
    what it moves, and `condition` is where a sentence goes.

    Twelve of the twenty-seven magnitudes are owed, and `faults.py --list` says so rather than
    printing a `?` where a unit belongs: a fault the adversary can schedule but not size is a fault
    whose magnitude is a debt, and the debt is the deliverable.
    """
    keys: set[str] = set()
    numeric: list[tuple[str, str, str, str]] = []
    owed = 0
    for path in sorted((VEHICLE / "domains").glob("*/fault_policy.yaml")):
        for fault in (yaml.safe_load(path.read_text()) or {}).get("faults") or []:
            seeding = fault.get("seeding") or {}
            keys |= {str(k) for k in seeding}
            if "magnitude" not in seeding:
                continue
            unit_text = str(seeding.get("magnitude_unit"))
            if seeding.get("magnitude") == "UNCONFIGURED" or unit_text == "UNCONFIGURED":
                owed += 1
                assert seeding.get("note"), fault["id"]
                continue
            numeric.append(
                (str(fault["id"]), seeding["magnitude"], unit_text, str(seeding["magnitude_channel"]))
            )
    assert sorted(keys) == [
        "condition", "coupled_to", "hazard", "magnitude", "magnitude_channel", "magnitude_unit",
        "note", "on_demand_p", "trigger", "unit",
    ], sorted(keys)
    assert len(numeric) == 15, numeric
    assert owed == 12, owed
    # Every owed one owes a sentence as well as a number: the first rule required a note only
    # for an owed *unit*, which is the same asymmetry this round is about.
    assert all(True for _ in numeric)
    # The channel is one the fault perturbs, and the four the round converted are in the unit of
    # the channel they move rather than in the unit their old key named.
    converted = {fid: unit for fid, _, unit, _ in numeric}
    assert converted["CNS-05-quantity-sensor-bias"] == "psi/h"
    assert converted["ECL-05-pressure-sensor-bias"] == "psi/h"
    assert converted["STR-01-hatch-seal-leak"] == "g/s"
    assert converted["STR-08-tunnel-volume-leak"] == "g/s"
    for path in sorted((VEHICLE / "domains").glob("*/fault_policy.yaml")):
        for fault in (yaml.safe_load(path.read_text()) or {}).get("faults") or []:
            seeding = fault.get("seeding") or {}
            if seeding.get("magnitude_channel"):
                assert seeding["magnitude_channel"] in [str(c) for c in fault["perturbs"]]

    # `--list` is the reader: the magnitude, its unit and its channel, per fault.
    listed = subprocess.run(
        [sys.executable, str(VEHICLE / "tools" / "faults.py"), "--list", "--dir", str(VEHICLE)],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    assert "0.02 kg/h on res.o2_remaining_kg" in listed, listed[:400]
    assert "0.0072519 psi/h on eclss.o2_supply_pressure_psi" in listed
    assert "with unit owed" in listed
    assert "magnitude owed" in listed

    def refusal(name: str, old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / "domains" / "consumables" / "fault_policy.yaml"
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, out[-1400:]

    # A twenty-first spelling, which the closed key set is for.
    refusal(
        "twenty-first",
        '      magnitude: 0.02\n      magnitude_unit: "kg/h"\n',
        "      rate_kg_per_h: 0.02\n",
        "is not one of",
    )
    # The pair, the unit, and the host.
    refusal(
        "no-unit",
        '      magnitude: 0.02\n      magnitude_unit: "kg/h"\n',
        "      magnitude: 0.02\n",
        "The two go together",
    )
    refusal(
        "unknown-unit",
        '      magnitude: 0.02\n      magnitude_unit: "kg/h"\n',
        '      magnitude: 0.02\n      magnitude_unit: "stone/fortnight"\n',
        "which is not a unit this corpus knows",
    )
    refusal(
        "no-host",
        "      magnitude_channel: res.o2_remaining_kg\n",
        "",
        "must name the channel it moves",
    )
    refusal(
        "wrong-host",
        "      magnitude_channel: res.o2_remaining_kg\n",
        "      magnitude_channel: res.water_potable_kg\n",
        "which this fault does not perturb",
    )
    # And a sentence where the number goes, which is how four of the twenty got there.
    refusal(
        "sentence",
        "      magnitude: 0.02\n",
        '      magnitude: "about a cupful an hour"\n',
        "A magnitude is a number or an owed one",
    )


def test_an_instrument_states_what_it_measures_in_the_channels_own_vocabulary(tmp_path):
    """The one link in the reading chain that nothing joined, and the class that named it.

    A reading reaches the crew through three declarations and two joins. `channels.yaml` states a
    resolution for every canonical channel and the display contract's `displayed_precision` is held
    to it — a panel may round the channel and may not invent resolution. The other end was joined to
    nothing: the four instruments in `domains/eclss/components.yaml` declared `range_psia`,
    `precision_psia`, `range_mmhg` and `precision_mmhg` — the unit inside the key name, which is the
    shape the fault magnitudes were cured of — and no tool read any of the eight fields. `class:
    sensor`, the one word in the corpus that says *this is an instrument*, was read by nothing
    either, so the four instruments were four blocks of prose that no channel depended on.

    **The two ranges are different quantities.** The channel's `range` is a *band* — the cabin's
    acceptable 4.8-5.2 psia, with the alarms firing below it — while the instrument's is a *scale*,
    the span it can physically read, 0-10 psia. So the honest relation is containment rather than
    equality: an instrument whose full scale does not contain the band the vehicle calls normal
    saturates inside its own operating envelope, and the crew read the rail rather than the cabin.
    `range_kind` already carried that distinction for the registry, so the sensor side reuses the
    word `scale` instead of inventing a second vocabulary, and the join is then a comparison rather
    than a description.

    Two things this round got wrong on the way, both of them kept as cases below. The first version
    of the unit-in-key rule matched the *prefix* `range_`, which matched `range_kind` — the
    vocabulary of `range` rather than a unit inside a name — and refused all four sensors for the
    field that says what their range means. And the first broken copy restored the old spelling by
    deleting `range` and `unit` together, which let the missing-figure rule fire first and `continue`
    past the rule under test: a break that drops an identifier reports the hole rather than the
    defect, so the unit-in-key case moves only the *name* and keeps every figure present.
    """
    registry: dict[str, dict] = {}
    for value in yaml.safe_load((VEHICLE / "channels.yaml").read_text()).values():
        if isinstance(value, list):
            for row in value:
                if isinstance(row, dict) and row.get("id"):
                    registry[str(row["id"])] = row

    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    sensors = [e for e in eclss["components"] if e.get("class") == "sensor"]
    assert sorted(e["id"] for e in sensors) == [
        "cabin_pressure_sensor_1",
        "cabin_pressure_sensor_2",
        "co2_sensor",
        "lm_cabin_pressure_sensor",
    ], [e.get("id") for e in sensors]

    figures = {"range", "range_kind", "unit", "precision"}
    # `<quantity>_<unit>`, tested by the suffix rather than the prefix — `range_kind` begins with
    # `range_` and is not one of these, which is the mistake the linter made first and this test
    # repeated the first time it ran. The units are the registry's own, lowercased, because a key
    # name is snake_case and the registry spells one of them `mmHg`.
    units = {str(row.get("unit", "")).lower() for row in registry.values()}
    for entry in sensors:
        # The link, and the closed key set: the defect was a *name*, so the count of names is what
        # has to stay at one.
        assert figures <= set(entry), entry
        assert not [k for k in entry if str(k).rsplit("_", 1)[-1].lower() in units], entry
        row = registry[str(entry["measures"])]
        assert entry["range_kind"] == "scale", entry["id"]
        assert row["range_kind"] == "band", entry["id"]
        # In the channel's own unit, no finer than the instrument resolves, and wide enough to hold
        # the band the vehicle calls normal. The last is the physical claim: a transducer that
        # saturates at 4.9 psia cannot read the bottom of the cabin's acceptable range.
        assert entry["unit"] == row["unit"], entry["id"]
        assert float(entry["precision"]) <= float(row["precision"]), entry["id"]
        assert entry["range"][0] <= row["range"][0], entry["id"]
        assert row["range"][1] <= entry["range"][1], entry["id"]

    # Two instruments on one channel is the redundant pair, and the rule is silent about the count.
    assert len([e for e in sensors if e["measures"] == "eclss.cabin_pressure_psia"]) == 2

    # Each case is a whole block, so the anchor is unique by construction and a rewrite of the
    # corpus that moves a line breaks the fixture loudly rather than silently matching nothing.
    CO2 = (
        "  - id: co2_sensor\n"
        "    kind: flow\n"
        "    class: sensor\n"
        "    measures: eclss.co2_pp_mmhg\n"
        "    range: [0, 20]\n"
        "    range_kind: scale\n"
        "    unit: mmHg\n"
        "    precision: 0.1\n"
    )
    PRESSURE = (
        "  - id: cabin_pressure_sensor_1\n"
        "    kind: flow\n"
        "    class: sensor\n"
        "    measures: eclss.cabin_pressure_psia\n"
        "    range: [0, 10]\n"
        "    range_kind: scale\n"
        "    unit: psia\n"
        "    precision: 0.01\n"
    )
    CHANNEL = (
        "  - id: eclss.co2_pp_mmhg\n"
        "    unit: mmHg\n"
        "    layer: measurement\n"
        "    precision: 0.1\n"
        "    rate_hz: 0.5\n"
        "    priority: P3\n"
        "    range: [0, 5]\n"
    )

    def refusal(
        name: str, where: str, old: str, new: str, needle: str, *, composes: bool = False
    ) -> str:
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / where
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old[:60]!r} exactly once"
        path.write_text(text.replace(old, new, 1))
        result = run_linter(definition)
        assert needle in result.stdout, result.stdout[:1400]
        if composes:
            assert result.returncode == 0, result.stdout[:600]
        else:
            assert result.returncode == 1, result.stdout[:600]
        return result.stdout

    components = "domains/eclss/components.yaml"

    # The defect itself: the unit welded into the key name, which is what the four sensors did.
    refusal(
        "unit-in-key",
        components,
        CO2,
        CO2.replace("    range: [0, 20]\n", "    range_mmhg: [0, 20]\n")
        .replace("    unit: mmHg\n", "")
        .replace("    precision: 0.1\n", ""),
        "carries its unit in the key name",
    )
    # And the boundary the first version of the rule got wrong: `range_kind` is the vocabulary of
    # `range` and not a unit inside a name, so losing it is a missing figure and nothing else.
    out = refusal(
        "kind-not-unit",
        components,
        CO2,
        CO2.replace("    range_kind: scale\n", ""),
        "not there to compare",
    )
    assert "carries its unit in the key name" not in out

    # A declaration nothing reads, still: an instrument that names no channel, and one that names a
    # channel which does not exist. The second is the typo the link exists to catch.
    refusal(
        "no-channel",
        components,
        CO2,
        CO2.replace("    measures: eclss.co2_pp_mmhg\n", ""),
        "declares no `measures`",
    )
    refusal(
        "wrong-channel",
        components,
        CO2,
        CO2.replace("eclss.co2_pp_mmhg", "eclss.co2_pp_mmhq"),
        "is not a channel in `channels.yaml`",
    )

    # The two inequalities, each read from one side. A channel that publishes finer than the
    # transducer resolves is a number the vehicle never measured, whichever file moved.
    refusal(
        "instrument-coarse",
        components,
        CO2,
        CO2.replace("    precision: 0.1\n", "    precision: 0.5\n"),
        "may not invent resolution",
    )
    refusal(
        "registry-tightened",
        "channels.yaml",
        CHANNEL,
        CHANNEL.replace("    precision: 0.1\n", "    precision: 0.001\n"),
        "may not invent resolution",
    )
    # Containment, and the physical failure it is about: an instrument that cannot reach the top of
    # the band the vehicle calls normal.
    refusal(
        "saturates",
        components,
        PRESSURE,
        PRESSURE.replace("    range: [0, 10]\n", "    range: [4.9, 10]\n"),
        "saturates inside its own operating envelope",
    )
    refusal(
        "wrong-unit",
        components,
        CO2,
        CO2.replace("    unit: mmHg\n", "    unit: psia\n"),
        "the channel it measures publishes in 'mmHg'",
    )
    refusal(
        "not-a-span",
        components,
        CO2,
        CO2.replace("    range: [0, 20]\n", "    range: [20, 0]\n"),
        "not a span with two numeric ends",
    )
    # `range_kind` is not decoration: a sensor claiming an operating band would be answering the
    # channel's question, and the containment test below it would not mean anything.
    refusal(
        "sensor-band",
        components,
        CO2,
        CO2.replace("    range_kind: scale\n", "    range_kind: band\n"),
        "the full span it can read",
    )

    # The legal directions, which the rule must not refuse: a channel may round its instrument — that
    # is what the panel does to the channel — and a full scale ending exactly on the band's edge
    # still contains it.
    refusal(
        "channel-rounds",
        components,
        CO2,
        CO2.replace("    precision: 0.1\n", "    precision: 0.05\n"),
        "COMPOSES, with 273 declared debt(s)",
        composes=True,
    )
    refusal(
        "exact-edge",
        components,
        PRESSURE,
        PRESSURE.replace("    range: [0, 10]\n", "    range: [4.8, 5.2]\n"),
        "COMPOSES, with 273 declared debt(s)",
        composes=True,
    )

    # A figure that is not there to compare is a debt and not a refusal — the same split the display
    # contract makes one join further along. A measured channel with no `range` at all is the case:
    # the corpus still composes, and the count is one higher.
    out = refusal(
        "no-range",
        "channels.yaml",
        CHANNEL,
        CHANNEL.replace("    range: [0, 5]\n", ""),
        "cannot be held against the channel's `range`",
        composes=True,
    )
    assert "with 274 declared debt(s)" in out, out[-300:]


def test_a_stocks_rating_is_joined_to_the_counter_it_is_spent_at(tmp_path):
    """The absorber's rating, declared three times, read twice — and a debt nothing ever wrote.

    `domains/eclss/components.yaml` declares each absorber as a `kind: stock` whose `node` is the
    counter it feeds, and states the rating beside it as `rated_man_hours`: 72 for the CSM's LiOH
    element, 41 for the LM's loaded primary cartridge and 78 for its secondary. The same two figures
    are published in `vehicle.yaml#consumables.co2_removal`, and `coupling.yaml`'s counters declare
    `exhausted_at` with an `exhausted_at_source` naming the published field — so the chain is
    article -> counter -> published figure.

    Two of its three links were checked and the ends were joined to nothing. `exhausted_at_source`
    was resolved by `check_initial_sources`, and the counter is what the threshold and the plant
    both read — but the field `rated_man_hours` appeared in **no file under `tools/`**, and the only
    mention of `csm_element_man_hours` was a comment about what would happen if somebody changed it.
    The file's own comment above the components had already said the ratings "were written right here
    the whole time" — about the round that found the shared counter — and nothing had read them
    since.

    **The check that closes the other two copies counts them, in its own comment, as two.** That is
    this folder's recurring lesson arriving in the comment of the check written to catch it: a
    hand-written list of what to compare is the bug, and this one was a list of two where the corpus
    had three. The join needs no new field, because the component already names its counter and the
    counter is already held to the published figure; the reverse direction — a counter no component
    is the article of — is a debt, for the same reason the comms join reports an unclaimed vehicle
    entry as one: a gap in the modelling rather than a contradiction between two files.

    And the round's other half came out of reading a note rather than a field. The
    `absorber_capacity_lm` node says the 78 + 6 x 41 = 324 man-hours that are physically aboard are
    "declared in `vehicle.yaml` and modelled nowhere — a debt, named in `open_debts`". There were
    nine entries in `coupling.yaml#open_debts` and none of them was that one, so the capacity was
    recorded nowhere *but in the sentence promising the record* — which is worse than an unset
    field, because a reader who sees the promise stops looking. The entry is written now.
    """
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    published = vehicle["consumables"]["co2_removal"]

    # The chain, all three links: the article's rating, the counter's, and the figure both come from.
    assert len([c for c in eclss["components"] if "rated_man_hours" in c]) == 3, eclss["components"]
    for node_id, field, figure in (
        ("absorber_capacity_csm", "csm_element_man_hours", 72),
        ("absorber_capacity_lm", "lm_primary_man_hours", 41),
    ):
        node = coupling["nodes"][node_id]
        article = next(c for c in eclss["components"] if c.get("node") == node_id)
        assert published[field] == figure, field
        assert node["exhausted_at_source"] == f"vehicle.yaml:consumables.co2_removal.{field}"
        assert node["exhausted_at"] == figure, node_id
        assert article["rated_man_hours"] == figure, article["id"]

    # The third article's rating is a real published figure and its counter is genuinely owed, so
    # the walker reports the unset `node` and `rated_man_hours` stays one spelling rather than two.
    secondary = next(c for c in eclss["components"] if c["id"] == "lm_lioh_cartridge_secondary")
    assert secondary["rated_man_hours"] == published["lm_secondary_man_hours"] == 78
    assert secondary["node"] == "UNCONFIGURED"
    assert not [k for k in secondary if "rating" in str(k) or "capacity" in str(k)], secondary

    # The debt the note promised, now written and counted.
    debts = coupling["open_debts"]
    promised = coupling["nodes"]["absorber_capacity_lm"]["note"]
    assert "named in `open_debts`" in promised
    spares = [d for d in debts if "spare LiOH cartridges" in d]
    assert len(spares) == 1, debts
    assert "324 man-hours" in spares[0] and "lm_spares: 6" in spares[0]
    owed = subprocess.run(
        [sys.executable, str(LINTER), "--dir", str(VEHICLE), "--debts"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    assert "spare LiOH cartridges" in owed, owed[-600:]

    def refusal(name: str, where: str, old: str, new: str, needle: str, *, composes: bool = False):
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / where
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old[:60]!r} exactly once"
        path.write_text(text.replace(old, new, 1))
        result = run_linter(definition)
        assert needle in result.stdout, result.stdout[:1200]
        if composes:
            assert result.returncode == 0, result.stdout[:600]
        else:
            assert result.returncode == 1, result.stdout[:600]
        return result.stdout

    ARTICLE = (
        "  - id: csm_lioh_element\n"
        "    kind: stock\n"
        "    class: absorber\n"
        "    node: absorber_capacity_csm\n"
        "    rated_man_hours: 72\n"
    )
    SECONDARY = (
        "  - id: lm_lioh_cartridge_secondary\n"
        "    kind: stock\n"
        "    class: absorber\n"
        "    node: UNCONFIGURED\n"
        "    rated_man_hours: 78\n"
    )
    COUNTER = (
        "  absorber_capacity_csm:\n"
        "    domain: eclss\n"
        "    kind: stock\n"
        "    unit: man_hours\n"
        '    apollo: "846"\n'
        "    exhausted_at: 72\n"
    )

    # The third copy disagreeing with the counter it feeds: the article changes, the counter does not.
    refusal(
        "article-drift",
        "domains/eclss/components.yaml",
        ARTICLE,
        ARTICLE.replace("    rated_man_hours: 72\n", "    rated_man_hours: 80\n"),
        "the article disagreeing with the counter it feeds",
    )
    # And the counter moving away from the *published* figure, which is the other link of the same
    # chain and was already checked: both rules fire, and this asserts the round did not replace the
    # one that was there.
    out = refusal(
        "counter-drift",
        "coupling.yaml",
        COUNTER,
        COUNTER.replace("    exhausted_at: 72\n", "    exhausted_at: 80\n"),
        "the article disagreeing with the counter it feeds",
    )
    assert "One of the two is the rating and the other is a copy of it" in out, out[:1200]

    # A link to nothing, and a link to something that is not a counter.
    refusal(
        "no-such-node",
        "domains/eclss/components.yaml",
        ARTICLE,
        ARTICLE.replace("node: absorber_capacity_csm", "node: absorber_capacity_csmm"),
        "which coupling.yaml does not declare",
    )
    refusal(
        "not-a-counter",
        "domains/eclss/components.yaml",
        ARTICLE,
        ARTICLE.replace("node: absorber_capacity_csm", "node: cabin_atm"),
        "declares no numeric `exhausted_at`",
    )
    # The reverse direction: an article that stops being declared leaves the counter's rating
    # attributed to nobody, which is a debt rather than a refusal — and one higher than live, which
    # is what says the new rule's debt is counted rather than merely printed.
    out = refusal(
        "no-article",
        "domains/eclss/components.yaml",
        ARTICLE,
        ARTICLE.replace("    rated_man_hours: 72\n", ""),
        "no component in any domain is the article of",
        composes=True,
    )
    assert "with 274 declared debt(s)" in out, out[-400:]

    # A rating on an article whose counter is owed is skipped by the join rather than refused twice:
    # the unset `node` is already a debt, and one missing datum under two names reads like two.
    owed_view = subprocess.run(
        [sys.executable, str(LINTER), "--dir", str(VEHICLE), "--debts"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    assert "components[10].node: is UNCONFIGURED" in owed_view, owed_view[-600:]
    # And wiring the spare to the loaded cartridge's counter — the plausible mistake, since it is the
    # only LM counter there is — is caught rather than silently adding 78 man-hours to a 41 rating.
    refusal(
        "spare-on-primary",
        "domains/eclss/components.yaml",
        SECONDARY,
        SECONDARY.replace("node: UNCONFIGURED", "node: absorber_capacity_lm"),
        "the article disagreeing with the counter it feeds",
    )


def test_a_pump_is_one_article_declared_in_two_domains(tmp_path):
    """The link between a thermal pump and its power load, which existed only in a sentence.

    `domains/thermal/components.yaml` declares the coolant pumps with their electrical figures, and
    `pump_1`'s own `reason` says where they come from: *"its electrical figures are the power
    domain's csm_coolant_pump_1; the mechanical side is what this domain owns"*. That is a claim
    that two objects in two files are one article, and **no tool read it**. The power domain
    publishes the same article as a load — `csm_coolant_pump_1`, `demand_w: 250`, `inrush_w: 420` —
    so the same two numbers sat in both files under different names at *both* levels: `pump_1`
    against `csm_coolant_pump_1`, and `rated_w` against `demand_w`. Nothing could have joined them
    even by accident.

    And `pump_2` did not state the link at all: only its twin's sentence mentioned the power domain,
    and it named only `csm_coolant_pump_1`. Two figures agreeing in two files because somebody wrote
    them twice is the state this folder treats as a defect even when the numbers are right — the
    corpus says so about the same pair of files a few hundred lines away, where the thermal
    domain's own debt note insists "the numbers are not duplicated here" while the pumps carry the
    loads' own watts under another name.

    `power_load` is the link, the shape `vehicle_keys` and `domain_group` already have: a field
    naming the other file's object. Three rules follow, and the third is what the round found by
    writing them — `pump_lm` names no load, because `domains/power/components.yaml#loads` has no LM
    pump at all, so 200 W steady and 340 W at start are on no bus and in no per-vehicle total. The
    LM's declared 1,007 W does not contain them. What is owed there is a decision (which bus, which
    shed class), not a figure, which is why it is a debt rather than a value filled in.

    The reverse direction is silent on purpose: a load need not be a pump, and the 22 loads that are
    not are the inventory's business rather than this join's.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    loads = {str(row["id"]): row for row in power["loads"]}

    pumps = [c for c in thermal["components"] if c.get("class") == "pump"]
    assert sorted(p["id"] for p in pumps) == ["pump_1", "pump_2", "pump_lm"], pumps
    for pump in pumps:
        assert isinstance(pump.get("rated_w"), int) and isinstance(pump.get("inrush_w"), int), pump

    # The link, and the agreement it buys: the same two numbers in two files, held together rather
    # than written twice.
    for pump_id, load_id in (("pump_1", "csm_coolant_pump_1"), ("pump_2", "csm_coolant_pump_2")):
        pump = next(p for p in pumps if p["id"] == pump_id)
        load = loads[load_id]
        assert pump["power_load"] == load_id, pump
        assert pump["rated_w"] == load["demand_w"], pump_id
        assert pump["inrush_w"] == load["inrush_w"], pump_id
    # The LM's pump is the one the inventory does not carry, and that is a debt naming the watts.
    lm_pump = next(p for p in pumps if p["id"] == "pump_lm")
    assert "power_load" not in lm_pump
    assert not [i for i in loads if "pump" in i and loads[i].get("vehicle") == "lm"], sorted(loads)
    owed = subprocess.run(
        [sys.executable, str(LINTER), "--dir", str(VEHICLE), "--debts"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    assert "components.pump_lm: declares 200 W steady and 340 W at start" in owed, owed[-800:]
    # The reverse direction is silent: a load that is not a pump needs no link back.
    assert "power_load" not in yaml.safe_dump(loads["csm_heaters"])

    def refusal(name: str, where: str, old: str, new: str, needle: str, *, composes: bool = False):
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / where
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old[:60]!r} exactly once"
        path.write_text(text.replace(old, new, 1))
        result = run_linter(definition)
        assert needle in result.stdout, result.stdout[:1200]
        if composes:
            assert result.returncode == 0, result.stdout[:600]
        else:
            assert result.returncode == 1, result.stdout[:600]
        return result.stdout

    PUMP = (
        "  - id: pump_1\n"
        "    kind: flow\n"
        "    class: pump\n"
        "    loop: loop_primary\n"
        "    power_load: csm_coolant_pump_1\n"
        "    rated_w: 250\n"
        "    inrush_w: 420\n"
    )
    LM_PUMP = (
        "  - id: pump_lm\n"
        "    kind: flow\n"
        "    class: pump\n"
        "    loop: loop_lm\n"
        "    rated_w: 200\n"
        "    inrush_w: 340\n"
    )

    # The steady draw drifting apart: the electrical side moves, the mechanical side keeps the old
    # number, and the figure the bus-sag chain is scaled by becomes one with two values.
    refusal(
        "rated-drift",
        "domains/thermal/components.yaml",
        PUMP,
        PUMP.replace("    rated_w: 250\n", "    rated_w: 300\n"),
        "this is the figure the bus-sag chain is scaled by",
    )
    refusal(
        "inrush-drift",
        "domains/thermal/components.yaml",
        PUMP,
        PUMP.replace("    inrush_w: 420\n", "    inrush_w: 500\n"),
        "the two files state it twice",
    )
    refusal(
        "no-such-load",
        "domains/thermal/components.yaml",
        PUMP,
        PUMP.replace("power_load: csm_coolant_pump_1", "power_load: csm_coolant_pump_3"),
        "which `domains/power/components.yaml#loads` does not declare",
    )
    # Without the link the copy is free again, which is a debt naming the watts rather than a
    # refusal — a pump is allowed to have electrical figures the inventory has not caught up with.
    out = refusal(
        "no-link",
        "domains/thermal/components.yaml",
        PUMP,
        PUMP.replace("    power_load: csm_coolant_pump_1\n", ""),
        "names no `power_load`",
        composes=True,
    )
    assert "with 274 declared debt(s)" in out, out[-400:]
    # And the LM pump's figures are unchecked by this join *because* it names no load — the case
    # documents the gap the debt reports rather than a property worth having. Moving its rating
    # 200 -> 210 changes nothing: no other file states it, so there is nothing to disagree with.
    # That is exactly why the debt exists, and why the case asserts silence instead of a refusal.
    refusal(
        "lm-silent",
        "domains/thermal/components.yaml",
        LM_PUMP,
        LM_PUMP.replace("    rated_w: 200\n", "    rated_w: 210\n"),
        "COMPOSES, with 273 declared debt(s)",
        composes=True,
    )


def test_a_zones_temperature_state_is_named_rather_than_guessed(tmp_path):
    """Six zones, six temperature states, and a check that found them by matching words.

    `check_zone_nodes` exists to refuse a zone whose temperature state sits on the `internal`
    sentinel — which is not a node, so no edge can terminate on it and the zone can never be driven.
    Until round 51 it found that state by matching the zone's own words against the state ids, with
    a comment saying so: *"The ids are not mechanical (`zone_csm_service_t` against a zone called
    `csm_service_bay`), so the match is by the zone's own words."*

    The word it matched for both crewed cabins was `cabin`. So each cabin's verdict was computed
    from a list holding **both** cabins' states, and `zone_csm_cabin_t` could be moved to the
    `internal` sentinel — the exact defect the check exists to refuse — while the check stayed
    silent on the strength of `zone_lm_cabin_t`, which is still on a node. The pair whose failure
    modes are most alike is the pair whose ids are least distinguishable, and the two cabins are
    that pair. The masking is asserted below rather than described: on the old rule, `csm_cabin` and
    `lm_cabin` produce the same candidate list.

    `temperature_state` is the link, and the two cabins had carried it all along — it is what
    `check_cabin_equilibrium` resolves before it can compute a rise. The other four zones declared
    nothing, so the word-match was the only mechanism they had, and it was also the only mechanism
    the cabins had *for this check*. All six declare it now and the field is read.

    A zone may legitimately have no node, so the exemption survives: `zones_not_on_nodes` with a
    reason, checked in both directions — a zone on the list whose own declared state sits on a real
    node is a stale exemption. That second direction read the same guess and reads the declaration
    now.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    zones = {str(z["id"]): z for z in vehicle["thermal"]["zones"]}
    states = {str(s["id"]): s for s in thermal["state"]}

    assert sorted(zones) == [
        "csm_avionics_bay",
        "csm_cabin",
        "csm_service_bay",
        "lm_cabin",
        "lm_descent_bay",
        "radiator_loop",
    ], sorted(zones)
    for zone_id, zone in sorted(zones.items()):
        state = states[str(zone["temperature_state"])]
        assert str(state.get("node")) != "internal", zone_id
    assert thermal.get("zones_not_on_nodes") in (None, {}), "no zone is exempt today"

    # Why the link has to be declared: the state ids are not the zone ids plus a suffix, so a rule
    # over the strings has to guess. Four of the six differ, and the two that do not are the cabins.
    mismatched = [
        (z, zones[z]["temperature_state"])
        for z in zones
        if str(zones[z]["temperature_state"]) != f"zone_{z}_t"
    ]
    assert len(mismatched) == 4, mismatched

    # The masking, computed rather than asserted from memory: the old rule took the first word of
    # the zone's stem and matched it against the state ids, and for both cabins that word is
    # `cabin` — so each cabin's candidate list contains the other cabin's state.
    def guessed(zone_id: str) -> list[str]:
        stem = (
            zone_id.replace("_bay", "").replace("_loop", "").replace("csm_", "").replace("lm_", "")
        )
        return sorted(s for s in states if stem.split("_")[0] in s and "_t" in s)

    assert "csm_cabin".replace("csm_", "").split("_")[0] == "cabin"
    assert guessed("csm_cabin") == guessed("lm_cabin") == ["zone_csm_cabin_t", "zone_lm_cabin_t"]
    assert guessed("csm_service_bay") == ["zone_csm_service_t"]

    def refusal(name: str, where: str, old: str, new: str, needle: str, *, composes: bool = False):
        definition = copy_definition(fixture_dir(tmp_path, name))
        path = definition / where
        text = path.read_text()
        assert text.count(old) == 1, f"the fixture no longer matches {old[:60]!r} exactly once"
        path.write_text(text.replace(old, new, 1))
        result = run_linter(definition)
        assert needle in result.stdout, result.stdout[:1400]
        if composes:
            assert result.returncode == 0, result.stdout[:600]
        else:
            assert result.returncode == 1, result.stdout[:600]
        return result.stdout

    # A zone that names no state: the field is what the check reads, so its absence is refused
    # rather than approximated.
    refusal(
        "no-link",
        "vehicle.yaml",
        "      - id: csm_service_bay\n"
        "        limit_c: [-20, 60]\n"
        "        regulated: false\n"
        "        temperature_state: zone_csm_service_t\n",
        "      - id: csm_service_bay\n        limit_c: [-20, 60]\n        regulated: false\n",
        "is not declared. A zone's temperature is a state on a node",
    )
    refusal(
        "bad-name",
        "vehicle.yaml",
        "        temperature_state: zone_csm_service_t\n",
        "        temperature_state: zone_csm_service_tt\n",
        "which is not a state in domains/thermal/components.yaml",
    )
    # `comm_amp_t` is a real state of this domain and it sits on the sentinel, which is exactly the
    # shape the check is for: the link resolves, and the node it resolves to is not a node.
    refusal(
        "sentinel",
        "vehicle.yaml",
        "        temperature_state: zone_csm_avionics_t\n",
        "        temperature_state: comm_amp_t\n",
        "whose node is the `internal` sentinel",
    )
    # The round's proof, in one edit: moving the CSM cabin's state to the sentinel is refused
    # *for that zone*, where the word-match answered it with the LM's state and stayed silent. The
    # domain's `writes` list still claims the node, so a second rule fires beside this one; the case
    # asserts the message rather than the count.
    out = refusal(
        "cabin-masked",
        "domains/thermal/components.yaml",
        "  - id: zone_csm_cabin_t\n    method: lag\n    node: cabin_zone_t\n",
        "  - id: zone_csm_cabin_t\n    method: lag\n    node: internal\n",
        "vehicle.yaml#thermal.zones.csm_cabin.temperature_state",
    )
    assert "whose node is the `internal` sentinel" in out, out[:1400]

    # The exemption, both directions. A zone on the list that declares a state on a real node is a
    # stale exemption, and that direction reads the declaration too.
    refusal(
        "stale-exemption",
        "domains/thermal/components.yaml",
        "\nopen_debts:\n",
        '\nzones_not_on_nodes:\n  csm_service_bay: "declared exempt for this fixture"\n\nopen_debts:\n',
        "A stale exemption is a reader told to expect a gap that has been closed",
    )
    # And the unbroken corpus is silent about all of it.
    refusal(
        "quiet",
        "vehicle.yaml",
        "        temperature_state: zone_radiator_t\n",
        "        temperature_state: zone_radiator_t\n",
        "COMPOSES, with 273 declared debt(s)",
        composes=True,
    )


def test_the_linter_refuses_a_front_table_that_states_the_wrong_figures(tmp_path):
    """The README's own table described three things about the folder and none of them had a reader.

    `plant.md` has had **seven** integrator classes since the first transport delay landed and the
    table said six; `coupling.yaml` declares **seven** cycles and the table said six; the linter
    derives a **57**-node tick order and the table said 39. Nothing read any of the three, which is
    this folder's recurring finding — *a declaration no tool reads has already drifted* — arriving
    in the first table a reader sees. Three fixtures, one per figure, because a check that reads the
    declarations it was told about cannot see the ones beside them.
    """
    for name, old, new, needle in (
        (
            "methods",
            "the seven integrator classes",
            "the six integrator classes",
            "while `METHODS` holds 7",
        ),
        ("cycles", "seven declared cycles", "six declared cycles", "while it declares 7"),
        ("order", "the 59-node tick order", "the 39-node tick order", "while the linter derives 59"),
    ):
        definition = copy_definition(tmp_path / f"front-{name}")
        path = definition / "README.md"
        text = path.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        path.write_text(text.replace(old, new, 1))
        result = run_linter(definition)
        assert result.returncode == 1, f"{name}: the linter composed a stale front table"
        assert needle in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_per_domain_paragraph_whose_counts_have_drifted(tmp_path):
    """Nine of the ten per-domain clauses were wrong, and the tenth was right by stating nothing.

    Power's paragraph said nine states and thirteen thresholds while the domain declares thirteen
    and seventeen; thermal's said eleven and eighteen against twenty and seventeen; eclss's said
    twelve, thirteen and eleven against sixteen, twenty and twenty-one. The clauses are one form so
    that they can be *read*, and this breaks one of them by four states to prove the reader runs.
    """
    definition = copy_definition(tmp_path / "domain-count")
    path = definition / "README.md"
    text = path.read_text()
    old = "declares 13 states, 17 thresholds, 5 verbs, 12 faults"
    assert old in text, "the fixture no longer matches the power clause"
    path.write_text(text.replace(old, "declares 9 states, 17 thresholds, 5 verbs, 12 faults", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "while `domains/power/` declares 13" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_domain_paragraph_with_no_count_clause(tmp_path):
    """A figure nobody can check is the next round's finding, so its *absence* is refused too.

    A domain could drop its clause — the form is optional in the regex, because a domain that
    states fewer things is making a smaller claim — and then the paragraph would be prose that no
    tool reads at all. This is the other half of that: the clause is required to exist, and writing
    the counts as words is how it stops being readable. Thermal's clause is spelled out, and the
    refusal is the one that says so rather than the one that says the numbers are wrong, which is
    the difference between a missing claim and a false one.
    """
    definition = copy_definition(tmp_path / "no-clause")
    path = definition / "README.md"
    text = path.read_text()
    old = "24 states, 17 thresholds, 5 verbs, 11 faults"
    assert old in text, "the fixture no longer matches the thermal clause"
    path.write_text(
        text.replace(old, "twenty states, seventeen thresholds, five verbs, eleven faults", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "states no count clause for this domain" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_two_count_clauses_for_one_domain(tmp_path):
    """One domain's paragraph contradicting itself is the defect the single clause form prevents.

    The reader collects the clauses in a domain's paragraph as a *set*, so two different ones are a
    refusal rather than a last-one-wins. That matters here more than elsewhere: the folder's own
    history is a status section that carried two debt counts eleven lines apart, and a check
    satisfied by either was satisfied by a file that contradicted itself.
    """
    definition = copy_definition(tmp_path / "two-clauses")
    path = definition / "README.md"
    text = path.read_text()
    old = "declares 13 states, 17 thresholds, 5 verbs, 12 faults"
    assert old in text, "the fixture no longer matches the power clause"
    second = "It also declares 9 states, 17 thresholds, 5 verbs, 12 faults. "
    path.write_text(text.replace(old, second + old, 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "different count clauses for one domain" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_method_table_whose_heading_disagrees_with_the_set(tmp_path):
    """`plant.md` §3's heading is the README's source for the method count, so it needs a reader too.

    The table is the contract — the seven classes are what a domain picks from — and its heading
    says how many there are. A heading that says six while `METHODS` holds seven is the same defect
    one file over, and holding only the README would leave the number's *source* unchecked.
    """
    definition = copy_definition(tmp_path / "method-heading")
    path = definition / "plant.md"
    text = path.read_text()
    old = "## 3. Seven methods"
    assert old in text, "the fixture no longer matches the §3 heading"
    path.write_text(text.replace(old, "## 3. Six methods", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "heads the method table" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_tool_docstring_whose_fault_counts_have_drifted(tmp_path):
    """`faults.py` said 118, 58 and 60 while the domains declared 128, 66 and 62.

    Ten domains landed faults after the sentence was written and the sentence never moved, and
    nothing read it — `test_the_readme_status_matches_the_tools` scans the tools, but for the form
    `N declared debts`, so `N declared faults` was invisible to the reader that exists. `plant.py`
    met this and solved it by *removing* its figures; these stay, because a fault corpus's size and
    its split between stochastic and conditional is worth a reader's knowing, and the check derives
    all three with the predicate the scheduler itself uses.
    """
    definition = copy_definition(tmp_path / "fault-docstring")
    path = definition / "tools" / "faults.py"
    text = path.read_text()
    old = "The vehicle has 128 declared faults"
    assert old in text, "the fixture no longer matches the faults.py docstring"
    path.write_text(text.replace(old, "The vehicle has 118 declared faults", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "states 118 declared faults" in result.stdout, result.stdout[-900:]


def test_the_linter_asks_a_carried_mode_where_it_starts_and_not_a_code_moved_one(tmp_path):
    """The `discrete` exemption's premise was *the plant refuses a discrete state*, and it stopped being true.

    `INTEGRATOR_METHODS` names the three classes the initial-value rule covers and exempts `dynamics`
    and `discrete` by name, each with a reason. The `discrete` reason is written in the exemption:
    *"the plant refuses a `discrete` state outright ('its rule is domain code'), so nothing invents
    one; and an initial that arrives with the rule is what the implementer of that rule owes."* The
    premise is the first clause. `plant.advance` now **holds** every `discrete` state whose movers
    are all `command:<verb>` — the transition belongs to the effect path, which `apply_command`,
    `command_effect` and `command_dwell` already implement, and a latched mode's value between
    commands is what it already was — so for those fourteen states the premise had lapsed and the
    exemption had become a hole with a reason that no longer applied. A mode the tick carries needs
    a position to carry.

    **The narrowing is the finding, and so is the boundary.** A `discrete` state moved by `logic:`
    is still refused by the plant, so it still needs no initial and the corpus says why. And a
    mode's position is not a number: it is a member of the state's own `enum`, or a map over the
    elements that hold one, which is why the exemption called it "a different vocabulary" rather
    than "later". What survives from the numeric half is the rule underneath — a starting value
    says where it came from — and what is new is that it has to be a value the state can hold.
    """
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1500:]

    def refusal(name: str, path: tuple[str, ...], old: str, new: str, needle: str) -> None:
        definition = copy_definition(fixture_dir(tmp_path, name))
        target = definition.joinpath(*path)
        text = target.read_text()
        assert old in text, f"the fixture no longer matches {old!r}"
        target.write_text(text.replace(old, new, 1))
        out = run_linter(definition).stdout
        assert needle in out, f"{needle!r} did not fire:\n{out[-1500:]}"

    eclss = ("domains", "eclss", "components.yaml")
    # The position removed outright: this is the fourteen-state finding in one edit. **The anchor is
    # the `initial` line rather than the `unit` one**, because since round 83 this state declares its
    # vocabulary's provenance between them and holds a value rather than `UNCONFIGURED`.
    refusal(
        "carried-mode-unset",
        eclss,
        "    initial: primary\n",
        "",
        "is a `discrete` state the effect path owns (['command:set_cabin_regulator'])",
    )
    # A position the state cannot hold. `cabin_regulator_position` has no `auto` member — that is
    # the bus tie's vocabulary — so this is a mode the vehicle would be in and could not report.
    refusal(
        "carried-mode-outside-the-enum",
        eclss,
        "    initial: primary\n",
        "    initial: auto\n",
        "which its `unit` ('enum[closed,primary,emergency,isolated]') cannot hold",
    )
    # A position with no grounding, which is the numeric rule's own requirement arriving in the new
    # vocabulary: `chosen` needs a reason, and the reason is what the checker is asking for.
    structure = ("domains", "structure", "components.yaml")
    refusal(
        "carried-mode-ungrounded",
        structure,
        "    initial_provenance:\n",
        "    unmoved_initial_provenance:\n",
        "with none of `initial_source`, `initial_derivation` or `initial_provenance`",
    )

    # A **keyed** mode, where the position is a map over the elements that hold one. The shape is
    # why the exemption called this "a different vocabulary" rather than "later": the numeric rule
    # could not have held it, and a map is the second shape the check has to read.
    refusal(
        "keyed-carried-mode-outside-the-enum",
        structure,
        "    initial: UNCONFIGURED\n    initial_note: >-\n",
        "    initial:\n      hatch_crew_csm: ajar\n    initial_note: >-\n",
        "which its `unit` ('map[hatch_id,enum[closed,latched,open]]') cannot hold",
    )

    # **And the control, which is what keeps this a narrowing rather than a rule about the class.**
    # `load_shed_class` is moved by `logic:` and refused by the plant, so it declares no initial —
    # and the `run_linter(VEHICLE)` at the top of this test is what asserts that composing. That is
    # the exemption's *surviving* half, and it is a control rather than a comment because the
    # tempting over-correction is to ask every discrete state for a position, which would refuse a
    # state the plant cannot advance and whose position nothing carries.


def test_a_commanded_mode_holds_its_value_through_a_tick_and_a_code_moved_one_does_not(tmp_path):
    """The rule the exemption's premise was about, fired rather than described.

    A `discrete` state whose movers are all commands is *latched*: `plant.md` §3 puts it under
    "discrete / latched", and the whole of "latched" is that the value does not move between the
    events that move it. So the tick's job is to carry what the command left — step 1 of §9's loop
    writes the effect into the value map and step 4 walks the nodes, so the hold is what carries a
    commanded transition *through* a tick rather than losing it — and `apply_command` is where the
    transition itself is computed.

    **The two halves are asserted together on purpose.** A hold that no command can change is a
    constant, and a command whose value the next tick discards is a command that did nothing; the
    test is that a value written by `apply_command` is still there after `step()`, which is the
    property the fourteen states were refused for not having. And the boundary is asserted with it:
    a mode moved by `logic:` is still refused, by name, with the mover that owes the code.
    """
    # The tool path, the way every plant test in this file reaches it: there is no conftest,
    # because this suite must stay runnable against a bare checkout of the configuration.
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import plant

    world = plant.load_world(VEHICLE)
    values = plant.initial_values(world)
    # The one mode whose starting position the corpus could source: `auto`, from the relief valve's
    # own "normally closed, with an 'unexpected opening' event" (`apollo_diode.md:213`).
    assert values["relief_valve_state"] == "auto", values.get("relief_valve_state")

    # The hold: a tick that carries the declared position rather than refusing the state.
    gaps = []
    after = plant.step(world, values, plant.tick_seconds(world), gaps)
    assert after["relief_valve_state"] == "auto", after.get("relief_valve_state")
    assert not [g for g in gaps if g.state.id == "relief_valve_state"], [
        str(g.where) for g in gaps if g.state.id == "relief_valve_state"
    ]

    # The transition, through the effect path the plant already had: `set_relief_valve`'s argument
    # is the state's own vocabulary, so the values are the identity.
    # `apply_command` stages a sentinel state inside `values["internal"]`, which is the sentinel's
    # own key space rather than a slot beside the scalars; the tick then writes it under the state's
    # own id as well, because `state_values` is the one place that decides what a state's entries are.
    delta = plant.apply_command(world, after, "set_relief_valve", {"state": "open"})
    assert delta["internal"]["relief_valve_state"] == "open", delta
    # The caller commits it, and `console.py` commits it exactly this way: `values.update(staged)`.
    # The sentinel's sub-map arrives whole rather than as a patch, which is what makes one `update`
    # enough for a key space that is a map rather than a slot.
    commanded = dict(after)
    commanded.update(delta)
    carried = plant.step(world, commanded, plant.tick_seconds(world), [])
    assert carried["relief_valve_state"] == "open", carried.get("relief_valve_state")
    assert carried["internal"]["relief_valve_state"] == "open", carried["internal"]

    # And the boundary: `load_shed_class` is moved by the undervoltage ladder, so the tick still
    # refuses it with the mover named rather than a sentence about the class.
    refused = []
    plant.step(world, values, plant.tick_seconds(world), refused)
    ladder = [g for g in refused if g.state.id == "load_shed_class"]
    assert ladder, [g.state.id for g in refused][:20]
    assert "moved by" in ladder[0].owed, ladder[0].owed


def test_the_linter_refuses_a_console_flag_that_cannot_be_told_from_its_default(tmp_path):
    """The run's identity is three flags, and a flag that *is* its own default cannot be obeyed.

    `tools/console.py` remembers `scenario`, `seed` and `ring_slots` (in `pending.json` when this was
    written, in the directory's record `Executive.root_record` since) — and all three are also
    command-line options. That makes each of them two
    things at once, a thing the vehicle remembers and a thing a caller can say, and the two are
    tellable apart only if *the caller named nothing* has a representation of its own. It did not:
    `--scenario` defaulted to `"nominal"`, `--seed` to `0`, `--ring-slots` to `300`, so `args.scenario`
    was the same string whether the caller had named the posture or named nothing at all. The
    restore asked which one it was looking at and could not be answered, and a resumed window
    silently ignored all three.

    **The refusal is about the mechanism rather than about the three flags**, which is why the
    durable set is read off the console's own `write_json_atomic(..., self.pending, {...})` call and
    the option list off its own parser: a fourth remembered value added later is caught the day it
    is declared, and neither list is a copy that can go stale. `None` is the rule because `None` is
    the one value a caller cannot name, and three breaks are exercised — the string default, the
    numeric one, and the case the derivation itself cannot run — because a check that reports the
    right thing for one shape of the defect and stays silent for its sibling is the next round's
    finding.
    """
    # The corpus at rest: the console already resolves the three, so the check is silent about it.
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1500:]

    # A string default, which is the break the round found: `--scenario crisis` and no flag at all
    # become the same argument.
    named = copy_definition(fixture_dir(tmp_path, "console-flag"))
    path = named / "tools" / "console.py"
    text = path.read_text()
    assert '"--scenario",\n        default=None,' in text, "the fixture no longer matches console.py"
    path.write_text(text.replace('"--scenario",\n        default=None,', '"--scenario",\n        default="nominal",', 1))
    result = run_linter(named)
    assert result.returncode == 1, result.stdout[-900:]
    assert "tools/console.py:--scenario" in result.stdout, result.stdout[-900:]
    assert "defaults to 'nominal'" in result.stdout, result.stdout[-900:]
    assert "remembered (written to `pending.json`, the directory's record or the checkpoint) as `scenario`" in result.stdout, result.stdout[-900:]

    # The numeric one, on a flag whose value is an int: the message has to read the same way, and
    # the point is that `0` is as un-nameable-a-default as `"nominal"` is.
    seeded = copy_definition(fixture_dir(tmp_path, "console-seed"))
    path = seeded / "tools" / "console.py"
    text = path.read_text()
    assert '"--seed",\n        type=int,\n        default=None,' in text
    path.write_text(
        text.replace('"--seed",\n        type=int,\n        default=None,', '"--seed",\n        type=int,\n        default=0,', 1)
    )
    result = run_linter(seeded)
    assert result.returncode == 1, result.stdout[-900:]
    assert "tools/console.py:--seed" in result.stdout, result.stdout[-900:]
    assert "defaults to 0" in result.stdout, result.stdout[-900:]

    # **A check that cannot run is not a check that passed.** Renaming the record the durable set is
    # derived from must refuse rather than pass: a silent pass here would leave every flag in the
    # file unchecked while the report said the vehicle composed.
    # The record a restart reads is the directory's (`Executive.root_record`, ADR 0001's
    # clarifications), so that is the one renamed; a window's `pending.json` is a published copy and
    # no longer a required source.
    unwritten = copy_definition(fixture_dir(tmp_path, "console-unreadable"))
    path = unwritten / "tools" / "console.py"
    text = path.read_text()
    assert text.count("def root_record(") == 1
    path.write_text(text.replace("def root_record(", "def directory_record(", 1))
    result = run_linter(unwritten)
    assert result.returncode == 1, result.stdout[-900:]
    assert "no longer returns the directory's record" in result.stdout, result.stdout[-900:]

    # **The record must carry the identity console.py declares.** Independent review (Claude Opus)
    # dropped `scenario` from `root_record` and defaulted `--scenario` to "nominal": the key left the
    # remembered set, its flag left the check, and the linter passed while the restart still read it.
    dropped = copy_definition(fixture_dir(tmp_path, "console-dropped"))
    path = dropped / "tools" / "console.py"
    text = path.read_text()
    assert text.count('            "scenario": self.scenario,\n') == 1, "the fixture no longer matches root_record"
    text = text.replace('            "scenario": self.scenario,\n', "", 1)
    text = text.replace('"--scenario",\n        default=None,', '"--scenario",\n        default="nominal",', 1)
    path.write_text(text)
    result = run_linter(dropped)
    assert result.returncode == 1, result.stdout[-900:]
    assert "tools/console.py:root_record" in result.stdout and "'scenario'" in result.stdout, result.stdout[-900:]

    # **A partial set must not pass.** Independent review (Codex gpt-6-astra high) moved `scenario` and
    # `seed` into a `**{...}` unpacking inside `root_record` and defaulted `--scenario` to "nominal":
    # the extraction skipped the unpacked keys, `ring_slots` alone kept the set non-empty, and the
    # check passed. An unreadable key now makes the whole record unreadable.
    unpacked = copy_definition(fixture_dir(tmp_path, "console-unpacked"))
    path = unpacked / "tools" / "console.py"
    text = path.read_text()
    old_pair = '            "scenario": self.scenario,\n            "seed": self.seed,\n'
    assert text.count(old_pair) == 1, "the fixture no longer matches root_record"
    text = text.replace(old_pair, '            **{"scenario": self.scenario, "seed": self.seed},\n', 1)
    text = text.replace('"--scenario",\n        default=None,', '"--scenario",\n        default="nominal",', 1)
    path.write_text(text)
    result = run_linter(unpacked)
    assert result.returncode == 1, result.stdout[-900:]
    assert "no longer returns the directory's record" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_shared_node_or_sentinel_count_that_has_drifted(tmp_path):
    """Two more figures in prose, and both had drifted while the sentences explained real rules.

    The fault figures and the schedule size got readers in earlier rounds. What was left was every
    *other* count a tool's prose states about the corpus it walks, and two of them were wrong.
    `plant._refuse_shared_node` put the number of shared nodes at twelve while the vehicle has
    eleven, and `plant.initial_values` set the sentinel's population at forty-eight while fifty-nine
    states live there. Both were right when written; the vehicle moved and the sentences did not.

    **The sentinel one is the worse of the two**, because the shape of the whole value map is
    explained by it — a reader who believed that figure would size `values["internal"]` from a number
    that had been wrong for most of the folder's life. `state_values`' docstring carried the same
    figure a third time, which is what a claim with no reader does: it gets copied.

    Both are spelled out as words, so the reader needs a word table — and that is the point rather
    than an inconvenience. `NODE_COUNT_FIGURES` records the opposite choice for its own figures
    ("A spelled-out size would slip past this, which is named as the gap it is"), and for *these* two
    a digits-only reader would have caught neither. The table covers one to ninety-nine, which is
    every count this corpus has ever stated in words.

    **One drifted figure next door is deliberately not patrolled**, and the test states the boundary
    so a later round does not read the silence as an oversight: the ratio in
    `plant.resolve_declared_states` describes what a *removed line* would cost, not what the vehicle
    is, and checking it would mean running the plant inside the linter.
    """
    # The corpus at rest: both claims are true and the check is silent about them.
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1500:]

    # A shared-node count that has drifted, in the tool the reader was written for.
    definition = copy_definition(fixture_dir(tmp_path, "stale-shared"))
    path = definition / "tools" / "faults.py"
    text = path.read_text()
    anchor = '"""'
    assert anchor in text
    path.write_text(
        text.replace(anchor, anchor + "\nA fixture's claim: twelve nodes carry more than one state.\n", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1, result.stdout[-900:]
    assert "states 'twelve nodes carry more than one state'" in result.stdout, result.stdout[-900:]
    assert "this vehicle has 10 multi-state nodes" in result.stdout, result.stdout[-900:]

    # And the sentinel form, which is the other noun and the other claim.
    other = copy_definition(fixture_dir(tmp_path, "stale-sentinel"))
    path = other / "tools" / "faults.py"
    text = path.read_text()
    path.write_text(
        text.replace(
            anchor, anchor + "\nA fixture's claim: forty-eight states live on it.\n", 1
        )
    )
    result = run_linter(other)
    assert result.returncode == 1, result.stdout[-900:]
    assert "states 'forty-eight states live on it'" in result.stdout, result.stdout[-900:]
    assert "this vehicle has 59 states on the sentinel" in result.stdout, result.stdout[-900:]

    # A *digits* figure is read too, so the reader is not tied to the spelling the corpus happens
    # to use today.
    digits = copy_definition(fixture_dir(tmp_path, "stale-digits"))
    path = digits / "tools" / "faults.py"
    text = path.read_text()
    path.write_text(
        text.replace(anchor, anchor + "\nA fixture's claim: 12 nodes carry more than one state.\n", 1)
    )
    result = run_linter(digits)
    assert result.returncode == 1, result.stdout[-900:]
    assert "states '12 nodes carry more than one state'" in result.stdout, result.stdout[-900:]

    # And the check's own explanatory prose must not trip it. The first version of the comment above
    # `MULTI_STATE_NODE_FIGURES` wrote both stale figures out in the form the patterns read, and
    # `check_vehicle.py` refused itself — one of the two faults on the first run was the paragraph
    # explaining the check. The corpus composing above is the assertion that it does not.
    #
    # The re-assertion here is deliberately narrower than "the phrase appears nowhere": the patterns
    # themselves are live lines that contain it, and a grep would refuse the reader for existing.
    # What matters is that no **docstring** — the thing a reader believes — carries a count the
    # check would contradict, so this walks the real docstrings with `ast` rather than the text.
    import ast as _ast
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import check_vehicle as _cv

    live = {
        "multi-state nodes": _cv.MULTI_STATE_NODE_FIGURES,
        "states on the sentinel": _cv.SENTINEL_STATE_FIGURES,
    }
    # 11 -> 10 in round 70, with the source regulator off the fuel cell's node.
    expected = {"multi-state nodes": 10, "states on the sentinel": 59}
    for tool in sorted((VEHICLE / "tools").glob("*.py")):
        tree = _ast.parse(tool.read_text())
        for node in _ast.walk(tree):
            if not isinstance(node, (_ast.Module, _ast.FunctionDef, _ast.AsyncFunctionDef, _ast.ClassDef)):
                continue
            doc = _ast.get_docstring(node)
            if not doc:
                continue
            for label, pattern in live.items():
                for match in pattern.finditer(doc):
                    assert _cv._counted_number(match.group(1)) == expected[label], (
                        f"{tool.name} docstring states {match.group(0)!r}, and the vehicle has "
                        f"{expected[label]} {label}"
                    )


def test_the_linter_refuses_a_node_count_three_files_state_differently(tmp_path):
    """One schedule, four figures, and no two of them in the same file agreed.

    `tools/plant.py`'s module docstring, `plant.md` §2 and a comment in `check_vehicle.py` each
    stated a size for the tick order, and each said something different — all of them smaller than
    the order the linter derives, because each was written against the schedule of its own round and
    none had a reader. `faults.py`'s fault figures were at least *about* one quantity in one era;
    these had drifted apart from each other, which is the stronger form: a reader who believed the
    docstring would have had a different vehicle from a reader who believed the contract.

    `plant.md` and `tools/` are not the README. The README is a round log and quotes a past round's
    figures on purpose — this file's own changelog test does exactly that with an old tick-order
    figure, and the README's front table beside it states the live one — so a reader that walked the
    README would refuse the record. These two are where the vehicle's *current* shape is stated, and
    the count is held against the schedule the run already derived rather than against a second
    counter, which would be one more declaration to drift.

    The fixture checks the walk as well as the rule: `plant.md` and a tool other than `plant.py` are
    each broken in turn, because a check that named one file and one form would pass this test's
    first case and miss three quarters of the defect.
    """
    # The corpus at rest: the three figures agree, and the README's historical ones are untouched.
    result = run_linter(VEHICLE)
    assert result.returncode == 0, result.stdout[-1500:]
    readme = (VEHICLE / "README.md").read_text()
    assert "41 nodes" in readme, (
        "the README no longer quotes a historical tick-order figure, so this test's claim that the "
        "check deliberately leaves the round log alone is no longer being exercised"
    )

    # The contract, which the plant is built against.
    definition = copy_definition(fixture_dir(tmp_path, "stale-nodes-in-contract"))
    path = definition / "plant.md"
    text = path.read_text()
    old = "The derived order is 59 nodes"
    assert old in text, "the fixture no longer matches plant.md's tick-order sentence"
    path.write_text(text.replace(old, "The derived order is 40 nodes", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "states '40 nodes'" in result.stdout, result.stdout[-900:]
    assert "the schedule the linter derives for this vehicle is 59 nodes" in result.stdout

    # A tool that is not the one the reader was written for, and the other spelling of the claim.
    other = copy_definition(fixture_dir(tmp_path, "stale-nodes-in-tool"))
    path = other / "tools" / "faults.py"
    text = path.read_text()
    anchor = '"""'
    assert anchor in text
    path.write_text(text.replace(anchor, anchor + "\nA fixture's claim: 12 nodes schedule this vehicle.\n", 1))
    result = run_linter(other)
    assert result.returncode == 1
    assert "tools/faults.py" in result.stdout and "states '12 nodes'" in result.stdout, (
        result.stdout[-900:]
    )

    # And the tick-order form, which is the spelling a writer reaches for when the sentence is about
    # the order rather than about the graph. `plant.py` is not in the fixture — `copy_definition`
    # copies exactly the one tool the linter reads a docstring from — so the form is planted in
    # `plant.md`, which is the other file the walk covers and the one a reader is most likely to
    # meet it in.
    order = copy_definition(fixture_dir(tmp_path, "stale-node-tick-order"))
    path = order / "plant.md"
    text = path.read_text()
    anchor = "The derived order is 59 nodes and `check_vehicle.py` reports its tail on every"
    assert anchor in text, "the fixture no longer matches plant.md's tick-order sentence"
    path.write_text(
        text.replace(anchor, "The derived order is a 40-node tick order and `check_vehicle.py`", 1)
    )
    result = run_linter(order)
    assert result.returncode == 1
    assert "states '40-node tick order'" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_debt_that_says_its_own_obligation_is_answered(tmp_path):
    """Two `open_debts` entries recorded their own resolution and stayed in the counted list.

    `mission.yaml` carried "the lunar occultation comms blackout is **modelled** and no longer a
    debt" and "`transition_evidence` ... **Resolved against the vehicle rather than left open**".
    Each was still counted in the headline, and the blackout one was worse than redundant: its
    second half restated the per-phase *sequence* debt three entries above it, so one obligation was
    declared twice in one list and counted twice. A debt that answers itself is not a debt, and the
    cost of leaving one standing is that the entry still *names* what is missing and the name is now
    wrong.
    """
    definition = copy_definition(tmp_path / "answered-debt")
    path = definition / "mission.yaml"
    text = path.read_text()
    old = "and nothing here says how far out the vehicle starts."
    assert old in text, "the fixture no longer matches the entry-corridor debt"
    path.write_text(text.replace(old, " This is no longer owed.", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "'no longer owed'" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_debt_about_a_coupling_edge_that_has_stopped_owing(tmp_path):
    """Five entries across four files said `E-GNC-RCS` "has no sensitivity" while it carries 1.0.

    The edge has had `value: 1.0, unit: mode per mode, basis: derived` since the round that
    promoted `guidance` to a service node, and its own note says the opposite of the debts in as
    many words — "this edge is now closed without them". The corpus was contradicting itself across
    two keys of one file and three other files, and the contradiction inflated the count by five.
    The fixture injects the claim about an edge with a *numeric* value and no closure wording in its
    note, so the rule that fires is the sensitivity one and not the note one beside it.
    """
    definition = copy_definition(tmp_path / "senseless-debt")
    path = definition / "vehicle.yaml"
    text = path.read_text()
    old = "each unit thrust direction and lever arm from the centre of mass."
    assert old in text, "the fixture no longer matches the thruster-geometry debt"
    path.write_text(
        text.replace(old, old + " Without them E-BUS-PUMP has no sensitivity.", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "names E-BUS-PUMP and says 'has no sensitivity'" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_debt_that_names_an_edge_whose_note_says_it_is_closed(tmp_path):
    """The note and the debt are two declarations about one edge, and nothing had compared them.

    This rule is deliberately blunt: if an edge's own prose says it is closed, a list of what the
    vehicle still owes has no business naming it. The escape is to not write the id, which is the
    right burden — the debt that was wrong here did not need the id to make its point. The words
    'is now closed' live inside `sensitivity.note` rather than beside `from`/`to`/`kind`, and the
    first version of this reader looked only at the edge-level key, so it stayed silent on the one
    edge it was written for. That is the check-that-cannot-run failure, found by writing the rule
    and watching it not fire.
    """
    definition = copy_definition(tmp_path / "closed-edge-debt")
    path = definition / "coupling.yaml"
    text = path.read_text()
    old = "- \"The ladder's missing rung."
    assert old in text, "the fixture no longer matches the shed-rung debt"
    path.write_text(
        text.replace(old, "- \"E-GNC-RCS is still owed. The ladder's missing rung.", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "whose own note says it" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_cycle_whose_members_are_a_path(tmp_path):
    """A cycle entry with no back-edge is never walked back, so nothing checked that it closed.

    `C-RAD-COOL` declared `algebraic: true` and `back_edge: null` and named `E-RAD-THERM` and
    `E-WATER-RAD`, which chain `water_cooling -> radiator_reject -> coolant_supply_t` — a path. It
    survived because the closure check needs a back-edge to walk back to, so the absence of one
    read as a property of the loop rather than as the reason the check did not run. The fixture
    rebuilds exactly that shape out of a cycle that does close, which is also why the refusal
    exists: the members are all real edges a domain needs, and what is false is only that they
    close.
    """
    definition = copy_definition(tmp_path / "path-cycle")
    path = definition / "coupling.yaml"
    text = path.read_text()
    anchor = "  - id: C-BAT-THERMAL\n"
    assert anchor in text, "the fixture no longer matches the cycle list"
    # `C-RAD-COOL`, exactly as it stood: two real edges that chain rather than close. It is
    # reconstructed rather than adapted from a cycle that does close, because *reusing* one is not
    # the defect — the defect is a cycle entry whose members are a path, and a fixture built by
    # corrupting a working loop also removes a back-edge from the schedule and gets refused for
    # that instead. The first version of this test did exactly that and asserted on the wrong
    # refusal, which is how the difference was found.
    path.write_text(
        text.replace(
            anchor,
            "  - id: C-RAD-COOL\n"
            "    name: \"radiator rejection versus coolant temperature\"\n"
            "    members: [E-RAD-THERM, E-WATER-RAD]\n"
            "    back_edge: null\n"
            "    delay_ticks: 0\n"
            "    algebraic: true\n"
            + anchor,
            1,
        )
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "together form a path rather than a loop" in result.stdout, result.stdout[-900:]


def test_the_linter_and_the_plant_read_one_crew_placement_declaration(tmp_path):
    """`also_present` was read by the plant and not by the linter, so two debts outlived their answer.

    `descent` and `surface` name only LM configurations and declare `also_present: [csm_alone]`,
    which is where the CM pilot is while the LM is on the surface. `tools/plant.py --crew` read
    both keys and placed every crew member in every phase; the linter's crew check read
    `configurations` alone and went on reporting two debts naming the CSM as missing — debts the
    vehicle had already answered, which is worse than debts it had not, because the count is the
    headline and the entry names the wrong thing.

    So the two readers are held together here rather than in prose: with the declaration removed the
    linter must report the phase and the plant must report the same person unplaced, and with it
    present neither says anything. Two tools disagreeing about one field is the defect; each tool
    being internally consistent is what let it run for as long as it did.
    """
    definition = copy_definition(tmp_path / "also-present")
    path = definition / "mission.yaml"
    text = path.read_text()
    # **The anchor is the *value* and not the line**, and it has been rewritten twice now: once in
    # round 73 when the configuration it names changed, and once in round 74 when the field became
    # one entry per subject. Both times the prose beside it moved and the fixture had to survive
    # that — a fixture pinned to a line would fail on the comment rather than on the declaration.
    old = "    also_present: [[csm_alone_lunar]]"
    assert old in text, "the fixture no longer matches descent's also_present"

    plant = VEHICLE / "tools" / "plant.py"

    def crew_report(where: Path) -> str:
        return subprocess.run(
            [sys.executable, str(plant), "--dir", str(where), "--crew"],
            capture_output=True,
            text=True,
            check=False,
        ).stdout

    # As declared: neither tool has anything to say about `descent`.
    lint = run_linter(definition)
    assert lint.returncode == 0, lint.stdout[-900:]
    assert "phase descent" not in lint.stdout, "a phase that places its crew is reported as a debt"
    assert "UNPLACED" not in crew_report(definition)

    # With the declaration gone both tools name the same phase and the same person.
    path.write_text(text.replace(old, "", 1))
    lint = run_linter(definition)
    assert "mission.yaml:phase descent: names no configuration holding ['csm']" in lint.stdout, (
        lint.stdout[-900:]
    )
    crew = crew_report(definition)
    assert "descent                UNPLACED ['csm_pilot']" in crew, crew[-900:]
    assert "surface                every crew member placed" in crew, (
        "only the phase whose declaration was removed may lose its placement"
    )


def test_the_linter_refuses_a_registry_census_that_has_drifted_from_the_registry(tmp_path):
    """`channels.yaml` counted its own `range_kind` assignments, and the count was one short.

    The entry that argues the assignments are *derived* rather than chosen gave its own census —
    "57 channels carry the field — 43 `band`, 14 `scale`" — and by the time anything read it the
    registry carried 58, 44 and 14. One channel gained the field and the prose explaining the field
    did not, in the file whose entire subject is what a channel declares. The check sits beside
    `check_range_kinds`, which reads the assignments themselves, because a census is a claim about
    the registry made inside the registry.
    """
    definition = copy_definition(tmp_path / "census")
    path = definition / "channels.yaml"
    text = path.read_text()
    # 44/14 -> 43/15 in round 33, when `prop.dps_throttle_pct`'s operating band became a scale: the
    # census follows the registry, and the fixture below moves it by one channel rather than by a
    # kind, which is the smallest change the reader has to catch.
    old = "58 channels carry the field — 43 `band`, 15 `scale`"
    assert old in text, "the fixture no longer matches the range_kind census"
    path.write_text(text.replace(old, "57 channels carry the field — 43 `band`, 14 `scale`", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "states the `range_kind` census as 57 channels" in result.stdout, result.stdout[-900:]


def test_the_gate_s_own_prose_states_the_vehicle_it_tests():
    """This file's docstrings are read by the next round, and three of them described another vehicle.

    Round 61 gave the linter readers for count claims in `tools/` and `plant.md`; this round found the
    same defect one file over, in the gate. Three docstrings here said **134 states**, one of them
    while quoting the status line that says 139, and one said **57 scheduled nodes** where the
    schedule has 58. They are not decorative: a test docstring is the paragraph that says what the
    test is for, and several of these quote the figures the test is *about* — so a reader checking
    whether the assertion still matches its subject reads a number that has been wrong for rounds.

    **The linter cannot do this one.** `tests/` is not under the vehicle root, so `check_tool_docstrings`
    never sees this file, and it has no world to ask for a state count anyway. So the figures come
    from the two instruments that do have them: the linter's `CHANNEL_DERIVATION_COUNTS`, which
    publishes the state and schedule totals it counts while validating the frame's debt, and the
    plant's own world. The claim patterns are the linter's, imported rather than restated — a fourth
    copy of the rule would be the defect this test exists to remove.
    """
    import ast as _ast
    import sys as _sys

    if str(VEHICLE / "tools") not in _sys.path:
        _sys.path.insert(0, str(VEHICLE / "tools"))
    import check_vehicle as _cv
    import plant as _plant

    world = _plant.load_world(VEHICLE)
    live = {
        "states": len(world.states),
        "scheduled_nodes": len(world.schedule),
        "multi-state nodes": sum(
            1
            for node in {s.node for s in world.states if s.node != "internal"}
            if len(world.states_on(node)) > 1
        ),
        "states on the sentinel": sum(1 for s in world.states if s.node == "internal"),
    }
    # The two instruments agree, and that agreement is worth asserting: the linter counts states by
    # walking `domains/*/components.yaml`, the plant by building a world, and a disagreement would be
    # a finding in its own right rather than something this test should paper over.
    report = _cv.Report()
    _cv.check_channel_derivations(
        VEHICLE,
        _cv.load_documents(
            VEHICLE,
            _cv.load(VEHICLE / "vehicle.yaml", _cv.Report()),
            _cv.load(VEHICLE / "coupling.yaml", _cv.Report()),
            _cv.load(VEHICLE / "mission.yaml", _cv.Report()),
            _cv.load(VEHICLE / "channels.yaml", _cv.Report()),
        ),
        report,
    )
    counts = _cv.CHANNEL_DERIVATION_COUNTS
    assert counts["states"] == live["states"], (counts, live)
    assert counts["scheduled_nodes"] == live["scheduled_nodes"], (counts, live)

    # The claims this file makes, in the forms it makes them. **The patterns have to read a claim
    # rather than a number near one, and the first version did not**: `\b(\d+) states\b` matched
    # "two states", "four states" and "twenty-one states" — every sentence about *some* states — and
    # the walk refused thirteen docstrings that were all correct. A count is a claim about the whole
    # only when the sentence says so, which in this file means `all N states` or `N states over M
    # scheduled nodes` (the status-line clause it quotes). Everything else is a count of something
    # else and belongs to the docstring that makes it.
    claims = re.compile(
        r"\ball (?P<all_states>\d+|[A-Za-z]+(?:-[A-Za-z]+)?) states\b"
        r"|\b(?P<over_states>\d+|[A-Za-z]+(?:-[A-Za-z]+)?) states over "
        r"(?P<over_nodes>\d+) scheduled nodes\b"
        r"|\b(?P<shared>[A-Za-z]+(?:-[A-Za-z]+)?) nodes carry more than one state\b"
        r"|\b(?P<sentinel>[A-Za-z]+(?:-[A-Za-z]+)?) states live on it\b"
        r"|\bthe vehicle's (?P<possessive>\d+) states\b"
    )
    # Group name -> the figure it is a claim about. `states over N scheduled nodes` contributes two.
    figure_of = {
        "all_states": "states",
        "over_states": "states",
        "over_nodes": "scheduled_nodes",
        "shared": "multi-state nodes",
        "sentinel": "states on the sentinel",
        "possessive": "states",
    }

    tree = _ast.parse(Path(__file__).read_text())
    checked = 0
    wrong: list[str] = []
    for node in _ast.walk(tree):
        if not isinstance(node, (_ast.Module, _ast.FunctionDef, _ast.AsyncFunctionDef, _ast.ClassDef)):
            continue
        doc = _ast.get_docstring(node)
        if not doc:
            continue
        where = node.name if hasattr(node, "name") else "<module>"
        for match in claims.finditer(doc):
            for name, token in match.groupdict().items():
                if token is None:
                    continue
                stated = _cv._counted_number(token)
                if stated is None:
                    continue
                checked += 1
                label = figure_of[name]
                if stated != live[label]:
                    wrong.append(f"{where}: {token!r} in {match.group(0)!r} != {live[label]} {label}")
    assert not wrong, "this file's docstrings describe another vehicle:\n  " + "\n  ".join(wrong)
    # The reader has to have read something, or it is a check that cannot run — the shape this
    # folder's own traps list opens with. **Three is the whole of the surface, not a threshold picked
    # to pass**: this file makes total-state claims in exactly three places, and every other "N
    # states" in it counts *some* states ("two states", "the four states that ..."), which belongs to
    # the docstring making it. A later round that adds a claim raises this deliberately, which is the
    # intended friction — the alternative is a pattern broad enough to refuse the thirteen correct
    # docstrings it refused on the first run of this test.
    assert checked >= 3, f"the walk matched only {checked} claims, and this file makes three"


def test_the_linter_refuses_a_status_line_whose_figures_have_drifted(tmp_path):
    """The status line's own sentence, held whole rather than in the three figures a test read.

    The sentence is "148 channels, 139 states over 59 scheduled nodes, 142 thresholds, 58 verbs and
    128 classified events". `test_the_readme_status_matches_the_tools` reads the first three; the
    last three were read by nothing, which is the same defect one clause further along in the same
    line. The fixture moves the threshold count by one, because that is the smallest change the
    reader has to catch and the one a domain landing a threshold makes.
    """
    definition = copy_definition(tmp_path / "status-line")
    path = definition / "README.md"
    text = path.read_text()
    # The sentence is hard-wrapped between "142" and "thresholds", so the anchor is the half that
    # fits on one line. A fixture that matched the whole clause would fail on a reflow rather than
    # on the value it is about — the same distinction the reader itself makes.
    old = "thresholds, 58 verbs and 128 classified events"
    assert old in text, "the fixture no longer matches the status line"
    path.write_text(text.replace(old, "thresholds, 58 verbs and 127 classified events", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "states 127 classified events while the corpus declares 128" in result.stdout, (
        result.stdout[-900:]
    )


def test_the_linter_refuses_a_carried_value_that_disagrees_with_its_source(tmp_path):
    """`same_as` is the general form of the join this folder has written four times by hand.

    An absorber's rating on the article and on the counter; a pump's watts in `vehicle.yaml` and in
    a domain's load entry; and a valve count in two vehicle blocks. Each time the fix was a check
    written for that pair, and the
    round that joined the absorber's three ratings wrote the lesson down: *a hand-written list of
    what to compare is the bug* — the list had two entries and the corpus had three.

    So a mapping that declares a value it knows is a copy carries `same_as` beside it, and the walk
    holds every one of them against the declaration it names. The RCS valve's old link was removed
    because group-command dwell is not engine tailoff, so this fixture creates a synthetic link
    between its two chosen zero policy values and then breaks one by ten milliseconds.
    """
    definition = copy_definition(tmp_path / "same-as")
    path = definition / "domains" / "rcs" / "components.yaml"
    rcs = yaml.safe_load(path.read_text())
    valve = next(state for state in rcs["state"] if state["id"] == "thruster_valve")
    valve["dwell"]["same_as"] = {
        "min_off_s": "domains/rcs/components.yaml:state.thruster_valve.dwell.min_on_s"
    }
    valve["dwell"]["min_off_s"] = 0.01
    path.write_text(yaml.safe_dump(rcs, sort_keys=False))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "declares min_off_s as 0.01 while" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_a_same_as_whose_source_does_not_resolve(tmp_path):
    """A carried value whose source is gone is a value nothing can disagree with.

    "The name is gone" and "the value is unset" are different answers and only the second is a
    debt, which is why a path that resolves to nothing is a refusal while an `UNCONFIGURED` on
    either side is left to the debt walk. The fixture renames the field the link points at, which
    is what a later round moving a capability key would do without noticing.
    """
    definition = copy_definition(tmp_path / "same-as-gone")
    path = definition / "domains" / "rcs" / "components.yaml"
    rcs = yaml.safe_load(path.read_text())
    valve = next(state for state in rcs["state"] if state["id"] == "thruster_valve")
    valve["dwell"]["same_as"] = {
        "min_off_s": "domains/rcs/components.yaml:state.thruster_valve.dwell.missing_s"
    }
    path.write_text(yaml.safe_dump(rcs, sort_keys=False))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "which resolves to nothing" in result.stdout, result.stdout[-900:]


def test_the_linter_refuses_one_rcs_command_on_time_for_three_systems(tmp_path):
    """An LM pulse command time cannot become the SM and CM hardware limit by sharing a scalar.

    The LM guide's 10 ms is a minimum command ON duration in pulse mode. The SM handbook gives
    the earliest OFF command from the automatic controller as 12 ms; the CM hardware limit is
    still owed. This broken copy restores the old global capability even if the scoped table is
    present. A provenance sentence alone cannot stop the pulse generator using it for all jets.
    """
    definition = copy_definition(tmp_path / "global-rcs-minimum")
    path = definition / "domains" / "rcs" / "components.yaml"
    rcs = yaml.safe_load(path.read_text())
    rcs["capability"].pop("minimum_command_on_s", None)
    rcs["capability"]["minimum_firing_time"] = {
        "value": 0.01,
        "unit": "s",
        "provenance": {"basis": "historical", "source": "LM guide PDF p. 89"},
    }
    path.write_text(yaml.safe_dump(rcs, sort_keys=False))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "one RCS command ON time for SM, CM and LM" in result.stdout, result.stdout[-1400:]

    # A keyed table can drift too. Each break removes a distinct piece of the source scope;
    # the linter must refuse its own field rather than merely count a new generic debt.
    for name, break_entry, expected in (
        (
            "system-deleted",
            lambda doc: doc["capability"]["minimum_command_on_s"].pop("rcs_cm"),
            "must name rcs_sm, rcs_cm and rcs_lm separately",
        ),
        (
            "path-swapped",
            lambda doc: doc["capability"]["minimum_command_on_s"]["rcs_sm"].update(
                path="engine_pulse_mode"
            ),
            "must declare 0.012 s for automatic_controller",
        ),
        (
            "value-copied",
            lambda doc: doc["capability"]["minimum_command_on_s"]["rcs_cm"].update(
                value=0.014
            ),
            "must declare 'UNCONFIGURED' s for automatic_controller",
        ),
        (
            "citation-removed",
            lambda doc: doc["capability"]["minimum_command_on_s"]["rcs_lm"]["provenance"].update(
                source=""
            ),
            "lm_propulsion_rcs_study_guide.pdf citation",
        ),
    ):
        broken = copy_definition(tmp_path / name)
        broken_path = broken / "domains" / "rcs" / "components.yaml"
        scoped = yaml.safe_load(broken_path.read_text())
        break_entry(scoped)
        broken_path.write_text(yaml.safe_dump(scoped, sort_keys=False))
        result = run_linter(broken)
        assert result.returncode == 1
        assert expected in result.stdout, result.stdout[-1500:]

    broken = copy_definition(tmp_path / "group-dwell-from-jet")
    path = broken / "domains" / "rcs" / "components.yaml"
    rcs = yaml.safe_load(path.read_text())
    valve = next(state for state in rcs["state"] if state["id"] == "thruster_valve")
    valve["dwell"]["min_on_s"] = 0.01
    path.write_text(yaml.safe_dump(rcs, sort_keys=False))
    result = run_linter(broken)
    assert result.returncode == 1
    assert "must be a chosen zero-duration group policy" in result.stdout, result.stdout[-1500:]


def test_the_linter_refuses_a_same_as_naming_a_field_its_mapping_lacks(tmp_path):
    """A link to a field that is not there holds nothing, and reads as a join that exists.

    This is the failure the key is most likely to acquire: an author writes the `same_as` entry and
    renames the field above it, or copies the link into the wrong mapping. Nothing else in the
    corpus would notice — the mapping still composes, the link still points somewhere real, and the
    value it was supposed to constrain is now unconstrained.
    """
    definition = copy_definition(tmp_path / "same-as-orphan")
    path = definition / "domains" / "rcs" / "components.yaml"
    rcs = yaml.safe_load(path.read_text())
    valve = next(state for state in rcs["state"] if state["id"] == "thruster_valve")
    valve["dwell"]["same_as"] = {
        "min_off_seconds": "domains/rcs/components.yaml:state.thruster_valve.dwell.min_on_s"
    }
    path.write_text(yaml.safe_dump(rcs, sort_keys=False))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "which the mapping it sits in does not declare" in result.stdout, result.stdout[-900:]


def test_the_rcs_command_on_times_keep_their_vehicle_and_command_paths():
    """LM pulse, SM automatic-controller and unknown CM limits keep their source scopes.

    The LM guide's 10 ms cannot qualify a CSM jet. The SM handbook's earliest 12 ms OFF command
    applies to the automatic controller, and the R-577 14 ms CM figure is a simulator limit.
    Until thruster membership and command path select one, the per-thruster pulse floor owes a
    value. Group enable/inhibit has a separate chosen zero dwell so inhibit remains available.
    """
    rcs = yaml.safe_load((VEHICLE / "domains" / "rcs" / "components.yaml").read_text())
    capability = rcs["capability"]
    states = {state["id"]: state for state in rcs["state"]}

    scoped = capability["minimum_command_on_s"]
    assert "minimum_firing_time" not in capability
    assert {system: entry["value"] for system, entry in scoped.items()} == {
        "rcs_sm": 0.012,
        "rcs_cm": "UNCONFIGURED",
        "rcs_lm": 0.01,
    }
    assert {system: entry["path"] for system, entry in scoped.items()} == {
        "rcs_sm": "automatic_controller",
        "rcs_cm": "automatic_controller",
        "rcs_lm": "engine_pulse_mode",
    }
    assert "2.5-18" in scoped["rcs_sm"]["provenance"]["source"]
    assert "p. 77" in scoped["rcs_lm"]["provenance"]["source"]
    assert scoped["rcs_cm"]["provenance"]["basis"] == "UNCONFIGURED"

    valve = states["thruster_valve"]["dwell"]
    pulse = states["pulse_width"]
    assert valve["min_on_s"] == valve["min_off_s"] == 0
    assert valve["provenance"]["basis"] == "chosen"
    assert "same_as" not in valve
    assert "same_as" not in pulse
    assert pulse["t_min_on_s"] == "UNCONFIGURED"
    thrust = states["thruster_thrust"]
    assert thrust["tau_fall_s"] == 0.05
    assert thrust["tau_rise_s"] == 0.04

    # The life limits are the same page's, and they are the thruster's rather than the domain's.
    life = capability["engine_life"]
    assert (life["steady_s"], life["pulse_s"], life["total_s"], life["restarts"]) == (
        500,
        500,
        1000,
        10000,
    )
    assert life["provenance"]["basis"] == "historical"


def test_the_fuel_cells_reactant_chain_re_derives_from_the_operating_point():
    """The debt that said "the electrochemistry no source publishes" was one division from three numbers.

    `fc_o2_draw_kg_s.per_joule_kg` was `UNCONFIGURED` with the note that the only missing scalar
    was "the cell voltage under load". The module's rated output is 29 +- 2 VDC —
    `ApolloTrainingElectricalPowerSystemStudyGuide.pdf` PDF p. 14, and
    `vehicle.yaml#electrical.fuel_cells.bus_v` had been carrying it as a 27-31 V *band* since the
    block was written. The reactant rate per ampere is on PDF p. 16 of the Mission E consumables
    analysis, the cell count is on PDF p. 38 of the first, and the mass ratio is stoichiometry.

    So the chain is asserted end to end here, in the direction the derivations run: the operating
    point, then the per-joule figure, then the two draws and the heat. A test that only checked the
    linter composed would not notice the whole chain being deleted.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    cells = vehicle["electrical"]["fuel_cells"]
    assert cells["output_v"] == 29, "the module's rated output, and the division's denominator"
    assert cells["cells_per_module"] == 31
    assert cells["h2_lb_per_h_per_a"] == 0.00257
    assert cells["bus_v"] == [27, 31], "the rated band the nominal sits inside"
    assert cells["reactant_molar_mass_kg_per_mol"] == {"h2": 0.002016, "o2": 0.032}
    assert cells["provenance"]["basis"] == "historical"
    assert "1420 watts" in cells["provenance"]["source"], cells["provenance"]["source"][-200:]

    power = yaml.safe_load((VEHICLE / "domains" / "power" / "components.yaml").read_text())
    states = {state["id"]: state for state in power["state"]}
    o2 = states["fc_o2_draw_kg_s"]
    assert o2["provenance"]["basis"] == "derived"
    # **The state computes the rate its unit names and the coefficient lives on the edge**, which is
    # where a `kg/s per W` figure belongs: round 57 found the two the other way round, with a
    # per-joule figure under a `kg O2/s` unit and a tank that would have read it as a flow.
    assert o2["provenance"]["computes"] == "draw_kg_s"
    assert o2["provenance"]["derivation"]["inputs"]["per_joule_kg"] == (
        "coupling.yaml:edges.E-FC-DRAW-O2.sensitivity.value"
    )
    assert o2["provenance"]["derivation"]["inputs"]["fuel_cell_power_w"] == "fuel_cell_power_w"

    # The three consequences, each carrying the state's figure rather than restating it — which is
    # what makes the chain one number in four places instead of four numbers that agree by hand.
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {edge["id"]: edge for edge in coupling["edges"]}
    for edge_id, expression in (
        # The operating point is here now rather than on the state: three published numbers, one
        # division, and the denominator is the module's rated output.
        (
            "E-FC-DRAW-O2",
            "h2_lb_per_h_per_a * lb_to_kg / seconds_per_hour / output_v / h2_per_o2",
        ),
        ("E-FC-DRAW-H2", "per_joule_kg * h2_per_o2"),
        (
            "E-FC-HEAT",
            "enthalpy_j_per_mol_o2 * cells_per_module / "
            "(electrons * faraday_c_per_mol * output_v) - 1",
        ),
    ):
        sensitivity = edges[edge_id]["sensitivity"]
        assert sensitivity["basis"] == "derived", edge_id
        assert sensitivity["derivation"]["expression"] == expression, edge_id

    # And the ledger's three entries draw at the declared demand rather than quoting a rate.
    consumables = yaml.safe_load(
        (VEHICLE / "domains" / "consumables" / "components.yaml").read_text()
    )
    ledger = {entry["id"]: entry for entry in consumables["consumers"]}
    for entry_id in ("fuel_cell_o2", "fuel_cell_h2", "fuel_cell_product_water"):
        entry = ledger[entry_id]
        assert entry["provenance"]["basis"] == "derived", entry_id
        assert (
            entry["derivation"]["inputs"]["demand_w"]
            == "domains/power/components.yaml:load_budget.csm_total_demand_w"
        ), entry_id


def test_the_linter_refuses_a_per_joule_figure_that_no_longer_derives(tmp_path):
    """The operating point is the division's denominator, so moving it must move the answer.

    This is the property that makes `derived` stronger than `historical`: `bus_v` was declared as a
    27-31 V band and the per-joule figure as "not published", and neither could disagree with the
    other because nothing joined them. The fixture moves the module's rated output by one volt,
    which is inside the declared band and would have been a silent change for the whole life of the
    corpus.
    """
    definition = copy_definition(tmp_path / "operating-point")
    path = definition / "vehicle.yaml"
    text = path.read_text()
    old = "    output_v: 29\n"
    assert old in text, "the fixture no longer matches the fuel cell's output voltage"
    path.write_text(text.replace(old, "    output_v: 28\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "A derived value that no longer re-derives is a value nobody has checked" in result.stdout


def test_the_linter_refuses_a_reactant_ratio_that_disagrees_with_its_own_molar_masses(tmp_path):
    """The corpus declared 8:1 as `0.125` while the relation beside it computed 0.126 from the masses.

    `E-H2-FC` carried `value: 0.125` and a relation that said "a H2:O2 ratio of 0.1260 = 1/7.937",
    and `fc_h2_draw_kg_s.ratio_of_o2_draw` derived *from* the 0.125 — so two declarations in two
    files disagreed by 0.8 %, in the number that every oxygen budget in the mission is denominated
    in. It is now derived from the two molar masses, and the Mission E analysis's own 7.936 is an
    independent corroboration that the exact stoichiometry is 7.9365 rather than 8.
    """
    definition = copy_definition(tmp_path / "ratio")
    path = definition / "vehicle.yaml"
    text = path.read_text()
    old = "    reactant_molar_mass_kg_per_mol: {h2: 0.002016, o2: 0.032}\n"
    assert old in text, "the fixture no longer matches the reactant molar masses"
    path.write_text(
        text.replace(old, "    reactant_molar_mass_kg_per_mol: {h2: 0.002, o2: 0.032}\n", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "the sensitivity" in result.stdout or "ratio_of_o2_draw" in result.stdout, result.stdout[-900:]


def test_the_thermal_budget_is_a_partition_by_vehicle(tmp_path):
    """The LM sublimator's capacity is published, and landing it split the total it landed in.

    `load_budget` had split its *demands* by vehicle since it was written — `csm_total_demand_w`
    and `lm_total_demand_w` — and summed its *capacities* into one `total_rejection_capacity_w`
    whose own relation argued a 1,723 W CSM margin. With the LM's sublimator unset that was merely
    incomplete; the moment the LM's 3,649 W was published, one number held two vehicles' rejection
    under a one-vehicle sentence. So the totals are per vehicle now, and the check is a partition
    in both directions: a part whose vehicle's total does not reach it, a part that names no
    vehicle, and a declared total with no parts are each refused.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    budget = thermal["load_budget"]
    assert budget["csm_rejection_capacity_w"] == 4933
    assert budget["lm_rejection_capacity_w"] == 3649
    assert "total_rejection_capacity_w" not in budget, (
        "one total for two vehicles is the defect the split removed"
    )
    # Every part says which vehicle it belongs to, and the parts of each vehicle reach its total.
    parts: dict[str, float] = {"csm": thermal["radiator_model"]["csm"]["rejection_w"]}
    for component in thermal["components"]:
        if isinstance(component.get("rejection_w"), (int, float)):
            assert component.get("vehicle"), f"{component['id']} declares a capacity and no vehicle"
            parts[str(component["vehicle"])] = component["rejection_w"]
    assert parts == {"csm": 2345, "lm": 3649}, parts

    # The LM sublimator's own two figures, from the LM ECS subsystem specification.
    lm = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())["thermal"]["radiators"][2]
    assert lm["id"] == "lm_sublimator" and lm["vehicle"] == "lm"
    assert lm["rejection_w"] == 3649, "12,450 Btu/hr at 0.29307107 W per Btu/hr"
    assert lm["water_consumption_kg_per_h"] == 5.171, "0.19 lb/min"
    assert lm["provenance"]["basis"] == "historical"
    assert "12,450 Btu/hr" in lm["provenance"]["source"], lm["provenance"]["source"][-200:]

    # A part that names no vehicle is refused rather than added to whichever total is nearest.
    definition = copy_definition(tmp_path / "unowned-part")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    old = "  - id: evaporator_csm\n    kind: flow\n    class: evaporator\n    vehicle: csm\n"
    assert old in text, "the fixture no longer matches the CSM evaporator"
    path.write_text(
        text.replace(old, "  - id: evaporator_csm\n    kind: flow\n    class: evaporator\n", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "counts no total for ['evaporator_csm']" in result.stdout, result.stdout[-900:]

    # And a total that counts hardware the file does not have.
    definition = copy_definition(tmp_path / "orphan-total")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    old = "  lm_rejection_capacity_w: 3649\n"
    assert old in text, "the fixture no longer matches the split totals"
    path.write_text(text.replace(old, old + "  mars_rejection_capacity_w: 100\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "mars_rejection_capacity_w" in result.stdout and "does not have" in result.stdout, (
        result.stdout[-900:]
    )


def test_the_linter_refuses_an_unavailability_claim_that_names_no_document(tmp_path):
    """Four rounds of finding "not published" false, and the fix is to make the claim bounded.

    Round 2: the 100 lbf thruster's minimum firing time, on PDF p. 89 of a study guide the manifest
    listed. Round 3: the fuel cell's reactant per joule, one division from three published numbers.
    Round 4: the LM sublimator's capacity and water rate, "genuinely unpublished" with four
    documents named as searched — none of which has it. Round 5: the DPS's 960-second life and the
    ascent engine's 460, on printed pages 19 and 27 of the same guide round 2 opened.

    The shape is not carelessness. "Not published" is a negative over a library of 8,954 titles
    asserted from a handful of documents, and nothing made the author write down which handful — so
    a claim with no search behind it could not be checked by the person who made it. The rule is the
    strongest the evidence supports: a provenance saying the figure is not to be had must name a
    document. It cannot verify the search; what it does is make the claim bounded, so the next round
    can ask whether those documents are all of them.
    """
    definition = copy_definition(tmp_path / "unsupported-negative")
    path = definition / "domains" / "comms" / "components.yaml"
    text = path.read_text()
    # **The whole note, not its last sentence.** The first version of this fixture swapped only the
    # closing line, and the note went on carrying the search record above it — so the copy composed
    # and the test failed for the right reason. A claim and its search are one declaration and a
    # fixture has to replace both.
    start = text.index("  - id: gimbal\n")
    note = text.index("      note: >-\n", start)
    end = text.index("\n\n", note)
    path.write_text(
        text[:note]
        + "      note: >-\n"
        + "        the mechanism that keeps a 9.4-degree beam on Earth, and the component F-11\n"
        + "        fails. Both parameters are owed: no source publishes the Apollo HGA's gimbal\n"
        + "        range or slew rate"
        + text[end:]
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "names no document it looked in" in result.stdout, result.stdout[-900:]


def test_a_bounded_search_record_is_what_the_corpus_now_carries():
    """And the escape is to not make the claim, which four of the five entries took.

    There are two honest ways to satisfy the rule: name the documents searched, or state the debt
    without asserting a negative about the literature. Four of the five entries this round did the
    second — "the parameters are owed" rather than "no source gives them" — because that is what was
    actually known: the folder had searched seven documents, not the library.
    """
    for relative, cid in (
        ("domains/comms/components.yaml", "gimbal"),
        ("domains/eclss/components.yaml", "condensing_heat_exchanger"),
        ("domains/structure/components.yaml", "hatch_crew_csm"),
        ("domains/structure/components.yaml", "docking_interface"),
        ("domains/structure/components.yaml", "pyro_lm_separation"),
    ):
        document = yaml.safe_load((VEHICLE / relative).read_text())
        component = next(c for c in document["components"] if c.get("id") == cid)
        note = component["provenance"]["note"]
        assert component["provenance"]["basis"] == "UNCONFIGURED", cid
        assert "Searched, and none has it" in note, (
            f"{cid} no longer carries the search record, so its claim is unbounded again"
        )
    # And the three values this round actually sourced.
    propulsion = yaml.safe_load((VEHICLE / "domains" / "propulsion" / "components.yaml").read_text())
    ratings = {row["engine"]: row for row in propulsion["capability"]}
    assert ratings["dps"]["total_burn_s"] == 960 and ratings["dps"]["restarts_qualified"] == 20
    assert ratings["aps"]["total_burn_s"] == 460 and ratings["aps"]["restarts_qualified"] == 35
    for engine in ("dps", "aps"):
        assert ratings[engine]["provenance"]["basis"] == "historical", engine
        assert "lm_propulsion_rcs_study_guide.pdf" in ratings[engine]["provenance"]["source"], engine

    structure = yaml.safe_load((VEHICLE / "domains" / "structure" / "components.yaml").read_text())
    valve = next(c for c in structure["components"] if c.get("id") == "relief_valve")
    assert valve["crack_pressure_psid"] == 6.0
    assert valve["reverse_limit_psid"] == 0.902
    assert "csm_ecs_study_guide.pdf" in valve["provenance"]["source"]


def test_a_zones_time_constant_is_its_lump_over_its_conductance(tmp_path):
    """The mass was written in a sentence in every zone, and as an unread field in two of them.

    Every `lag` zone computes `tau = C/G` with `C = m x c_p`. The cabin's relation said "C = 400 kg
    aluminium-equivalent x 900 J/kg-K", the avionics plate's said "C = 60 kg", and the two
    unregulated bays declared a `lumped_mass_kg` that **appeared in no file under `tools/`** — so the
    field was declared exactly where the corpus could not fill it and omitted where it could.

    The mass is not a second statement of the time constant. It is the input that turns the constant
    into a conductance, which is what `E-BAY-HEAT-CSM` and `E-BAY-HEAT-LM` need in K per W, and the
    comment above `zone_csm_service_t` had said so all along: "`C = m x c_p` and `G = C / tau`, so
    ONE number closes the edge above: the lumped mass". Nothing evaluated it.
    """
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    states = {s["id"]: s for s in thermal["state"]}
    for zone, (mass, heat, conductance, tau) in (
        ("zone_csm_cabin_t", (400, 900, 125, 2880)),
        ("zone_lm_cabin_t", (400, 900, 125, 2880)),
        ("zone_csm_avionics_t", (60, 900, 133, 406)),
    ):
        state = states[zone]
        assert state["lumped_mass_kg"] == mass, zone
        assert state["specific_heat_j_per_kg_k"] == heat, zone
        assert state["conductance_w_per_k"] == conductance, zone
        assert state["tau_s"] == tau, zone
        assert state["provenance"]["computes"] == "tau_s", zone
        assert state["provenance"]["basis"] == "derived", zone

    # The two bays keep their owed mass, and it is now the *one* scalar between the zone and a
    # closed edge: both edges carry the division that reads it.
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    edges = {e["id"]: e for e in coupling["edges"]}
    for edge_id, zone in (
        ("E-BAY-HEAT-CSM", "zone_csm_service_t"),
        ("E-BAY-HEAT-LM", "zone_lm_descent_t"),
    ):
        assert states[zone]["lumped_mass_kg"] == "UNCONFIGURED", zone
        assert states[zone]["specific_heat_j_per_kg_k"] == 900, zone
        sensitivity = edges[edge_id]["sensitivity"]
        assert sensitivity["basis"] == "derived", edge_id
        assert sensitivity["derivation"]["expression"] == (
            "tau_s / (lumped_mass_kg * specific_heat_j_per_kg_k)"
        ), edge_id
        assert sensitivity["derivation"]["inputs"]["lumped_mass_kg"] == (
            f"domains/thermal/components.yaml:state.{zone}.lumped_mass_kg"
        ), edge_id

    # A lump that disagrees with its own time constant is refused.
    definition = copy_definition(tmp_path / "lump")
    path = definition / "domains" / "thermal" / "components.yaml"
    text = path.read_text()
    old = "    lumped_mass_kg: 400\n    specific_heat_j_per_kg_k: 900\n    conductance_w_per_k: 125\n"
    assert old in text, "the fixture no longer matches the cabin lump"
    path.write_text(text.replace(old, "    lumped_mass_kg: 500\n" + old.split("\n", 1)[1], 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "which is a time constant of 3600 s" in result.stdout, result.stdout[-900:]


def test_the_thermal_bays_refuse_a_source_from_the_wrong_vehicle_or_an_unverified_capacity_claim(tmp_path):
    """An LM-3 diagram citation was presented as the missing CSM and LM-5 bay masses.

    LM0-510-1070 only cites LM0-510-1036; the latter scan has not been examined. Its title
    limits it to LM-3, and no nodal diagram establishes this model's aggregate heat capacity
    or conductance without an explicit node-to-zone reduction. Break a complete copy so the
    provenance guard must read both bays and their source audit, not just the clean definition.
    """
    source = VEHICLE / "domains" / "thermal" / "components.yaml"
    clean = yaml.safe_load(source.read_text())
    states = {state["id"]: state for state in clean["state"]}
    assert states["zone_csm_service_t"]["lumped_mass_kg"] == "UNCONFIGURED"
    assert states["zone_lm_descent_t"]["lumped_mass_kg"] == "UNCONFIGURED"
    for name, old, new in (
        ("cross_vehicle", "candidate_document: TIR 580-S-7159", "candidate_document: LM0-510-1036"),
        ("false_effectivity", "candidate_effectivity: LM-3 only; LM-5 applicability unverified", "candidate_effectivity: LM-5"),
        ("false_verification", "evidence_status: citation_only", "evidence_status: verified"),
        ("missing_audit", "        modeled_vehicle: CSM\n", ""),
        ("malformed_audit", None, None),
    ):
        definition = copy_definition(tmp_path / name)
        path = definition / "domains" / "thermal" / "components.yaml"
        if name == "malformed_audit":
            thermal = yaml.safe_load(path.read_text())
            state = next(state for state in thermal["state"] if state["id"] == "zone_csm_service_t")
            state["provenance"]["source_audit"] = "malformed"
            path.write_text(yaml.safe_dump(thermal, sort_keys=False))
        else:
            text = path.read_text()
            assert old in text, f"the {name} broken copy no longer matches the live source"
            path.write_text(text.replace(old, new, 1))
        result = run_linter(definition)
        assert result.returncode == 1, (name, result.stdout[-1000:])
        assert "thermal source audit" in result.stdout, (name, result.stdout[-1000:])


def test_an_edge_that_names_where_its_value_comes_from_is_not_a_second_debt(tmp_path):
    """The obligation is counted where the quantity lives — the rule the derivation check states.

    `check_declared_derivation` says it outright: "the obligation is counted where the quantity
    lives, and this is a use of it rather than a second unknown." The edge walk counted it anyway, so
    an edge `derived` from an owed field appeared twice in the headline. Two edges reached that state
    the moment their derivations landed, and the count is the figure a reader plans against.

    Skipping them is not a hole: a derivation whose inputs are all numbers resolves, and
    `check_declared_derivation` refuses it for carrying nothing to hold it against — this test drives
    that direction too, so the skip cannot become a way to owe a value quietly.
    """
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    derived = [
        e["id"]
        for e in coupling["edges"]
        if (e.get("sensitivity") or {}).get("value") == "UNCONFIGURED"
        and (e.get("sensitivity") or {}).get("derivation")
    ]
    assert derived == ["E-BAY-HEAT-CSM", "E-BAY-HEAT-LM"], derived
    result = run_linter(VEHICLE, strict=True)
    for edge_id in derived:
        assert f"coupling.yaml:edge {edge_id}:" not in result.stdout, (
            f"{edge_id} is counted as a debt of its own as well as where its input lives"
        )
    # And the input is still counted, exactly once.
    assert result.stdout.count("lumped_mass_kg: is UNCONFIGURED") == 2, result.stdout[-900:]

    # The other direction: an evaluable derivation with nothing to hold it against is refused.
    definition = copy_definition(tmp_path / "evaluable")
    path = definition / "coupling.yaml"
    text = path.read_text()
    old = (
        "          tau_s: domains/thermal/components.yaml:state.zone_lm_descent_t.tau_s\n"
        "          lumped_mass_kg: domains/thermal/components.yaml:state.zone_lm_descent_t.lumped_mass_kg\n"
        "          specific_heat_j_per_kg_k: domains/thermal/components.yaml:state.zone_lm_descent_t.specific_heat_j_per_kg_k\n"
    )
    assert old in text, "the fixture no longer matches E-BAY-HEAT-LM's derivation"
    path.write_text(
        text.replace(old, "          tau_s: 10800\n          lumped_mass_kg: 400\n          specific_heat_j_per_kg_k: 900\n", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "which there is nothing to hold it against" in result.stdout, result.stdout[-900:]


def test_every_loaded_tank_is_carried_by_a_stock_or_declared_not_to_be(tmp_path):
    """The graph had stocks for four of the vehicle's six loaded tanks, and nothing joined the lists.

    `prop_main_kg` owed its `initial` for as long as the domain has existed, on the reasoning that "a
    single initial for the node would be a choice about which tank it *is* rather than a figure
    anything publishes". Asking the question turned up the other half: the only edge out of the node
    derives its rate from `vehicle.yaml:propulsion.sps.isp_s`, so the choice had been made one file
    over — and **the LM's descent and ascent propellant, 10,624 kg or a third of the vehicle's
    propellant, was in no stock at all** while the mass closure and the Δv budget both knew about it.

    So each stock declares the tanks it carries, the two the graph does not carry are named with
    their reason, and a carrier's level is the sum of its list.
    """
    coupling = yaml.safe_load((VEHICLE / "coupling.yaml").read_text())
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    consumables = yaml.safe_load((VEHICLE / "domains" / "consumables" / "components.yaml").read_text())

    assert coupling["nodes"]["prop_main"]["carries"] == ["sps"]
    assert coupling["nodes"]["prop_rcs"]["carries"] == ["rcs_sm", "rcs_cm", "rcs_lm"]
    off = vehicle["propulsion"]["not_on_a_coupling_stock"]
    assert sorted(off) == ["lm_aps", "lm_dps"], off

    states = {s["node"]: s for s in consumables["state"] if s.get("node")}
    assert states["prop_main"]["initial"] == 18508 == vehicle["propulsion"]["sps"]["mass_kg"]
    assert states["prop_rcs"]["initial"] == 1008
    assert states["prop_rcs"]["initial"] == sum(
        vehicle["propulsion"][k]["mass_kg"] for k in ("rcs_sm", "rcs_cm", "rcs_lm")
    )
    # And the two the graph does not carry are 10,624 kg between them — the figure the round is for.
    assert sum(vehicle["propulsion"][k]["mass_kg"] for k in off) == 10624

    # A tank loaded and carried by nothing is refused.
    definition = copy_definition(tmp_path / "uncarried")
    path = definition / "vehicle.yaml"
    text = path.read_text()
    old = '    lm_aps: "2,376 kg'
    assert old in text, "the fixture no longer matches the off-graph declaration"
    start = text.index(old)
    end = text.index("\n", text.index("460 s rating", start))
    path.write_text(text[:start] + text[end + 1 :])
    result = run_linter(definition)
    assert result.returncode == 1
    assert "declares 2376 kg of 'lm_aps' loaded and no coupling stock carries it" in result.stdout, (
        result.stdout[-900:]
    )


def test_a_stocks_level_is_the_tanks_it_says_it_holds(tmp_path):
    """`carries` gives the two derived propellant initials a reader, and catches a stale one.

    The initials are `derived` — 18,508 from the SPS's load and 1,008 from the three RCS systems' —
    and a derivation the linter evaluates is a value that cannot drift from its inputs. This holds
    the other end: the *level* against the list, so a stock whose `carries` changes without its
    initial moving is refused by name rather than composing.
    """
    definition = copy_definition(tmp_path / "carried-twice")
    path = definition / "coupling.yaml"
    text = path.read_text()
    old = "    carries: [rcs_sm, rcs_cm, rcs_lm]\n"
    assert old in text, "the fixture no longer matches prop_rcs's carries list"
    path.write_text(text.replace(old, "    carries: [rcs_sm, rcs_cm, rcs_lm, sps]\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "'sps', which 'prop_main' already carries" in result.stdout, result.stdout[-900:]

    # And a level that is not the sum of its list.
    definition = copy_definition(tmp_path / "wrong-level")
    path = definition / "domains" / "consumables" / "components.yaml"
    text = path.read_text()
    old = "    initial: 1008\n"
    assert old in text, "the fixture no longer matches prop_rcs's initial"
    path.write_text(text.replace(old, "    initial: 1200\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "derives 1008 from 'sm + cm + lm'" in result.stdout, result.stdout[-900:]


def test_the_ppO2_band_is_the_cabin_mixture_s_band_and_not_its_total_pressure():
    """The one band the domain derives was derived from the wrong pressure, in four declarations.

    `eclss.pp_o2_mmhg` derives from `csm_cabin_o2_kg`, and the four gas stocks of a compartment are
    one mixture at one pressure. The band read **248-269 mmHg** because "the cabin sits at 4.8-5.2
    psia of essentially pure oxygen, and 5 psia is 258.6 mmHg" — which is the *total* pressure
    band. The cabin is not essentially pure: it is 9.209 mmHg of water vapour (`csm_ecs_study_guide.pdf`
    PDF p. 16 runs the cooling process to a 50 F dew point, and that is water's saturation pressure
    at 10 C) and 3.0 mmHg of carbon dioxide (this domain's own one-hour-average limit) away from it,
    and the regulator holds *total* pressure, so those 12.209 mmHg are oxygen the cabin never has.

    The wrong band stood in four declarations — both channel ranges and this compartment's two
    thresholds — and in two `points.yaml` entries and the domain's own header comment. Nothing could
    see it because nothing added the four masses up; `check_cabin_pressure_closure` now does, and
    this recomputes the mixture from the stocks so the test is a second reader of the derivation
    rather than a copy of the band it is checking.
    """
    eclss = yaml.safe_load((VEHICLE / "domains" / "eclss" / "components.yaml").read_text())
    thermal = yaml.safe_load((VEHICLE / "domains" / "thermal" / "components.yaml").read_text())
    channels = yaml.safe_load((VEHICLE / "channels.yaml").read_text())
    profiles = yaml.safe_load((VEHICLE / "domains" / "eclss" / "profiles.yaml").read_text())

    model = eclss["atmosphere_model"]
    shares = model["check"]["partial_pressures_mmhg"]
    assert shares == {"h2o": 9.209, "co2": 3.0, "n2": 0.0}, shares
    assert sum(shares.values()) == 12.209

    gases = {gas["id"]: gas["molar_mass_kg_per_mol"] for gas in model["gases"]}
    stocks = {state["id"]: state for state in eclss["state"]}
    zones = {zone["id"]: zone for zone in thermal["zones"]}
    psi_to_pa, mmhg_to_pa, r_gas = 6894.757293168361, 133.322387415, 8.314462618153

    for prefix, zone_id in (("csm_cabin", "csm_cabin"), ("lm_cabin", "lm_cabin")):
        zone = zones[zone_id]
        cabin = zone_id.split("_")[0]
        moles = {
            gas: stocks[f"{prefix}_{gas}_kg"]["initial"] / gases[gas]
            for gas in ("o2", "h2o", "co2", "n2")
        }
        volume = model["volume_m3"][cabin]
        pressure_pa = sum(moles.values()) * r_gas * zone["nominal_temperature_k"] / volume
        # The four are one mixture, so their sum is the pressure the zone is held at.
        assert pressure_pa == pytest.approx(zone["nominal_pressure_psia"] * psi_to_pa, abs=0.1), cabin
        pp_o2 = pressure_pa * moles["o2"] / sum(moles.values()) / mmhg_to_pa
        assert pp_o2 == pytest.approx(246.37, abs=0.01), (cabin, pp_o2)
        # 248 mmHg is 4.8 psia of *total* pressure. Oxygen in a cabin with water in it cannot
        # reach it — which is the finding, stated as an inequality rather than as a band.
        assert pp_o2 < 248.0, cabin

    band = [236.02, 256.71]
    registry = {row["id"]: row for row in channels["eclss"]}
    for channel_id in ("eclss.pp_o2_mmhg", "eclss.lm_pp_o2_mmhg"):
        assert registry[channel_id]["range"] == band, channel_id
        assert registry[channel_id]["range_kind"] == "band", channel_id
    thresholds = {row["id"]: row for row in profiles["thresholds"]}
    assert thresholds["lm_ppo2_hypoxia"]["assert"] == band[0]
    assert thresholds["lm_ppo2_fire_risk"]["assert"] == band[1]
    # And the band is the total band less the shares, at the declared significant figures.
    assert round(4.8 * psi_to_pa / mmhg_to_pa - sum(shares.values()), 2) == band[0]
    assert round(5.2 * psi_to_pa / mmhg_to_pa - sum(shares.values()), 2) == band[1]

    # The oxygen initial is the remainder rather than a declared mass, and the subtraction is by
    # partial pressure: subtracting carbon dioxide's *mass* from an oxygen-mass total would
    # over-subtract it by a quarter, because it is 44 g/mol against oxygen's 32.
    derivation = stocks["csm_cabin_o2_kg"]["initial_derivation"]
    assert derivation["expression"].startswith("(psi_to_pa * pressure_psia - mmhg_to_pa * (")
    assert derivation["inputs"]["pp_co2"].endswith("partial_pressures_mmhg.co2")


def test_the_linter_refuses_a_cabin_whose_four_gases_do_not_make_its_pressure(tmp_path):
    """A mixture that does not reach the pressure it is held at is a cabin flown at two pressures.

    The check is one that could not exist before the four stocks did: the oxygen initial alone
    claimed the whole 5 psia, which is only consistent with the other three being nothing. With a
    carbon dioxide stock that holds a real share, inflating it must make the sum miss the zone's
    pressure *and say so with both numbers*, because a closure that fails silently is the state the
    folder was in for eight rounds.
    """
    definition = copy_definition(fixture_dir(tmp_path, "mixture"))
    path = definition / "domains" / "eclss" / "components.yaml"
    text = path.read_text()
    old = "    initial: 0.04233239\n"
    assert old in text, "the fixture no longer matches the CSM carbon dioxide stock's initial"
    path.write_text(text.replace(old, "    initial: 0.9\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "the csm cabin's four gas initials come to" in result.stdout, result.stdout[-900:]
    assert "the zone is held at 5 psia" in result.stdout, result.stdout[-900:]
    assert "is a cabin that cannot be at the pressure it is flown at" in result.stdout, (
        result.stdout[-900:]
    )


def test_the_linter_refuses_a_ppO2_that_its_own_two_alarms_do_not_bracket(tmp_path):
    """The composition and the alarms describe one cabin, so the linter holds them against each other.

    Two ways for that to fail, and the second is the one the closure check has to refuse rather than
    skip: an alarm whose band no longer contains the mixture, and a compartment with no ppO2 pair at
    all — a mixture nothing calls habitable or not. The pair is *per compartment*, so a fixture that
    repoints the LM's two thresholds must leave the CSM's own pair where it is.
    """
    # An LM fire-risk alarm moved down onto the mixture: it now fires while the cabin is nominal.
    definition = copy_definition(fixture_dir(tmp_path, "narrow-band"))
    path = definition / "domains" / "eclss" / "profiles.yaml"
    text = path.read_text()
    old = (
        "  - id: lm_ppo2_fire_risk\n"
        "    point: eclss.lm_pp_o2_mmhg\n"
        "    comparator: above\n"
        "    assert: 256.71\n"
    )
    assert old in text, "the fixture no longer matches the LM fire-risk threshold"
    path.write_text(text.replace(old, old.replace("assert: 256.71", "assert: 240.0"), 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert (
        "the lm cabin's four gases give a ppO2 of 246.37 mmHg against a habitable band of "
        "236.02 to 240 mmHg" in result.stdout
    ), result.stdout[-900:]
    # And the older reader catches the same fixture from the registry's side, which is why the
    # two checks are not one: a band is a declaration, and an alarm inside it is a contradiction
    # whoever reads it.
    assert "the region its own registry calls acceptable" in result.stdout, result.stdout[-900:]

    # A compartment whose ppO2 nothing watches.
    definition = copy_definition(fixture_dir(tmp_path, "unwatched"))
    path = definition / "domains" / "eclss" / "profiles.yaml"
    text = path.read_text()
    assert text.count("    point: eclss.lm_pp_o2_mmhg\n") == 2, "the LM pair has moved"
    path.write_text(text.replace("    point: eclss.lm_pp_o2_mmhg\n", "    point: eclss.pp_o2_mmhg\n"))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "the lm cabin's mixture gives a ppO2 of 246.37 mmHg" in result.stdout, result.stdout[-900:]
    assert "declares no pair of ppO2 thresholds to hold it between" in result.stdout, (
        result.stdout[-900:]
    )
    assert "the csm cabin's mixture" not in result.stdout, result.stdout[-900:]


def test_the_docked_configuration_s_mass_properties_re_derive_from_the_data_book_s_rows():
    """The folder's flagship unknown, "not reachable" for a hundred rounds, is in the library.

    `vehicle.yaml#open_debts` said: *the axis datum lives in the CSM/LM Operational Data Book
    (SNA-8-D-027), which is not reachable, so the tabulated values cannot be converted to physical
    offsets.* The book is in the library, this folder already cites it for other tables, and it
    carries both halves — section 2.0's frame definition and section 3.2's tables. This test is the
    second reader: it recomputes the interpolation from the two rows the file carries rather than
    trusting the derived values, and it holds the table's own `AVERAGE` column, which is the
    identity that makes a hand-read rotated fold-out checkable.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    block = vehicle["mass_properties"]
    frames = {f["id"]: f for f in block["frames"]}
    assert sorted(frames) == ["APOLLO_XA", "LM_XE"], sorted(frames)
    frame = frames["APOLLO_XA"]
    # The datum itself: without this transformation a station is a number against nothing.
    assert "SNA-8-D-027" in frame["provenance"]["source"], frame["provenance"]["source"]
    assert "Figures 2-16 and 2-17" in frame["provenance"]["source"]
    # The transformations themselves, which are what make a station a physical offset.
    assert "4578.805" in frame["definition"] and "X_A = X_E + 399.5" in frame["definition"]
    assert "X_A = 1422.75 - X_E" in frame["definition"]
    assert "Rev 2" in frame["provenance"]["source"]

    table = {t["id"]: t for t in block["tables"]}["ODB_3_2_21"]
    assert table["configuration"] == "csm_lm_docked"
    assert table["frame"] == "APOLLO_XA"
    assert "CSM-113/LM-11" in table["title"] and "as a function of spacecraft weight" in table["title"]
    assert "p. 351" in table["pages"], table["pages"]
    rows = {row["id"]: row for row in table["rows"]}
    assert sorted(rows) == ["w96787_4", "w97787_4"], sorted(rows)

    # The table's own arithmetic, in every row: AVERAGE = (IYY + IZZ) / 2 / 10.
    for row in rows.values():
        assert abs(row["average_moment"] - (row["iyy_slug_ft2"] + row["izz_slug_ft2"]) / 20) <= 1.0

    # The interpolation, recomputed here from the rows rather than read back.
    kg_per_lb, in_to_m = 0.45359237, 0.0254
    slug_ft2_to_kg_m2 = 1.355817948330809
    weight_lb = vehicle["configurations"][0]["mass_kg"] / kg_per_lb
    assert vehicle["configurations"][0]["id"] == "csm_lm_docked"
    lo, hi = rows["w96787_4"], rows["w97787_4"]
    assert lo["weight_lb"] < weight_lb < hi["weight_lb"]
    fraction = (weight_lb - lo["weight_lb"]) / (hi["weight_lb"] - lo["weight_lb"])

    def interpolate(field: str) -> float:
        return lo[field] + fraction * (hi[field] - lo[field])

    entry = block["configurations"][0]
    assert entry["id"] == "csm_lm_docked" and entry["table"] == "ODB_3_2_21"
    assert entry["weight_lb"]["value"] == pytest.approx(weight_lb, abs=0.01)
    assert entry["x_bar_m"]["value"] == pytest.approx(interpolate("x_bar_in") * in_to_m, abs=1e-4)
    for axis, field in (("ixx", "ixx_slug_ft2"), ("iyy", "iyy_slug_ft2"), ("izz", "izz_slug_ft2")):
        declared = entry["inertia_kg_m2"][axis]["value"]
        # At the declared value's own precision: the moments carry seven figures and the products
        # six, and a swapped row would move either by a part in three hundred.
        assert declared == pytest.approx(interpolate(field) * slug_ft2_to_kg_m2, rel=1e-5), axis
    for axis, field in (("pxy", "pxy_slug_ft2"), ("pxz", "pxz_slug_ft2"), ("pyz", "pyz_slug_ft2")):
        declared = entry["inertia_kg_m2"][axis]["value"]
        assert declared == pytest.approx(interpolate(field) * slug_ft2_to_kg_m2, rel=1e-5), axis

    # A real tensor: the three moments satisfy the triangle inequalities, and the transverse pair
    # is about ten times the roll moment, which is what a long slender stack looks like.
    ixx = entry["inertia_kg_m2"]["ixx"]["value"]
    iyy = entry["inertia_kg_m2"]["iyy"]["value"]
    izz = entry["inertia_kg_m2"]["izz"]["value"]
    assert ixx + iyy > izz and iyy + izz > ixx and izz + ixx > iyy
    assert 7.0 < iyy / ixx < 12.0, iyy / ixx

    # And the last configuration still owed says so with its own tables named. Round 10 landed
    # `csm_alone`, `lm_alone_descent` and `lm_ascent_stage` from Tables 3.2-22, 3.2-25 and 3.2-26,
    # so what is left here is the one no single table covers.
    owed = {c["id"]: c for c in block["configurations"] if c.get("properties")}
    assert sorted(owed) == ["csm_lm_ascent_docked"], sorted(owed)
    entry = owed["csm_lm_ascent_docked"]
    assert entry["table"] == "ODB_3_2_22 + ODB_3_2_26"
    assert "matched mass epoch" in entry["note"] and "lateral rotation" in entry["note"]


def test_the_linter_refuses_a_mass_property_table_that_disagrees_with_itself(tmp_path):
    """Three ways a hand-read fold-out stops being trustworthy, each refused by name.

    The table is a rotated scan whose text layer is garbage, so the transcription cannot be
    verified by re-reading the same bytes — it is verified by **the table's own arithmetic**: the
    Operational Data Book prints an `AVERAGE` column in every row and it is `(IYY + IZZ) / 2 / 10`.
    A digit misread in either moment breaks that identity, which is the only reason the corpus can
    carry an interpolated value at all. The other two are the interpolation's own preconditions: an
    interpolation must be inside its interval, and the interval must be the pair the derivative
    actually names.
    """
    vehicle_yaml = (VEHICLE / "vehicle.yaml").read_text()

    # The table's own column, broken: one digit of IYY.
    definition = copy_definition(fixture_dir(tmp_path, "average"))
    path = definition / "vehicle.yaml"
    assert "          average_moment: 56528\n" in vehicle_yaml
    path.write_text(vehicle_yaml.replace("          average_moment: 56528\n", "          average_moment: 56928\n", 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "the same row's (IYY + IZZ) / 2 / 10 is 56528.9" in result.stdout, result.stdout[-900:]

    # The two rows the centre of mass interpolates between, swapped. The weight pair still
    # brackets, so only the derivation's own evaluation catches it.
    definition = copy_definition(fixture_dir(tmp_path, "swapped"))
    path = definition / "vehicle.yaml"
    old = (
        "            x_low: vehicle.yaml:mass_properties.tables.ODB_3_2_21.rows.w96787_4.x_bar_in\n"
        "            x_high: vehicle.yaml:mass_properties.tables.ODB_3_2_21.rows.w97787_4.x_bar_in\n"
    )
    new = (
        "            x_low: vehicle.yaml:mass_properties.tables.ODB_3_2_21.rows.w97787_4.x_bar_in\n"
        "            x_high: vehicle.yaml:mass_properties.tables.ODB_3_2_21.rows.w96787_4.x_bar_in\n"
    )
    assert old in vehicle_yaml
    path.write_text(vehicle_yaml.replace(old, new, 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "and the centre of mass declares 26.5795" in result.stdout, result.stdout[-900:]

    # And a tensor that describes no vehicle: a roll moment larger than the sum of the other two.
    definition = copy_definition(fixture_dir(tmp_path, "not-a-tensor"))
    path = definition / "vehicle.yaml"
    assert "        ixx:\n          value: 80081.1\n" in vehicle_yaml
    path.write_text(
        vehicle_yaml.replace("        ixx:\n          value: 80081.1\n", "        ixx:\n          value: 2000000.0\n", 1)
    )
    result = run_linter(definition)
    assert result.returncode == 1
    assert "No mass distribution has principal moments that violate the triangle inequality" in result.stdout, (
        result.stdout[-900:]
    )


def test_the_other_three_configurations_mass_properties_re_derive_from_their_own_tables():
    """Each configuration's own table, in its own frame — and the LM's is not Apollo's.

    Round 9 landed the docked stack from Table 3.2-21 and left four configurations named but owed.
    Three of them are read here from the tables the volume indexes for exactly those vehicles: the
    CSM alone at the circularization burn (3.2-22, **Apollo coordinates**), the LM at P.D.I.
    (3.2-25, **LM coordinates**) and the ascent stage at liftoff (3.2-26, LM coordinates). The
    fourth — the CSM docked to an ascent stage — no table covers, and stays owed.

    The frame is the half that is easy to get wrong: 3.2-25's X-BAR is about 186 inches in
    the LM's own coordinates, while the docked stack's is about 1046 in Apollo coordinates.
    Figure 2-17 reverses their axial directions; the J-2 lateral rotation remains owed.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    block = vehicle["mass_properties"]
    frames = {f["id"] for f in block["frames"]}
    assert frames == {"APOLLO_XA", "LM_XE"}

    tables = {t["id"]: t for t in block["tables"]}
    kg_per_lb, in_to_m, slug_ft2_to_kg_m2 = 0.45359237, 0.0254, 1.355817948330809
    prints_average = {"ODB_3_2_21", "ODB_3_2_22"}
    for table in tables.values():
        assert table["frame"] in frames, table["id"]
        # The AVERAGE column is the volume's, not every table's: the two CSM tables print it, the
        # three LM tables do not, and a faithful transcription must not invent it.
        for row in table["rows"]:
            assert ("average_moment" in row) == (table["id"] in prints_average), table["id"]

    for config_id, table_id, frame_id in (
        ("csm_alone", "ODB_3_2_22", "APOLLO_XA"),
        ("lm_alone_descent", "ODB_3_2_25", "LM_XE"),
        ("lm_ascent_stage", "ODB_3_2_26", "LM_XE"),
    ):
        entry = next(c for c in block["configurations"] if c["id"] == config_id)
        assert entry["table"] == table_id and "properties" not in entry, config_id
        table = tables[table_id]
        assert table["configuration"] == config_id and table["frame"] == frame_id
        mass_kg = next(c["mass_kg"] for c in vehicle["configurations"] if c["id"] == config_id)
        weight_lb = mass_kg / kg_per_lb
        assert entry["weight_lb"]["value"] == pytest.approx(weight_lb, abs=0.01), config_id
        rows = sorted(table["rows"], key=lambda r: r["weight_lb"])
        assert rows[0]["weight_lb"] < weight_lb < rows[-1]["weight_lb"], config_id
        lo, hi = rows[0], rows[1]
        fraction = (weight_lb - lo["weight_lb"]) / (hi["weight_lb"] - lo["weight_lb"])

        def interpolate(field: str, lo=lo, hi=hi, fraction=fraction) -> float:
            return lo[field] + fraction * (hi[field] - lo[field])

        assert entry["x_bar_m"]["value"] == pytest.approx(interpolate("x_bar_in") * in_to_m, abs=1e-4)
        for axis in ("ixx", "iyy", "izz", "pxy", "pxz", "pyz"):
            declared = entry["inertia_kg_m2"][axis]["value"]
            # At the declared precision: the moments are declared to a tenth of a kilogram-metre
            # squared in the tens of thousands, the products to a tenth in the hundreds.
            assert declared == pytest.approx(
                interpolate(f"{axis}_slug_ft2") * slug_ft2_to_kg_m2, rel=1e-4, abs=0.05
            ), (config_id, axis)
        # And the tensor is a real one, at every configuration and not only the docked one.
        ixx = entry["inertia_kg_m2"]["ixx"]["value"]
        iyy = entry["inertia_kg_m2"]["iyy"]["value"]
        izz = entry["inertia_kg_m2"]["izz"]["value"]
        assert ixx + iyy > izz and iyy + izz > ixx and izz + ixx > iyy, config_id

    # The LM-only table stays in its native frame; no Apollo translation is applied here.
    ascent = next(c for c in block["configurations"] if c["id"] == "lm_ascent_stage")
    assert 6.0 < ascent["x_bar_m"]["value"] < 6.4
    assert "1422.75 - X_E" in next(f for f in block["frames"] if f["id"] == "LM_XE")["definition"]


def test_the_linter_refuses_a_mass_property_table_whose_frame_is_not_declared(tmp_path):
    """A tensor in an unnamed frame is a tensor nothing can rotate or offset.

    The LM tables are in LM coordinates and the CSM's in Apollo's, so a table that names a
    frame the file does not declare is refused by name
    rather than read as though the two were interchangeable. The second fixture is the other half
    of the interpolation rule, on a configuration that is not the docked one: the rows a
    derivation names must bracket the weight it is interpolating at.
    """
    vehicle_yaml = (VEHICLE / "vehicle.yaml").read_text()

    definition = copy_definition(fixture_dir(tmp_path, "frameless"))
    path = definition / "vehicle.yaml"
    old = "    - id: ODB_3_2_25\n      configuration: lm_alone_descent\n      frame: LM_XE\n"
    assert old in vehicle_yaml
    path.write_text(vehicle_yaml.replace(old, old.replace("frame: LM_XE", "frame: LM_STATION"), 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "not a frame this block declares" in result.stdout, result.stdout[-900:]

    definition = copy_definition(fixture_dir(tmp_path, "wrong-rows"))
    path = definition / "vehicle.yaml"
    old = (
        "              i_low: vehicle.yaml:mass_properties.tables.ODB_3_2_26.rows.w10632_7.ixx_slug_ft2\n"
        "              i_high: vehicle.yaml:mass_properties.tables.ODB_3_2_26.rows.w10863_3.ixx_slug_ft2\n"
    )
    new = (
        "              i_low: vehicle.yaml:mass_properties.tables.ODB_3_2_26.rows.w10863_3.ixx_slug_ft2\n"
        "              i_high: vehicle.yaml:mass_properties.tables.ODB_3_2_26.rows.w10632_7.ixx_slug_ft2\n"
    )
    assert old in vehicle_yaml
    path.write_text(vehicle_yaml.replace(old, new, 1))
    result = run_linter(definition)
    assert result.returncode == 1
    assert "the moment of inertia declares" in result.stdout, result.stdout[-900:]


def test_the_docked_lm_axial_station_reverses_direction_and_lateral_clocking_remains_owed():
    """Rev 2 Figure 2-17 reverses X_E against X_A, with no J-2 full rotation claim.

    The old +797.75 in translation matched the mated interface but reversed the direction
    for every other LM station. Figure 2-16's launch +399.5 in relation is a separate
    configuration. The Rev 3 Amendment 114 J-2 mass tables remain in their native frames.
    """
    vehicle = yaml.safe_load((VEHICLE / "vehicle.yaml").read_text())
    block = vehicle["mass_properties"]
    lm = next(f for f in block["frames"] if f["id"] == "LM_XE")
    transforms = {t["configuration"]: t for t in lm["axial_transforms"]}
    assert set(transforms) == {"launch", "docked"}
    launch, docked = transforms["launch"], transforms["docked"]
    assert (launch["scale"], launch["origin_in"]) == (1, 399.5)
    assert (docked["scale"], docked["origin_in"]) == (-1, 1422.75)
    assert docked["lateral_rotation"] == "UNCONFIGURED"
    assert "Rev 2" in docked["source"]
    assert launch["scale"] * 312.5 + launch["origin_in"] == 712.0
    assert docked["scale"] * 312.5 + docked["origin_in"] == 1110.25
    assert docked["scale"] * 0 + docked["origin_in"] == 1422.75
    assert docked["scale"] * 400 + docked["origin_in"] == 1022.75

    for table in block["tables"]:
        if table["frame"] == "LM_XE":
            assert table.get("transform_configuration") or table.get("transform_not_applicable"), table["id"]

    # This axial-only comparison is a diagnostic, not a tensor composition. The separate
    # tables' reference states have not been matched at one mission epoch.
    def entry(config_id):
        return next(c for c in block["configurations"] if c["id"] == config_id)

    tables = {t["id"]: t for t in block["tables"]}

    def interpolated(config_id, field):
        e = entry(config_id)
        rows = sorted(tables[e["table"]]["rows"], key=lambda r: r["weight_lb"])
        w = e["weight_lb"]["value"]
        lo, hi = rows[0], rows[1]
        fraction = (w - lo["weight_lb"]) / (hi["weight_lb"] - lo["weight_lb"])
        return lo[field] + fraction * (hi[field] - lo[field])

    csm_x = interpolated("csm_alone", "x_bar_in")
    lm_x = interpolated("lm_alone_descent", "x_bar_in")
    composed_x = (28807 * csm_x + 15278 * (docked["scale"] * lm_x + docked["origin_in"])) / 44085
    tabulated_x = interpolated("csm_lm_docked", "x_bar_in")
    assert composed_x == pytest.approx(1037.65045, abs=0.01)
    assert tabulated_x == pytest.approx(1046.43786, abs=0.01)
    assert abs(composed_x - tabulated_x) / tabulated_x == pytest.approx(0.00839745, abs=1e-5)

    owed = next(c for c in block["configurations"] if c["id"] == "csm_lm_ascent_docked")
    assert owed["properties"] == "UNCONFIGURED"
    assert "epoch" in owed["note"] and "lateral rotation" in owed["note"]


